INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 15, '');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 16, '');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 17, '');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 18, '');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 19, 'Dies [ist] die Geschlechtsgeschichte Isaaks, des Sohnes Abrahams. Abraham zeugte Isaak.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 20, 'Isaak [war] vierzig Jahre alt, als er nahm Rebekka, die Tochter Betuels des Aramäers aus Padan-Aram, die Schwester Labans des Aramäers, für sich zur Frau.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 21, 'Isaak betete zu JHWH für seine Frau, denn unfruchtbar [war] sie. Ihn erhörte JHWH und schwanger wurde Rebekka, seine Frau.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 22, 'Die Kinder stießen sich (sprangen, hüpften) in ihrem Inneren und sie sagte: Wenn [das] so [ist], warum [geschieht] dies mir? (Wenn [das] so [ist], warum [ist] dieses Leben mir?) Und sie ging um zu befragen JHWH.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 23, 'JHWH sagte ihr: Zwei Völker [sind] in deinem Leib und zwei Nationen von deinem Mutterleib werden sie sich zerstreuen (sich verteilen, sich trennen). Eine Nation wird stärker sein als [die andere] Nation (eine Nation wird [die andere] Nation überwältigen), und [der] Große wird dienen [dem] Kleinen ([der] Ältere wird dienen [dem] Jüngeren).');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 24, 'Als erfüllt waren ihr Tage um zu gebären, siehe, Zwillinge [waren] in ihrem Leib.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 25, 'Der Erste kam heraus rotbraun (rot) und sein Ganzes [war] wie ein Haarmantel (Pelzmantel) und sie riefen seinen Namen Esau.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 26, 'Danach kam heraus sein Bruder und seine Hand hielt an der Ferse Esaus und er rief seinen Namen Jakob (man rief seinen Namen Jakob). Isaak war sechzig Jahre alt bei ihrer Geburt.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 27, 'Die Jungen wurden groß und Esau [war] ein jagdkundiger Mann, ein Mann des Feldes und Jakob [war] ein häuslicher Mann (ein gesitteter Mann), wohnend (sitzend, bleibend) [bei (in) den] Zelten.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 28, 'Isaak liebte Esau, denn Wild [war] in seinem Mund (Wild [war] nach seinem Mund) und Rebekka liebte Jakob.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 29, '');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 30, '');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 31, '');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 32, '');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 33, '');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 34, '');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 1, 'Und es war eine Hungersnot im Land - es war nicht die frühere Hungersnot in den Tagen Abrahams - und Isaak zog zu Abimelech, dem König der Philister, nach Gerar.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 2, 'Und der Herr erschien ihm und sprach: „Ziehe nicht nach Ägypten hinunter, (sondern) lebe in dem Land, das ich dir nennen werde.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 3, 'Bleibe als Schutzbürger in diesem Land und ich werde mit dir sein und dich segnen. Denn ich werde dir und deinen Nachkommen all diese Länder geben und werde den Eid halten, den ich Abraham, deinem Vater, geschworen habe.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 4, 'Und ich will deine Nachkommen zahlreich machen wie die Sterne am Himmel und deinen Nachkommen all diese Länder geben und durch deine Nachkommen werden alle Völker der Erde gesegnet werden.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 5, 'Denn Abraham hat meine Stimme gehört und meine Gebote, meine Anordnungen, meine Gesetze und meine Weisungen geachtet.“');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 6, 'So ließ sich Isaak in Gerar nieder.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 7, 'Als ihn die Männer des Ortes nach seiner Frau fragten, antwortete er: „Sie ist meine Schwester“, weil er sich fürchtete zu sagen: „Sie ist meine Frau“; (denn er dachte:) „Die Männer des Ortes könnten mich sonst um Rebbekas Schönheit willen töten.“');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 8, 'Als er nun eine Zeit lang dort verweilt hatte, sah Abimelech, der König der Philister, durchs Fenster und wurde überrascht gewahr, dass Isaak mit Rebbeka koste, seiner Frau.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 9, 'Da rief Abimelech nach Isaak und sprach: „Sieh an, bestimmt ist sie deine Frau. Wie konntest du sagen: Sie ist meine Schwester?“Da entgegnete ihm Isaak: „Gewiss, ich habe es gesagt, damit ich nicht ihretwillen sterbe.“');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 10, 'Da sprach Abimelech: „Wie kannst du uns das antun? Wie leicht hätte einer aus dem Volk mit deiner Frau schlafen können und du hättest Schuld auf uns kommen lassen.“');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 11, 'Nun befahl Abimelech dem gesamten Volk, indem er sprach: „Wer diesen Mann oder seine Frau antastet, wird mit dem Tod bestraft.“');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 12, '');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 13, '');
