INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 1, 'Und Jakob hob seine Füße und er ging zur Erde der Söhne des Morgenlandes (Osten).');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 2, 'Und er sah und siehe, [da war] ein Brunnen auf dem Feld und siehe, dort waren drei Herden [von] Kleinvieh, [das] lagerte an ihm, denn aus dem Brunnen tränkte man die Herden. Und der Fels auf der Öffnung des Brunnen war groß.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 3, 'Und sie versammelten dort alle Herden und wälzten den Fels von der Öffnung des Brunnen und sie tränkten das Kleinvieh und sie brachten den Fels zurück auf die Öffnung des Brunnen zu seinem Platz.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 4, 'Und Jakob sprach zu ihnen: „Meine Brüder, woher [seid] ihr?“Und sie sagten: „Wir [sind] aus Haran.“');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 5, 'Und er sprach zu ihnen: „Kennt ihr Laban, den Sohn Nahors?“Und sie sagten: „Wir kenne ihn!“');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 6, 'Und er sprach zu ihnen: „Geht es ihm gut?“Und sie sagten: „Es geht ihm gut! Und siehe, [da] ist Rahel, seine Tochter; sie begleitet das Kleinvieh.“');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 7, '');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 8, '');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 9, '');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 10, 'Und es begab sich, als Jakob Rahel, die Tochter Labans, des Bruders seiner Mutter und das Kleinvieh Labans, des Bruders seiner Mutter sah, [da] kam er hinzu, und Jakob wälzte den Stein von der Öffnung des Brunnens, und tränkte das Kleinvieh Labans, des Bruders seiner Mutter.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 11, '');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 12, '');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 13, 'Und es geschah, als Laban die Nachricht von Jakob, dem Sohn seiner Schwester hörte, [da] lief er hin, um ihn (für ihn) zu treffen und umarmte ihn und küsste ihn und brachte ihn in sein Haus. Und er sagte ihm all diese Worte.');
