INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 22, '');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 23, 'Und er erhob sich in der Nacht, und nahm seine zwei Frauen (Weiber) und seine zwei Sklavinnenund seine ein zehn (elf) Kinder. Und sie gingen durch den Übergang des Jabbok.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 24, 'Und er nahm sie und er führte sie durch das Tal. Und er brachte auch das hinüber, was ihm war.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 25, 'Und Jakob blieb zurück, alleine für sich. Und es rang ein Mann mit ihm bis zum aufgehen der Morgenröte.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 26, 'Und er sah, dass er nicht zu ihm konnte, und er berührte [ihn] an seiner Hüftpfanne. Und die Hüftpfanne Jakobs verrenkte sich in seinem Kampf mit sich.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 27, 'Und er sagte: „Lass mich los, weil die Morgenröte aufgeht.“Und er sagte: „Ich lasse dich nicht los, als wenn du mich segnest.“');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 28, 'Und er sagte zu ihm: „Was ist dein Name?“Und er sagte: „Jakob“');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 29, 'Und er sagte: „Nicht länger soll dein Name Jakob sein (gesagt werden), sondern er sei Israel. Denn du hast gestritten mit Gott und mit Menschen und du hast obsiegt.“');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 30, 'Und Jakob fragte, und er sagte: „Erzähle doch deinen Namen.“Und er sagte: „Warum fragst du {dies} [nach] meinen Namen?“Und er segnete ihn dort.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 31, 'Und Jakob sagte den Namen der Stätte: Penuel. Denn ich habe Gott gesehen, Angesicht zu Angesicht und meine Seele wurde gerettet.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 32, 'Und es ging die Sonne zu ihm auf, als er vorbeizog an Penuel. Und er hinkte an der Hüftpfanne. Deswegen essen die Israeliten nicht die Sehne der Hüfte, die auf der Hüftpfanne ist, bis zu diesem Tag. Denn Jakobs Hüftpfanne berührte sie an der Sehne der Hüfte.');
