INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 18, 'Josef sagte zu ihnen am dritten Tag: Tut dies, damit ihr am Leben bleibt! Ich fürchte JHWH.');
