INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 14, 'Und Israel streckte seine rechte Hand aus und legte sie auf Ephraims Kopf, obwohl (und) dieser der Jüngere (Junge, Jüngste) war; seine linke Hand [legte er] auf Manasses Kopf. Er hatte Verständnis (bewies Verständnis, sollte Verständnis beweisen) an seinen Händen (er überkreuzte seine Hände), obwohl (weil) Manasse der Erstgeborene [war].');
