INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 9, '');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 10, '');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 11, '');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 12, '');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 13, '');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 14, '');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 15, 'Und die Brüder des Josef fürchteten sich, denn ihr Vater war gestorben. Und sie sprachen: „O, wenn Josef uns gram sein wird und er wird gewiss die ganze Bosheit zu uns zurückführen, die wir ihm angetan haben.“');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 16, 'Und sie ließen Josef befehlen: Dein Vater hat vor seinem Tod folgendermaßen befohlen:');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 17, '„So sollt ihr zu Josef sprechen: \'Ach! Hebe doch die Missetat deiner Brüder auf und ihre Verfehlung, denn Bosheit haben sie dir angetan und nun hebe auf die Missetat der Diener Gottes deines Vaters.\'“Und Josef weinte als sie das sagten (durch ihre Worte zu ihm).');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 18, 'Und auch seine Brüder gingen und sie fielen vor sein Angesicht und sie sprachen: „Siehe zu dir, zu den Dienern!“');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 19, 'Und Josef sprach zu ihnen: „Fürchtet euch nicht, denn ich bin unter Gott!');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 20, 'Aber ihr habt die Bosheit auf mich zurückgeführt. Gott wird sie zurückführen zum Guten um zu machen wie es jetzt ist: um das Leben des großen Volks zu retten.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 21, 'Und nun fürchtet euch nicht! Ich werde euch und eure Kinder erhalten.“Und er tröstete sie und redete zu ihrem Herzen.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 22, 'Und Josef lebte in jenem Ägypten und das Haus seines Vaters. Und Josef lebte hundertzehn Jahre.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 23, 'Und Josef sah von (zu) Ephraim drei Söhne; sogar die Söhne Machirs, dem Sohn Manasses: er wurde geboren auf den Knien Josefs.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 24, '');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 25, '');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 26, '');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 1, 'Dies sind die Namen der Söhne Israel (Israeliten), die nach Ägypten gekommen sind, mit Jakob, jeder [mit] seinem Haus, kamen sie:');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 2, 'Ruben, Simeon, Levi und Juda.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 3, 'Issaschar, Sebulon und Benjamin.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 4, 'Dan und Naftali, Gad und Asser.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 5, 'Und alle Seelen aus Jakobs Stamm (Oberschenkel) waren siebzig Seelen; Joseph aber war in Ägypten.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 6, 'Und Joseph starb und all seine Brüder und seine (jene) Generation (Geschlecht).');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 7, 'Und die Söhne Israels (Israeliten) waren fruchtbar und pflanzten sich fort und sie wurden viele und sie wurden überaus (im höchsten Grade) stark (mächtig) und das Land war voll (erfüllt) mit ihnen.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 8, 'Und es stand ein neuer König über Ägypten auf, der Joseph nicht [mehr] kannte.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 9, 'Und er sprach zu seinem Volk: Siehe, das Volk der Söhne Israels (Israeliten) ist zahlreich und mächtiger als wir.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 10, 'Wohlan! Wir wollen klug gegen es vorgehen, damit es nicht groß wird und damit es nicht geschieht, dass sie eine Schlacht ausrufen und damit nicht dem auch noch hinzugefügt wird, dass es uns hasst und uns bekämpft und es aufsteigt von der Erde (sich zum Herren über das Land macht).');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 11, 'Und sie setzten über es Befehlshaber der Frondienste (Fronvögte), um es zu bedrücken mit ihrem Frondienst (Lasttragen). Und es baute Vorratsstädte für den Pharao: Pitom und Ramses.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 12, 'Und wie sie es bedrückten, so wurde es zahlreich und so wurde es stark. Und sie hatten Furcht vor den Söhnen Israels (Israeliten).');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 13, 'Und sie hielten die Söhne Israels zur Arbeit an durch Misshandlung.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 14, 'Und sie verbitterten deren (ihr) Leben durch harte Arbeit im Ton und in den Ziegeln und durch alle Arbeit auf dem Feld. Und ihre ganze Arbeit arbeiteten sie bei ihnen durch Misshandlung.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 15, 'Und der König von Ägypten sagte zu den hebräischen Hebammen, der Name der ersten war Schifra und der Name der zweiten war Pua.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 16, 'und er sprach: Wenn die Hebräerinnen gebären und ihr seht auf den Töpferscheiben dass es ein Sohn ist, tötet ihn; wenn es eine Tochter ist, lasst sie leben.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 17, 'Aber die Hebammen fürchteten JHWH und taten nicht, wie ihnen der König von Ägypten gesagt hatte und ließen die Kinder leben.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 18, 'Da rief der König von Ägypten die Hebammen und sagte zu ihnen: Warum habt ihr diese Sache getan und habt die Kinder leben lassen?');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 19, 'Die Hebammen sagten zu dem Pharao: Weil die Hebräerinnen nicht so sind wie die Ägypterinnen, denn sie sind kräftig und haben schon geboren bevor die Hebamme hineinkommt.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 20, 'Und JHWH tat den Hebammen Gutes und das ganze Volk vermehrte sich und wurde zahlreich.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 21, 'Und es geschah, weil die Hebammen JHWH fürchteten und er schenkte ihnen Nachkommen.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 22, 'Und der Pharao befahl seinem ganzen Volk folgendes: Jeden Sohn, der geboren wird, sollt ihr in den Fluß werfen und alle Töchter sollt ihr leben lassen.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 1, '{Und} Ein Mann aus dem Hause Levi ging und nahm eine Nachfahrin Levis [zur Frau].');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 2, '{Und} Die Frau wurde schwanger und gebar einen Sohn. Als (und) sie sah {ihn}, dass er gut (schön) [war], {und} verbarg sie ihn drei Monate (Monde) [lang].');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 3, 'Als (und) sie ihn nicht länger verbergen konnte; {und} nahm sie für ihn ein Kästchen (Korb) [aus] Schilf und dichtete (bestrich) es mit Erdharz und Pech ab. {und} Sie legte das Kind (den Knaben) hinein und legte [es] in das Schilf am Rande des Nils.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 4, '{Und} Seine Schwester stand in [einiger] Entfernung, um zu erfahren, was mit ihm geschehen (getan) würde.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 5, '{Und} Die Tochter des Pharaos ging hinab, um am Nil (Fluss) zu baden, und ihre [Dienst] mädchen gingen am Rande des Nils spazieren. Als (Und) sie das Kästchen inmitten des Schilfes sah, {und} sandte sie ihre Dienerin (Sklavin) und sie nahmen es.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 6, '{Und} Sie öffnete [es] und sah {ihn} das Kind (den Knaben) - einen Jungen, weinend! -. Da (und) hatte sie Mitleid mit ihm und sagte: Dies ist einer [von] den Knaben (Kindern) der Hebräer!');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 7, 'Und seine Schwester sprach zu der Tochter des Pharaos: Soll ich gehen und für dich eine Frau als Säugamme von den Hebräerinnen rufen, damit sie das Kind (den Knaben) für dich stillt?');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 8, 'Da sagte die Tochter des Pharaos zu ihr: Geh! Also (und) ging das Mädchen und rief die Mutter des Kindes (Knaben).');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 9, 'Und die Tochter des Pharaos sagte zu ihr: Nimm diesen Knaben (dieses Kind) und stille ihn für mich, und ich werde [dir] deinen Lohn geben. Da (und) nahm die Frau den Knaben (das Kind) und stillte ihn.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 10, 'Als (und) das Kind (der Knabe) gewachsen (groß/größer geworden) war (wuchs), {und} brachte sie ihn zur Tochter des Pharaos, und er wurde ihr Sohn. {und} Sie gab ihm den Namen Mose und sagte: Weil ich ihn aus dem Wasser gezogen habe!');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 11, 'Und es geschah in jenen Tagen, als Mose groß geworden war. Da ging er heraus zu seinen Brüdern und sah ihren Frondienst (ihr Lasttragen). Da sah er einen ägyptischen Mann einen hebräischen Mann von seinen Brüdern schlagen.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 12, 'Und er wendete sich hierher und dorthin (so und so) und sah, dass kein [anderer] Mann [da war] (und sah niemanden). Da schlug er den Ägypter und verscharrte ihn im Sand.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 13, 'Und am zweiten Tag ging er wieder heraus. Und siehe, zwei hebräische Männer stritten sich. Da sprach er zu dem, der im Unrecht war: Warum schlägst du deinen Volksgenossen?');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 14, 'Und er antwortete (sprach): Wer hat dich gestellt zum Aufseher und zum Richter (Mann des Aufsehens und Richtens) über uns? Willst du mich töten - sprach er - wie du den Ägypter getötet hast? Und Mose fürchtete sich und sprach: Fürwahr! Die Sache ist bekannt geworden.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 15, 'Und der Pharao hörte von dieser Sache und trachtete danach, Mose zu töten. Da floh Mose vor dem Pharao und blieb (ließ sich nieder) im Lande Midian und setzte sich auf den Brunnen.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 16, 'Und der Priester von Midian hatte sieben Töchter. Und sie kamen und schöpften und füllten die Wassertröge, um das Vieh ihres Vaters zu tränken.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 17, 'Und es kamen die Hirten und vertrieben sie. Da stand Mose auf und half ihnen (rettete sie) und tränkte das Vieh.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 18, 'Und sie kamen zu Re\'uël, ihrem Vater. Und er sprach: Warum habt ihr euch heute [so] beeilt, [zurück] zu kommen?');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 19, 'Da antworteten (sagten) sie: Ein ägyptischer Mann hat uns gerettet vor der Hand (Gewalt) der Hirten. Und auch schöpfte {und} schöpfte er für uns und tränkte das Vieh.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 20, 'Da sprach er zu seinen Töchtern: Und wo ist er? Warum habt ihr den Mann da zurückgelassen? Ruft ihn und er soll mit uns essen!');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 21, 'Und Mose entschloss isch bei dem Mann zu bleiben. Und er gab Zippora, seine Tochter, {dem} Mose {zur Frau}.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 22, 'Und sie gebar einen Sohn. Und er nannte seinen Namen Gerschom, denn er sprach: Ein Fremder bin ich gewesen in einem fremden Land.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 23, 'Und {es geschah} in jenen vielen Tagen (während jener langen Zeit) {und} starb der König von Ägypten. {und} Die Kinder (Söhne) Israels stöhnten wegen der Sklavenarbeit (Knechtschaft, Arbeit), und sie schrien, und ihr Hilferuf erreichte (ging hinauf zu) Gott wegen der Sklavenarbeit (Knechtschaft, Arbeit).');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 24, 'Da (und) hörte Gott ihr Stöhnen (Wehklagen) und Gott erinnerte sich (dachte) an seinen Bund mit Abraham, {mit} Isaak und {mit} Jakob.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 25, 'Und Gott sah die Kinder (Söhne) Israels und Gott wusste (verstand).');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 1, 'Währenddessen (und, als) hütete Mose das Kleinvieh (war Hirte des Kleinviehs) Jitros, seines Schwiegervaters, des Priesters von Midian. Und (einmal, da, als) er trieb das Kleinvieh hinter (auf die Westseite) die Wüste (Wildnis; Weideland) und (da) kam zum Berg Gottes, dem Horeb.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 2, 'Da (und) zeigte sich (erschien) ihm der Engel (Bote) JHWH s in einer Feuerflamme aus der Mitte des Busches. {und} Er sah hin - obwohl der Busch mit (im) Feuer brannte, wurde er nicht aufgezehrt!');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 3, 'Da (und) sagte Mose: „Ich will (muss) doch einmal [von meinem Weg] abweichen und (um) diese außergewöhnliche (großartige) Erscheinung ansehen. Warum verbrennt der Busch nicht?“');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 4, 'Als (und, da) JHWH sah, dass er [von seinem Weg] abwich, um [nach] zusehen, da (und) rief Gott zu ihm aus der Mitte des Busches {und sagte}: „Mose, Mose!“Und [dieser] sagte: „Hier bin ich!“');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 5, '{und} Er sagte: „Komm nicht näher heran (hierher)! Zieh deine Sandalen (Schuhe) von deinen Füßen, denn die Stelle, auf der du stehst, ist heiliger Boden (Erde)!“');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 6, 'Weiter (und) sagte er: „Ich [bin] der Gott deines Vaters, der Gott Abrahams, der Gott Isaaks und der Gott Jakobs.“Da bedeckte (verbarg) Mose sein Gesicht, weil er sich [davor] fürchtete, Gott anzuschauen.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 7, 'Da (und) sagte JHWH: „ [Sei versichert], ich habe das Elend meines Volkes, das in Ägypten [ist], gesehen und sein Schreien wegen (gegen) seiner Unterdrücker gehört. Ja (denn), ich kenne seine Schmerzen.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 8, 'Und ich bin herabgekommen, um es aus der Gewalt (Hand) Ägyptens (der Ägypter) zu erretten und es hinaufzuführen aus jenem Land in ein schönes (gutes) und weites Land, in ein Land, [das von] Milch und Honig fließt, in das Gebiet (Land; Ort) der Kanaaniter, {und} Hetiter, {und} Amoriter, {und} Perisiter, {und} Hiwiter und Jebusiter.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 9, 'Doch (und; weil) jetzt {siehe} ist das Schreien der Kinder (Söhne) Israels zu mir gekommen, und ich habe auch die Unterdrückung gesehen, [mit] der Ägypten sie unterdrückt.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 10, 'Deshalb (und; also) geh nun! Ich will dich zum Pharao senden, so dass du mein Volk, die Kinder (Söhne) Israels, aus Ägypten herausführen wirst.“');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 11, 'Da (und) sagte Mose zu Gott: „Wer [bin] ich, dass ich zum Pharao gehen und die Kinder (Söhne) Israels (Israeliten) aus Ägypten herausführen könnte?“');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 12, 'Da (und) sagte [Gott]: „ {denn} Ich werde bei dir sein (bin bei dir). Und dies [soll] dein Zeichen [sein], dass ich ich dich gesandt habe: Wenn du das Volk aus Ägypten herausgeführt hast, werdet ihr Gott auf diesem Berg dienen.“');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 13, 'Da (und) sagte Mose zu Gott: „Wenn ich zu den Kindern (Söhnen) Israels (Israeliten) komme und zu ihnen sage: Der Gott eurer Vorfahren (Väter) hat mich zu euch geschickt. Dann (und) werden sie zu mir sagen: Was [ist] sein Name? Was sage (antworte) ich [dann] zu ihnen?“');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 14, 'Da (und) sagte Gott zu Mose: „Ich bin, der ich bin. {Und} Er sagte: So sollst (wirst) du zu den Kindern (Söhnen) Israels (Israeliten) sprechen: » »Ich bin« hat mich zu euch gesandt.« “');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 15, 'Und Gott sagte weiter (wieder) zu Mose: „So sollst (wirst) du zu den Kindern (Söhnen) Israels (Israeliten) sprechen: JHWH, der Gott eurer Vorfahren (Väter), der Gott Abrahams, der Gott Isaaks und der Gott Jakobs, hat mich zu euch gesandt. Dies [ist] mein Name für immer (auf ewig), {und} dies [ist] mein Name von Generation (Geschlecht) zu Generation.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 16, 'Geh und versammle die Ältesten Israels und sage zu ihnen: JHWH, der Gott eurer Vorfahren (Väter), ist mir erschienen (hat sich mir gezeigt), der Gott Abrahams, Isaaks und Jakobs und sprach: Ich habe mich eurer und dessen, was euch in Ägypten angetan wird (wurde), [genau] angenommen (beobachtet, mich gekümmert, eingegriffen).');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 17, 'Da (und) sagte (dachte) ich: Ich will (werde) euch aus dem Elend [von] Ägypten hinaufführen in das Land der Kanaaniter, {und} Hetiter, {und} Amoriter, {und} Perisiter, {und} Hiwiter und Jebusiter, ein Land, [das von] Milch und Honig [über] fließt.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 18, 'Wenn (und) sie auf dich (deine Stimme) hören {werden}, dann (und) sollst (wirst) du mit (und) den Ältesten Israels zum König [von] Ägypten gehen und ihr sollt (werdet) zu ihm sagen: JHWH, der Gott der Hebräer, begegnete (traf) uns. Deshalb (und) lass uns (wollen wir) doch jetzt drei Tagesreisen [weit] in die Wüste ziehen und (damit) JHWH, unserem Gott, ein Opfer darbringen.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 19, 'Aber (und) ich weiß, dass der König [von] Ägypten euch nicht zu gehen erlauben wird, und (wenn, auch) nicht mit starker Hand.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 20, 'Deshalb (und) werde ich meine Hand ausstrecken und Ägypten (die Ägypter) mit all meinen Wundern schlagen, die ich in ihrer Mitte tun werde. {und} Danach wird er euch gehen lassen (wegschicken).');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 21, 'Doch (und) ich werde die Gunst (Gnade) [für] dieses Volk in den Augen der Ägypter (Ägyptens) geben und {es wird geschehen} wenn ihr [weg] zieht, werdet ihr nicht [mit] leeren [Händen] [weg] ziehen.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 22, 'Und eine Frau soll (kann; wird) von ihrer Nachbarin und der Besucherin (Fremden) in ihrem Haus Silber- {Gefäße} und Goldgefäße (-schmuck, -gegenstände) und Kleidung (Mäntel) erbitten, [die] ihr dann (und) euren Söhnen und Töchtern gebt. So (und) werdet ihr die Ägypter (Ägypten) ausplündern (berauben).“');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 1, 'Da (und) antwortete Mose {und sagte}: Und (aber) wenn (sicherlich) sie mir nicht vertrauen (glauben), dann (und) werden sie nicht auf mich (meine Stimme) hören, sondern (dann, denn; und) werden (könnten) sagen: JHWH hat sich dir [gar] nicht gezeigt (ist dir nicht erschienen)!');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 2, 'Da (und) sagte JHWH zu ihm: Was [ist] das in deiner Hand? Er sagte: Ein Stab.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 3, 'Da (und) sagte er: Wirf ihn auf den Boden! Also (da; und) warf [Mose] ihn auf den Boden, da (und) wurde [er] zu einer Schlange, und Mose floh davor [zurück].');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 4, 'Doch (da; und) JHWH sagte zu Mose: Strecke deine Hand aus und packe (fasse) sie beim Schwanz! Also (da; und) streckte er seine Hand aus und packte sie daran. Da (und) wurde sie in seiner Hand (Handfläche) [wieder] zu einem Stab.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 5, 'Damit sie [dir] glauben {werden}, dass sich dir JHWH, der Gott ihrer Vorfahren (Väter), der Gott Abrahams, der Gott Isaaks und der Gott Jakobs gezeigt hat (dir erschienen ist).');
