INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 25, '');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 26, '');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 27, '');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 28, '');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 29, 'Und JHWH sprach zu Mose {und sagte}: „Ich [bin] JHWH! Sage [dem] Pharao, dem König von Ägypten, alles, was ich zu dir sage!“');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 30, '');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 1, 'Und JHWH sprach zu Mose: Sieh! Ich habe dich für den Pharao zum (zu) Gott gemacht. Und Aaron, dein Bruder, wird dein Prophet sein.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 2, 'Du erzählst (sagst) [ihm] alles, was ich dir befehle und Aaron, dein Bruder, sagt [es] dem Pharao und dann wird er die Söhne Israels (Israeliten) ziehen lassen aus seinem Land.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 3, 'Und ich werde das Herz des Pharaos verhärten und zahlreich sein lassen meine Zeichen und meine Wunder im Land Ägypten.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 4, 'Aber er wird nicht auf euch hören, der Pharao, und ich werde meine Hand auf Ägypten legen (geben). Dann führe ich meine Heere heraus, mein Volk, die Söhne Israels (Israeliten) aus dem Land Ägypten durch große Strafgerichte.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 5, 'Dann wird Ägypten erkennen, dass ich JHWH bin durch mein Ausstrecken meiner Hand über Ägypten. Und ich werde herausführen die Söhne Israels (Israeliten) aus ihrer Mitte.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 6, 'Und Mose und Aaron taten, wie JHWH ihnen befohlen hatte - so taten sie es.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 7, 'Und Mose war 80 Jahre alt und Aaron war 83 Jahre alt, als sie redeten zu dem Pharao.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 8, '');
