INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 21, 'Du aber suche dir aus dem ganzen Volk tüchtige, JHWH -fürchtige Männer aus, zuverlässige Männer, die Bestechungsgeld hassen, und setze sie über sie. Oberste von Tausend, Oberste von Hundert, Oberste von Fünfzig, Oberste von Zehn.');
