INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 26, '');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 1, 'Und dies sind die Gesetze (Rechtsbestimmungen), die du ihnen vorlegen (vor ihr Angesicht legen) sollst.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 2, '');
