INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 12, 'Wer einen Mann schlägt und er stirbt, der muss getötet werden.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 13, 'Und wenn gilt, dass er [ihm] nicht nachgestellt (ihn nicht belauert) hat, sondern Gott hat es seiner Hand widerfahren lassen, und ich setze dir einen Ort (Stelle) wohin er fliehen kann (soll).');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 14, '');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 15, '');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 16, '');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 17, '');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 18, '');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 19, '');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 20, 'Und wenn ein Mann schlägt seinen Slaven oder Sklavin (Magd) mit dem Stab (Stock) und er stirbt unter seiner Hand, muss er gerächt werden');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 21, 'Wenn er einen Tag oder zwei Tage steht (überlebt), wird er nicht gerächt werden (verfällt er nicht der Rache), denn er (es) ist sein Geld (Silber).');
