INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 1, 'Und JHWH sprach zu Mose: „Geh, brich auf von hier, du und das Volk, das du aus Ägypten herausgeführt hast, in das Land, das ich Abraham, Isaak und Jakob zugeschworen habe {und sagte}: Deinen Nachkommen werde ich es geben.“');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 2, '');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 3, '');
