INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 13, '');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 14, '');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 15, '');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 16, '');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 17, 'Da sprach JHWH zu Mose: Auch dieses Wort, das (diese Sache, die) du gesagt hast, werde ich tun. Denn du hast Gunst (Gnade, Gefallen) gefunden in meinen Augen und ich kenne dich (habe dich erkannt) mit Namen.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 18, 'Und er sprach: Lass mich doch sehen deinen Herrlichkeit (Ehrenglanz, Machtfülle).');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 19, 'Und er sprach: Ich, ich werde vorübergehen lassen all mein Gutes (meine Güte, meine Güter) vor deinem Gesicht, und ich werde rufen den Namen JHWH s vor deinem Angesicht. Und ich werde gnädig sein, wem ich gnädig sein werde, und ich werde mich erbarmen, wessen ich mich erbarmen werde.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 20, 'Und er sprach: Nicht wirst du vermögen zu sehen mein Angesicht. Denn kein Mensch wird mich sehen und leben (am Leben bleiben).');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 21, 'Und JHWH sprach: Da [ist] (Siehe,) ein Ort bei mir. Du sollst (wirst) dich stellen auf (neben) den Felsen.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 22, '{Es wird sein,} Wenn vorbeigeht meine Herrlichkeit, werde ich dich setzen (stellen) in die Kluft (Spalte) des Felsens, und ich werde meine Hand über dich decken, bis ich vorüber gegangen bin.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 23, 'Und ich werde wegnehmen meine Hand, und du wirst mich sehen von hinten, aber mein Gesicht wird nicht sichtbar sein (erscheinen, gesehen werden).');
