INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 1, 'Und JHWH sprach zu Mose {und sagte}:');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 2, 'Sprich zu den Söhnen (Kindern) Israels und sage zu ihnen: Ich [bin] JHWH, (Ich, JHWH, [bin]) euer Gott!');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 3, 'Ihr sollt nicht so handeln (handelt nicht) wie {die Praktiken (die Taten) } [die Bewohner] des Landes Ägypten, in dem ihr lebtet, und ihr sollt nicht so handeln (handelt nicht) wie {die Praktiken (die Taten) } [die Bewohner] des Landes Kanaan, in das ich euch [bald] führe (bringe), und ihr sollt nicht nach ihren Bräuchen (Vorschriften) leben (lebt nicht)!');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 4, '\'\'Meine\'\' Verordnungen sollt (werdet; tut) ihr tun (handeln) und \'\'meine\'\' Vorschriften einhalten (befolgen; haltet ein), indem ihr nach ihnen lebt! Ich [bin] JHWH, (Ich, JHWH, [bin]) euer Gott.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 5, 'Und ihr sollt meine Vorschriften und Verordnungen einhalten (befolgen; haltet ein), denn (von denen gilt:) der Mensch, [der] sie tut (tun wird), {und} wird durch sie (nach/in ihnen) leben. Ich [bin] JHWH.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 6, '');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 7, '');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 8, '');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 9, '');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 10, '');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 11, '');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 12, '');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 13, '');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 14, '');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 15, '');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 16, '');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 17, '');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 18, '');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 19, '');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 20, '');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 21, '');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 22, '');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 23, '');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 24, 'Verunreinigt (Ihr sollt) euch nicht mit all diesen [Praktiken], denn durch all diese [Praktiken] wurden die (heidnischen) Völker unrein,, die ich vor euch vertreibe,');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 25, 'und [dadurch] war (wurde) das Land unrein, sodass (und) ich seine Strafe über es brachte (Schuld bestrafte) und das Land seine Bewohner auswürgte (erbrach).');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 26, 'Darum (doch; und) sollt \'\'ihr\'\' meine Vorschriften und Verordnungen einhalten und keine von diesen Abscheulichkeiten (Gräueln) begehen, [weder] der Einheimische noch (und) der Ausländer, [der] als Fremder unter euch lebt!');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 27, 'Denn all diese Abscheulichkeiten (Gräuel) begingen die Männer des Landes, die vor euch [dort waren], und [dadurch] war (wurde) das Land unrein.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 28, '[Ihr sollt sie einhalten], damit euch das Land nicht auswürgt (erbricht), wenn (weil) ihr es verunreinigt, genau wie es das Volk auswürgte (erbrach), das vor euch [dort war].');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 29, 'Denn jeder, der irgendeine von diesen Abscheulichkeiten (Gräueln) begeht, und die Personen (Seelen), die [sie] begehen, werden (sollen) aus dem Inneren ihres Volkes abgeschnitten werden.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 30, 'Darum (doch; und) sollt ihr (haltet) meine Anweisung (Bedingung) einhalten (erfüllen), niemals [irgendeinen] von ihren abscheulichen Bräuchen (Vorschriften) zu übernehmen (tun, verüben), denen sie vor euren Augen (vor eurer Ankunft; vor euch) nachgegangen sind (verübt/getan haben), und euch nicht an ihnen (wie sie) verunreinigen. Ich [bin] JHWH, (Ich, JHWH, [bin]) euer Gott!');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 1, 'Und JHWH sprach zu Mose {und sagte}:');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 2, 'Sprich zu der ganzen Gemeinde (Schar) der Söhne Israels und sage ihnen: Seid heilig, denn ich bin heilig, JHWH, euer Gott');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 3, 'Ihr habt jeder eine Mutter und einen Vater, ihr sollt sie fürchten und meine Sabatte sollt ihr halten. Ich bin JHWH, euer Gott.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 4, 'Ihr sollt euch nicht wenden zu Fremdgöttern (Götzen) und metallgegossene Göttern sollt ihr euch nicht machen. Ich bin JHWH, euer Gott.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 5, 'Und wenn ihr opfert (schlachtet zum Opfer) für JHWH, opfert (schlachtet zum Opfer) zu seinem Gefallen.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 6, 'An dem Tag des Opfers, esst am folgenden Tag, das übrige am dritten Tag soll im Feuer verbrannt werden');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 7, '');
