INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 17, 'Hasse deinen Bruder nicht in deinem Herzen, weise deinen Volksgenossen zurecht, und trage nicht Sünde wegen ihm.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 18, 'Räche dich nicht (Nehme keine Rache) und grolle (bewahre deinen Zorn) nicht gegen die Söhne deines Volkes (Stammes) und du sollst lieben deinen Nächsten (Nachbarn) wie dich selbst. Ich bin JHWH.');
