INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 1, 'Und JHWH sprach zu Mose in der Wüste Sinai im Zelt der Begegnung am ersten [Tag] des zweiten Monats im zweiten Jahr nach dem Auszug aus dem Land Ägypten {und sagte}:');
