INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 14, 'Und Mose sandte Boten aus Kadesch zum König von Edom: So sprach dein Bruder Israel: Du hast die ganze Mühsal erkannt, die uns getroffen hat.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 15, 'Und unsere Väter stiegen nach Ägypten herab und wir wohnten lange Zeit (viele Tage) in Ägypten. Und die Ägypter behandelten uns und unsere Väter schlecht.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 16, 'Und wir flehten um Hilfe zu JHWH und er erhörte unseren Ruf und er sandte einen Boten und er führte uns aus Ägypten heraus und siehe, wir sind in Kadesch, einer Stadt an deiner äußersten Grenze.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 17, 'Lass uns doch dein Land durchqueren! Wir werden keinesfalls aufs Feld gehen und nicht auf einen Weinberg und nicht das Wasser der Brunnen trinken. Wir werden [nur] auf dem Weg des Königs gehen [und] keinesfalls nach rechts und nach links abweichen, bis wir über deine Grenzen gegangen sind!');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 18, 'Aber Edom sprach zu ihm: Du wirst bei mir keinesfalls hindurch ziehen, sonst (damit nicht) werde ich mit dem Schwert dir entgegen ziehen!');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 19, 'Und die Söhne Israels sprachen zu ihm: Wir werden [nur] auf den Hauptstraßen herabziehen und wenn ich und mein Besitz [von] deinen Gewässern trinken, zahle ich ihren Preis (gebe ich den Kaufpreis) [dafür] – es handelt sich nur darum, dass ich [mit] meinen Füßen (zu Fuß) [dein Land] überqueren will (werde).');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 20, 'Er aber sprach: Du sollst keinesfalls hindurch ziehen! Und Edom zog mit zahlreichem Volk [zu] ihm hinaus und mit starker Hand.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 21, 'Und Edom weigerte sich Israel durch sein Gebiet ziehen zu lassen; und Israel bog oberhalb seiner ab.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 22, '');
