INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 2, '');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 3, '');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 4, 'Und sie brachen auf vom Berg Hor, [auf] dem Weg [zum] Schilfmeer um das Land Edom zu umgehen. Und der Atem des Volkes war kurz auf dem Weg.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 5, 'Und das Volk sprach mit Gott und mit Mose: Warum habt ihr uns von Ägypten hinaufsteigen lassen um in der Wüste zu sterben? Denn es gibt kein Brot und es gibt kein Wasser und unser Leben ist [zu] Ende ohne (mit geringem) Brot!');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 6, 'Und JHWH schickte brennende Schlangen ins Volk und sie bissen das Volk und viele [des] Volkes starben aus Israel.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 7, 'Und das Volk kam zu Mose und sie sprachen: Wir haben gesündigt, denn wir redeten gegen (mit) JHWH und gegen (mit) dich! Wir haben zu JHWH gebetet und er hat uns mit Schlangen gezüchtigt! Und Mose betete für das Volk.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 8, 'Und JHWH sprach zu Mose: Mache für dich eine Schlange und setzte sie auf eine hohe Stange! Und es wird geschehen, jeder, der gebissen wird und sieht sie {und} wird leben!');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 9, 'Und Mose bereitete die eherne Schlange und setzte sie auf die hohe Stange und es geschah, wenn die Schlange einen Mann biss und er blickte zur ehernen Schlange und er lebte.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 10, '');
