INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 33, '');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 6, 1, 'Und das [sind] das Gebot, die Gesetze und die Rechtsvorschriften, die JHWH, euer Gott [mir] aufgetragen hat euch zu lehren, damit ihr [danach] handelt (tut) in dem Land, [in] das ihr zieht, um es in Besitz zu nehmen,');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 6, 2, 'damit du JHWH, deinen Gott, fürchtest, indem (um) [du] alle seine Gesetze und Gebote befolgst, die ich die ich dir [heute] auftrage – du, {und} dein Sohn und dein Enkel (Sohnessohn) [an] allen Tagen deines Lebens, und damit deine Tage lange währen (du lange lebst).');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 6, 3, 'Nun (und) höre, Israel, und achte darauf, [danach] zu handeln (tun), damit es dir gut geht und damit du sehr zahlreich (groß) {werden} wirst, wie JHWH, der Gott deiner Vorfahren (Väter), es dir zugesichert (gesagt) hat, [in] einem Land, [das von] Milch und Honig [über] fließt.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 6, 4, 'Höre, Israel, JHWH [ist] unser Gott, JHWH [ist] eins (einzig, einer).');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 6, 5, 'Darum (und) sollst du (liebe) JHWH, deinen Gott mit deinem ganzen Herzen und deinem ganzen Sein (Leben, Seele) und deiner ganzen Kraft lieben.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 6, 6, 'Und (dann) diese Worte, die ich dir heute auftrage, sollen (werden) in deinem Herzen sein.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 6, 7, '{und} Du sollst sie deinen Kindern (Söhnen) einprägen (einschärfen, wiederholen) (präge ein) und über sie sprechen, wenn du in deinem Haus sitzt und wenn du auf der Straße gehst, {und} wenn du liegst und wenn du aufstehst,');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 6, 8, 'und sie als Zeichen auf deine Hand binden (binde) und sie werden als Bänder (Erinnerungszeichen, Stirnbänder) zwischen deinen Augen sein,');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 6, 9, 'und du sollst (schreibe) sie auf die Türpfosten deines Hauses und auf deine Tore (Eingänge) schreiben.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 6, 10, '');
