INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 13, 4, 'Hört nicht auf die Worte dieses Propheten oder auf diesen Träumer von Träumen, denn JHWH, euer Gott, prüft euch um zu erkennen, ob ihr JHWH, euren Gott, mit eurem ganzen Herzen und eurer ganzen Seele liebt.');
