INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 22, 'Verzehnte (Du sollst/musst verzehnten) allen Ertrag deiner Aussaat, der aus dem Feld hervorgeht, Jahr [um] Jahr!');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 23, 'Verzehre (Du sollst/musst verzehren) ihn im Angesicht (in der Gegenwart) JHWH s, deines Gottes, an dem Ort, den er erwählen wird, um seinen Namen dort wohnen zu lassen: Den Zehnten deines Getreides, deines Weins und deines Öls sowie die Erstgeburt deiner Rinder und deines Kleinviehs, damit du lernst, JHWH, deinen Gott, alle Tage (immer) zu fürchten.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 24, '{und} Wenn der Weg von dir aus zu groß ist, wenn du ihn nicht tragen kannst, wenn der Ort von dir zu fern ist, den JHWH erwählen wird, um seinen Namen dort niederzulegen, wenn JHWH, dein Gott, dich segnen wird (segnet, segnen soll):');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 25, 'Gib (du sollst/musst geben) ihn hin für Silber und halte das Silber fest in deiner Hand und gehe zu dem Ort, den JHWH erwählen wird.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 26, 'Gib (du darfst/sollst/musst geben) das Silber aus für alles, was dein Herz (Seele, Verlangen, Kehle) begehrt, für Rinder und Kleinvieh, für Wein und Bier und für alles, nach dem dein Herz dich gelüstet, und verzehre es dort im Angesicht (in der Gegenwart) JHWH s, deines Gottes und freue dich (du sollst/musst dich freuen), du und dein Haus (Familie, Haushalt)!');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 27, 'Und den Leviten, der in deinen Toren [wohnt]: Vergiss (du darfst vergessen) ihn nicht, denn er hat nicht Erbanteil und Besitz wie du!');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 28, 'Nach jedem dritten Jahr sollst (schaffe) du den ganzen Zehnten deines Ertrags in diesem Jahr bei Seite schaffen und in deiner Stadt lassen,');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 29, 'und es sollen kommen der Levit, denn er hat nicht Erbanteil und Besitz wie du, {und} der Fremde, {und} der Waise und die Witwe, die in deinen Toren [wohnen], und ihn verzehren und satt sein, damit JHWH, dein Gott, dich segnet bei allem Werk deiner Hand, das du verrichtest.');
