INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 28, 'Was verborgen ist (das Verborgene), ist (gehört) JHWH unserem Gott und was offenbart ist, ist (gehört) uns und unseren Kindern (Söhnen/Nachkommen) für immer in Ewigkeit (in Zukunft), zu tun alle Worte (Dinge) dieser Weisung (Gesetz/Anweisung).');
