INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 35, 'Mein ist Rache und Vergeltung, zu der Zeit, ihr Fuß wird wanken. Denn nahe ist der Tag ihres Verderbens und schnell kommt das Vorbereitete zu ihnen.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 36, '');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 37, '');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 38, '');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 39, 'Nun seht, dass ich, ich es [bin], und kein Gott mit (neben) mir! Ich, ich werde töten und am Leben erhalten (lebendig machen), ich habe zerschmettert und ich, ich werde heilen. Und [es ist] keiner, der von meiner Hand entreißt (rettet, wegnimmt, entzieht).');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 40, '');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 41, '');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 42, '');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 43, 'Ihr Nationen preist sein Volk. Denn Blut seiner Sklaven rächt er und Rache bringt er zu den Feinden und den Ackerboden seines Volkes entsühnt er.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 44, '');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 45, '');
