INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 47, '');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 48, 'Und JHWH sprach zu Mose an eben diesem Tag {und sagte}:');
