INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 1, '');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 2, '');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 3, '');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 4, '');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 5, '');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 6, '');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 7, '');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 8, 'Tatsächlich gingen die Bäume, um einen König über sich zu salben; und dann sprachen sie zu dem Ölbaum: Herrsche du doch als König über uns!');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 9, 'Und dann sprach der Ölbaum zu ihnen: Soll ich [etwa] auf mein Fett verzichten, das in mir ist [und] Götter und Menschen ehrt, [damit] ich gehe, um über die Bäume zu herrschen?');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 10, 'Und dann sprachen die Bäume zu dem Feigenbaum: Komm, herrsche du als König über uns!');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 11, 'Und dann sprach der Feigenbaum zu ihnen: Soll ich [etwa] auf meine Süße und meinen guten Ertrag verzichten, [damit] ich gehe, um über die Bäume zu herrschen?');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 12, 'Und dann sprachen die Bäume zu dem Weinstock: Komm, herrsche du als König über uns!');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 13, 'Und dann sprach der Weinstock zu ihnen: Soll ich [etwa] auf meinen Wein verzichten, [der] Götter und Menschen erfreut, [damit] ich gehe, um über die Bäume zu herrschen?');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 14, 'Und dann sprachen alle Bäume zu dem Dornbusch: Komm, herrsche du als König über uns!');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 15, 'Und dann sprach der Dornbusch zu den Bäumen: Wenn ihr mich wirklich zum König über euch salbt, kommt ihr [und] beugt euch in meinen Schatten; und wenn [das] nicht [so] ist, wird Feuer aus dem Dornbusch hervorbrechen und die Zedern des Libanons verzehren.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 16, '');
