INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 1, 'Hanna betete {und sprach}: Mein Herz freut sich (jauchzt, frohlockt, triumphiert) über JHWH, erhoben (siegreich) ist mein Horn wegen JHWH. Weit offen ist mein Mund gegen meine Gegner (Feinde), denn ich habe mich über deine Hilfe gefreut (= deiner Hilfe erfreut).');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 2, 'Keiner [ist] heilig wie JHWH, denn außer dir [ist] keiner, und [es gibt] keinen Fels wie unseren Gott.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 3, '');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 4, '');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 5, '');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 6, 'JHWH tötet (lässt sterben) und erhält am Leben (macht lebendig), er lässt herabsteigen (bringt hinab) in den Scheol und er lässt hinaufsteigen (bringt hinauf).');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 7, 'JHWH macht arm (lässt verarmen) und macht reich, er erniedrigt (demütigt) und erhöht.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 8, 'Er stellt auf (richtet auf) aus dem Staub den Hilflosen, aus der Abfallgrube (dem Aschehaufen) erhöht er den Armen, um [ihn] unter Fürsten zu setzen, und den Thron (Sessel) der Ehre (des Ruhms, des Reichtums) teilt er ihnen als Erbschaft aus. Denn für JHWH [sind] (JHWH gehören) die Säulen der Erde, und auf sie hat er gesetzt das Festland.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 9, 'Die Füße seiner Frommen wird er bewachen (behüten) und die Frevler (Gottlosen) werden umkommen (verstummen) in der Finsternis. Denn nicht aus [eigener] Kraft wird ein Mann (Mensch) stark.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 10, '');
