INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 10, 1, 'Und Samuel ergriff den Krug mit Öl (Ölkrug) und er goss [es] auf (über) sein Haupt (Kopf) und er küsste ihn und sprach: [Ist es] nicht [so], dass JHWH dich über seinm Erbe (Besitz) gesalbt hat zum König?');
