INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 31, '');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 32, 'Und der König David sagte: Ruft Zadok, den Priester, zu mir und Natan, den Propheten und Benaja, den Sohn Jojadas. Und sie kamen vor den König.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 33, 'Und der König sprach zu ihnen: Nehmt die Knechte eures Herrn mit euch und lasst meinen Sohn Salomo auf das Maultier setzen, das mir gehört und führt ihn nach Gichon.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 34, 'Und dort salbten der Priester Zadok und der Prophet Natan zum König über Israel und blast in die Schofar und ruft: Es lebe der König Salomo!');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 35, 'Und zieht hinter ihm herauf und er soll kommen und auf meinem Thron sitzen und er soll an meiner Stelle König werden, ihn habe ich bestimmt Herrscher zu sein über Israel und Juda.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 36, 'Und Benaja, der Sohn Jojadas, antwortete dem König: So sei es! So soll es auch Jahwe, der Gott meines Herrn, des König, sagen.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 37, 'Wie Jahwe mit meinem Herrn dem König war, so soll er auch mit Salomo sein! Und er soll seinen Thron noch größer machen als den Thron meines Herrn, des Königs David.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 38, 'Und der Priester Zadok und der Prophet Natan und Benaja, der Sohn Jojadas, und die Kreter und Pleter hinab und sie setzen Salomo auf das Maultier des Königs David und sie führten ihn nach Gichon.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 39, 'Und der Priester Zadok nahm das Horn mit Öl aus dem Zelt und er salbte Salomo und sie bliesen in die Schofar und das ganze Volk rief: Es lebe der König Salomo!');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 40, 'Und das ganze Volk zog hinter ihm herauf und das Volk flötete in Flöten und freute sich in großem Jubel und die Erde erbebte unter ihrem Stimmen.');
