INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 15, '');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 16, 'Damals kamen zwei Frauen, die Huren waren, zu dem König und standen (stellten sich) vor ihm (sein Angesicht).');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 17, 'Dann (und) sprach die eine Frau: „Ach, mein Herr! Während (und) ich und diese Frau in einem Haus wohnten (wohnen), da (und) gebar ich bei ihr im Haus (während sie im Haus [war] / [ist]).');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 18, 'Und es war am dritten Tag nach meinem Gebären, [da] gebar auch diese Frau; und wir waren beieinander und es war kein Fremder da, nur wir beide waren in dem Haus.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 19, 'Und dann starb der Sohn dieser Frau in der Nacht, weil sie sich auf ihn gelegt hatte.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 20, 'Und sie stand in der Mitte der Nacht auf und nahm meinen Sohn weg von meiner Seite, während deine Sklavin schlief, und legte ihn an ihren Busen – und ihren Sohn, den Toten, legte sie an meinen Busen.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 21, 'Und dann stand ich am Morgen auf um meinen Sohn zu säugen und siehe, er war tot. Und dann sah ich ihn am Morgen genau an und siehe, er war nicht mein Sohn, den ich geboren hatte.“');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 22, 'Und dann sprach die andere Frau: „Nein, vielmehr ist mein Sohn der Lebendige und deiner der Tote!“Und dann sagte die andere Frau: „Nein, vielmehr ist dein Sohn der Tote und mein Sohn der Lebendige!“Und so sprachen sie vor dem Angesicht des Königs.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 23, 'Und dann sprach der König: „Diese sagt: \'Mein Sohn ist der Lebendige und dein Sohn der Tote\', und die andere sagt: \'Nein, vielmehr ist dein Sohn der Tote und mein Sohn der Lebendige.\'“');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 24, 'Und dann sprach der König: „Holt mir ein Schwert!“Und sie brachten das Schwert vor das Angesicht des Königs.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 25, 'Und dann sprach der König: „Zerschneidet den Knaben, den Lebendigen, in zwei Teile und gebt die Hälfte der einen und die Hälfte der anderen.“');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 26, 'Und dann sprach die Frau, deren Sohn der Lebendige war, zu dem König – denn sie war erregt [vor] Mitleid und Liebe wegen ihres Sohnes – und sie sagte: „Fürwahr, mein Herr, gebt den Knaben, den Lebendigen, zur ihr, aber tötet ihn keinesfalls.“Und die andere sprach: „Auf keinen Fall, weder zu mir, noch zu ihr, [sondern] zerteilt den Lebendigen in zwei Teile!“');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 27, 'Und dann antwortete der König und sprach: „Gebt ihr den Knaben, den Lebendigen, und tötet ihn keinesfalls – sie ist seine Mutter!“');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 28, 'Und dann hörte ganz Israel das Urteil, das der König richtete. Und sie fürchteten sich vor dem König, denn sie sahen, dass die Weisheit Gottes in ihm (seinem Innersten) war Recht zu schaffen.');
