INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 1, 'Und eine Frau unter den Frauen der Prophetensöhne schrie zu Elischa folgendes: „Dein Knecht, mein Mann, ist tot, aber du weißt, dass dein Knecht JHWH fürchtete. [Nun] aber ist der Gläubiger gekommen um meine beiden Söhne als Knechte mitzunehmen!“');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 2, 'Da sagte Elischa zu ihr: „Was soll ich für dich tun? Sag mir, was hast du im Haus?“Und sie sagte: „Nichts hat deine Magd im ganzen Haus außer einen Krug mit Öl.“');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 3, 'Er sagte: „Geh, bitte auf der Gasse für dich um Gefäße von all deinen Nachbarinnen, leere Gefäße, und nimm davon nicht wenige.“');
