INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 22, 1, 'Josia war bei seiner Königwerdung acht Jahre alt und herrschte 31 Jahre als König in Jerusalem. Und der Name seiner Mutter war Jedidah, Tochter des Adija von Bozkath.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 22, 2, 'Und er tat, was recht war in den Augen JHWH \'s und ging den ganzen Weg Davids, seines Vaters, und wich nicht ab zur Rechten oder zur Linken.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 22, 3, 'Und es war im 18. Jahr König Josias, da sandte der König den Schafan, Sohn des Azalijahu, Sohn des Meschulam, den Schreiber, zum Haus JHWH \'s:');
