INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 1, 'Adam, Set, Enosch.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 2, 'Kenan, Mahalalel, Jered.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 3, 'Henoch, Metuschelach, Lamech.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 4, 'Noach, Sem, Ham und Jafet.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 5, '[Die] Söhne Jafets [sind] Gomer und Magog und Madai und Jawan und Tubal und Meschech und Tiras.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 6, 'Und [die] Söhne Gomers [sind] Aschkenas und Difat und Togarma.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 7, 'Und [die] Söhne Jawans [sind] Elischa und Tarschisch, [die] Kittäer und [die] Rodaniter.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 8, '[Die] Söhne Hams [sind] Kusch und Mizrajim, Put und Kanaan.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 9, 'Und [die] Söhne Kuschs [sind] Seba und Hawila und Sabta und Ragma und Sabtecha. Und [die] Söhne Ragmas [sind] Saba und Dedan.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 10, 'Und Kusch hatte (hat) gezeugt den Nimrod, der [dann] angefangen hat, zu werden ein Machthaber auf [der] Erde.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 11, 'Und Mizrajim hat gezeugt die Luditer und die Anamiter und die Lehabiter und die Naftuhiter.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 12, 'Und die Patrositer und die Kasluhiter, dass ausgegangen sind von dort [die] Philister, und die Kaftoriter.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 13, 'Und Kanaan hat gezeugt den Sidon, seinen Erstgeborenen [Sohn], und den Het.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 14, 'Und den Jebusiter und den Amoriter und den Girgaschiter.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 15, 'Und den Hiwiter und den Arkiter und den Siniter.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 16, 'Und den Arwaditer und den Zemariter und den Hamatiter.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 17, '[Die] Söhne (Nachkommen) Sems [sind] Elam und Assur und Arpachschad und Lud und Aram und Uz und Hul und Geter und Meschech.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 18, 'Und Arpachschad hatte (hat) gezeugt den Schelach und Schelach hat gezeugt [dann] den Eber.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 19, 'Und für Eber sind geboren worden zwei Söhne, [der] Name des einen [ist] Peleg, entsprechend (denn/weil) in seinen Tagen es war zerteilt worden die Erde, und [der] Name seines Bruders [ist] Joktan.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 20, 'Und Joktan hat gezeugt den Almodad und den Schelef und den Hazarmawet und den Jerach.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 21, 'Und den Hadoram und den Usal und den Dikla.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 22, 'Und den Obal und den Abimaël und den Saba.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 23, 'Und den Ofir und den Hawila und den Jobab. Alle diese [sind] Söhne Joktans.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 24, 'Sem, Arpachschad, Schelach.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 25, 'Eber, Peleg, Regu.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 26, 'Serug, Nahor, Terach.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 27, 'Abram, der [ist] Abraham.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 28, '[Die] Söhne Abrahams [sind] Isaak und Ismaël.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 29, 'Diese [sind] ihre Genealogien: der Erstgeborene [Sohn] Ismaëls [ist] Nebajot, und [dann] Kedar und Adbeel und Mibsam.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 30, 'Mischma und Duma, Massa, Hadad und Tema.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 31, 'Jetur, Nafisch und Kedma; diese, sie [sind die] Söhne Ismaëls.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 32, 'Und [die] Söhne Keturas, der Nebenfrau Abrahams: sie hat geboren den Simran und Jokschan und Medan und Midian und Jischbak und Schuach. Und [die] Söhne Jokschans [sind] Saba und Dedan.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 33, 'Und [die] Söhne Midians [sind] Efa und Efer und Henoch und Abida und Eldaga. Alle diese [sind die] Söhne Keturas.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 34, 'Und es zeugte Abraham den Isaak. [Die] Söhne Isaaks [sind] Esau und Israel.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 35, '[Die] Söhne Esaus [sind] Elifas, Reguël und Jëusch und Jalam und Korach.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 36, '[Die] Söhne Elifas\' [sind] Teman und Omar, Zefo und Gatam, Kenas und Timna und Amalek.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 37, '[Die] Söhne Reguëls [sind] Nahat, Serach, Schamma und Misa.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 38, 'Und [die] Söhne Seïrs [sind] Lotan und Schobal und Zibon und Ana und Dischon und Ezer und Dischan.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 39, 'Und [die] Söhne Lotans [sind] Hori und Hemam, und [die] Schwester Lotans [ist] Timna.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 40, '[Die] Söhne Schobals [sind] Alwan und Manahat und Ebal, Schefi und Onam. Und [die] Söhne Zibons [sind] Aja und Ana.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 41, '[Die/der?] Nachkommen? Anas [sind/ist?] Dischon, und [die] Söhne Dischons [sind] Hemdan und Eschban und Jitran und Keran.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 42, '[Die] Söhne Ezers [sind] Bilhan und Saawan [und] Akan. [Die] Söhne Dischans: Uz und Aran.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 43, 'Und diese [sind] die Könige, die regiert hatten (haben) im Lande Edom, bevor ein König regiert hat von [den] Söhnen (Nachkommen) Israels: Bela, [der] Sohn Beors, und [der] Name seiner Stadt [ist] Dinhaba.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 44, 'Und es starb Bela, und es regierte nach ihm Jobab, der Sohn Serachs aus Bozra.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 45, 'Und es starb Jobab, und es regierte nach ihm Huscham, aus [dem] Land der Temaniter.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 46, 'Und es starb Huscham, und es regierte nach ihm Hadad, [der] Sohn Bedads, er vernichtete Midian im Gebiet Moabs, und [der] Name seiner Stadt [ist] Awit.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 47, 'Und es starb Hadad, und es regierte nach ihm Samla aus Masreka.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 48, 'Und es starb Samla, und es regierte nach ihm Schaul aus Rehobot [an] dem Strom.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 49, 'Und es starb Saul, und es regierte nach ihm Baal-Hanan, [der] Sohn Achbors.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 50, 'Und es starb Baal-Hanan, und es regierte nach ihm Hadad, und [der] Name seiner Stadt [ist] Pagu, und [der] Name seiner Frau [ist] Mehetabel, [die/eine] Tochter Matreds, [der] Tochter Me-Sahabs.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 51, 'Und es starb Hadad. Und es waren [dann die] Häuptlinge Edoms: [Der] Häuptling Timna, [der] Häuptling Alwa, [der] Häuptling Jetet.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 52, '[Der] Häuptling Oholibama, [der] Häuptling Ela, [der] Häuptling Pinon.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 53, '[Der] Häuptling Kenas, [der] Häuptling Teman, [der] Häuptling Mibzar.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 54, '[Der] Häuptling Magdiël, [der] Häuptling Iram. Diese [sind die] Häuptlinge Edoms.');
