INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 1, 'Und {ein} Satan trat hin (stellte sich, trat auf) gegen Israel und er verführte (reizte, verlockte, verleitete) David, Israel zu zählen.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 2, 'Und David sprach zu Joab und zu den Mächtigen (Obersten, Fürsten) des Volks: Geht, zählt Israel, von Beerscheba {und} bis Dan, und bringt (lasst kommen, tragt vor) mir, dass ich kenne (weiß) ihre Zahl (Aufzählung, Liste).');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 3, '');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 4, '');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 5, '');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 6, '');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 7, 'Und es war böse (schlecht) in den Augen Gottes diese Sache, und er schlug (schädigte, verheerte) Israel.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 8, 'Und David sprach zu Gott: Ich habe sehr gesündigt (habe mich sehr verfehlt), dass (indem) ich diese Sache getan habe! Und nun, nimm doch weg die Sünde (Schuld) deines Knechtes (Dieners, Sklaven), denn ich habe sehr töricht gehandelt (ich habe mich sehr versündigt)!');
