INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 3, 1, 'Danach öffnete Hiob seinen Mund und verfluchte seinen Tag.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 3, 2, 'Und Hiob hob an und sprach:');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 3, 3, '„Ausgelöscht sei [der] Tag, [an dem] ich geboren wurde, und die Nacht, [die] sprach: »ein starker Mann ist empfangen worden!«.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 3, 4, 'Jener Tag – er werde zur Finsternis, Gott oben suche ihn nicht! Kein Lichtstrahl leuchte auf über ihm!');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 3, 5, 'Finsternis und Todesschatten sollen ihn zurückfordern, Gewölk sich auf ihn lagern, [Sonnen] finsternisse ihn schrecken!');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 3, 6, 'Diese Nacht – Düsternis reiße sie hinweg, sie reihe sich nicht ein in die Tage des Jahres! In den Ablauf der Monate trete sie nicht ein!');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 3, 7, 'Ja, jene Nacht sei unfruchtbar! Kein Freudenlaut komme auf in ihr!');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 3, 8, 'Verwünschen sollen sie die Tagverflucher, die, die befähigt sind, den Leviathan aufzuscheuchen.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 3, 9, 'Verfinstern sollen sich die Sterne ihrer Abenddämmerung. Sie hoffe sehnsüchtig auf Licht – doch nichts! Sie soll nicht sehen die Wimpern der Morgenröte!');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 3, 10, 'Denn sie hat weder die Türen des Schoßes [meiner Mutter] verschlossen, noch hat sie die Mühsal verborgen vor meinen Augen.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 3, 11, 'Warum bin ich nicht bei der Geburt gestorben und nicht hingeschieden, als ich aus dem Mutterleib kam?');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 3, 12, 'Warum sind mir Knie begegnet und wozu Brüste, damit ich saugte?');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 3, 13, 'Dann könnte ich jetzt daliegen und ausruhen. Ich könnte schlafen und hätte dann meine Ruhe');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 3, 14, 'zusammen mit Königen und Reichsverwaltern, die zerstörte Denkstätten für sich [wieder auf] gebaut haben,');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 3, 15, 'oder mit Fürsten, die Gold hatten, die ihre Häuser mit Silber füllten!');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 3, 16, 'Oder wie eine verscharrte Fehlgeburt, hätte ich nie existiert, wie Kinder, die nie Licht gesehen haben.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 3, 17, 'Dort haben die Frevler ihr Wüten beendet. Dort ruhen die, deren Kraft ermattet ist.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 3, 18, 'Da fühlen sich alle Gefangenen wohl; sie hören nicht mehr die Stimme eines Treibers.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 3, 19, 'Dort ist der Unbedeutende ebenso wie der Große – und ein Sklave ist frei von seinem Herrn.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 3, 20, 'Warum gibt er einem Leidenden Licht und Leben denen, deren Seele bitter ist,');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 3, 21, 'die auf den Tod warten – doch nichts, die nach ihm graben mehr als nach Schätzen,');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 3, 22, 'die sich freuten bis zum Jubel, die froh wären, wenn sie ein Grab fänden?');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 3, 23, '(Warum) dem (starken) Mann, dessen Weg verborgen ist, der von Gott getrennt ist?');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 3, 24, 'Denn vor meinem Brot kommt mein Stöhnen, und wie Wasser ergießen sich meine Schreie.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 3, 25, 'Denn, wovor ich mich fürchterlich fürchtete, das kam über mich, und wovor mir grauste, das traf mich.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 3, 26, 'Ich kann mich nicht wohlfühlen, ich kann nicht ruhig sein und ich kann nicht ausruhen – stattdessen kommt der Aufruhr.“');
