INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 33, 6, 'Durch das Wort JHWH s wurden die Himmel gemacht und durch den Hauch (Geist) seines Mundes ihr ganzes Heer (all ihr Heer).');
