INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 42, 1, 'Ein Kunstlied für den Musikmeister (Lehrgedicht für den Chorleiter, Andachtslied für die Liturgie) von den Korachiten (für die Nachkommen des Korach).');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 42, 2, 'Wie eine Hirschkuh (ein Hirschbulle) Wasserbäche herbeisehnt (verlangt, ruft), so sehnt sich mein ganzes Wesen (verlangt meine Lebenskraft, ruft meine Kehle) nach dir (zu dir), Gott.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 42, 3, 'Alles, was in mir ist, (meine Lebenskraft, meine Kehle) durstet nach dir, Gott, nach dem lebendigen Gott: Wann werde (darf) ich [zu ihm] kommen, dass ich in Gottes Gegenwart trete?');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 42, 4, 'Es sind mir [nämlich] meine Tränen zur [einzigen] Speise geworden, Tag und Nacht, denn sie fragen mich (wenn man sagt) zu mir jeden Tag: „Wo ist dein Gott?“');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 42, 5, 'Ich will mich erinnern und mit meiner ganzen Existenz trauern: Ich gehe [in einer] großen Menschenmenge zu Gottes Haus mit Jubelruf und Lobgesang in einer feiernden Menge.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 42, 6, '');
