INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 50, 1, 'Ein Psalm (begleitetes Lied) von (für) Asaf. Gott, Gott, JHWH, hat geredet und ruft die Erde (das Land) vom Aufgang der Sonne bis zu ihrem Untergang.');
