INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 67, 1, 'Für den obersten Musiker (Chorleiter, Dirigenten, Aufseher, vorzusingen). Mit Saiteninstrumenten (fröhlicher Musik, Zupfinstrumenten). Ein Psalm (begleitetes Lied). Ein Lied.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 67, 2, 'Gott sei uns gnädig (erbarme sich über uns, sei uns wohlgesinnt) und segne uns! Er lasse sein Gesicht bei (auf, über) uns scheinen, – Sela –');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 67, 3, 'damit (dann) auf der Erde (im Land) dein Weg erkannt [wird], unter allen Völkern (Nationen) deine rettende Kraft (Hilfe, Rettung, dein Eingeifen, Heil).');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 67, 4, '[Die] Völker sollen (mögen, werden) dich preisen (bekennen, dir danken), Gott, [die] Völker sollen (mögen, werden) dich preisen {sie} alle!');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 67, 5, '[Die] Völker (Völkerschaften) sollen (mögen, werden) sich freuen und singen, denn du richtest (wirst richten) [die] Völker gerecht ([mit] Gerechtigkeit), und [die] Völker (Völkerschaften) auf der Erde (im Land) führst (geleitest, regierst; wirst führen) du {sie}. Sela');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 67, 6, '[Die] Völker sollen (mögen, werden) dich preisen (bekennen, dir danken), Gott, [die] Völker sollen (mögen, werden) dich preisen {sie} alle!');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 67, 7, '[Das] Land ([die] Erde) hat (gibt) seinen Ertrag (ihre Frucht) gegeben. Es segne uns (segnet uns; wird, möge uns segnen) Gott, unser Gott! Es segne uns (möge, wird uns segnen, segnet uns) Gott, so dass (damit, und) alle Enden der Erde (die ganze Welt) ihn fürchten!');
