INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 20, 'Gelobt (gepriesen, gesegnet) sei der Herr Tag für Tag, er trägt für uns, Gott [ist] für uns Heil (Hilfen, Rettung). Sela.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 21, 'Gott [ist] für uns Gott zum Heil (der Rettungen), und bei JHWH Adonai [sind] die Auswege (Rettungen) vom Tod.');
