INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 73, 1, 'Ein Psalm (begleitetes Lied) von (für) Asaf. Lauter Güte ist Gott gegen Israel, gegen die, die reinen Herzens sind.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 73, 2, 'Ich aber wäre beinahe ausgeglitten mit meinen Füßen, um ein Haar wären meine Füße ins Wanken geraten.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 73, 3, 'Denn ich ereiferte mich über die Prahler, als ich sah, dass es den Frevlern gut geht.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 73, 4, 'Sie leiden keine Qualen bis zu ihrem Tod und fett ist ihr Leib.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 73, 5, 'Von der Mühsal der Sterblichen sind sie frei, sie werden nicht geplagt wie andere Menschen.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 73, 6, 'Darum ist ihr Hochmut ihr Halsgeschmeide, Gewalttat das Gewand, das sie umhüllt.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 73, 7, 'Sie sehen kaum aus den Augen vor fett, ihr Herz quillt über vor bösen Plänen.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 73, 8, 'Bösartig höhnen und reden sie, gewalttätig reden sie von oben herab.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 73, 9, 'Sie reißen ihr Maul auf bis an den Himmel, und ihre Zunge hat auf der Erde freien Lauf.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 73, 10, 'Darum wendet sich sein Volk ihnen zu, in vollen Zügen schlürfen sie Wasser.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 73, 11, 'Sie sagen: Wie sollte JHWH es wissen, gibt es ein Wissen bei dem Höchsten?');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 73, 12, 'Sieh, das sind die Frevler, immer im Glück häufen sie Reichtum.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 73, 13, 'Ganz umsonst hielt ich mein Herz rein, wusch ich meine Hände in Unschuld.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 73, 14, 'Ich war geplagt jeden Tag, Morgen für Morgen traf mich Züchtigung.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 73, 15, 'Hätte ich gesagt: So will ich auch reden!, dann hätte ich Generationen deiner Söhne verraten.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 73, 16, 'Dann dachte (sann) ich nach, um es zu verstehen, Qual war es in meinen Augen,');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 73, 17, 'bis ich zum Heiligtum Gottes kam und acht hatte auf ihr Ende.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 73, 18, 'Du stellst sie auf schlüpfrigen Boden, du lässt sie ins Leere fallen.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 73, 19, 'Wie werden sie zum Entsetzen im Nu, sie verschwinden, nehmen ein Ende mit Schrecken.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 73, 20, 'Wie einen Traum nach dem Erwachen, Herr, so verachtest du, wenn du aufwachst, ihr Bild.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 73, 21, 'Als mein Herz verbittert war und ich stechenden Schmerz in den Nieren spürte,');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 73, 22, 'da war ich ein Narr und hatte keine Einsicht, dumm wie ein Vieh war ich vor dir.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 73, 23, 'Nun aber bleibe ich stets bei dir, du hältst mich an meiner rechten Hand.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 73, 24, 'Nach deinem Ratschluss leitest du mich, und danach (hernach) nimmst du mich auf in Herrlichkeit.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 73, 25, 'Wen hätte ich im Himmel? Bin ich bei dir, so begehre ich nichts auf Erden.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 73, 26, 'Mögen mein Leib und mein Herz verschmachten, der Fels meines Herzens und mein Teil ist JHWH auf ewig.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 73, 27, 'Denn sieh, die dir fern sind, kommen um, du vernichtest jeden, der dich treulos verlässt.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 73, 28, 'Mein Glück aber ist es, Gott nahe zu sein; bei Gott, JHWH, habe ich meine Zuflucht. Alle deine Werke will ich verkünden.');
