INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 82, 1, 'Ein Psalm (begleitetes Lied) von (für) Asaf: Gott (Elohim) steht in der Versammlung Els (Gottesversammlung), inmitten der Götter hält er Gericht:');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 82, 2, '„Wie lange wollt ihr ungerecht richten (regieren) und die Angesichte der Frevler erheben? - Sela.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 82, 3, 'Verhelft zum Recht dem Schwachen und der Waise, dem Elenden und Bedürftigen schafft Gerechtigkeit!');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 82, 4, 'Befreit den Schwachen und Armen, aus der Hand der Frevler rettet (ihn)!“');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 82, 5, 'Nicht erkennen sie und nicht verstehen sie, in der Dunkelheit laufen sie hin und her. Es wanken alle Grundfesten der Erde.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 82, 6, 'Ich habe gesagt: „Götter seid ihr und Söhne des Höchsten, ihr alle.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 82, 7, 'Jedoch wie ein Mensch werdet ihr sterben und wie einer von den Obersten (Heeroberste, Fürsten) werdet ihr fallen.“');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 82, 8, 'Erhebe dich Gott (Elohim)! Richte die Erde, denn du hast zum Erbbesitz alle Völker!');
