INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 97, 1, 'JHWH ist König (herrscht als König). Die Erde soll jubeln! Die großen (vielen) Inseln sollen sich freuen!');
