INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 100, 1, 'Ein Psalm (begleitetes Lied) zum Dank (zum Dankopfer, zum Dankgottesdienst, Preis, Lob, Wechselgesang?). Jubelt (schreit vor Freude) (über) JHWH zu, du ganze Erde (du ganzes Land)!');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 100, 2, 'Dient (feiert Gottesdienst, feiert, verehrt) JHWH in Freude (Fröhlichkeit, Lustigkeit) kommt (hinein) vor ihn (in seine Wohnung, in sein Heiligtum) in Freudengeschrei (Freudenliedern)');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 100, 3, 'Erkennt (Bekennt), dass (: Wahrlich!, denn) JHWH Gott ist! Er hat uns erschaffen, sein sind wir (und nicht wir) [wir sind] sein Volk und die Herde seiner Weide.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 100, 4, 'Kommt (hinein) durch seine Tore (die Tore seiner Wohnung/seines Heiligtums) mit Danklied (Dankopfer, Loblied)! [Kommt (hinein)] in seine Höfe (die Höfe seiner Wohnung/seines Heiligtums) mit Lobgesang (Lobpreis)! Preist ihn, lobsingt (segnet) seinem Namen (ihm)!');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 100, 5, '{Ja! (Denn) } JHWH ist gut! Für immer ist (währt) seine Huld und von Generation zu Generation ist (währt) seine Treue (Verlässlichkeit)!');
