INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 1, '\'\' ([Von (für, nach Art von) David]) \'\' Preise, meine Seele, JHWH! JHWH, mein Gott, [du bist] ([ist]) sehr groß! Du bist bekleidet (hast dich bekleidet) mit Majestät und Herrlichkeit (majestätischer Herrlichkeit/Pracht),');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 2, '[Bist] mit Licht wie mit einem Mantel umhüllt (verhüllt, ein Eingehüllter), [Oh, du] [bists], der den Himmel wie eine Zeltdecke ausspannte (bist ausspannend),');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 3, '[Bist] der, der bälkte (zimmerte) im (mit) Wasser ein Obergemach [Bist] der, der dort Wolken [als] seinen Wagen (sein Fahrzeug) [hat], [Bist] der, der sich fortbewegt (bist [dich] fortbewegend) auf den Flügeln des Windes,');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 4, '[Bists], der macht (bist machend) zu seinen Boten Winde (seine Boten zu Winden),Zu seinen Dienern (Seine Diener [sind]) flammendes Feuer (Flamme [und] Feuer),');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 5, '[Bists,] der gründete (bist gründend, er gründete) die Erde auf ihre Fundamente, Damit sie nicht wanken wird auf immer und ewig.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 6, 'Das Urmeer bedecktest du wie mit einem Gewand. Auf (über) den Bergen sollten Wasser stehen (sich stellen):');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 7, 'Vor deinem Schelten mussten (sollten) sie fliehen,Vor dem Klang deines Donnerns (deiner donnernden Stimme) mussten (sollten) sie fortlaufen,');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 8, 'Mussten (sollten) hinaufziehen [auf] Berge,Mussten (sollten) hinabsteigen [in] TälerZum Ort, den du ihnen gegründet hast.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 9, '[Die] Grenze, [die] du gesetzt hast, dürfen sie nicht übertreten, Dürfen nicht zurückkehren, um die Erde zu bedecken (dürfen die Erde nicht wieder bedecken).');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 10, '[Oh, du] [bist] der, der entsendet Quellen in Wadis – Sie sollen (müssen) zwischen [den] Bergen fließen (gehen),');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 11, 'Sollen (müssen) alle wilden Tiere (alle Tiere dessen vom Berge) tränken,Es sollen [selbst] die Wildesel ihren Durst brechen können (sollen/müssen stillen).');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 12, 'Über ihnen wohnt das Gevögel des Himmels,Von zwischen den Felsen (Zweigen) geben sie [ihre] Stimme –,');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 13, '[Bists,] der tränkt die Berge von seinen Obergemächern: Von der Frucht deiner Werke (deines Arbeitens) soll die Erde sitt (satt) werden.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 14, '[Bists,] der sprossen lässt das Gras für ViehUnd Pflanzen zum Nutzen (für den Ackerbau) der Menschen: Damit [dieser] Brot aus der Erde hervorbringe (um hervorzubringen...),');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 15, 'Soll Menschenherzen Wein erfreuen; Damit ihr Gesicht von Öl glänzt (mehr glänzt als Öl), Soll Menschenherzen Brot (Nahrung) stärken.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 16, 'Es sollen sitt werden (sättigen) die Bäume des Feldes (JHWH s),Die Libanon-zedern, die er gepflanzt hat.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 17, 'Dort (, auf denen) sollen Vöglein nisten,Der Habicht (Storch?, Reiher?) in ihren Wipfeln (auf Zypressen) sein Haus [haben].');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 18, 'Die hohen Berge [sollen] den Steinböcken [gehören],Die Felsen den Klippdachsen Zuflucht [sein].');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 19, 'Er machte den Mond für Festzeiten, Die Sonne kennt ihren Untergang.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 20, 'Du willst Finsternis setzen,Es soll Nacht werden, In ihr sollen alle Waldtiere schleichen (pirschen):');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 21, 'Die Junglöwen brüllen nach Beute, Um zu fordern von Gott ihre Speise.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 22, 'Die Sonne soll scheinen,Sie sollen sich sammeln und in ihre Höhlen legen.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 23, 'Der Mensch soll an sein Werk gehenUnd an seine Arbeit bis zum Abend.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 24, 'Wie zahlreich (groß) [sind] deine Werke, JHWH! Sie alle hast du mit Weisheit gemacht! Voll ist die Erde mit seinem Besitz,');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 25, 'So auch das Meer: (Dies – das Meer – [ist], dort [ist] das Meer:) groß und weit {die Seiten}: Dort [gibt es] Gewürm ohne Zahl,Kleine Tiere und große.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 26, 'Dort schwimmen Schiffe, (schwimmen dort gleich Schiffen.) [Schwimmt der] Leviathan, den du gebildet, um mit ihm Spaß zu haben (damit er darinnen Spaß habe).');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 27, 'Sie alle warten auf dich,dass du [ihnen] gibst Nahrung zur rechten Zeit.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 28, 'Du gibst ihnen (Gibst du ihnen,...) [Nahrung], sie sammeln [sie].Du öffnest deine Hand (Öffnest du deine Hand,...), sie werden gesättigt mit Gutem.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 29, 'Du verbirgst dein Gesicht (verbirgst du dein Gesicht,...), sie werden vernichtet (erschrecken),Du nimmst ihren Atem (Geist), sie sterben (hauchen aus) Und zu ihrem Staub kehren sie zurück.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 30, 'Du sendest deinen Atem (Geist) aus, sie werden geschaffen;Du erneuerst das Gesicht (die Oberfläche) der Erde.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 31, 'Es währe die Herrlichkeit (Pracht) JHWH s auf ewig,Es freue sich JHWH über seine Werke!');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 32, 'Der auf die Erde blickt, so dass sie bebt, Er rührt die Berge an, sie rauchen.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 33, 'Ich will singen JHWH mein [ganzes] Leben,ich will lobsingen meinem Gott meine [ganze] Dauer,');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 34, 'Möge ihm angenehm sein meine Rede (mein Sinnen),Ich will mich freuen über JHWH!');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 35, 'Es mögen (werden) schwinden Sünder von der ErdeUnd Frevler, von Dauer [mögen (werden)] sie nicht [sein]. Preise, meine Seele, JHWH! –Hallelujah (Preist Jah!, Preist JHWH!)!');
