INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 4, 'Für meine Liebe feinden (klagen sie mich an) sie mich an. Aber ich [bin] Gebet (Bittgebet, Anrufung).');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 5, '{Und} sie legen auf mich Böses statt (für) Gutes – {und} Hass (Feindschaft) statt (für) meiner Liebe:');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 6, 'Übergebe ihn (bestelle für ihn) einem Gottlosen (Frevler)! Und ein Ankläger (Widersacher, Gegner) soll stehen auf seiner rechten Seite (zu seiner Rechten).');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 7, 'Während er gerichtet wird (den/einen Rechtsstreit führt), soll er herausgehen (hervorgehen) [als] ein Gottloser (Frevler), und sein Gebet (Bittgebet, Anrufung) soll werden zur Sünde.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 8, '');
