INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 110, 1, 'Von (Für; [Über den neuen]) David. Ein Psalm (begleitetes Lied). Spruch JHWH s für meinen Herrn: Setze dich zu meiner Rechten, bis ich deine Feinde gemacht habe zum Schemel deiner Füße.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 110, 2, 'Den Stab deiner Macht (deinen machtvollen Stab) wird JHWH aus Zion ausstrecken, herrsche inmitten deiner Feinde.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 110, 3, 'Dein Volk ist Bereitwilligkeit am Tage deiner Macht. In heiliger Pracht aus dem Schoß der Morgenröte der Tau deiner Jugend ist dein.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 110, 4, 'Geschworen hat JHWH und es gereut ihn nicht: Du bist Priester in Ewigkeit (für immer) nach der Weise Melchisedeks (des gerechten Königs?).');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 110, 5, 'Der Herr/ JHWH zu deiner Rechten zerschmettert Könige am Tag seines Zorns.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 110, 6, 'Er richtet unter den Völkern, er füllt Leichen. Er zerschmettert das Haupt auf der weiten Erde.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 110, 7, 'Auf dem Weg trinkt er aus dem Bach, darum hebt er das Haupt.');
