INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 117, 1, 'Lobt JHWH, alle Völker! Preist (ehrt) ihn, alle Stämme (Ethnien, Geschlechter),');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 117, 2, 'denn mächtig (groß) ist uns zugunsten seine Güte (Gnade, Liebe, Gewogenheit), und JHWH s Treue (Beständigkeit, Zuverlässigkeit) hat ewig Bestand ([bleibt] für immer). Halleluja (Lobt Jah)!');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 1, 'Preist JHWH, denn er ist gut, ewig währt seine Treue.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 2, 'Es spreche Israel: Ewig währt seine Treue.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 3, 'Es spreche das Haus Aaron: Ewig währt seine Treue.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 4, 'Sprechen sollen, die JHWH fürchten: Ewig währt seine Treue.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 5, 'Aus der Bedrängnis rief ich zu JHWH, JHWH erhörte mich in weitem Raum.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 6, 'JHWH ist für mich, ich fürchte mich nicht. Was könnten die Menschen mir antun?');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 7, 'JHWH ist für mich als mein Helfer, weiden wird sich mein Blick an denen, die mich hassen.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 8, 'Besser ist es, bei JHWH Zuflucht zu suchen, als Menschen zu vertrauen.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 9, 'Besser ist es, bei JHWH Zuflucht zu suchen, als Fürsten zu vertrauen.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 10, 'Alle Völker umringen mich, im Namen JHWH s aber wehre ich sie ab.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 11, 'Sie umkreisen, sie umringen mich, im Namen JHWH s aber wehre ich sie ab.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 12, 'Wie Bienen umkreisen sie mich; wie ein Dornenfeuer verlöschen sie, im Namen JHWH s wehre ich sie ab.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 13, 'Du hast mich hart gestoßen zu fallen, JHWH aber hat mir geholfen.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 14, 'Meine Kraft und meine Stärke ist JHWH, und er wurde mir zur Rettung.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 15, 'Klang des Jubels und der Rettung ist in den Zelten der Gerechten. Es macht Kraft (Heil; Gewaltiges) die Rechte (rechte Hand) JHWH s.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 16, 'Die Rechte (rechte Hand) JHWH s erhöht, es macht Kraft (Heil; Gewaltiges) die Rechte (rechte Hand) JHWH s.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 17, 'Ich werde nicht sterben, sondern leben und die Taten JHWH s verkünden.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 18, 'JHWH hat mich stark zurechtgewiesen, dem Tod aber nicht preisgegeben.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 19, 'Macht (Tut) mir auf die Tore der Gerechtigkeit. Ich will durch sie einziehen, um JHWH zu danken.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 20, 'Dies ist das Tor JHWH s, die Gerechten ziehen hier ein.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 21, 'Ich will dir danken, denn du hast mir geantwortet und bist für mich zur Rettung geworden.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 22, 'Der Stein, den die Bauleute verworfen haben, ist zum Eckstein geworden.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 23, 'Durch JHWH ist es geschehen, wunderbar ist es in unseren Augen.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 24, 'Dies ist der Tag, den JHWH gemacht hat, wir wollen jauchzen und uns an ihm freuen!');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 25, 'Ach JHWH, hilf! Ach JHWH, lass gelingen!');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 26, 'Gesegnet sei, wer kommt im Namen JHWH s. Wir segnen euch vom Haus JHWHs.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 27, 'JHWH ist Gott, er gab uns Licht. Schmückt das Fest mit Zweigen bis zu den Hörnern des Altars!');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 28, 'Du bist mein Gott! Ich will dir danken, mein Gott, ich will dich erheben!');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 29, 'Preist JHWH, denn er ist gut, ewig währt seine Treue!');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 1, '');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 2, '');
