INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 120, 1, 'Ein Lied der Wallfahrten (großen Aufstiege, aufsteigenden Frauen) Zu JHWH rief (schrie; rufe) ich in (wegen) meiner Not (Elend) und er antwortete (antwortet).');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 120, 2, 'JHWH, rette meine Person doch vor lügenden Lippen (Lippen der Lüge), vor einer täuschenden Zunge!');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 120, 3, 'Was soll [man] dir geben und was soll [man] dir noch antun, [du] täuschende Zunge?');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 120, 4, 'Die scharfen Pfeile eines Kriegers mit glühenden (brennenden) Kohlen aus Ginster!');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 120, 5, 'Weh mir, denn ich lebe (habe gelebt) [als Ausländer in] Meschech, ich wohne (habe gewohnt) bei den Zelten von Kedar!');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 120, 6, 'Lange (zu lange) hat meine Person bei (den) Friedensverächtern (Friedenshassern; Verächtern des Friedens) gewohnt (wohnt)!');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 120, 7, 'Ich [liebe] Frieden (Harmonie; [bin] friedfertig), aber wenn ich spreche, [sind] sie für den Krieg ([bereit] zum Krieg).');
