INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 126, 1, 'Ein Wallfahrtslied. Als zurückführte JHWH die Gefangenen Zions, waren wir wie Träumende.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 126, 2, 'Da wurde voll Lachens unser Mund und unsere Zunge [voll] Jubels. Da sagen sie in (unter) den Völkern: Große Dinge hat getan JHWH mit diesen.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 126, 3, 'Es hat getan JHWH große Dinge mit uns. Wir sind freudig.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 126, 4, 'Kehre um (wende), JHWH, unser Gefängnis, wie die Ströme im Südland.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 126, 5, 'Die mit Tränen Säenden - mit Jubel werden sie ernten.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 126, 6, 'Er geht hin und weinend trägt er eine Saat-Tasche. Er kommt zurück mit Jubel tragend seine Garben.');
