INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 133, 1, 'Ein Lied der Wallfahrten (großen Aufstiege, aufsteigenden Frauen). Von (Für) David. Siehe wie gut und wie schön es ist, wenn Brüder einträchtig zusammen (beieinander) wohnen (siedeln).');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 133, 2, 'Wie gutes Öl auf dem Kopf (Haupt), das auf den Bart hinunter (herunter) fällt (läuft, rinnt), auf den Bart Aarons, der herunter (hinunter) fällt (läuft, wallt) auf den Saum (Mund) seiner Gewänder');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 133, 3, 'Wie der Tau des Hermon, der herunter (hinunter) fällt (läuft, rinnt) auf die Berge Zions. Denn dort hin befiehlt JHWH den Segen, Leben bis in Ewigkeit (für immer).');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 134, 1, 'Ein Lied der Wallfahrten (großen Aufstiege, aufsteigenden Frauen). Siehe (Wohlan, Auf), preiset (segnet, lobet) JHWH, alle Diener (Knechte, Sklaven) JHWH s, die im Haus JHWHs stehen (die Stehenden) in den Nächten.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 134, 2, 'Hebt eure Hände zum Heiligtum (in Heiligkeit) und preiset (segnet, lobet) JHWH.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 134, 3, 'JHWH möge dich segnen (preisen, loben) vom (aus) Zion, der Himmel und Erde gemacht hat.');
