INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 145, 1, 'Ein Lobgesang. Von David. Ich will dich erheben, mein Gott, der König, und ich will preisen deinen Namen bis in alle Ewigkeit.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 145, 2, 'Den ganzen Tag über will ich dich preisen und ich will loben deinen Namen bis in alle Ewigkeit.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 145, 3, 'Groß ist JHWH und sehr zu loben und seine Größe ist nicht zu erforschen.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 145, 4, 'Generation für Generation wird deine Werke rühmen und deine Machttaten werden sie verkünden.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 145, 5, 'Reden sollen sie von der herrlichen Pracht deiner Majestät und deine Wunder will ich erzählen.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 145, 6, 'Und sie sollen sprechen von der Kraft deiner furchtbaren Taten und deine Größe will ich erzählen.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 145, 7, 'Das Gedächtnis deiner großen Güte sollen sie wecken und deine Gerechtigkeit werden sie jubelnd preisen.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 145, 8, 'Gnädig und barmherzig ist JHWH, langsam im Zorn und groß an Güte.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 145, 9, 'JHWH ist gut gegen alle und sein Erbarmen ist über alle seine Werke.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 145, 10, 'Es werden dich loben, JHWH, alle deine Werke und deine Frommen werden dich preisen.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 145, 11, 'Sie werden von der Herrlichkeit deines Reiches sprechen und von deinen Machttaten werden sie reden,');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 145, 12, 'Um den Menschensöhnen seine Machttaten kundzutun und die prachtvolle Herrlichkeit seines Reiches.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 145, 13, 'Dein Reich ist ein Reich für alle Ewigkeit und deine Herrschaft dauert von allem Geschlecht zu Geschlecht.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 145, 14, 'JHWH ist ein Stützender für alle Fallenden, er ist ein Aufrichtender für alle Niedergebeugten.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 145, 15, 'Augen (von) allen warten auf dich und du gibst ihnen Speise zu seiner Zeit.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 145, 16, 'Du tust deine Hand auf und sättigst alles Lebendige nach Wohlgefallen.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 145, 17, 'JHWH ist gerecht in allen seinen Wegen und treu in allen seinen Werken.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 145, 18, 'Nahe ist JHWH all denen, die ihn rufen, all denen die ihn in Wahrheit anrufen.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 145, 19, 'Er erfüllt das Verlangen von denen, die ihn fürchten. Ihr schreien hört er und er rettet sie.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 145, 20, 'JHWH bewahrt alle, die ihn lieben, aber alle Frevler vertilgt er.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 145, 21, 'Mein Mund soll das Lob JHWH aussprechen und alles Fleisch soll seinen heiligen Namen preisen bis in alle Ewigkeit.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 146, 1, 'Halleluja! (Lobt JH!) Meine Seele, lobe JHWH!');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 146, 2, 'Ich will JHWH in meinem Leben loben. Ich will Gott singen, solange ich bin.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 146, 3, 'Vertraut nicht auf Fürsten und nicht auf einen Menschensohn, bei dem keine Hilfe ist.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 146, 4, 'Sein Geist geht aus. Er geht zurück zu seiner Erde. An dem Tag gehen seine Gedanken verloren.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 146, 5, 'Wohl dem, dessen Hilfe der Gott Jakobs ist, dessen Hoffnung auf JHWH, seinem Gott, ist,');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 146, 6, 'welcher Himmel und Erde gemacht hat, das Meer und alles, was in ihnen ist; der, der ewiglich Treue hält.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 146, 7, 'Einer, der Recht schafft denen, die bedrückt werden; einer, der Brot gibt denen, die Hunger haben. JHWH befreit die Gefesselten.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 146, 8, 'JHWH lässt Blinde sehen. JHWH richtet Gebeugte auf. JHWH liebt die Gerechten.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 146, 9, 'JHWH beschützt Fremde. Waise und Witwe richtet er wieder auf. Aber den Weg der Gottlosen krümmt er.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 146, 10, 'JHWH wird ewig König sein, dein Gott, Zion, von Generation zu Generation. Halleluja! (Lobt JH!)');
