INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 2, 9, 'Dann wirst du achten auf Recht (das Rechte, Gerechtigkeit) und Gesetz und Gerechtigkeit (Aufrichtigkeit) [und] alle guten Pfade.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 2, 10, 'Denn Weisheit komme in dein Herz und Erkenntnis sei deiner Seele angenehm (lieblich).');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 2, 11, 'Klugheit (Gewandheit) schütze (bewahre) dich, Einsicht (Klugheit) bewahre (behüte) dich.');
