INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 12, 22, 'Ein Gräuel für JHWH sind die Lippen der Lüge, wer aber Treue übt, hat sein Wohlgefallen.');
