INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 12, 25, 'Sorge (Kummer, Furcht) im Herzen des Menschen (Mannes) drückt es nieder, aber ein gutes Wort erfreut es.');
