INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 26, 'In der Furcht JHWH s ist starkes Vertrauen, auch für seine Söhne ist es Zuflucht.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 27, 'Die Furcht JHWH s ist eine Quelle des Lebens um die Fallen des Todes zu meiden.');
