INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 1, 1, '\'\'\'Das Lied der Lieder, welche [sind] (welches [ist]) von (für, über, nach Art von) Salomon\'\'\' t');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 1, 2, '[\'\'\'Frau\'\'\':] „Er küsse mich mit Küssen (mit einigen von den Küssen) seines Mundes!Oh!, (Denn) deine Liebkosungen [müssen] besser [sein] ([sind] besser) als Wein;');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 1, 3, 'Als der Geruch [deiner] Öle (deiner Öle) [müssen sie] besser [sein] (An Geruch/zum Riechen [sind] [deine] Öle gut):Öl, [das] ausgegossen wird, ist dein Name (bist du selbst)! Darum lieben dich die jungen Frauen.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 1, 4, 'Zieh mich! Hinter dir wollen wir [ja alle] herrennen!Der König bringt mich in seine Zimmer! Wir wollen [ja alle] jubeln und uns freuen über dich,Wir wollen deine Liebkosung mehr als Wein preisen. Die Gerechten (mit Recht?) lieben dich.“★');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 1, 5, '[\'\'\'Frau\'\'\':] „Schwarz [bin] ich, aber [trotzdem] (und) schön, [oh] Töchter Jerusalems!Wie die Zelte Kedars, wie die Zelte Salomos!');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 1, 6, 'Seht nicht auf mich herab, (Wollt ihr mich nicht ansehen...!?) weil ich so schwarz [bin],Weil die Sonne auf mich geblickt hat! Die Söhne meiner Mutter waren gegen mich entbrannt;Sie haben mich zur Hüterin der Weinberge gemacht -Meinen Weinberg, der mein [ist], habe ich nicht gehütet.“★');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 1, 7, '[\'\'\'Frau\'\'\':] „Sag mir, [du,] den meine Seele liebt,Wo du weiden wirst, Wo du lagern lassen wirst am Mittag, Damit ich nicht sein muss (werde) als Verschleierte (wie eine Wandernde) Bei [den] Herden deiner Gefährten!“');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 1, 8, '[\'\'\'Mann (Töchter Jerusalems) \'\'\':] „Wenn du es {dir} nicht wissen wirst, Schönste unter den Frauen, Folge {dir} den Spuren der SchafeUnd weide deine Zicklein (Brüste?) Bei den Zelten der Hirten!“★');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 1, 9, '[\'\'\'Mann\'\'\':] „Pferden (meinen Pferden, einer Stute, meiner Stute) vor den Wagen des PharaoVergleiche ich dich (mache ich dich gleich), meine Freundin!');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 1, 10, 'Lieblich sind (wären) deine Wangen (Backen) zwischen den Ketten (in Zaumzeug),Dein Hals zwischen den Perlen (?).');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 1, 11, 'Goldene Ketten (Goldenes Zaumzeug) will ich (wollen wir) dir machen [lassen],Mit Punkten aus Silber!“★');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 1, 12, '[\'\'\'Frau\'\'\':] „Solange (bis [dorthin], wo) der König auf seiner Couch [ist],Gibt meine Narde ihren Duft.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 1, 13, 'Ein Myrrhensäckchen [ist] mir mein Geliebter,Ruhend zwischen meinen Brüsten.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 1, 14, 'Eine Hennadolde [ist] mir mein GeliebterAus den Weinbergen von En-Gedi.“★');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 1, 15, '[\'\'\'Mann\'\'\':] „Siehe! (Fürwahr!), schön [bist du, (ist)] meine Freundin!Siehe! (Fürwahr!), schön [bist du (ist)]! Deine Augen [sind] Tauben ([wie die von] Tauben)!“');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 1, 16, '[\'\'\'Frau\'\'\':] „Siehe (Fürwahr!), schön [bist du, (ist)] mein Geliebter; ja, lieblich;Ja, unser Bett [ist] grün:');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 1, 17, 'Die Balken unseres Hauses (unserer Häuser) [sind] Zedern (Zedernholz),Unsere Täfelung (unser Balken) [sind] Zypressen (Zypressenholz).“');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 2, 1, '[\'\'\'Frau\'\'\':] „Ich bin ([nur]) eine (die) Lilie in der Scharonebene, ([Nur]) eine (die) Iris (Lotusblume?) in den Tälern.“');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 2, 2, '[\'\'\'Mann\'\'\':] „Wie eine Iris (Lotusblume?) unter {den} Disteln (Dornen),So [ist] meine Freundin unter den Töchtern.“');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 2, 3, '[\'\'\'Frau\'\'\':] „Wie ein Aprikose [nbaum] unter {den} WaldbäumenSo [ist] mein Geliebter unter den Söhnen. In seinem Schatten erfreue ich mich (habe ich Lust) und sitze ichUnd seine Frucht [ist] süß an meinem Gaumen.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 2, 4, 'Er hat mich in das Haus des Weins gebracht,Und sein Banner über mir [ist] Liebe.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 2, 5, 'Unterstützt mich (Man unterstütze mich) mit {dem} Traubenkuchen,Stärkt mich (man stärke mich) mit {den} Aprikosen,Denn ich bin krank vor Liebe!');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 2, 6, 'Seine Linke [sei] unter meinem KopfUnd seine Rechte umfasse mich!');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 2, 7, 'Ich beschwöre euch, Töchter Jerusalems, Bei den Gazellen oder bei den Hirschkühen des Feldes: Entfacht nicht und facht nicht an die Liebe (Stört nicht den Geschlechtsverkehr?),Bis es ihr gefällt (solange sie begehrt)!“★');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 2, 8, '[\'\'\'Frau\'\'\':] „ [Das] Geräusch (Stimme, Horch!,) meines Geliebten!Siehe da, er kommt (Siehe, da kommt er)! Er springt über die Berge,Er hüpft über die Hügel -');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 2, 9, 'Es gleicht mein Geliebter einer Gazelle (einer Schönen) Oder einem Hirschkitz! Siehe da, er steht (Siehe, jetzt steht er) hinter unserer Wand!Er schaut [hinein] von den Fenstern [her],Er späht (blüht) [hinein] von den Öffnungen [her]!');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 2, 10, 'Mein Geliebter {antwortet und} sagt zu mir: [\'\'\'Mann\'\'\':] »Steh {dich} auf, meine Freundin, Meine Schöne, geh {dir}!');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 2, 11, 'Denn {siehe} der Winter (die Regenzeit) ist [ja] vorübergegangen,Der Regen ist weitergezogen, {sich} fortgelaufen!');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 2, 12, 'Die Blumen lassen sich sehen (zeigen sich, werden gesehen) auf dem Land,Die Zeit des Gesangs ist gekommenUnd die Stimme der Turteltaube lässt sich hören in unserem Land.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 2, 13, 'Der Feige [nbaum] würzt (?) seine JungfeigenUnd die blühenden Weinstöcke geben Duft. Steh {dich} auf (Steh auf, geh), meine Freundin, Meine Schöne, geh {dir}!');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 2, 14, 'Meine Taube in den Felsenspalten,Im Versteck der Terrasse (Steinwand) Lass mich deinen Anblick (deine Anblicke) sehen,Lass mich deine Stimme hören, Denn deine Stimme [ist] süßUnd dein Anblick lieblich!');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 2, 15, 'Man hat für uns Füchse gefangen (Sie haben für uns Füchse gefangen; Fangt uns Füchse!; Fangt uns, ihr Füchse!),Kleine Füchse, Die Weinberge zerstören - [Daher] [steht] unser Weinberg (unsere Weinberge) [in] Blüte.«');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 2, 16, '[\'\'\'Frau\'\'\':] Mein Geliebter ist mein und ich bin sein,Der bei den Iriden weidet (der Iriden frisst? der bei den Iriden grast?).');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 2, 17, 'Bis (Sobald) der Tag blästUnd die Schatten fliehen, Wende dich, gleiche, mein Geliebter, {dir} Einer Gazelle (einer Schönen) oder einem HirschkitzAuf den Duft (?) -Bergen (den zerklüfteten Bergen, den trennenden Bergen, dem Bether-Gebirge).“');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 3, 1, '[\'\'\'Frau\'\'\':] „Auf meinem Lager in den Nächten (in der Nacht) suchte ich (sehnte ich mich nach dem),Den meine Seele liebt (den ich liebe);Ich suchte ihn und (aber) fand ihn nicht.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 3, 2, '[Da sagte ich mir:] »Ich will aufstehen und umhergehen in der Stadt,Auf den Straßen und auf den Plätzen! Ich will suchen, den meine Seele liebt (den ich liebe)!«Ich suchte ihn und (aber) fand ihn nicht.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 3, 3, 'Es fanden (ergriffen) mich die Wächter,Die in der Stadt umhergingen (Umhergehenden) [Ich fragte sie:] »Den meine Seele liebt (den ich liebe), habt ihr [ihn] gesehen?«');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 3, 4, '[Nur] Weniges [war\'s], dass ich an ihnen vorbeigegangen war,Bis dass ich fand (ergriff), den meine Seele liebt (den ich liebe). Ich packte ihn und wollte ihn nicht mehr los lassen,Bis dass ich ihn gebracht hätte ins Haus meiner MutterUnd in die Kammer meiner Gebärerin.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 3, 5, 'Ich beschwöre euch, Töchter Jerusalems, Bei den Gazellen oder bei den Hirschkühen des Feldes: Entfacht nicht und facht nicht an die Liebe (Stört nicht den Geschlechtsverkehr?),Bis es ihr gefällt (solange sie begehrt)!“★');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 3, 6, '[\'\'\'Jerusalemerinnen\'\'\':] ([\'\'\'Frau\'\'\']): „Wer [ist] diese, die hinaufzieht von (aus) der WüsteWie eine Säule (wie Säulen) aus Rauch, Duftender nach Myrrhe und Weihrauch (Rauch aus dem Räucherwerk von Myrrhe und Weihrauch) Als alle Pulver des Händlers (Duftend nach Myrrhe und Weihrauch, nach allen Pulvern des Händlers)!? ★');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 3, 7, '[\'\'\'Jerusalemerinnen\'\'\'] ([\'\'\'Frau\'\'\':]) Siehe, das Bett (die Liegesänfte?) Salomos Sechzig Helden (Krieger, Männer) um esVon den Helden (Krieger, Männer) Israels:');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 3, 8, 'Sie alle sind schwerterfahren (halten ein Schwert),Geübt im Kampf. Jeder [hat] sein Schwert an seiner HüfteGegen (wegen) nächtliche Schrecken. (★)');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 3, 9, 'Eine Bettstatt (?, Sänfte) ließ sich machen (hat sich gemacht) der König SalomoAus Holz vom Libanon.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 3, 10, 'Ihre Säulen ließ er machen (hat er gemacht) silbern (aus Silber),Ihre Kopfstütze golden (aus Gold),Ihr Vorhang (Decke, Kissen, Sitz?) purpurn,Ihr Inneres [ist] ([war]) ausgelegt mit Leder (Liebe). {Von den} Töchter {n} Jerusalems,');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 3, 11, 'kommet herausUnd schauet, Töchter Zions Auf König Salomo,Auf seine Krone, mit der ihn seine Mutter gekrönt hat Am Tag seiner Hochzeit,Am Tag der Freude seines Herzens!“');
