INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 8, 6, 'Lege mich wie das Siegel (den Siegelring) auf dein Herz (an dein Innerstes) wie das Siegel (den Siegelring) an deinen Arm (deine Schulter, deine Stärke) denn stark (mächtig) wie der Tod [ist] die Liebe hart wie das Totenreich (die Unterwelt, die Sheol) [ist] die Leidenschaft (Eifersucht) Ihre Flammen sind Flammen eines Feuers eine Flamme Jahs.');
