INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 21, 'Wie wurde zur Hure die zuverlässige (treue/beständige) Stadt. Sie war voll von Recht. Richtigkeit (Korrektheit) wohnte in ihr und jetzt Mörder.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 22, 'Dein Silber ist zu Schlacke geworden und Dein Bier (Getränk) mit Wasser verfälscht (gepanscht/geschwächt).');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 23, 'Deine Obersten (Adeligen) sind abtrünnig (gesetzlos/fühlen sich nicht an das Gesetz gebunden) und Diebesgesellen und jeder liebt Bestechungsgeschenke und ist gierig (jagt) nach Bestechung [sgeld] (Vergütungen/„Boni“). Der Waise verschaffen sie kein Recht und der Rechtsstreit der Witwe kommt nicht zu ihnen.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 24, 'Deshalb, Spruch des Herrn JHWH s der Heerscharen (Zebaot), des Starken Israels: Wehe, ich werde mir Genugtuung an denen verschaffen, die mich anfeinden und mich rächen an meinen Feinden.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 25, 'Ich werde meine Hand gegen dich wenden (zurückbringen) und deine Schlacke verfeinern (ausschmelzen, reinigen) wie mit Pottasche und alle deine Schlacke wegnehmen.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 26, 'Ich werde zurückbringen deine Richter wie in der ersten Zeit und deine Ratgeber wie am Anfang. Danach wird man dich Stadt der Gerechtigkeit nennen, treue Stadt.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 27, '');
