INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 9, 'Der Scheol ist erschüttert (erregt) von unten deinetwegen (für dich), um dein Kommen auszurufen. Er erregt (beunruhigt, stört) deinetwegen (für dich) die Refaim (Totengeister, Schatten), alle Führer (Leitböcke) der Erde, er lässt von ihren Thronen aufstehen (er erhebt aus ihren Thronen) alle Könige der Völker.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 10, 'Sie alle antworten und sprechen zu dir: „Auch du bist schwach (kraftlos) geworden wie wir, uns gleich (ähnlich).“');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 11, 'Hinabgestürzt [in den] Scheol [ist] deine Herrlichkeit (Stolz, Majestät), das Rauschen (Geräusch) deiner Harfe. Unter dir ist Gewürm zum Lager ausgebreitet, und deine Decke [ist] ein Wurm.');
