INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 38, 18, 'Denn die Unterwelt lobt dich nicht und der Tod preist dich nicht, nicht warten die, die in die Grube hinabsteigen, auf deine Treue.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 38, 19, 'Allein Lebendige loben dich, wie ich heute. Ein Vater vermittelt den Kindern deine Treue.');
