INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 43, 13, 'Auch von nun an (fortan) bin ich es und es ist nichts das aus meiner Hand rettet (entreißt); ich tue (führe aus) und wer macht [es] rückgängig?');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 43, 14, '');
