INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 44, 3, '');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 44, 4, '');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 44, 5, '');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 44, 6, '');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 44, 7, '');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 44, 8, '');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 44, 9, 'Die, die Kultbilder erschaffen sind alle nichtig und was sie verehren nützt nichts und ihre Zeugen, sie sehen nicht und sie erkennen nicht, deswegen schämen sie sich.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 44, 10, 'Wer erschafft einen Gott und gießt ein Kultbild, ohne dass es hilft?');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 44, 11, 'Siehe, alle seine Gefährten schämen sich und die Arbeiter, sie sind aus dem Menschengeschlecht, sie versammeln sich alle, sie stellen sich hin, sie erschrecken sich, sie schämen sich zusammen.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 44, 12, 'Ein Eisenschmied der Dexel arbeitet mit der Glut und mit Hämmern formt er es und er macht es mit seinem starken Arm, auch hungert er und hat keine Kraft, Wasser trinkt er nicht und er ermüdet.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 44, 13, 'Der Schreiner spannt die Messschnur, er umzeichnet es mit einem Rotstift, er arbeitet mit dem Schabwerkzeug und mit einem Zirkel umzeichnet er es und er arbeitet es nach dem Modell eines Mannes, nach einem geschmückten Menschen, um ihn im Haus wohnen zu lassen.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 44, 14, 'Was das Fällen von Zedern für ihn betrifft: Er nimmt eine Steineiche und eine Eiche und er festigt einen unter den Bäumen des Waldes, er pflanzt eine Zeder und der Regen lässt sie wachsen.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 44, 15, 'Es ist für den Menschen zum Feuer machen und er nimmt davon und wärmt sich, auch zündet er es an und backt Brot, sogar einen Gott macht er und betet an, er arbeitet daraus ein Kultbild und fällt vor ihm nieder.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 44, 16, 'Seine eine Hälfte verbrennt er im Feuer, von seiner [anderen] Hälfte isst er Fleisch, er bereitet Gebratenes zu und wird satt, auch wärmt er sich und sagt: „Ha, ich bin warm geworden, ich sehe Feuer.“');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 44, 17, 'Und den Rest davon arbeitet er zu einem Gott, zu seinem Kultbild, er fällt vor ihm nieder und betet an und fleht zu ihm und sagt: „Rette mich, denn du bist mein Gott.“');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 44, 18, 'Nicht kennen sie und nicht verstehen sie, denn verklebt sind ihre Augen, dass sie nicht sehen, ihre Herzen, dass sie nicht verständnisvoll sind.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 44, 19, 'Und nicht kehrt einer um zu seinem Herzen und es ist nicht Wissen und nicht Verstand, indem er sagt: „Seine eine Hälfte habe ich verbrannt im Feuer und sogar Brot habe ich gebacken auf seiner Glut, ich briet Fleisch und habe gegessen und den Rest davon soll ich zu einem Gräuel machen, vor dem Erzeugnis eines Baumes soll ich niederfallen?“');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 44, 20, 'Der Asche hütet – ein irregeleitetes Herz verführt ihn und er rettet nicht sein Leben und er sagt nicht: „Ist es nicht Betrug in meinen Händen?“');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 44, 21, '');
