INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 45, 15, 'Gewiss, du bist ein verborgener Gott, der Gott Israels, Retter.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 45, 16, 'Sie schämen sich und werden auch alle beschämt, zusammen gehen sie in Schmach, die Hersteller von Bildern.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 45, 17, 'Israel wird gerettet durch JHWH, ewige Hilfe, nicht werdet ihr euch schämen und nicht beschämt werden bis in ewige Zeiten.');
