INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 46, 5, 'Mit wem wollt ihr mich vergleichen und ähnlich machen und mich gleichstellen, dass wir uns ähneln?');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 46, 6, 'Die Gold aus einem Beutel schütten und Silber auf der Waage abwiegen, sie engagieren einen Goldschmied und er soll daraus einen Gott machen, sie fallen nieder, sie beten ihn sogar an.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 46, 7, 'Sie heben ihn auf die Schulter, sie tragen ihn und lassen ihn ruhen an seinem Platz und er steht, von seinem Platz weicht er nicht, man schreit sogar zu ihm und er antwortet nicht, aus seiner Not rettet er ihn nicht.');
