INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 60, 1, 'Richte dich auf (erhebe dich), [Zion], werde hell, denn dein Licht kommt und die Herrlichkeit JHWH s geht auf (bricht hervor) über dir.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 60, 2, 'Denn sieh (e): Die Dunkelheit bedeckt die Erde und Wolkendunkel (Dunkel) die Völker. Aber über dir geht auf JHWH und seine Herrlichkeit erscheint (sichtbar werden/ sein, sich zeigen) über dir.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 60, 3, 'Und die Völker werden kommen zu deinem Licht und die Könige zum Glanz (hellen Schein), der [über] dir aufgeht.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 60, 4, 'Erhebe ringsum deine Augen und sieh: alle haben sich versammelt (wurden gesammelt) [und] kommen zu dir. Deine Söhne werden von ferne kommen und deine Töchter werden auf der Hüfte (Seite, Flanke) getragen werden.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 60, 5, 'Dann wirst du sehen und aufspringen und hüpfen, und dein Herz wird weit werden, dass (wenn) sich wenden wird zu dir der Reichtum des Meeres, das Vermögen der Völker zu dir kommen wird.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 60, 6, 'Die Menge der Kamele wird dich bedecken, die jungen Kamelhengste Midians und Efas, alle werden aus Saba kommen, Gold und Weihrauch werden sie tragen und Lobpreis (Lobgesang, Ruhm) JHWH s werden sie verkündigen.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 60, 7, '');
