INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 1, 'Das Wort, das an Jeremia von JHWH geschah:');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 2, 'Stell dich in das Tor des Hauses JHWH s und rufe dort dieses Wort und sage: Hört das Wort JHWHs, ganz Juda, die ihr kommt durch diese Tore, um JHWH anzubeten.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 3, 'So spricht JHWH, Herr der Heerschaaren, Gott Israel: Macht gut eure Wege und eure Taten, dann werde ich euch wohnen lassen an diesem Ort.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 4, 'Verlasst euch nicht auf Worte der Lüge, wenn sie sagen: Der Tempel JHWH s, der Tempel JHWHs, der Tempel JHWHs ist dieser.');
