INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 8, 2, '');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 8, 3, '');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 8, 4, 'Sprich zu ihnen, so hat JHWH gesprochen: Fällt man und steht nicht wieder auf? Oder wendet sich einer ab und kehrt nicht wieder zurück?');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 8, 5, 'Warum hat sich dieses Volk Jerusalems abgewendet in beharrlicher Abkehr? Sie halten fest an der Täuschung (Trug) und weigern sich, umzukehren.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 8, 6, 'Ich horche hin und höre: Sie sprechen nicht recht, nicht einer bereut seine Bosheit und sagt: „Was habe ich getan!“Alle rennen noch weiter fort, (sie kehren sich ab in ihrem Rennen) wie ein Pferd (Hengst) galoppiert (strömt) in die Schlacht.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 8, 7, 'Auch der Storch (Kranich) am Himmel kennt seine festgesetzten Zeiten (kennt die Zeit der Rückkehr), Taube, Schwalbe und Kranich hören auf die Zeit ihres Kommens aber mein Volk kennt nicht die Rechtsordnung (Recht,Rechtsbestimmung) JHWH s.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 8, 8, '');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 8, 9, '... Siehe, das Wort JHWH s haben sie verschmäht (verworfen), aber welche Weisheit haben sie?');
