INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 10, 11, 'Folgendes solltet (könnt, dürft) ihr zu ihnen sagen: „Die Götter, die den Himmel und die Erde nicht gemacht haben, werden (sollen, müssen) verschwinden (vergehen) von der Erde und von unter diesem Himmel!“');
