INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 1, '');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 2, '');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 3, '');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 4, 'So spricht JHWH der Heerscharen (Zebaot), der Gott Israels zu allen Weggeführten, die ich von Jerusalem [nach] Babel in Verbannung geführt habe:');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 5, '„Baut Häuser und wohnt [darin] und pflanzt Gärten und esst ihre Früchte!');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 6, 'Nehmt [euch] Frauen und zeugt Söhne und Töchter, und nehmt für eure Söhne Frauen und gebt Männern eure Töchter – sodass (und) sie Söhne und Töchter gebären werden und werdet dort groß und nicht weniger!');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 7, 'Und sucht der Stadt Wohlergehen, [in] die ich euch in Verbannung geführt habe und betet für sie zu JHWH: Denn in ihrem Frieden wird für euch Frieden sein!“');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 8, 'Fürwahr, so spricht JHWH der Heerscharen (Zebaot), der Gott Israels: „Und [es] sollen euch nicht eure Propheten täuschen, die in eurer Mitte sind und eure Wahrsager und ihr [sollt] (werdet) nicht [auf die] hören, die euch zum Träumen verleiten!');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 9, 'Denn in Lüge reden sie prophetisch zu euch in meinem Namen – ich habe sie nicht gesandt“, Ausspruch JHWH s.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 10, 'Fürwahr, so spricht JHWH: „Wenn (denn) für Babel siebzig Jahre gänzlich erfüllt sind, werde ich mich eurer annehmen und [...] (ich) mein gutes Wort über euch erfüllen um euch zu diesem Ort zurückzubringen!');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 11, 'Denn ich kenne die Pläne, die ich über euch dachte“, Ausspruch JHWH s. „Heilsgedanken und nicht [...] (für) Böses um [...] (für) euch Zukunft und Hoffnung zu geben!');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 12, 'Wenn (und) ihr mich anruft und ihr geht, [dass] (und) ihr zu mir betet: Und ich werde euch erhören!');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 13, 'Wenn (und) ihr mich sucht [...] (und) werdet ihr [mich] finden, denn [wenn] ihr mich suchen werdet mit eurem ganzen Herzen, [so] (und) werde ich mich finden lassen');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 14, 'von euch“, Ausspruch JHWH s. „Und ich werde eure Gefangenschaft wenden und ich werde euch sammeln aus allen Völkern und aus allen Orten von wo ich euch vertrieben habe“, Ausspruch JHWH s. „Und ich werde euch zurückbringen an (nach) den Ort, [...] (der) von dort [aus] ich euch in Verbannung geführt habe.“');
