INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 22, 'JHWH s (Gnadenerweise =) Gnade [ist es], dass wir nicht am Ende (umgekommen, vergangen) sind, denn sein Mitgefühl ist nicht zu Ende.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 23, 'Jeden Morgen [ist es] neu, groß [ist] seine Treue.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 24, 'JHWH ist mein Anteil (Besitz, Gewinn), (hat meine Seele =) habe ich gesagt, daher will ich auf ihn warten.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 25, 'Gut [ist] JHWH zu dem, der auf ihn hofft, zu (der Seele =) dem Menschen, der ihn sucht (sich an ihn wendet).');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 26, 'Gut [ist es], (still harrend [zu sein] =) still zu harren auf die Hilfe (Rettung, Heil) JHWH s.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 27, 'Gut [ist es] für jeden, wenn er erträgt das Joch in seiner Jugendzeit.');
