INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 1, 1, 'Worte des Amos – der unter den Schafzüchtern von Tekoa war –, die er über Israel sah in den Tagen Usijas, dem König Judas, und in den Tagen Jerobeams, dem Sohn Joas’, dem König Israels, zwei Jahre vor dem Erdbeben.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 1, 2, 'Und er sprach: „ JHWH wird von Zion brüllen und von Jerusalem seine Stimme geben, dass die Weideplätze der Hirten jammern und der Gipfel des Karmel vertrocknet.“');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 1, 3, 'So spricht JHWH: „Wegen drei Vergehen von Damaskus und wegen vier werde ich es nicht rückgängig machen (zurückbringen lassen), weil sie Gilead mit einer eisernen Dreschwalze gedroschen haben.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 1, 4, 'Und ich werde Feuer schicken in das Haus Hasaëls und es wird die Paläste Ben-Hadads fressen.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 1, 5, 'Und ich werde den Riegel von Damaskus zerbrechen und ich werde die Bewohner von Bikat-Awen ausrotten und den, der das Szepter hält, aus Bet-Eden; und das Volk von Aram wird nach Kir deportiert werden“, spricht JHWH.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 1, 6, 'So spricht JHWH: „Wegen drei Vergehen von Gaza und wegen vier werde ich es nicht rückgängig machen, weil sie sie alle ins Exil deportiert haben, um sie an Edom auszuliefern.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 1, 7, 'Und ich werde Feuer schicken an die Mauer von Gaza und es wird seine Paläste fressen.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 1, 8, 'Und ich werde die Bewohner von Aschdod ausrotten und den, der das Szepter hält, aus Aschkelon; und ich strecke meine Hand gegen Ekron aus und die Übriggebliebenen der Philister werden zu Grunde gehen“, spricht der Herr JHWH.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 1, 9, 'So spricht JHWH: „Wegen drei Vergehen von Tyrus und wegen vier werde ich es nicht rückgängig machen, weil sie sie alle an Edom [ins] Exil ausgeliefert haben und nicht des Bruderbundes gedachtet.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 1, 10, 'Und ich werde Feuer schicken an die Mauer von Tyrus und es wird seine Paläste fressen.“');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 1, 11, 'So spricht JHWH: „Wegen drei Vergehen von Edom und wegen vier werde ich es nicht rückgängig machen, weil sie seinen Bruder mit dem Schwert verfolgten und sein Erbarmen zu Grunde richteten und sein Zorn zerriss für immer und sein Grimm wachte stets.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 1, 12, 'Und ich werde Feuer schicken nach Teman und es wird die Paläste von Bozra fressen.“');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 1, 13, 'So spricht JHWH: „Wegen drei Vergehen der Söhne Ammons und wegen vier werde ich es nicht rückgängig machen, weil sie die Schwangeren in Gilead aufgeschlitzt haben, mit der Absicht ihre Grenzen zu erweitern.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 1, 14, 'Und ich werde ein Feuer anzünden an der Mauer von Rabba und es wird seine Paläste fressen im Kriegslärm am Tag der Schlacht, im Sturm am Tag des Sturmwindes.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 1, 15, 'Und ihr König geht ins Exil, er und seine Obersten zusammen“, spricht JHWH.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 2, 1, 'So spricht JHWH: Wegen drei Vergehen von Moab und wegen vier werde ich es nicht rückgängig machen, weil sie die Knochen des Königs von Edom zu Kalk zerbrannten.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 2, 2, 'Und ich werde Feuer schicken nach Moab und es wird die Paläste von Kerijot fressen und Moab stirbt im Getümmel, im Kriegslärm beim Ruf des Schofar.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 2, 3, 'Und ich werde die Richter aus ihrer Mitte vernichten und alle ihre Obersten mit ihm töten, spricht JHWH.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 2, 4, 'So spricht JHWH: Wegen drei Vergehen von Juda und wegen vier werde es nicht rückgängig machen, weil sie die Thora JHWHs verworfen haben und seine Ordnungen nicht hielten und ihre Lügen verführten sie, denen ihre Väter hinterher gelaufen sind.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 2, 5, 'Und ich werde Feuer schicken nach Juda und es wird die Paläste von Jerusalem fressen.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 2, 6, 'So spricht JHWH: Wegen drei Vergehen von Israel und wegen vier werde ich es nicht rückgängig machen, weil sie den Gerechten für Silber verkauft haben und den Armen für den Ertrag eines Paar Schuhe.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 2, 7, 'Sie treten den Kopf der Schwachen nieder auf den Staub der Erde und den Weg der Armen beugen sie und ein Mann und sein Vater gehen zu dem [selben] Mädchen um meinen heiligen Namen zu entweihen.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 2, 8, 'Und auf gepfändeten Kleidern strecken sie sich neben jeden Altar aus und trinken Wein von Strafgeldern im Haus ihres Gottes.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 2, 9, 'Und ich habe den Amoriter vor ihnen vernichtet, dessen Höhe [war] wie die Höhe der Zedern und dessen Stärke (Aussehen) [war] wie [die] der Eichen, und ich habe seine Frucht zerstört von oben und seine Wurzel von unten.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 2, 10, 'Und ich habe euch aus dem Land Ägypten heraufgeführt und habe euch in der Wüste vierzig Jahre geleitet um das Land des Amoriters in Besitz zu nehmen.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 2, 11, 'Und ich habe von euren Söhnen Propheten erweckt und von euren jungen Männern Nasiräer. Ja, war es nicht so, Söhne Israels? Ausspruch JHWH s.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 2, 12, 'Ihr habt die Nasiräer Wein trinken lassen und den Propheten habt ihr befohlen {folgendermaßen}: Ihr sollt nicht weissagen.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 2, 13, 'Siehe, ich mache es schwankend unter euch, wie der Wagen schwankt, der voll mit Heu ist.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 2, 14, 'Und es geht zu Grunde die Zuflucht für den Schnellen und den Starken festigt nicht seine Kraft und der Mächtige (Held) rettet nicht sein Leben (Seele).');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 2, 15, 'Und der den Bogen Ergreifende wird nicht standhalten und der Schnellfüßige rettet [sich] nicht und der auf dem Pferd Reitende rettet nicht sein Leben (Seele).');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 2, 16, 'Und sein starkes Herz unter den Mächtigsten (Helden) wird nackt fliehen an jenem Tag, Ausspruch JHWH s.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 3, 1, 'Hört dieses Wort, das gesagt hat JHWH über Euch, Söhne Israels, über das ganze Geschlecht (die ganzen Stämme), das ich aus Ägypten herausgeführt habe {folgendermaßen}:');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 3, 2, 'Nur eurer gedachte ich von allen Geschlechtern der Erde, deswegen suche ich heim an euch alle eure Sünden.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 3, 3, 'Gehen zwei zusammen, ohne dass sie zusammengekommen sind?');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 3, 4, 'Brüllt der Löwe im Gestrüpp, und hat keine Beute? Gibt ein junger Löwe seine Stimme (Laut) von seinem Lager, außer er hat [etwas] gefangen?');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 3, 5, 'Fällt ein Vogel in die Falle [das Klappnetz] am Boden, ohne dass ein Stellholz nach (zu) ihm [geworfen wurde]? Springt die Falle [das Klappnetz] von der Erde, wenn sie nichts gefangen hat?');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 3, 6, 'Wenn in der Stadt das Horn geblasen wird, erzittert das Volk [etwa] nicht? Geschieht etwa ein Unglück (Schlechtes/Böses) in der Stadt und JHWH hat es nicht gemacht?');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 3, 7, 'Denn nicht macht der Herr JHWH ein Wort, außer wenn er offenbart sein Geheimnis seinen Knechten, den Propheten.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 3, 8, 'Der Löwe brüllt, wer fürchtet ihn nicht? Der Herr JHWH spricht, wer weissagt nicht?');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 3, 9, 'Lasst es hören {über} den Palästen in Ashdoth und {über} den Palästen im Land Ägypten und sagt (sprecht): Versammelt euch auf den Bergen Samarias und seht die große Verwirrung (Bestürzung, Panik) in seiner Mitte und die Unterdrückung in ihrem Inneren (ihrer Mitte).');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 3, 10, 'Und nicht verstehen sie zu tun das Rechte, Spruch JHWH s, die Aufhäufenden (sie, die anhäuften) von Gewalt und Bedrückung.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 3, 11, 'Deshalb, so spricht der Herr JHWH: Ein Feind (Gegner) hat das Land umzingelt (ist um das Land herum), er wirft deine Macht nieder (reißt herunter, stürzt), und deine Paläste werden geplündert.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 3, 12, 'So spricht JHWH: Wie errettet der Hirte aus dem Maul des Löwen zwei Unterschenkel und Ohrzipfel, so werden errettet die Söhne Israels, die sitzen in Samaria in der Ecke des Lagers und auf dem Damast des Ruhebettes.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 3, 13, 'hört und bezeugt dem Haus Jakobs, Spruch des Herrn JHWH, Gott der Heerscharen (Zebaot).');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 3, 14, 'Denn (Führwahr) am Tag suche ich heim die Sünden Israels an ihm und ich suche heim auf den Altären Bet-Els und es werden zerbrechen die Hörner des Altars und zu Boden (auf die Erde) fallen.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 3, 15, 'Ich zerschlage (zertrümmere) dein Winterhaus zusammen mit (samt) deinem Sommerhaus und deine Elfenbeinhäuser werden zugrunde (verloren) gehen und deine vielen Häuser werden verschwinden. Spruch JHWH s.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 4, 1, '');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 4, 2, '');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 4, 3, '');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 4, 4, 'Kommt nach Bet-El und vergeht euch, nach Gilgal, vergeht euch noch mehr. Und bringt eure Schlachtopfer am Morgen, am dritten Tag eure Zehnten.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 4, 5, '');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 4, 6, '');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 4, 7, '');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 4, 8, '');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 4, 9, '');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 4, 10, '');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 4, 11, '');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 4, 12, '');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 4, 13, '');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 5, 1, 'Hört dieses Wort, das ich anhebe über euch [als] Totenklage, Haus Israel!');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 5, 2, 'Sie ist gefallen, sie kann nicht wieder aufstehen, die Jungfrau Israel, (ist) hingeworfen auf ihren Boden, es gibt keinen, der sie aufrichtet.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 5, 3, 'Denn (Fürwahr) so spricht JHWH: Die Stadt, die auszieht zu tausend, wird hundert übrigbehalten. Und die auszieht zu hundert, wird zehn übrigbehalten für das Haus Israel.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 5, 4, 'Denn so spricht JHWH zum Haus Israel: Sucht mich, dann werdet ihr leben.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 5, 5, 'Und sucht nicht Bet-El auf und geht nicht nach Gilgal und geht nicht hinüber nach Beerscheba. Denn Gilgal wird ganz bestimmt gefangen wegziehen und das Haus Gottes (Bet-El) wird zum Haus des Betrugs.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 5, 6, 'Sucht JHWH, dann werdet ihr leben, damit er nicht das Haus Josef [wie] Feuer wirkt, das frisst und für Bet-El niemand da ist, der löscht.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 5, 7, 'Die Recht in Wermut verwandeln und Gerechtigkeit zu Boden werfen.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 5, 8, 'Der das Siebengestirn und den Orion gemacht hat, in Morgen die Finsternis verwandelt und den Tag zur Nacht verfinstert, der die Wasser des Meeres ruft und sie ausgießt über der Fläche der Erde: JHWH ist sein Name.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 5, 9, 'Der über dem Starken (Mächtigen) Verwüstung (Zerstörung) aufblitzen lässt und Verwüstung (Zerstörung) kommt über die Festung (befestigte Stadt).');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 5, 10, 'Sie hassen den, der im Tor Recht spricht und verabscheuen den, der aufrichtig (untadelig) redet.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 5, 11, '');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 5, 12, '');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 5, 13, 'Darum wird der Kluge (Einsichtige) zu dieser Zeit schweigen, denn diese Zeit ist böse (schlecht).');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 5, 14, 'Sucht das Gute und nicht das Böse, damit ihr lebt! Und JHWH, der Gott der Heerscharen, wird so mit euch sein, wie er sagt.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 5, 15, 'Hasst das Böse und liebt das Gute und richtet das Recht auf im Tor! Vielleicht wird JHWH, der Gott der Heerscharen, dem Überrest Josefs gnädig sein!');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 5, 16, '');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 5, 17, 'Und in allen Weinbergen ist Trauer (Wehklagen), denn ich werde durch deine Mitte schreiten, spricht JHWH.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 5, 18, 'Wehe denen, die den Tag JHWH s herbeiwünschen! Wozu soll denn der Tag JHWHs sein? Er wird Finsternis sein und nicht Licht.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 5, 19, '');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 5, 20, 'Ist nicht der Tag JHWH s Finsternis (Dunkelheit) und nicht Licht? Dunkelheit, nicht Helligkeit (Glanz, Tageslicht) ist er.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 5, 21, 'Ich hasse, ich verwerfe eure Feste, und eure Festversammlungen kann ich nicht riechen.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 5, 22, 'Denn wenn ihr mir Brandopfer opfert, missfallen sie mir, und an euren Speiseopfern habe ich keinen Gefallen, und das Heilsopfer von einem Mastvieh will ich nicht ansehen.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 5, 23, 'Halte den Lärm deiner Lieder von mir fern! Und das Spiel deiner Harfen will ich nicht hören!');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 5, 24, 'Aber Recht ergieße sich wie Wasser und Gerechtigkeit wie ein immerfließender Bach!');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 5, 25, 'Habt ihr mir vierzig Jahre in der Wüste Schlachtopfer und Speiseopfer dargebracht, Haus Israel?');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 5, 26, 'Und habt ihr den Sikkut und Kiun getragen, eure Götzenbilder, den Stern eurer Götter, die ihr euch gemacht habt?');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 5, 27, 'So werde ich euch über Damaskus hinaus gefangen wegführen, spricht JHWH, Gott der Heerscharen ist sein Name.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 6, 1, 'Wehe den Sorglosen in Zion und den Sicheren auf dem Berg von Samaria, den Vornehmen des Erstlings der Völker, zu denen das Haus Israel kommt.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 6, 2, 'Geht hinüber nach Kalne und seht. Und geht von dort nach Hamat, der großen, und steigt hinab nach Gat, [die Stadt] der Philister. Sind sie besser als diese Königreiche, oder ist ihr Gebiet größer als euer Gebiet?');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 6, 3, '');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 6, 4, '');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 6, 5, '');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 6, 6, '');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 6, 7, '');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 6, 8, '');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 6, 9, '');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 6, 10, '');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 6, 11, '');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 6, 12, 'Rennen Pferde denn auf Felsen, oder pflügt man mit Rindern? Ihr aber verwandelt das Recht in Gift und die Furcht der Gerechtigkeit in Wermut.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 6, 13, '');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 6, 14, '');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 7, 1, 'So ließ mich der Herr JHWH sehen und siehe: einer, der Heuschrecke [n] zum Anfang als das Gras aufstieg - und siehe: das Gras nach der Heuernte des Königs.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 7, 2, 'Und es geschah, als sie fertig wurden, die Kräuter des Landes abzufressen, sprach ich: „Wie wird Jakob bestehen, weil er klein ist?“');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 7, 3, 'Es tat JHWH Leid über dieses. „Es soll nicht geschehen!“, spricht JHWH.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 7, 4, 'So ließ mich der Herr JHWH sehen und siehe: der Herr JHWH rief zum Gericht mit dem Feuer und es fraß die große Flut und es fraß das Feld.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 7, 5, 'Und ich sprach: „Herr JHWH, lass doch ab! Wie wird Jakob bestehen, weil er klein ist?“');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 7, 6, 'Es tat JHWH Leid über dieses. „Auch dies soll nicht geschehen!“, spricht der Herr JHWH.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 7, 7, 'So ließ er mich sehen und siehe: der Herr stellte sich auf eine senkrechte Mauer und in seiner Hand war ein Blei.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 7, 8, 'Und der Herr sprach zu mir: „Was siehst du, Amos?“Und ich sprach: „Ein Blei.“Und der Herr sprach: „Siehe, ich lege ein Blei an mein Volk Israel; ich werde nicht noch einmal fortfahren an ihm vorüberzugehen.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 7, 9, 'Und die Bamot Isaaks werden verwüstet und die Heiligtümer Israels werden verwüstet und ich werde mich erheben gegen das Haus Jerobeams mit dem Schwert.“');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 7, 10, 'Und Amazja, der Priester von Bethel, ließ Jerobeam, dem König Israels, sagen (folgendermaßen): „Amos verschwört sich gegen dich in mitten des Hauses Israels; das Land vermag nichts zu tun gegen alle seine Worte.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 7, 11, 'Denn so spricht Amos: \'Durch das Schwert wird Jerobeam sterben und Israel wird bestimmt aus seinem Land deportiert werden.\'“');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 7, 12, 'Und Amazja sprach zu Amos: „Prophet, gehe, fliehe zu dir in das Land Juda und iss dort Brot und weissage dort.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 7, 13, 'Und in Bethel fahre nicht fort weiter weiszusagen, denn es ist das Heiligtum des Königs und das Haus des Königreiches ist es.“');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 7, 14, 'Und Amos antwortete und sprach zu Amazja: „Ich bin kein Prophet und ich bin kein Prophetensohn, denn ich bin ein Hirte und ein Maulbeerfeigenbaumzüchter bin ich.“');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 7, 15, 'Und JHWH nahm mich aus der Herde und JHWH sprach zu mir: „Gehe, weissage meinem Volk Israel!“');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 7, 16, 'Und nun höre das Wort JHWH s: „Du sprichst: \'Du sollst nicht weissagen über Israel und du sollst nicht weissagen über das Haus Isaak!\'“');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 7, 17, 'Deshalb, so spricht JHWH: „Deine Frau wird in der Stadt zur Hure werden und deine Söhne und deine Töchter werden durch das Schwert fallen und dein Land wird mit der Messschnur verteilt werden und du wirst auf unreinem Land sterben und Israel wird gewiss von seinem Land deportiert werden.“');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 8, 1, 'So ließ mich der Herr JHWH sehen und siehe: ein Korb [mit] Sommerfrüchten.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 8, 2, 'Und er sprach: „Was siehst du, Amos?“Und ich sprach: „Ein Korb [mit] Sommerfrüchten.“Und JHWH sprach zu mir: „Das Ende ist gekommen für mein Volk Israel; ich werde nicht noch einmal fortfahren an ihm vorüberzugehen.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 8, 3, 'Und die Lieder des Tempels werden zu Wehklagen an jenem Tag,“Ausspruch des Herrn JHWH. „An allen Orten werfen sie schweigend viele Leichen.“');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 8, 4, 'Hört dieses, die ihr den Armen zermalmt, und des Armen Land ein Ende macht;');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 8, 5, 'um zu sagen: „Wann ist der Neumond vorübergegangen, dass wir das Getreide verkaufen, und der Sabbat, dass wir das Korn öffnen um das Efa zu verkleinern und um den Schekel zu vergrößern und eine falsche Waage zu beugen;');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 8, 6, 'um mit Silber die Schwachen zu kaufen und den Armen mit dem Ertrag eines Paar Schuhe und die Spreu des Korns verkaufen.“');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 8, 7, 'JHWH schwört beim Stolz Jakobs: „Wenn ich nicht für immer alle ihre Taten vergesse!');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 8, 8, 'Erbebt über diesen nicht die Erde und jammern alle, die auf ihr wohnen und völlig hinaufgehen wie der Fluss und aufwallen und sinken wie der Strom Ägyptens?');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 8, 9, 'Und es geschieht an jenem Tag, Ausspruch des Herrn JHWH, und ich werde die Sonne am Mittag untergehen lassen und verfinstern die Erde am hellen Tag.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 8, 10, 'Und ich werde umkehren eure Feste in Trauer und alle eure Lieder in Wehklagen; und ich werde auf alle Hüften einen Sack bringen und auf alle Köpfe eine Glatze; und ich werde es machen wie die Trauer um den einzigen Sohn und ihr Ende wie einen bitteren Tag.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 8, 11, 'Siehe, Tage kommen“, Ausspruch des Herrn JHWH, „dass ich Hunger über das Land schicken werde, nicht Hunger nach Brot und nicht Durst nach Wasser, sondern um zu hören das Wort JHWH s.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 8, 12, 'Und sie wanken von Meer zu Meer und vom Norden und bis zum Osten; sie werden umherschweifen um das Wort JHWH s zu suchen und werden es nicht finden.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 8, 13, 'An jenem Tag werde die schönen Jungfrauen und die jungen Männer vor Durst ohnmächtig dahinsinken.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 8, 14, 'Die bei der Schuld Samarias schwören und sprechen: \'So wahr dein Gott lebt, Dan! Und so wahr der Weg nach Beerscheba lebt!\' Und sie werden fallen und nicht wieder aufstehen.“');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 9, 1, 'Ich sah den Herrn auf dem Altar stehen und er sprach: Schlage auf das Kapitel, dass die Schwellen erschüttert werden und zerbrich sie ihnen allen auf dem Kopf. Und die Übriggebliebenen werde ich mit dem Schwert töten; kein Flüchtling flieht vor ihnen und kein Entkommener rettet sich vor ihnen.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 9, 2, 'Wenn sie in den Scheol einbrechen, wird meine Hand sie von dort nehmen; und wenn sie zum Himmel hinaufgehen, werde ich sie von dort hinunternehmen.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 9, 3, 'Und wenn sie sich auf dem Gipfel des Karmel verbergen, werde ich von dort suchen und sie nehmen; und wenn sie sich verstecken vor meinen Augen auf dem Grund des Meeres, werde ich von dort der Schlange befehlen und sie wird sie beißen.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 9, 4, 'Und wenn sie in die Gefangenschaft gehen vor den Augen ihrer Feinde, werde ich von dort dem Schwert befehlen und es wird sie töten; und ich werde meine Augen auf sie legen - zum Bösen und nicht zum Guten.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 9, 5, 'Und der Herr, JHWH der Heerscharen (Zebaot), schlägt auf das Land und es schwankt und alle, die auf ihm sitzen, werden jammern, dass es hinaufgeht wie der Fluss und zurückgeht wie der Strom Ägyptens.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 9, 6, 'Er baut im Himmel seine Stufe (Obergemach, Söller) und seine Himmelsgewölbe auf der Erde gründet er. Er ruft die Wasser des Meeres und er gießt sie aus auf dem Angesicht der Erde, JHWH ist sein Name.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 9, 7, 'Seid ihr nicht wie die Söhne der Kuschiter für mich, ihr Söhne Israels, sricht JHWH. Habe nicht ich Israel herausgefährt aus dem Land Ägypten und die Philister aus Kaftor und die Aramäer aus Kir.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 9, 8, 'Siehe, die Augen des Herrn JHWH sind auf dem sündigen Königreich, und ich vernichte es (rotte es aus) vom Angesicht der Erde. Nur, dass ich nicht völlig (vollständig) vernichte (ausrotte) das Haus Jakobs, spricht JHWH.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 9, 9, 'Denn siehe, ich will befehlen und will schütteln in alle Völker das Haus Israels, wie man schüttelt mit einem Sieb und nicht fällt ein Stein auf die (zur) Erde.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 9, 10, 'Mit dem Schwert werden getötet alle Sünder meines Volkes, die sagen: Du führst nicht herbei und lässt nicht zu uns kommen das Böse (Unheil).');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 9, 11, 'An diesem Tag will ich [wieder] aufstellen die Hütte Davids, die umgefallene (verfallene, eingestürzte). Und ich (ver) mauere ihre Risse und ihr Niedergerissenes (Abgebrochenes, ihre Trümmer) stelle ich auf und erbaue sie wieder wie in den Tagen der der Vorzeit.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 9, 12, 'Damit sie in Besitz nehmen das Übrige (den Rest) von Edom und alle (Fremd) völker, über die ausgerufen (genannt) ist mein Namen, spricht der JHWH, der dies tut.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 9, 13, 'Siehe, Tage kommen, spricht JHWH, da nähert sich (tritt heran) der Pflüger dem Schnitter und der Weintraubentreter an den Samensäer und sie werden herabtriefen lassen Most von den Bergen und alle Hügel zwerfließen.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 9, 14, 'Ich wende das Geschick meines Volkes Israel. Sie werden aufbauen ihre verwüsteten Städte und sie bewohnen und sie pflanzen Weinberge und trinken ihren (deren) Wein und sie machen Gärten und essen ihre Früchte.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 9, 15, 'Und ich pflanze sie in auf ihr Land (ihren Erdboden, ihre Erde). Und sie sollen nicht mehr vertrieben (herausgerissen) werden von iherem Land (ihrem Erdboden, ihrer Erde) die ich ihnen gegeben habe, spricht (sagt) JHWH, dein Gott.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 1, 1, '');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 1, 2, '');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 1, 3, '');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 1, 4, '');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 1, 5, '');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 1, 6, '');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 1, 7, '');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 1, 8, '');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 1, 9, '');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 1, 10, '');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 1, 11, '');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 1, 12, '');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 1, 13, '');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 1, 14, '');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 1, 15, '');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 1, 16, '');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 1, 17, '');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 1, 18, '');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 1, 19, '');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 1, 20, '');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 1, 21, '');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 1, 1, 'Und das Wort JHWH s kam zu Jona, Amittais Sohn {mit den Worten}:');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 1, 2, '„Brich auf (Auf!), gehe in die große Stadt Ninive und rufe [die Anklage] gegen sie, weil ihre Bosheit (bösen Taten) vor mich gekommen ist.“');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 1, 3, 'Doch (und) Jona brach auf, um vor JHWH nach Tarschisch zu fliehen, und ging hinab [nach] Jafo. {und} Er traf auf ein Schiff, das im Begriff war, nach Tarschisch zu fahren, {und} zahlte sein Fährgeld und bestieg es, um mit ihnen nach Tarschisch zu fahren, weg von JHWH');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 1, 4, 'Aber (da) JHWH ließ einen großen Wind auf das Meer los, und es kam ein so großer Sturm über dem Meer auf, dass (und) das Schiff zu zerbrechen drohte.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 1, 5, 'Da fürchteten sich die Seeleute und riefen jeder zu seinem Gott (seinen Göttern). {und} Sie warfen die Gegenstände (Ladung, Ausrüstung), die auf dem Schiff [waren], ins Meer, um [das Schiff] {von ihnen} leichter zu machen. Derweil (und) war Jona hinab in den Rumpf (unter Deck) des Schiffes gestiegen, {und} hatte sich hingelegt und schlief tief und fest.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 1, 6, 'Da kam der Oberste der Seeleute in seine Nähe und fragte (sprach) {zu ihm}: „Warum schläfst du? Steh auf [und] rufe zu deinem Gott, vielleicht schenkt der Gott uns ja Beachtung, so dass (und) wir nicht umkommen (sterben)!“');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 1, 7, 'Und sie sagten zueinander: „Kommt, {und} wir werfen Lose, damit (und) wir herausfinden, wie es kommt (wer daran schuld ist), dass uns so ein Unheil [geschieht]!“Und (also) sie warfen Lose und das Los fiel auf Jona.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 1, 8, 'Da sagten sie zu ihm: „Sag uns doch, wie es kommt, dass uns so ein Unheil [geschieht]! Was [ist] dein Beruf und woher kommst du? Was [ist] dein Land und von welchem Volk [bist] du?“');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 1, 9, 'Da entgegnete (sagte) er {zu ihnen}: „Ich [bin] ein Hebräer und verehre (fürchte) JHWH, den Gott des Himmels, der das Meer und das Land (Festland) erschaffen hat.“');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 1, 10, 'Da gerieten die Männer in große Furcht und sagten zu ihm: „Warum hast du das getan?“Denn die Männer wussten, dass er \'\'vor JHWH \'\' auf der Flucht war, weil er [es] ihnen erzählt hatte.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 1, 11, 'Da (also) sagten sie zu ihm: „Was müssen wir mit dir tun, damit das Meer sich beruhigt [und] von uns [ablässt]?“Denn das Meer stürmte immer heftiger.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 1, 12, 'Da sagte er zu ihnen: „Ergreift mich und werft mich ins Meer, dann wird das Meer sich beruhigen [und] von euch [ablassen]! Denn ich weiß, dass dieser große Sturm meinetwegen über euch [gekommen ist].“');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 1, 13, 'Stattdessen (und) ruderten die Männer mit aller Kraft, um zurück ans Festland zu kommen ([das Schiff] zurück... zu bringen), aber sie schafften [es] nicht, denn das Meer stürmte immer heftiger auf sie ein.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 1, 14, 'Da schrien sie zu JHWH {und sprachen}: „Bitte (Ach), JHWH, wir wollen doch nicht umkommen wegen des Lebens (der Seele) dieses Mannes! {und} Rechne uns kein unschuldiges Blut an, denn \'\'du\'\', (denn du [bist]) JHWH, tust (hast du getan), wie es dir gefällt (gefallen hat)!“');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 1, 15, 'Da ergriffen sie Jona und warfen ihn ins Meer, und das Meer beruhigte sich von seinem Toben,');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 1, 16, 'und die Männer gerieten in große Furcht (Ehrfurcht) vor JHWH, sodass (und) sie JHWH ein Opfer darbrachten und Gelübde ablegten.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 1, 17, '');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 2, 1, 'Da (und) bestellte (bestimmte, schickte; hatte bestimmt) JHWH einen großen Fisch, um (damit) Jona zu verschlingen (verschlucken), und Jona war im Bauch des Fisches drei Tage und drei Nächte.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 2, 2, 'Da (und) flehte (betete) Jona zu JHWH, seinem Gott, aus dem Bauch des Fisches,');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 2, 3, 'und er sprach: Ich rief aus meiner Not (Angst, Bedrängnis) zu JHWH Und er antwortete mir. Aus dem Bauch der Unterwelt (des Scheol) schrie ich um Hilfe - Du hörtest meine Stimme (Rufen; was ich sagte).');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 2, 4, '{und} Du warfst (hattest geworfen) mich [in die] Tiefe, Mitten ins Meer, Und eine Strömung ([die] Fluten) umschloss (umgab) mich, All deine Brecher (Wogen, Wellen) und {deine} Wellen (Wogen) (brechenden Wellen) überrollten (gingen über) mich.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 2, 5, 'Und ich sagte (dachte): Ich bin verstoßen (verbannt, vertrieben) aus deiner Sicht (Nähe, Augen). Dennoch (doch; wie) werde ich wieder {zu} deinen heiligen Tempel (den Tempel, dein Heiligtum) anschauen (sehen, erblicken).');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 2, 6, 'Wasser umgaben mich bis an die Kehle (die Seele, das Leben), Der Ozean bedrängte mich, Seetang war um meinen Kopf geschlungen.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 2, 7, 'Bis zum Untersten der Berge sank ich hinab, Der Erde Riegel [sind] für immer, Aber Du hast mein Leben herausgeführt aus der Grube, JHWH, mein Gott!');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 2, 8, 'Als meine Seele am Verschmachten war, Da dachte ich an JHWH, Und mein Gebet ging ein bei dir, Im Tempel, deinem Heiligtum.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 2, 9, 'Die völlig Nichtiges verehren, Die verlassen ihre Gnade.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 2, 10, 'Ich aber will mit der Stimme des Dankes Dir opfern, Was ich gelobt habe, will ich vollenden, Rettung [ist] bei JHWH! Da sprach JHWH zu dem Fisch, und er spie {den} Jona aus auf das trockene Land (Festland).');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 3, 1, 'Und es geschah das Wort JHWH s zu Jona zum zweiten Mal {folgendermaßen}:');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 3, 2, 'Stehe auf, gehe nach Ninive, der großen Stadt, und rufe ihr die Botschaft zu, die ich dir sage (n werde).');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 3, 3, 'Und Jona stand auf und ging nach Ninive, dem Wort JHWH s gemäß, aber Ninive war eine große Stadt vor (für) Gott, drei Tagesreisen [weit] (lang).');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 3, 4, 'Und Jona begann, in die Stadt hineinzugehen eine Tagesreise [weit] und rief und sprach: Noch vierzig Tage, und Ninive wird umgestürzt (werden).');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 3, 5, 'Da glaubten die Menschen von Ninive an Gott und riefen ein Fasten aus und zogen Säcke (Bußgewänder) an, von ihren Großen bis zu ihren Kleinen.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 3, 6, 'Als (und) die Angelegenheit vor den König von Ninive kam, da erhob er sich vom Thron, löste seinen Mantel ab, bekleidete sich mit einem Sack (Bußgewand) und setzte sich in den Staub.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 3, 7, 'Und er ließ ausrufen und sagen über Ninive: Auf Befehl des Königs und seiner Fürsten (Großen) {folgendermaßen}: Der Mensch und der Esel, das Rind und das Kleinvieh sollen überhaupt nichts genießen, sollen nicht weiden und vom Wasser nicht trinken.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 3, 8, 'Da bekleideten sich mit Säcken (Bußgewändern) die Menschen und die Esel und sie riefen zu Gott mit Gewalt und ein jeder bekehrte sich von seinem bösen Weg und von der Gewalttat, die in seinen Händen ist.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 3, 9, 'Wer weiß, [vielleicht] kehrt sich {der} Gott um und er verliert die Lust (es gereut ihn) und er wird sich abwenden von seinem hitzigen Zorn und wir werden nicht zugrunde gehen.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 3, 10, 'Da sah Gott ihre Taten, dass sie umkehrten vom bösen Weg, und es gereute Gott bezüglich des Übels, wovon er gesagt hatte, dass er es ihnen antun würde, und tat es nicht.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 4, 1, 'Aber Jona geriet in große Bosheit und wurde zornig:');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 4, 2, 'Da betete er zu JHWH und sagte: Ach JHWH, sind das nicht meine Worte [gewesen], als ich in meinem Land war, weshalb ich [dem] zuvorgekommen bin, indem ich nach Tarschisch floh, denn ich wusste, dass du gnädig, barmherzig, langmütig und von großer Güte bist und dass du des Übels gereust.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 4, 3, 'Und jetzt, JHWH, nimm doch mein Leben von mir, denn mein Tod ist besser als mein Leben.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 4, 4, 'Da sprach JHWH: Bist du mit Recht zornig?');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 4, 5, 'Da zog Jona aus der Stadt und ließ sich im Osten der Stadt nieder und machte sich dort eine Hütte und ließ sich nieder unter ihr im Schatten, {solange} bis er sähe, was in der Stadt passiert.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 4, 6, 'Und JHWH der Herr ließ eine Rizinusstaude wachsen und sie wuchs über Jona hinaus, sodass sie zum Schatten wurde über seinem Kopf und seine Bosheit von ihm nahm. Und Jona freute sich sehr über die Rizinusstaude.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 4, 7, 'Aber Gott ließ einen Wurm wachsen am Morgen bei Sonnenaufgang, und er befiel die Rizinusstaude, und sie ging ein.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 4, 8, 'Und es geschah, dass die Sonne aufging, und JHWH ließ einen glühend heißen sengenden Ostwind aufkommen, und die Sonne brannte auf Jonas Kopf, und er fiel in Ohnmacht, da wünschte er für sich zu sterben und sprach: Mein Tod ist besser als mein Leben.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 4, 9, 'Und Gott sprach zu Jona: Bist du mit Recht zornig? (Du bist aber richtig zornig!) Und er sprach: Es ist richtig, dass ich zornig bin (Ich bin richtig zornig), bis zum Tod!');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 4, 10, 'Da sprach JHWH: Du bist betrübt wegen der Rizinusstaude, um welche du dich nicht abgemüht hast, und die du nicht groß gemacht hast, die als Sohn einer Nacht entstand und als Sohn einer Nacht zugrunde ging.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 4, 11, 'Und ich sollte nicht betrübt sein wegen der großen Stadt Ninive, in der sind 120.000 Menschen, die nicht unterscheiden können zwischen ihrer Rechten und ihrer Linken, und viele Tiere.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 1, 1, '');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 1, 2, 'Hört, Völker ihr alle, merke auf Erde und was sie füllt. Der Herr JHWH wird Zeuge sein gegen euch, der Herr aus seinem heiligen Palast.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 1, 3, 'Führwar siehe: JHWH ist einer, der ausgeht von seiner Stätte, hinabsteigt und schreitet auf den Höhen der Erde.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 1, 4, 'Und die Gipfel schmelzen unter ihm und die Täler spalten sich, wie Wachs im Angesicht des Feuers, wie Wasser ausgeschüttet am Abgrund.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 1, 5, 'Wegen des Verbrechens Jakobs [geschieht] all dies und wegen der Sünde des Hauses Israels. Was ist das Verbrechen Jakobs? Ist es nicht Samaria? Und was sind die Anhöhen Judas? Ist es nicht Jerusalem?');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 1, 6, 'Und ich werde machen Samria zum Trümmerfeld, zu einer Weinbergpflanzung und ich werde stoßen ins Tal seine Steine und seine Grundfesten offenlegen.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 1, 7, 'Und alle ihre Kultbilder (Schnitzbilder) werden zerschlagen werden und alle ihre Geschenke (Löhne) werden verbrannt werden mit Feuer und alle seine Götzenbilder werde ich verwüsten, denn von Hurengeschenk hat sie gesammelt und zu Hurengeschenk sollen sie wieder werden.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 1, 8, 'Über dies (Darüber) will ich wehklagen und heulen, ich will gehen barfuß und nackt. Ich will Totenklage halten wie die Schakale und Trauer wie die Töchter der Strauße.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 1, 9, 'Denn unheilbar ist ihr Schlag, ja, er ist bis nach Juda gekommen, er reicht bis an das Tor meines Volkes, bis Jerusalem.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 1, 10, '');
