INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 3, 20, '');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 1, 1, 'Im zweiten Jahr des Königs Darius, im sechsten Monat, am ersten Tag des Monats, geschah das Wort JHWH s durch die Hand des Propheten Haggai zu Serubbabel, dem Sohn Schealtiëls, dem Pächa von Juda und zu Jeschua, dem Sohn Jozadaks, dem Hohenpriester {folgendermaßen}:');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 1, 2, 'So spricht JHWH der Heerscharen (Zebaot) {folgendermaßen}: Dieses Volk spricht: Die Zeit ist nicht gekommen, das Haus JHWH s zu erbauen.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 1, 3, 'Und es geschah das Wort JHWH s durch die Hand des Propheten Haggai {folgendermaßen}:');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 1, 4, 'Ist für euch selber Zeit in getäfelten Häusern zu wohnen und dieses Haus ist verwüstet?');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 1, 5, 'Und nun, so spricht JHWH der Heerscharen (Zebaot): Richtet euer Herz auf eure Wege!');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 1, 6, 'Ihr habt viel gesät, aber wenig hineingeführt; ihr esst, aber werdet nicht satt; ihr trinkt, aber seid doch durstig; ihr kleidet euch, aber werdet nie warm; und der Tagelöhner erwirbt Lohn in einen durchlöcherten Beutel.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 1, 7, 'So spricht JHWH der Heerscharen (Zebaot): Richtet euer Herz auf eure Wege!');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 1, 8, 'Steigt hinauf zum Berg und bringt Holz und baut das Haus und ich werde Wohlgefallen daran haben und mich verherrlichen, spricht JHWH.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 1, 9, 'Zu vielen habt ihr euch gewandt und siehe, es war wenig; und ihr brachtet es zum Haus und ich blies in es. Weshalb? Ausspruch JHWH s der Heerscharen (Zebaot). Wegen meines Hauses, das verwüstet [ist] und ihr rennt - jeder zu seinem Haus.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 1, 10, 'Deshalb, euretwegen, hat der Himmel den Tau zurückgehalten und die Erde hat ihren Ertrag zurückgehalten.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 1, 11, 'Und ich habe eine Dürre gerufen über das Land und über die Berge und über das Korn und über den Most und über das frische Olivenöl und über das, was die Erde hervorgehen lässt und über den Menschen und über das Vieh und über alle Arbeit der Hände.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 1, 12, 'Und [es] hörte Serubbabel, der Sohn Schealtiëls, und Jeschua, der Sohn Jozadaks, der Hohepriester und der ganze Rest des Volkes auf die Stimme JHWH s, ihres Gottes, und auf die Worte des Propheten Haggai, wie ihn JHWH, ihr Gott, sandte und das Volk fürchtete sich vor JHWH.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 1, 13, 'Und Haggai, der Bote JHWH s, sprach in der Botschaft (Auftrag) JHWH s, zum Volk {folgendermaßen}: Ich bin mit euch, Ausspruch JHWH s.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 1, 14, 'Und JHWH erweckte den Geist Serubbabels, des Sohnes Schealtiëls, des Pächa von Juda und den Geist Jeschuas, des Sohnes Jozadaks, des Hohenpriesters und den Geist des ganzes Rests des Volkes und sie kamen und sie machten die Arbeit am Haus JHWHs der Heerscharen (Zebaot), ihres Gottes,');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 1, 15, 'am vierundzwanzigsten Tag des sechsten Monats im zweiten Jahr des Königs Darius.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 2, 1, 'Im siebten [Monat], am einundzwanzigsten des Monats, geschah das Wort JHWH s durch die Hand des Propheten Haggai {folgendermaßen}:');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 2, 2, 'Sage doch zu Serubbabel, dem Sohn Schealtiëls, dem Pächa von Juda und zu Jeschua, dem Sohn Jozadaks, dem Hohenpriester und zu dem Rest des Volkes {folgendermaßen}:');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 2, 3, 'Wer ist unter euch übrig geblieben, der dieses Haus gesehen hat in seiner früheren Herrlichkeit? Und wie seht ihr es nun? Ist es nicht wie nichts in euren Augen?');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 2, 4, 'Und nun sei stark Serubbabel, Ausspruch JHWH s, und sei stark Jeschua, Sohn Jozadaks, du Hohepriester und sei stark alles Volk des Landes! Ausspruch JHWHs. Und arbeitet, denn ich bin mit euch, Ausspruch JHWHs der Heerscharen (Zebaot).');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 2, 5, 'Das Wort, das ich mit euch vereinbarte als ihr aus Ägypten auszogt und mein Geist bleiben in eurer Mitte; fürchtet euch nicht!');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 2, 6, 'Denn so spricht JHWH der Heerscharen (Zebaot): Noch einmal – wenig [ist] es – und ich werde erschüttern lassen den Himmel und die Erde und das Meer und das Trockene!');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 2, 7, 'Und ich lasse erschüttern alle Völker und die Kostbarkeiten aller Völker werden kommen und ich werde dieses Haus mit Herrlichkeit erfüllen, spricht JHWH der Heerscharen (Zebaot).');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 2, 8, 'Mein ist das Silber und mein ist das Gold, Ausspruch JHWH s der Heerscharen (Zebaot).');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 2, 9, 'Größer wird die Herrlichkeit dieses künftigen Hauses sein als die des früheren, spricht JHWH der Heerscharen (Zebaot), und an diesem Ort werde ich Frieden geben, Ausspruch JHWH s der Heerscharen (Zebaot).');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 2, 10, 'Am vierundzwanzigsten des neunten [Monats], im zweiten Jahr des Darius, geschah das Wort JHWH s zum Propheten Haggai {folgendermaßen}:');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 2, 11, 'So spricht JHWH der Heerscharen (Zebaot): Bittet doch die Priester um Weisung {folgendermaßen}:');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 2, 12, 'Wenn ein Mann heiliges Fleisch am Saum seines Kleides trägt und berührt mit seinem Saum Brot und Gekochtes und Wein und Öl und alle Speise, wird es [dann] heilig? Und die Priester antworteten und sie sprachen: Nein.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 2, 13, 'Und Haggai sprach: Wenn er, unrein durch einen Toten, dies alles berührt, wird es unrein? Und die Priester antworteten und die sprachen: Es wird unrein.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 2, 14, 'Und Haggai antwortete und sprach: So ist dieses Volk und so diese Nation vor mir, Ausspruch JHWH s, und so ist alles Tun ihrer Hände und was sie dort opfern – unrein ist es!');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 2, 15, 'Und nun, richtet doch euer Herz von diesem Tag [an] und weiterhin! Bevor Stein auf Stein gelegt wurde am Tempel JHWH s,');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 2, 16, 'wie ging es euch? [Einer] kam zu einem Getreidehaufen [von] zwanzig und er war zehn; [einer] kam zur Kelter um [davon] fünfzig Pura zu schöpfen und es war zwanzig.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 2, 17, 'Ich schlug euch mit Getreidebrand und mit Gelbwerden und mit Hagel, alle Arbeit eurer Hände, und ihr [seid] nicht zu mir [gekommen], Ausspruch JHWH s.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 2, 18, 'Richtet doch euer Herz von diesem Tag [an] und weiterhin! Vom vierundzwanzigsten Tag des neunten [Monats an], von diesem Tag [an], als der Tempel JHWH s gegründet wurde, richtet euer Herz!');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 2, 19, 'Ist die Saat noch in der Scheune? Und haben {bis} die Rebe und der Feigenbaum und der Granatbaum und der Ölbaum [noch] nicht getragen? Von diesem Tag [an] werde ich segnen.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 2, 20, 'Und das Wort JHWH s geschah zum zweiten Mal zu Haggai am vierundzwanzigsten des Monats:');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 2, 21, 'Sprich zu Serubbabel, dem Pächa von Juda: Ich werde erschüttern den Himmel und die Erde');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 2, 22, 'und werde umstürzen den Thron der Königreiche und werde vernichten die Stärke der Königreiche der Völker und werde umstürzen den Streitwagen und seinen Fahrer, Pferde und ihre Reiter stürzen; jeder durch das Schwert seines Bruders.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 2, 23, 'An jenem Tage, Ausspruch JHWH s der Heerscharen (Zebaot), nehme ich dich, Serubbabel, du Sohn Schealtiëls, meinen Knecht, Ausspruch JHWH s, und mache dich wie einen Siegelring (Siegel), denn ich habe dich erwählt, Ausspruch JHWH s der Heerscharen (Zebaot).');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 1, 1, 'Im achten Monat des zweiten Jahres des Darius geschah das Wort JHWH s zu Sacharja, dem Sohn Berechjas, des Sohns Iddos, dem Propheten {folgendermaßen}:');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 1, 2, 'JHWH zürnt Zorn gegen (über) eure Väter.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 1, 3, 'Und du sollst zu ihnen sprechen: So spricht JHWH der Heerscharen (Zebaot): Kehrt um zu mir, Ausspruch JHWH s der Heerscharen (Zebaot), und ich kehre um zu euch, spricht JHWH der Heerscharen (Zebaot).');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 1, 4, 'Seid nicht wie eure Väter, denen die ersten (früheren) Propheten zuriefen {folgendermaßen}: So spricht JHWH der Heerscharen (Zebaot): Kehrt doch um von euren bösen (schlechten) Wegen und von euren bösen (schlechten) Taten! Aber sie hörten nicht und merkten nicht auf micht, Ausspruch JHWH s.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 1, 5, 'Eure Väter, wo [sind] sie? Und die Propheten, leben sie ewig?');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 1, 6, 'Jedoch meine Worte und meine Ziele (Vorhaben), die ich meinen Dienern (Sklaven), den Propheten befahl, erreichten sie eure Väter nicht? Und sie kehrten um und sie sprachen: wie JHWH der Heerscharen (Zebaot) dachte (sann, trachtete) mit uns uns zu handeln (machen, tun) nach (wie) unseren Wege und nach (wie) unseren Handlungen, so tat (handelte, machte) er mit uns.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 1, 7, 'Am vierundzwandzigsten Tag des elften Monats, welcher ist der Monat Schebat, im zweiten Jahr des Darius geschah das Wort JHWH s zu Sacharja, dem Sohn Berechjas, des Sohns Iddos, dem Propheten {folgendermaßen}:');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 1, 8, 'ich sah nachts (in der Nacht), und siehe, ein Mann reitend auf einem roten Pferd und er blieb stehen zwischen den Myrten, die aus der Tiefe (Talgrund), und hinter ihm [waren] rote, hellrote und weiße Pferde.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 1, 9, 'Und ich sprach: Was [sind] diese, mein Herr? Und der Engel (Bote), der mit mir redete, sprach zu mir: Ich selbst zeige dir, wer diese [sind].');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 1, 10, 'Und der Mann, der zwischen den Myrten stehen blieb, antwortete und er sprach: Diese [sind es], welche JHWH geschickt (senden) hat, um auf der Erde (Welt, Land) umherzugehen.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 1, 11, 'Und sie antworteten dem Engel (Boten) JHWH s, der zwischen den Myrten stehen blieb, und sie sprachen: Wir sind auf [der] Erde (Welt, Land) umhergegangen, und siehe: die ganze Erde (Welt, Land) sitzt still (ist bewohnt) und ruht.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 1, 12, 'Und der Engel (Bote) JHWH s antwortete und sprach: JHWH der Heerscharen (Zebaot), wie lange erbarmst du dich nicht über Jerusalem und über die Städte Judas, welchen du zürnst diese siebzig Jahre.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 1, 13, 'Und JHWH antwortete dem Engel (Boten), der mit mir redete, Worte des Guten, Worte der (von) Tröstungen.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 1, 14, 'Und der Engel (Bote), der mit mir redete, sprach zu mir: Rufe (Schreie) {folgendermaßen}: So spricht JHWH der Heerscharen (Zebaot): Ich eifere für Jerusalem und für Zion [mit] großer Leidenschaft.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 1, 15, 'und [mit] großem Zorn zürne ich über (gegen) die stolzen (sorglosen, übermütigen) Völker, die, [als] ich wenig zürnte, aber haben jenen zur Bosheit (Unheil) geholfen.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 1, 16, 'Deshalb, so spricht JHWH: Ich bin umgekehrt zu Jerusalem in Erbarmen; mein Haus werde ich darin bauen, Ausspruch JHWH s der Heerscharen (Zebaot), und die Messschnur ausbreiten (erstrecken) über Jerusalem.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 1, 17, 'Rufe (Schreie) weiter {folgendermaßen}: So spricht JHWH der Heerscharen (Zebaot): Meine Stadt soll doch wieder überfließen von Gutem; und JHWH tröstet [immer] noch Zion, und erwählt [immer] noch {aus} Jerusalem.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 1, 18, '');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 1, 19, '');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 1, 20, '');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 1, 21, '');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 2, 1, 'Und ich erhob (tat auf) meine Augen und ich sah und siehe: vier Hörner.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 2, 2, 'Und ich sprach zu dem Engel (Boten), der mit mir redete: „Was [sind] diese?“Und er sprach zu mir: „Dies [sind] die Hörner, die Juda, Israel und Jerusalem zerstreut haben.“');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 2, 3, 'Und JHWH ließ mich vier Handwerker (Schmiede, Arbeiter) sehen.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 2, 4, 'Und ich sprach: „Was wollen diese tun (machen)?“Und er sprach {folgendermaßen}: „Dies [sind] die Hörner, die Juda [so] zerstreut haben, dass kein Mann (niemand) seinen Kopf erhob; und diese kamen um sie zu schrecken (in Schrecken zu versetzen), um niederzuwerfen die Hörner der Völker, die ein Horn zum Land Juda tragen um es zu zerstreuen.“');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 2, 5, 'Und ich erhob (tat auf) meine Augen und sah und siehe: ein Mann und in seiner Hand [war] eine Messschnur.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 2, 6, 'Und ich sprach zu ihm: „Wohin gehst du?“Und er sprach zu mir: „Jerusalem einzuüben (zu lernen) um zu sehen wie groß seine Breite und wie groß seine Länge [ist].“');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 2, 7, 'Und siehe: ein Engel (Bote), der mit mir redete, ging hinaus. Und ein zweiter Engel (Bote) ging hinaus ihm entgegen.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 2, 8, 'Und er sprach zu ihm: „Laufe, rede zu diesem Jungen {folgendermaßen}: »Jerusalem soll ein offenes Land bleiben wegen der vielen Menschen und Vieh in seiner Mitte.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 2, 9, 'Und ich werde für es, Ausspruch JHWH s, eine Feuermauer ringsumher sein und ich werde zur Herrlichkeit in seiner Mitte.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 2, 10, 'Auf (Wehe), auf (wehe), {und} flieht aus dem Land des Nordens, Ausspruch JHWH s! Denn wie (mit, gemäß) [die] vier Winde des Himmel habe ich euch zerstreut (ausgebreitet), Ausspruch JHWH s.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 2, 11, 'Auf (Wehe), Zion, entkomme (rette dich), die du [bei der] Tochter Babels wohnst (lebst, sitzt)!');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 2, 12, 'Denn so spricht JHWH Zebaot: Zur (nachdem, nach, mit, dessen) Herrlichkeit (Wichtigkeit) hat (hatte) er mich zu den Völkern gesandt, die euch geplündert hatten (ausplündern, berauben). Denn (ja) wer (diejenigen, die) {in} euch schlägt (anrührt), schlägt (rührt an) {in} seinen [eigenen] Augapfel.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 2, 13, 'Denn {siehe}, [ich] schüttle (schwinge, erhebe) meine Hand gegen sie, so dass (und) sie eine Beute für ihre Sklaven (Knechte, die ihnen dienen) werden {werden}, damit (so dass, dann, und) ihr erkennen (wissen) werdet, dass JHWH Zebaot mich gesandt hat. Rufe laut aus und freue dich, Tochter Zions, denn {siehe}, ich komme (werde kommen), um (und) in eurer Mitte zu bleiben (wohnen), Ausspruch JHWH s. Dann (und) werden sich viele Völker {zu} JHWH [gemeinsam] anschließen an jenem Tag, und (dann, so dass) sie werden mein Volk sein (werden) und (dann, so dass; aber) ich werde in deiner Mitte wohnen und (dann, so dass) du wirst erkennen (wissen), dass JHWH Zebaot mich zu dir gesandt hat. Dann (und) wird JHWH Juda in Besitz nehmen (erben) [als] seinen Anteil (Erbe, Gebiet, Belohnung) in (auf) dem heiligen Land, und er wird {in} Jerusalem wieder (erneut) erwählen. Pst ([Sei] still), alles Fleisch, vor (in der Gegenwart, vor dem Gesicht) JHWH! Denn er hat sich von seinem heiligen Wohnort aufgemacht (macht sich auf)!«“');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 3, 1, 'Und er ließ mich sehen (zeigte mir) Jeschua, den Hohenpriester, der stand vor {dem Angesicht} dem Engel (Bote) JHWH s; und auch {der} Satan stand auf seiner rechten Seite (zu seiner Rechten) um ihn anzuklagen.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 3, 2, 'Und JHWH sprach zu {dem} Satan: JHWH bedrohe (schelte, schreie dich an) dich, Satan! {Und} JHWH bedrohe (schelte, schreie dich an) dich, der auserwählt hat (erwählt hat) Jerusalem! Ist dieser nicht ein Holzscheit (Brandscheit), das herausgezogen wurde vom Feuer?');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 3, 3, 'Aber Jeschua war bekleidet (angezogen) mit schmutzigen Gewändern (Kleidern); und er stand vor {dem Angesicht} dem Engel (Bote).');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 3, 4, 'Und er antwortete und sprach zu denen, die vor ihm (vor seinem Angesicht) standen {folgendermaßen}: Entfernt (lasst weichen) die schmutzigen Gewänder (Kleider) von ihm! Und er sprach zu ihm: Schau (siehe)! Ich habe weggenommen (hinübergehen lassen, vergeben) von dir deine Sünde und bekleide (ziehe dich an) dich mit Festgewändern (Feierkleidern).');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 3, 5, 'Und ich sprach: Man setze {ihm} einen reinen Kopfbund (Turban) auf seinen Kopf (Haupt)! Und sie setzten den reinen Kopfbund (Turban) auf seinen Kopf (Haupt) und bekleideten ihn mit Gewändern (Kleidern); während auch der Engel (Bote) JHWH s [dabei] stand.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 3, 6, 'Und der Engel (Bote) JHWH s versicherte (beteuerte, bezeugte) Jeschua {folgendermaßen}:');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 3, 7, 'So spricht JHWH der Heerscharen (Zebaot): Wenn du auf meinen Wegen gehen wirst und wenn du meine Anordnungen ausführen (befolgen, bewahren) wirst, [dann] wirst du sowohl richten (zu seinem Recht verhelfen) mein Haus als auch behüten (schützen, bewachen) meine Vorhöfe und ich werde dir geben Zugang zwischen diesen, die [hier] stehen.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 3, 8, 'Höre doch, Jeschua, Hoherpriester - du und deine Freunde (Standesgenossen, Gefährten), die vor dir sitzen! Denn Männer des Wunders [sind] diese. Denn siehe, ich lasse meinen Knecht, den Spross kommen!');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 3, 9, 'Denn siehe, der Stein, den ich vor Jeschua gegeben habe: auf einem Stein [sind] sieben Augen. Siehe, ich graviere eine Gravur in (auf) ihn ein, Ausspruch JHWH s der Heerscharen (Zebaot), und ich lasse von der Sünde dieses Landes ab an einem Tag.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 3, 10, 'An einem Tag, Ausspruch JHWH s der Heerscharen (Zebaot), werdet ihr einander einladen unter einem Weinstock und unter einem Feigenbaum.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 4, 1, 'Und der Engel (Bote), der mit mir redete, kehrte zurück und er weckte mich, wie einen Mann, der aus seinem Schlaf erweckt wurde.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 4, 2, 'Und er sprach zu mir: Was siehst du? Und ich sprach: Ich sehe und siehe, ein Leuchter ganz aus Gold und seine Schale (Ölgefäß) auf seinem Haupt (Kopf) und seine sieben Lampen auf ihm, sieben und (mal) sieben Schnauzen (Gießgefäße) für die Lampen, die auf seinem Haupt (Kopf) [sind].');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 4, 3, 'Und zwei Ölbäume über ihm, einer zur Rechten der Schale (Ölgefäß) und einer an seiner Linken.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 4, 4, 'Und ich antwortete und sprach zu dem Engel (Bote), der mit mir redete, {folgendermaßen}: Was [sind] diese, mein Herr?');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 4, 5, 'Und der Engel (Bote), der mit mir redete, antwortete und er sprach zu mir: Hast du nicht erkannt (Weißt du nicht), was diese [sind]? Und ich sprach: Nein, mein Herr.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 4, 6, 'Und er antwortete und er sprach zu mir {folgendermaßen}: Dies ist das Wort JHWH s an Serubbabel {folgendermaßen}: Nicht durch {ein} Heer und nicht durch Kraft, sondern durch meinen Geist, spricht JHWH Zebaot.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 4, 7, 'Wer bist du, großer Berg? Vor Serubbabel [wirst du] zur Ebene. Und er bringt hervor den Schlussstein, [unter] Zuruf (Lärm, Geschrei): Gnade, Gnade für ihn!');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 4, 8, 'Und das Wort JHWH s geschah zu mir {folgendermaßen}:');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 4, 9, 'Die Hände Serubbabels haben dieses Haus gegründet und seine Hände werden [es] vollenden und du wirst erkennen, dass JHWH Zebaot mich zu euch gesandt hat.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 4, 10, 'Denn wer verachtet den Tag der Kleinen (Kleinigkeiten)? Und sie werden sich freuen und den Stein des Bleilots (Senkblei) sehen in der Hand Serubbabels. Diese sieben [sind] die Augen JHWH s - jene schweifen auf der ganzen Erde (Land) umher.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 4, 11, 'Und ich antwortete und sprach zu ihm: Was [sind] diese zwei Ölbäume auf der Rechten des Leuchters und auf seiner Linken?');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 4, 12, 'Und ich antwortete zum zweiten Mal und ich sprach zu ihm: Was [sind] die zwei Ähren (Zweigspitzen) der Ölbäume, die in der Hand der zwei goldenen Röhren [sind], die das Gold aus ihnen gießen?');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 4, 13, 'Und er sprach zu mir: Erkennst du nicht, was diese [sind]? Und ich sprach: Nein, mein Herr.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 4, 14, 'Und er sprach: Diese zwei [sind] die Söhne des Öls, die beim Herrn der ganzen Erde (Land) stehen.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 5, 1, '');
