INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 1, 1, 'Äußerung [des] Wortes JHWH s an (für) Israel in der (durch die) Hand Maleachis.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 1, 2, 'Ich habe euch geliebt sagt JHWH ihr sagt: Wie (In was) hast du uns geliebt? War nicht dem Jakob ein Bruder Esau, Ausspruch JHWH s (spricht JHWH, Spruch). Und ich liebte den Jakob.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 1, 3, 'Aber Esau hasse ich, und seine Berge habe ich gemacht zu einer Wüste (einem Trümmerfeld, einer Einöde) und seinen Besitz (Eigentum, Erbschaft, Erbe) den Schakalen der Wüste.');
