INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 1, 1, '[Dies ist das] Buch des Ursprungs (des Stammbaums, der Entstehung) von Jesus Christus, dem Sohn von David, dem Sohn von Abraham.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 1, 2, 'Abraham zeugte (brachte hervor) Isaak, Isaak {aber} zeugte Jakob, [und] Jakob {aber} zeugte Juda und seine Brüder.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 1, 3, 'Juda {aber} zeugte Perez und Serach mit Tamar [als Mutter]. Perez {aber} zeugte Hezron, Hezron {aber} zeugte Aram,');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 1, 4, 'Aram {aber} zeugte Amminadab, Amminadab {aber} zeugte Nachschon, Nachschon {aber} zeugte Salmon,');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 1, 5, '[und] Salmon {aber} zeugte Boas mit Rahab [als Mutter]. Boas {aber} zeugte Obed mit Rut [als Mutter]. Obed {aber} zeugte Isai,');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 1, 6, '[und] Isai {aber} zeugte David, den König. David {aber} zeugte Salomo mit der Frau des Urija.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 1, 7, 'Salomo {aber} zeugte Rehabeam, Rehabeam {aber} zeugte Abija, Abija {aber} zeugte Asa,');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 1, 8, 'Asa {aber} zeugte Joschafat, Joschafat {aber} zeugte Joram, Joram {aber} zeugte Usija,');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 1, 9, 'Usija {aber} zeugte Jotam, Jotam {aber} zeugte Ahas, Ahas {aber} zeugte Hiskija,');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 1, 10, 'Hiskija {aber} zeugte Manasse, Manasse {aber} zeugte Amos, Amos {aber} zeugte Joschija,');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 1, 11, '[und] Joschija {aber} zeugte Jojachin und seine Brüder zur [Zeit der] Wegführung nach Babyloniën.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 1, 12, 'Nach der Wegführung {aber} nach Babyloniën zeugte Jojachin Schealtiël, Schealtiël {aber} zeugte Serubbabel,');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 1, 13, 'Serubbabel {aber} zeugte Abihud, Abihud {aber} zeugte Eljakim, Eljakim {aber} zeugte Azor,');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 1, 14, 'Azor {aber} zeugte Zadok, Zadok {aber} zeugte Achim, Achim {aber} zeugte Eliud,');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 1, 15, 'Eliud {aber} zeugte Eleasar, Eleasar {aber} zeugte Mattan, Mattan {aber} zeugte Jakob,');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 1, 16, 'Jakob {aber} zeugte (brachte hervor) Josef, den Mann von Maria, von der Jesus geboren (mit der Jesus gezeugt, mit der Jesus hervorgebracht) wurde, der Christus genannt wird.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 1, 17, 'All die Generationen [sind] demnach (also) von Abraham bis David 14 Generationen und von David bis zur Wegführung nach Babyloniën 14 Generationen und von der Wegführung nach Babyloniën bis Christus 14 Generationen.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 1, 18, 'Die Geburt Jesu Christi {aber} ereignete sich folgendermaßen (fand folgendermaßen statt): Seine Mutter Maria war mit Josef verlobt (Josefs Braut geworden, dem Josef vertraut). Bevor sie zusammengekommen waren (er sie heimgeholt hatte, sie einander ehelich beigewohnten, die Ehe eingangen waren), stellte sich heraus, dass sie vom Heiligen Geist schwanger geworden war (ein Kind erwartete, etwas in ihrem Bauch hatte).');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 1, 19, 'Josef {aber}, ihr Verlobter, [weil] er gerecht (rechtschaffen) war und sie nicht bloßstellen (öffentlich zur Schau stellen, als Ehebrecherin hinstellen) wollte, überlegte sich, sie heimlich fortzuschicken.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 1, 20, 'Während er dieses abwägte (überlegte), siehe, ein Engel des Herrn erschien ihm während eines Traums (traummäßig, in einer Traumerscheinung) und sagte: „Josef, Sohn Davids, scheue (fürchte) dich nicht [davor], Maria, deine Verlobte, zu dir zu nehmen (heimzuholen). Denn das in ihr Gezeugte ist vom Heiligen Geist.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 1, 21, 'Sie wird {aber} einen Sohn gebären und du sollst ihm den Namen Jesus geben. Er wird nämlich sein Volk von ihren Sünden retten.“');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 1, 22, 'Dies {aber} Ganze passierte (geschah, ereignete sich, trug sich zu), damit sich das vom Herrn durch einen Propheten Gesagte erfüllte. Er sagte (Jes 7,14):');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 1, 23, '„Siehe, eine Jungfrau ist schwanger (erwartet ein Kind, hat etwas in ihrem Bauch) und wird einen Sohn gebären und sie werden ihm den Namen Immanuël geben.“Das ist übersetzt: „mit uns [ist] Gott“');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 1, 24, 'Aus dem Schlaf aufgewacht {aber} handelte Josef so, wie ihm der Engel des Herrn befohlen hatte, und nahm seine Frau auf');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 1, 25, 'und erkannte sie nicht bis sie einen Sohn gebar. {Und} er nannte ihn Jesus.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 2, 1, 'Als {aber} Jesus geboren worden war in Betlehem in Judäa (im jüdäischen Betlehem) in den Tagen des Königs Herodes, siehe, da kamen Magier von (aus dem) Osten (vom Sonnenaufgang her) nach Jerusalem');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 2, 2, '[und] sagten: Wo ist der neugeborene König der Juden? Wir haben nämlich im Osten seinen Stern gesehen und sind gekommen, ihn anzubeten (ihm zu huldigen, uns ihm zu unterwerfen, seinen Kleidersaum berühren).');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 2, 3, 'Als {aber} der König Herodes das hörte, geriet er in Verwirrung (erschrak er) und die ganze [Stadt] Jerusalem (die Bewohner Jerusalems) mit ihm');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 2, 4, 'und er versammelte all die Hohenpriester und Schriftgelehrten (theologische Lehrer, Ausleger des Gesetzes) des Volks [und] erkundigte sich (brachte durch Erfragen in Erfahrung) bei ihnen, wo der Christus geboren werde.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 2, 5, 'Sie {aber} sagten ihm: „In Bethlehem in Judäa. Folgendermaßen ist es nämlich aufgeschrieben mittels eines Propheten:');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 2, 6, '»Und du, Bethlehem, im Land Juda, bist keineswegs unbedeutend unter den Stammesführern in Juda. Aus dir {nämlich} wird ein Führender ausgehen, der mein Volk Israel weiden wird.«“');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 2, 7, 'Daraufhin rief Herodes die Magier heimlich [zu sich] und ließ sich von ihnen akribisch genau den Zeitraum der Sichtbarkeit des Sterns mitteilen.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 2, 8, 'Und als er sie nach Bethlehem schickte, sagte er: „Reist (geht) [dorthin] und forscht akribisch genau über das Kind nach. Wenn ihr dann ({aber}) fündig geworden seid, berichtet mir [davon] (vermeldet es mir), damit auch ich komme und es fußfällig verehre.“');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 2, 9, 'Als sie {aber} den König gehört hatten, gingen sie, und siehe, der Stern, den sie im Aufgang (Osten, Morgenland) kannten, ging ihnen voran, {und} während er ankam, stellte er sich auf dort, wo das Kind war.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 2, 10, 'Als sie {aber} den Stern erblickten, freuten sie sich eine sehr große Freude (sie wurden von einer sehr großen Freude erfüllt).');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 2, 11, 'Und als sie in das Haus gingen, erkannten sie das Kind mit seiner Mutter Maria und, niederfallend, beteten sie es an, und als sie ihren Schatz (Schatzbehälter) öffneten, brachten (darbringen, herzubringen, hinbringen, überreichen, geben) sie ihm Geschenke (Opfergaben) dar, Gold und Weihrauch und Myrrhe.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 2, 12, 'Und gemäß (in) einem Traum wurde ihnen befohlen, nicht zu Herodes zurückzukehren, durch einen anderen Weg kehrten sie in ihr Land zurück.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 2, 13, 'Als sie aber weggingen {siehe} ein Engel des Herrn erschien gemäß (in) einem Traum dem Josef und sagte: Steh auf, nimm das Kind und seine Mutter mit und fliehe nach Ägypten und bleibe dort, bis ich dir sage! Denn Herodes beabsichtigt, dass Kind suchen zu lassen (und) es zu töten.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 2, 14, 'Und als er aufstand nahm er das Kind und seine Mutter des Nachts (zur Nachtzeit) mit sich und ging weg (entfernte sich) nach Ägypten.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 2, 15, 'Und er blieb dort bis zum Tode des Herodes; Auf daß vollendet würde was gesagt wurde vom Herrn durch den Propheten, der sagt: „Aus Ägypten rief (berief) ich meinen Sohn.“');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 2, 16, 'Zu der Zeit, als Herodes verstand, dass er hintergangen (getäuscht) wurde von den Magiern wurde er sehr Zornig und indem er aussandte (aussendend) tötete (vernichtete, beseitigte) er alle der Kinder in Betlehem und in {jedem seinem Gebiet} (seiner ganzen Umgebung) bis zu zwei Jahren und darunter (weniger an Alter), gemäß der Zeit, nach der er sich genau von den Magiern erkundigt hatte.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 2, 17, 'Damals (darauf) erfüllte sich, was gesagt wurde durch Jeremia den Propheten, der da sagt:');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 2, 18, 'Geschrei (Rufe) sind gehört worden in Rama, Weinen und viel (heftiges, lautes) Klagen (Wehklagen); Rahel beweint ihre Kinder, und nicht mag (will) sie sich trösten lassen denn sie sind nicht mehr da.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 2, 19, 'Als aber Herodes (starb) ein Ende nahm, siehe, ein Engel des Herrn erschien im Traum dem Josef in Ägypten');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 2, 20, 'der sagte: Steh auf, nimm das Kind und seine Mutter und gehe in das Land Israel; denn es ist tot, der dem Kind nach dem Leben trachtet');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 2, 21, 'Er (aber) stand auf, nahm das Kind und seine Mutter und ging in das Land Israel.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 2, 22, 'Hörend aber (Als er aber hörte), dass Archelaus König {ist} war der Juden statt (anstelle) seines Vaters Herodes, hatte er Angst dort hinzugehen; Da ihm im eine Weisung gegeben wurde {aber} im Traum ging er in das Gebiet Galliläas');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 2, 23, 'und als er kam lies er sich nieder in einer Stadt die genannt wurde (namens) Nazareth; dass (damit) vollendet wurde, was gesagt wurde durch die Propheten: „Er wird Nazarener (aus Nazareth) genannt werden“.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 3, 1, 'In jenen Tagen aber predigte (tritt auf, kommt) Johannes der Täufer (verkündend) in der Wüste von Judäa');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 3, 2, '[und] sprach (sagte): Bekehrt euch (Tut Buße, Denkt um), denn das Himmelreich (Reich der Himmel, Königsherrschaft der Himmel) ist nahe (hat sich genaht).');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 3, 3, 'Dieser nämlich ist es (der Gesagte), von dem (durch) Jesaja der Prophet sprach (sagend), als er sagte: Eine Stimme ruft (eines Rufenden) in der Wüste: Bereitet den Weg des Herrn, ebnet (Gerade macht) seine Pfade!');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 3, 4, 'Er aber, Johannes, hatte ein (sein) Kleid aus Kamelhaar und einen ledernen Gürtel um seine Hüften (Lenden); (aber) seine Nahrung (Speise) bestand aus (war) Heuschrecken und wildem Honig.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 3, 5, 'Da (Damals) zog (ging) zu ihm hinaus Jerusalem, und ganz Judäa und das ganze Umland (die ganze Umgebung) des Jordans,');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 3, 6, 'und sie ließen sich taufen (wurden getauft) im Fluß Jordan von ihm, weil (indem) sie ihre Sünden bekannten.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 3, 7, '(Aber) Als Johannes (sah dass) viele der Pharisäer und Sadduzäer zu seiner Taufe kommen sah (kamen), sagte er zu ihnen: Ihr Schlangenbrut (Brut von Giftschlangen, Nachkommen der Giftschlangen), wer hat euch denn gelehrt (bewiesen), dass ihr dem kommenden Gericht (Zorn) entrinnen könnt?');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 3, 8, 'Zeigt also, dass ihr eure Einstellung geändert habt!');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 3, 9, 'Und denkt nicht (Lasst Euch nicht einfallen) dass ihr zu euch selbst sagen könntet: Wir haben Abraham als Vater. Denn ich sage euch: (Es kann) Gott kann aus diesen Steinen dem Abraham Kinder erwecken (hervorbringen).');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 3, 10, 'Schon aber ist die Axt an die Wurzeln der Bäume gelegt; denn jeder Baum, der nicht gute Früchte (Frucht) hervorbringt, wird abgehauen und ins Feuer geworfen.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 3, 11, 'Ich taufe euch (zwar, einerseits) mit (in) Wasser zur Umkehr (Buße); der aber nach mir kommen wird, ist stärker als ich, und ich bin es nicht wert (nicht gut/genügend genug), ihm die Sandalen zu tragen (seine Sandalen aufzuheben); er wird euch mit (in) dem Heiligen Geist und Feuer taufen;');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 3, 12, 'seine Worfschaufel ist in seiner Hand (und) er wird seine Tenne gründlich säubern (reinigen) und seinen Weizen (Korn, Getreide) in der Scheune sammeln (zusammenbringen), aber die Spreu wird er verbrennen mit (durch) unauslöschlichem Feuer.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 3, 13, 'Dann (Zu dieser Zeit) kam Jesus von Galiläa (her) an den Jordan zu Johannes, um sich von ihm taufen zu lassen (um von ihm getauft zu werden).');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 3, 14, 'Johannes aber hinderte ihn (wehrte ihm) und sprach: Ich habe es nötig von dir getauft zu werden und du kommst zu mir?');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 3, 15, 'Jesus antwortete ihm jedoch: Lass es jetzt gut sein (geschehen)! Denn so gebührt (geziemt) es uns (Denn es ist recht, dass wir), alle (die ganze) Gerechtigkeit zu erfüllen. Da ließ er ihn gewähren (es geschehen).');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 3, 16, 'Als Jesus getauft war, stieg er sofort aus dem Wasser herauf (heraus); und siehe, da öffneten sich [ihm] die Himmel und er sah den Geist Gottes wie eine Taube auf ihn herabkommen.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 3, 17, 'Und siehe, es kam eine Stimme vom (aus dem) Himmel, die sprach: Dies ist mein geliebter Sohn, an dem ich Wohlgefallen habe.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 4, 1, 'Zu dieser Zeit (Damals) wurde Jesus hinaufgeführt in die Wüste von dem Geist, damit er versucht würde vom Teufel.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 4, 2, 'Und er fastete vierzig Tage und vierzig Nächte, danach litt er Hunger (hungerte er).');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 4, 3, 'Und es ging voran der Versucher (der Versuchende) und sagte (zu) ihm: Wenn du wirklich (Vorausgesetzt, dass du) Sohn Gottes bist, sprich, dass (damit, so dass) diese Steine Brote werden.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 4, 4, 'Dieser aber antwortete: Es ist geschrieben (Es steht geschrieben): Nicht aufgrund von Brot allein wird der Mensch am Leben bleiben (leben, lebendig sein), sondern aufgrund jeden Wortes, das herauskommt (hinausgeht, sich verbreitet) durch den Mund Gottes.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 4, 5, 'Dann nahm ihn der Teufel mit sich in die heilige Stadt und stellte ihn auf den zum Tempel gehörenden (heiligen, geweihten) Rand (Abschluss, Zinne)');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 4, 6, 'und sagte (zu) ihm: Wenn du wirklich Sohn Gottes bist, wirf dich selbst hinunter; denn es steht geschrieben, dass er seine Engel befehlen wird für (über) dich und auf Händen werden sie dich tragen (heben) damit du nicht stößt an einem Stein deinen Fuß.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 4, 7, 'Jesus sagte ihm: Wieder (Weiterhin, Ferner) steht (ist) geschrieben: Du wirst (darfst) nicht versuchen den Herrn deinen Gott.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 4, 8, 'Wiederum nahm ihn der Teufel mit sich auf einen sehr hohen Berg und zeigte ihm alle Königreiche der Erde und ihre Herrlichkeit');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 4, 9, 'und sagte ihm: Diese werde ich dir alle geben, wenn du niederfallend mich anbetest (verehrst).');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 4, 10, 'Darauf sagte Jesus (zu) ihm: Gehe weg (fort), Satan; Denn es steht geschrieben: Den Herrn deinen Gott wirst (sollst) du anbeten und nur ihm dienen.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 4, 11, 'Dann lies von ihm ab (verlies ihn) der Teufel und siehe, Engel näherten sich (kamen herzu) und dienten ihm (umsorgten ihn, kümmerten sich um ihn).');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 4, 12, 'Aber als er hörte, dass Johannes gefangen genommen war (ausgeliefert/übergeben worden war), zog er sich zurück (ging er weg, entfernte er sich) nach Galiläa.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 4, 13, 'Und als er Nazareth verlies ging er (und) nahm seinen Wohnsitz in Kafarnaum, dass am Meer gelegen war (wohnte er in dem am See gelegenen Kafarnaum), im Gebiet von Sebulon und Naftali.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 4, 14, 'Damit erfüllt wurde das Gesagte durch Jesaja, den Propheten, der spricht:');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 4, 15, 'Land Sebulon und Land Naftali, zum See hin, gegenüber dem (auf der anderen Seite des) Jordan [gelegen], Galiläa der Völker (Nicht-Juden, Heiden) -');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 4, 16, 'Das Volk, das sitzt (wohnt) in Finsternis, hat ein großes Licht gesehen (erblickt), und denen, die sitzen (wohnen) in einem Gebiet (Land) und einem Schatten des Todes, ihnen ist ein Licht aufgegangen.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 4, 17, 'Seit dann (Von da an) fing Jesus an zu verkünden (bekanntzumachen) und zu sprechen: Kehrt um (tut Buße), denn nahe herbeigekommen ist die Königsherrschaft (das Reich) der Himmel.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 4, 18, 'Als er aber entlang des Galiläischen Meeres ging (wanderte), sah er zwei Brüder, Simon, den man Petrus nennt und Andreas, seinen Bruder, als sie Netze in den See warfen; denn sie waren Fischer.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 4, 19, 'und er sagte ihnen: Kommt her (auf!), hinter mich und ich werde euch machen zu Fischern der Menschen.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 4, 20, 'Diese aber ließen sofort die Netze zurück (und) folgten ihm nach (begleiteten ihn).');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 4, 21, 'Und von dort ging er weiter und sah zwei andere Brüder, Jakobus den (Sohn) des Zabedäus und Johannes, den Bruder von ihm (seinen Bruder), in dem Schiff mit Zabedäus, den Vater von ihnen (ihrem Vater), als sie ihre Netze in Ordnung brachten (zurechtbrachten), und berief sie (lud sie ein, rief sie an, sprach sie an).');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 4, 22, 'Diese aber ließen sofort das Schiff und ihren Vater zurück (und) folgten ihm nach (begleiteten ihn).');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 4, 23, 'Und er zog (ging) umher in ganz Galiläa, lehrte in ihren Synagogen, verkündigte das Evangelium (die Frohe Botschaft) vom Reich (der (Königs-) Herrschaft) und heilte jede (alle) Krankheit und jedes Gebrechen (Schwachheit) im Volk.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 4, 24, 'Und es (ver) breitete sich (ging aus) die Kunde (das Gerücht, die Nachricht) von ihm in ganz Syrien; und sie (man) brachten (zu) ihm alle Kranken, von verschiedensten (verschiedenartigen, mannigfachen) Gebrechen (Krankheiten) und Beschwerden (Qual, Pein) Gezeichnete [und] (von Dämonen) Besessene, Mondsüchtige (Epileptiker) und Gelähmte und er heilte sie.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 4, 25, 'Und es folgten ihm viele Leute (eine große (Volks-) Menge) aus Galiläa, der Dekapolis, aus Jerusalem, Judäa und jenseits vom Jordan.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 1, 'Aber als er die (Volks-) Menge sah, stieg er auf den Berg (ging hinauf) und setzte sich (nieder), seine Schüler (Jünger) traten (kamen) zu ihm.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 2, 'Er öffnete seinen Mund und lehrte sie {sagend}:');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 3, 'Glücklich (selig, reich, gesegnet, zu beneiden, zu beglückwünschen) sind die Armen (in) dem Geist, denn ihnen gehört (ihrer) (ist) die Herrschaft (Königreich) der Himmeln (das Himmelreich).');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 4, 'Glücklich sind die Trauernden (die traurig sind, die Kummer haben), denn sie werden getröstet werden.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 5, 'Glücklich sind die Sanftmütigen (Freundlichen, Gnädigen), denn sie werden die Erde erben (erlangen).');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 6, 'Glücklich sind, die hungern und dürsten (sehnsüchtig warten auf) nach Gerechtigkeit, denn sie werden gesättigt (sattgemacht, ernährt) werden.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 7, 'Glücklich sind die Barmherzigen (die Erbarmen erweisen, Mitleid haben), denn sie werden Barmherzigkeit erlangen (finden).');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 8, 'Glücklich sind die Reinen im Herzen, denn sie werden Gott sehen (schauen, bemerken, erkennen).');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 9, 'Glücklich die Frieden schaffen (schließen) (die Friedensstifter, die Friedlichen, die zum Frieden bereiten), denn sie werden Gottes Kinder (Söhne) heißen (genannt werden).');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 10, 'Glücklich sind, die um der Gerechtigkeit willen verfolgt werden, denn ihnen ist (gehört) die (Königs) Herrschaft (Reich) in den (der) Himmeln.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 11, 'Glücklich seid ihr, wenn sie euch meinetwegen schmähen (beschimpfen, Vorwürfe machen) und verfolgen und [lügend] viel Schlechtes reden gegen euch.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 12, 'Freut euch und jubelt, denn (weil) (dass) euer Lohn ist vielfältig (groß) in den Himmeln; So (derart, ebenso) haben sie nämlich [auch] die Propheten verfolgt, die vor euch waren.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 13, 'Ihr seid das Salz der Erde; wenn das Salz töricht (fade, geschmacklos) wird (sich als Torheit erweist), womit wird man salzen? (womit wird man es wieder salzig machen?, womit wird Gott salzen?) Zu nichts ist es noch nutze, außer (als dass) man es hinausschütte (hinauswirft) und es von den Menschen zertreten (verächtlich behandelt) werde.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 14, 'Ihr seid das Licht der Welt. Eine Stadt, die oben auf einem Berg liegt, kann nicht verborgen bleiben.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 15, 'Auch nicht zündet man eine Lampe (ein Licht) an und stellt sie (es) unter den Scheffel (Gefäß, Schüssel), sondern auf den Leuchter (Lampenständer); und sie leuchtet (denen) allen in dem Haus.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 16, 'So sollt ihr euer Licht leuchten lassen (soll euer Licht leuchten) vor den Menschen, damit sie sehen eure guten Taten (Werke) und preisen (ehren, rühmen) euren Vater im Himmel.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 17, 'Ihr sollt nicht denken (Meint nicht), (dass) ich sei gekommen, das Gesetz oder die Propheten aufzulösen (zerstören, abbrechen, annullieren, außer Kraft setzen); Ich bin nicht gekommen um aufzulösen (zerstören, abbrechen, annullieren, außer Kraft setzen), sondern um zu erfüllen (vollenden, abschließen).');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 18, 'Amen (wahrlich), denn ich sage euch: Bis vergehen (der) Himmel und (die) Erde soll vom Gesetz nicht ein einziges Jota oder ein einziges Häkchen (Strichlein) vergehen, bis (dies) alles geschieht (geschehen ist).');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 19, 'Wer also (den, wie gesagt) auflöst (außer Kraft setzt) auch nur eines (das kleinste) dieser Gebote, und sei es das kleinste, und so (derart, solches) lehrt die Menschen, der wird der Geringste (Kleinste) sein (genannt, berufen, gerufen) im Reich der Himmel (Himmelreich). Wer aber so (derart) tut (, was das Gebot verlangt) und so lehrt, der wird groß sein (berufen, genannt) im Reich der Himmel.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 20, 'Denn ich sage euch, dass (:) wenn euch nicht überfließend zuteil wird Gerechtigkeit, die der Schriftgelehrten und Pharisäer (diese nicht weit übertrifft), werdet ihr nicht ins Reich der Himmel (Himmelreich) hineinkommen.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 21, 'Ihr habt gehört, dass zu den Alten gesagt wurde: Du sollst nicht töten; wer aber tötet (mordet), der ist schuldig (festgehalten, verfallen) dem Gericht (sei dem Gericht übergeben).');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 22, 'Ich aber sage euch, dass (:) jeder (alle, die), der zürnt (zornig ist) seinem Bruder, ist schuldig (festgehalten, verfallen) dem Gericht (sei dem Gericht übergeben). (Und) Wer (Der) sagt zu seinem Bruder: Narr (Hohlkopf) („Du Trottel“), der ist verfallen dem Hohen Rat (lokalen Gericht) (sei dem Hohen Rat übergeben); (Und) wer (Der) sagt: Tor (Idiot) („Du Narr“), der sei (schuldig) der Feuerhölle (Hölle des Feuers) übergeben.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 23, 'Wenn du nun (also) bringst (darbringst, überreichst) deine Opfergabe zum (auf) Altar und dir dort einfällt (du dich dort erinnerst), dass dein Bruder etwas gegen dich hat,');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 24, 'dann lass deine Gabe dort vor dem Altar liegen (zurück) und geh (hin), versöhne dich zuerst mit deinem Bruder; und dann (darauf) [komm] bring deine Gabe dar.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 25, 'Verständige (Einige, Komme entgegen) dich mit deinem Gegner (Widersacher, Feind) [in einem Rechtsstreit] unverzüglich (schnell, bald, rasch), solange (während) du mit ihm unterwegs bist, damit er dich nicht dem Richter übergeibt und der Richter dem Gerichtsdiener und man dich ins Gefängnis wirft.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 26, 'Amen (Wahrlich), ich sage dir: Du wirst nicht herauskommen von dort, bis du den letzten Heller (Kupfermünze) bezahlt hast.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 27, 'Ihr habt gehört, dass gesagt wurde: Du sollst nicht ehebrechen!');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 28, 'Ich aber sage euch, dass (:) jeder, der eine Frau ansieht und sie begehrt (um sie zu begehren), hat schon Ehebruch mit ihr begangen in seinem Herzen.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 29, 'Wenn aber dein rechtes Auge dich zu Fall bringt (verführt), reiß es aus und wirf es von dir (weg); Es ist besser [für dich] (es ist von Vorteil), eines deiner (Körper-) Glieder geht verloren, als dass dein ganzer Leib in die Hölle geworfen wird.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 30, 'Und wenn deine rechte Hand dich zu Fall bringt (verführt), hau sie ab und wirf sie von dir (weg). Es ist besser [für dich] (es ist von Vorteil), eines deiner (Körper-) Glieder geht verloren, als dass dein ganzer Leib zur Hölle fährt (in die Hölle eingeht, hingeht).');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 31, 'Es wurde aber auch gesagt: Wer seine Frau entlässt (fortschickt, sich von ihr scheidet), soll ihr einen Scheidebrief geben.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 32, 'Ich aber sage euch, dass (:) jeder, der seine Frau entlässt, außer sie ist der Unzucht schuldig, treibt sie in den Ehebruch (tut, das die Ehe mit ihr gebrochen wird), und wer eine entlassene (geschiedene) Frau heiratet, bricht ihre Ehe (begeht Ehebruch).');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 33, 'Weiter (wiederum) habt ihr gehört, dass gesagt wurde zu den Alten: Du sollst keinen Meineid schwören, du sollst aber erfüllen dem Herrn deine Eide (sondern dem Herrn deine Eide einlösen).');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 34, 'Ich aber sage (befehle, fordere euch auf) euch, ihr sollt überhaupt nicht schwören. Nicht bei [dem] Himmel, denn er ist Gottes Thron (ein Thron Gottes)');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 35, 'nicht bei der Erde, denn sie ist ein Schemel (Fußbank) seiner Füße, nicht bei Jerusalem, denn sie ist eine Stadt des großen Königs');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 36, 'und auch bei deinem Haupt sollst du nicht schwören, denn es steht nicht in deiner Macht (du vermagst nicht), auch nur ein einziges Haar weiß zu machen (werden zu lassen) oder schwarz.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 37, 'Es sei eure Rede (Wort) Ja Ja, Nein Nein; was über dies (das übliche) hinausgeht (jedes weitere Wort) ist aus dem Bösen (von Übel).');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 38, 'Ihr habt gehört, dass gesagt wurde: Auge um (gegen) Auge und Zahn um (gegen) Zahn.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 39, 'Ich aber sage euch: Leistet (widersetzt euch nicht) dem, der Böses tut, (dem bösen Menschen) keinen Widerstand! Nein (im Gegenteil, sondern), wenn dich einer schlägt auf die [deine] rechte Backe, [dann] halte (anbieten, darbieten) ihm auch die andere hin.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 40, 'Und wenn dich einer vor Gericht ziehen (verurteilen) will und dein Untergewand bekommen (Nehmen, ergreifen) will, [dann] lass (gib) ihm auch den Mantel (das Gewand).');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 41, 'Und wenn dich einer zwingt, eine Meile [mitzugehen], [dann] geh mit ihm zwei.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 42, 'Dem, der dich bittet, sollst du geben (gib) und von dem, der von dir borgen (leihen) will wende dich nicht ab.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 43, 'Ihr habt gehört, dass gesagt wurde: Du sollst deinen Nächsten (Mitmenschen) lieben und deinen Feind hassen.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 44, 'Ich aber sage euch: Liebt eure Feinde und betet für die, die euch verfolgen,');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 45, 'auf dass (damit) ihr werdet Söhne eures Vaters [der ist] in den Himmeln, weil (da, denn) er lässt aufgehen die Sonne über bösen und guten und lässt [es] regnen über gerechten und ungerechten.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 46, 'Denn wenn ihr die liebt, die euch lieben, welchen Lohn habt ihr (könnt ihr da erwarten)? Tun nicht auch die Zöllner das selbe?');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 47, 'Und wenn ihr freundlich seid zu (grüßt) euren Brüdern, was tut ihr mehr (Besonderes, Aussergewöhnliches)? Tun nicht auch die Heiden das selbe?');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 48, 'Ihr sollt wie gesagt (also, demnach) vollkommen sein, wie euer himmlischer Vater vollkommen ist.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 1, 'Hütet euch [aber] eure Gerechtigkeit zu tun vor den Menschen [und] sie vor ihnen zur Schau zu stellen; sonst (andernfalls) werdet ihr keinen haben Lohn bei (vor) eurem Vater in den Himmeln.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 2, 'Sooft (wenn, wann immer) du also tust Wohltaten (Almosen) (aus Barmherzigkeit spenden möchtest), [dann] blase nicht die Posaune (Trompete) vor dir, wie es die Heuchler tun in den Synagogen und auf den Straßen (in den Gassen), damit (auf das) sie geehrt werden von den Menschen (um {sie} von den Menschen verherrlicht zu werden). Wahrlich, ich sage euch: Sie haben den Lohn empfangen.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 3, 'Wenn du aber tust Wohltaten (Almosen gibst), lass nicht deine Linke wissen, was deine rechte tut,');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 4, 'damit deine Wohltaten im Verborgenen sind; und dein Vater, der in das Verborgene sieht, wird dich entlohnen (belohnen).');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 5, 'Und wenn ihr betet, tut dies nicht wie die Heuchler, denn sie lieben es (tun es gern) in den Synagogen und in den Ecken (auf dem Eckstein) der breiten Straßen (Plätze) ihr Gebet zu machen damit es sichtbar ist den Menschen; Wahrlich, ich sage euch: Sie haben den Lohn empfangen.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 6, 'Wenn du aber betest, gehe in dein Zimmer (Kammer) [hinein] und schließe deine Türe um zu beten zu deinem Vater im Verborgenen; und dein Vater, der in das Verborgene sieht, wird dich entlohnen (belohnen).');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 7, 'Wenn ihr (aber) betet, redet nicht gedankenlos (plappert nicht) wie die Heiden, denn sie denken (meinen) durch ihre vielen Worte werden sie erhört werden (wird auf sie gehört).');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 8, 'macht es also ihnen nicht gleich (wie sie); denn euer Vater kennt, was ihr für braucht (nötig habt, eure Not, Sorgen, Bedarf) bevor ihr ihn bittet.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 9, 'Ihr sollt daher (also) folgendermaßen beten: Unser Vater {der} im Himmel, Möge (Mögest) dein Name (du) geheiligt werden.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 10, 'Möge dein Königtum (Königsherrschaft, Königreich) kommen.Möge dein Wille geschehen - wie im Himmel so auch auf der Erde.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 11, 'Unser Brot (Essen) für den kommenden Tag (unser notwendiges Brot, unser heutiges Brot, unser Brot, das auf uns kommt) gib uns heute');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 12, 'und vergib uns unsere Schulden (Schuld, Sünden),wie auch wir unseren Schuldnern vergeben haben (vergeben).');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 13, 'Und führe (lass nicht zu, dass wir geraten) uns nicht in Versuchung (Tests),sondern rette (erlöse) uns von dem Bösen.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 14, 'Denn wenn ihr verzeiht (vergebt) den Menschen ihre Schuld (Fehltritt, Verfehlung, Sünde), wird auch euch der Vater in dem Himmel vergeben.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 15, 'Wenn ihr aber nicht vergebt den Menschen, wird auch der Vater euch eure Schuld nicht vergeben.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 16, 'Wenn ihr aber fastet, werdet (seid) nicht verdrießlich wie die Scheinheiligen (Heuchler), die ihr Gesicht verschwinden lassen, damit die Leute wahrnehmen (sehen, bemerken), dass sie fasten. Wirklich (wahrlich), ich sage euch, sie haben ihren Lohn [bereits] erhalten.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 17, 'Du aber, wenn du fastest, parfümiere (salbe) deinen Kopf (dein Haupt) und wasche dein Äußeres (Gesicht),');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 18, 'damit nicht die Leute wahrnehmen (sehen, bemerken), dass du fastest, sondern (aber) dein Vater, der im Verborgenen (verborgen) ist. Und dein Vater, der ins das Verborgene sieht, wird dir [dein Fasten] vergelten (dich belohnen).');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 19, 'Sammelt euch nicht Schätze auf der Erde (auf Erden), wo Motten und Fraß (Holzwurm, Wurmfraß) [sie] verschwinden lassen (zerstören, vernichten) und [wo] Diebe einbrechen und stehlen.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 20, 'Sammelt aber euch Schätze im Himmel, wo weder Motten noch Fraß (Holzwurm, Wurmfraß) [sie] verschwinden lassen (zerstören, vernichten) und [wo] Diebe nicht einbrechen und auch nicht stehlen.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 21, 'Denn (dort) wo dein Schatz ist, da (dort) wird auch dein Herz sein.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 22, 'Die Lampe des Leibes (Körpers) ist das Auge. Wenn nun dein Auge lauter (gesund) ist, so wird dein ganzer Leib (Körper) licht (erleuchtet) sein.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 23, 'Wenn aber dein Auge böse (schlecht) ist, so wird dein ganzer Leib finster (dunkel) sein. Wenn also das Licht, das in dir ist, Finsternis ist, wie groß ist die Finsternis!');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 24, 'Niemand (keiner) ist fähig (stark, mächtig) zwei Herren zu dienen; denn entweder wird er den einen hassen und den anderen lieben, oder er wird sich zu dem einen halten (sich um ihn kümmern) und den anderen verachten (mißachten). Ihr könnt nicht Gott dienen und dem Mammon (Geld, Reichtums, Vermögen) dienen.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 25, 'Deswegen (Darum, Deshalb) sage ich euch: Seid nicht besorgt (beunruhigt, macht euch keine Sorgen) um euer Leben (eure Seele), was ihr essen [oder was ihr trinken] sollt, auch nicht (und nicht, oder) um euren Leib (Körper), über das, was ihr anziehen sollt. Ist (bedeutet) nicht das Leben (die Seele) mehr als Essen (die Speise) und der Leib mehr als Gewänder (Kleidung)?');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 26, 'Seht (Schaut, Beobachtet) [euch] die Vögel des Himmels an, denn sie säen nicht und (, noch) ernten nicht, noch sammeln sie [etwas] ([Vorräte]) in Vorratshäuser (Scheunen); und [doch] (aber) euer himmlischer Vater ernährt (füttert) sie; seid ihr (unterscheidet ihr euch) nicht viel mehr wert (wertvoller) als sie?');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 27, 'Wer aber von euch könnte dadurch, dass er sich sorgt (mit seinem Sorgen, Sorgen macht), hinzufügen (anfügen) an sein (zu seinem) Lebensalter [auch nur] eine Elle?');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 28, 'Und um ein Gewand (Auch was Die Kleidung betrifft), was sorgt (beunruhigt) ihr euch (warum macht ihr euch Sorgen)? Seht (Beobachtet, Lernt von den) die Blumen des Ackers (Feldes), wie sie wachsen; sie mühen sich (quälen) nicht und (noch) noch spinnen sie;');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 29, 'Ich aber sage euch, dass (:) nicht einmal Salomo in all seiner Herrlichkeit (Pracht, Glanz) bekleidet (angezogen) war wie eine von diesen (ihnen).');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 30, 'Wenn {nun (aber) } obwohl das Gras des Feldes, das heute steht und morgen in den Ofen geworfen wird, Gott es trotzdem kleidet, [wird er] euch nicht viel mehr [kleiden], ihr Kleingläubigen?');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 31, 'Also (Deswegen) sorgt euch nicht, indem (und) ihr sagt: Was sollen wir essen? oder: Was sollen wir trinken? oder: Was sollen wir anziehen?');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 32, 'Denn nach allen diesem (diesen Dingen) streben (suchen, trachten) die Völker (Nationen, Heiden). Denn euer himmlischer Vater weiß, dass ihr all diese Dinge braucht (nötig habt).');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 33, 'Sucht {aber} erst (zuerst) das Reich (Herrschaft) [Gottes] (die Gottesherrschaft) und seine Gerechtigkeit, und dies alles (all dies) (andere) wird euch hinzugefügt (geschenkt) werden.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 34, 'Sorgt euch also nicht (Macht euch also keine Sorgen) um den morgigen Tag (morgen, den nächsten Tag), denn der morgige Tag (morgen, der nächste Tag) hat eigene Sorgen (wird für sich selbst sorgen, bringt seine eigenen Sorgen mit): [Jeder] Tag hat genug eigenes Schlechtes (Übel).');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 1, 'Richtet (beurteilt, verurteilt) nicht, damit (auf dass) ihr nicht gerichtet (beurteilt, verurteilt) werdet.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 2, 'Denn mit dem Urteil (Entscheidung), mit dem ihr richtet, werdet ihr gerichtet werden, und mit dem Maß, mit dem ihr messt, werdet ihr gemessen werden (wird man euch messen).');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 3, 'Warum aber siehst du den Splitter im Auge deines Bruders, den Balken aber in deinem Auge bemerkst (siehst) du nicht?');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 4, 'Wie (mit welchem Recht) wirst du deinem Bruder sagen (wie kannst du deinem Bruder sagen): Lass mich den Splitter aus deinem Auge ziehen, und siehe, [es ist] der Balken in deinem Auge?');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 5, 'Heuchler (Scheinheiliger), zieh zuerst aus deinem Auge den Balken, und danach wirst du klar sehen, um den Splitter aus dem Auge deines Bruders zu ziehen!');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 6, 'Gebt nicht das Heilige den Hunden und werft nicht eure Perlen vor die Schweine, damit (dass) sie nicht zertreten diese und sie sich hinwenden (umwenden) und euch zerreißen.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 7, 'Bittet und euch wird gegeben, sucht und ihr werdet finden (entdecken), klopft an und euch wird aufgemacht (geöffnet).');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 8, 'Denn jeder, der bittet, bekommt (empfängt), und der sucht findet (entdeckt), und dem Anklopfenden wird geöffnet (aufgemacht).');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 9, 'Oder wer ist von euch ein Mensch, der, wenn, sein Sohn fragt nach Brot, ihm etwa (dann etwa) einen Stein gibt?');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 10, 'Oder wenn er fragt nach einem Fisch, ihm etwa eine Schlange gibt?');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 11, 'Obwohl ihr also (nun) böse seid, wisst ihr gute Gaben zu geben (schenken) euren Kindern, wie viel mehr wird euer Vater in den Himmeln euch Gutes geben, die ihr ihn bittet?');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 12, 'Alles, was ihr nun wünscht (wollt), dass euch die Menschen tun, das erweist (tut) auch ihnen; denn dies ist das Gesetz und die Propheten.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 13, 'Tretet ein (kommt hinein) durch die enge Tür (das Tor): Weil (da) die breite Tür (Tor) und der weite (geräumige) Weg in das Verderben führen (wegführen, verführen, irreführen) und viele sind es, die eingehen durch diesen;');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 14, 'wie eng [ist] die Tür (Tor) und drückend (drängend, bedrängend) der Weg, der führt in das Leben und wenige sind es, die ihn finden (entdecken, antreffen).');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 15, 'Nehmt euch in Acht (hütet euch) vor den Lügenpropheten, da sie gehen vor euch im Gewand (Kleid) der Schafe, von innen (inwendig, innen) aber sind sie räuberische (reißende) Wölfe.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 16, 'An ihren Früchten werdet ihr sie erkennen (völlig kennen). Sammelt (pflückt, erntet) ihr etwa von Dornbüschen Weintrauben oder aus Disteln Feigen?');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 17, 'Jeder gute Baum bringt gute Früchte, aber der schlechte Baum bringt schlechte (böse) Früchte.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 18, 'Es ist nicht möglich, dass ein guter Baum schlechte Früchte bringt und auch nicht, dass ein schlechter Baum gute Früchte bringt.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 19, 'Jeder Baum, der keine gute Frucht trägt, wird abgehauen (abgehackt, gefällt) und ins Feuer geworfen.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 20, 'Also (folglich): an ihren Früchten werdet ihr sie erkennen.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 21, 'Nicht jeder, der zu mir sagt: Herr, Herr, wird hineinkommen (eintreten, teilhaben am) in das Königreich der Himmel, sondern der, der tut den Willen meines Vaters in den Himmeln.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 22, 'Viele werden mir (zu mir) in jenen Tagen sagen: Herr, Herr, haben wir nicht in deinem Namen geweissagt (prophetisch geredet) und in deinem Namen Dämonen ausgetrieben (verstoßen, fortgejagt) und in deinem Namen viele Machttaten vollbracht (getan, bewirkt, geschafft)?');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 23, 'und dann (darauf) werde ich ihnen sagen, dass ich sie niemals gekannt habe: Geht weg von mir, ihr, die ihr arbeitet (macht, tätig seid) an der Gesetzlosigkeit.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 24, 'Jeder nun, der hört meine {diese} Worte und tut sie (so), wird ähnlich (gleichartig) gemacht einem klugen (verständigen) Mann, {einem} der sich ein Haus auf dem Felsen (Felsengrund) baut;');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 25, 'und als (wenn) der Regen herabstürzt (herabkommt, herabfällt) und der Fluss kommt und es blasen (wehen) die Winde und stürzen sich (niederfallen) auf dieses Haus und es stürzt nicht ein, denn es war gegründet (festgemacht) auf dem Fels.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 26, 'Jeder nun, der hört meine {diese} Worte und tut sie (so) nicht, wird einem dummen (törichten) Mann gleichen, einem, der sich das Haus auf dem Sand (Ufer, Strand) baut.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 27, 'und als (wenn) der Regen herabstürzt (herabkommt, herabfällt) und der Fluss kommt und es blasen (wehen) die Winde und stürzen sich (niederfallen) auf dieses Haus und es stürzt ein und sein Fall (Sturz, Einsturz) war groß (und es wurde völlig zerstört).');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 28, 'Und es geschah, nachdem (als, zur Zeit) Jesus vollendet (beendet) hatte diese Worte, dass die Volksmenge außer sich geriet (sich erstaunte) über seine Lehre;');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 29, 'denn es war, was er lehrte, wie (als) einer, der Vollmacht hatte und nicht wie (ganz anders als) ihre Schriftgelehrten (Gesetzeslehrer).');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 1, 'Als er {aber} vom Berg stieg (herabkam), folgte ihm (folgte ihm nach, war Jünger) eine große Volksmenge (Menge).');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 2, 'und siehe, ein Aussätziger kam herzu [und] kniete vor ihm nieder [und] sagte: Herr, wenn du willst kannst du mich heilen (rein machen).');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 3, 'und indem er die (seine) Hand ausstreckte berührte er ihn und sagte: Ich will [es]; und sofort (sogleich) wurde er von seinem Aussatz (seiner Unreinheit) geheilt.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 4, 'und es sagte ihm Jesus: Schau (sieh zu) niemandem (keinem) [etwas] zu sagen, sondern geh und du selbst zeige [dich] dem Priester und bringe das Opfer dar, das durch Moses befohlen (angeordnet) wurde, zum Zeugnis ihnen.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 5, 'Als er aber nach Kapernaum hineinging (ankam, hereinkam) kam (ging, kam herzu) zu ihm ein Hauptmann (um) ihn zu bitten');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 6, 'und sagte: Herr, mein Diener liegt gelähmt nieder in dem Haus und [ist] furchtbar (schrecklich) gefoltert (gequält).');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 7, 'Und er sagte ihm: ich werde (will) kommen [und] werde ihn heilen.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 8, 'und der Hauptmann antwortete [und] sagte: Herr, ich bin nicht würdig (genügend), dass du unter das (mein) Dach trittst (eintrittst, hineingehst), aber (sondern) sage nur ein Wort und mein Knecht wird geheilt werden (gesund gemacht werden, wiederhergestellt werden).');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 9, '{und} nämlich (denn, also, doch) ich bin unter Vollmacht (Macht, Kommandogewalt), denn ich habe unter mir Soldaten, und wenn ich sage diesem geh und er geht und einem anderen: komm und er kommt und meinem Diener: tue (mache) dies und er tut.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 10, 'Als aber Jesus [dies] hörte wunderte er sich (staunte er) und sagte den Jüngern (Nachfolgern): Amen, ich sage euch, bei niemandem in Israel habe ich so großen (so viel) Glauben gefunden (angetroffen, entdeckt).');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 11, 'Ich sage euch aber, dass viele aus dem Osten und Westen kommen (ankommen) werden und sich niederlegen (an die Tafel legen) mit Abraham und Isaak und Jakob im Königreich der Himmel (der Herrschaft der Himmel, dem Himmelreich),');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 12, 'aber die Söhne der Königsherrschaft (des Königreiches) werden fortgejagt (hinausgeworfen, weggetrieben) werden in die äußerste Dunkelheit (das äußerste Dunkel): Dort (da) wird sein (lautes) Weinen und Knirchen (Klappern) der Zähne (Zähneknirchen).');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 13, 'und es sagte Jesus dem Hauptmann: Geh, (so) wie du glaubst soll dir geschehen. Und [sein] Knecht wurde gesund (wiederhergestellt) in dieser Stunde.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 14, 'Und als Jesus in das Haus des Petrus ging, sah er seine Schwiegermutter, die lag und Fieber hatte;');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 15, 'und er berührte ihre Hand und das Fieber verlies sie (wich von ihr) und sie stand auf und diente ihm.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 16, 'Als es Abend wurde brachten sie ihm (herzu, dar) viele Besessene; und er trieb die Geister mit (durch) einem Wort (Rede) aus und viele, die Krankheiten hatten heilte er;');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 17, 'damit erfüllt würde, was gesagt wurde durch Jesaja den Propheten, der da spricht: er wird beseitigen unsere Schwachheit (Schwäche, Krankheit) und [unsere] Krankheiten wird er aufheben (wegtragen, wegschaffen).');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 18, 'Als Jesus aber die Volksmenge um ihn sah befahl er (ordnete er an) auf die andere Seite [des Sees] (an das jenseitige Ufer) hinüberzufahren.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 19, 'Und ein Schriftgelehrter, der hinzukam, sagte ihm: Lehrer, ich will dir folgen wo (wo auch immer) du hingehst.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 20, 'Und es sagte ihm Jesus: Die Füchse haben einen Bau (eine Höhle, eine Grube) und die Vögel des Himmels Wohnstätten, aber der Sohn des Menschen (Menschensohn) hat nichts, wo er [seinen] Kopf (sein Haupt) senken (neigen, beugen, hinlegen) kann.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 21, 'Ein anderer aber [seiner] der Jünger sagte (zu) ihm: Herr, erlaube (gestatte, gewähre) mir erst zu gehen (wegzugehen, mich zu entfernen) und meinen Vater zu begraben.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 22, 'Aber Jesus sagte (zu) ihm: Folge mir (nach) und lass die Toten zurück zu begraben ihre eigenen Toten (lass die Toten ihre eigenen Toten begraben).');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 23, 'Und als er einstieg (hineintrat) in das Boot (Schiff) folgten ihm seine Jünger.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 24, 'Und siehe (plötzlich), ein großes (Erd-) Beben (ein großer Sturm) entstand (ging los) auf dem See, so dass das Boot (Schiff) bedeckt (verdeckt) wurde von den Wellen; er aber schlief.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 25, 'Und sie traten heran (kamen hinzu), weckten sie ihn auf und sagten: Herr, rette, wir gehen zugrunde (sind verloren, werden umkommen, gehen unter)!');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 26, 'Und er sagte (sprach) [zu] ihnen: Was seid ihr feige (verzagt, ängstlich), Kleingläubige? Dann stand er auf [und] tadelte (fuhr an) die Winde und den See (das Meer); und es entstand eine große Stille (es trat eine völlige (Meeres-) Stille ein).');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 27, 'Die Menschen aber wunderten sich [und] sprachen: Was für einer ist dieser (Was ist er für einer), dass sowohl (auch) die Winde als auch (und) der der See (das Meer) ihm gehorchen?');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 28, 'Und als er ankam auf dem anderen Ufer (der anderen Seite des Sees) in das Land (die Landschaft, das Gebiet) der Gadarener gingen ihm entgegen zwei Besessene, die aus den Gräbern kamen sehr gefährlich (schlimm, wild), so daß niemand konnte vorübergehen (vorbeigehen) durch jenen Weg.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 29, 'und siehe, sie rufen {sagend}: Lass uns in Ruhe, Sohn Gottes! Kommst du hierher vor der Zeit (dem rechten Zeitpunkt) uns zu foltern (quälen)?');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 30, 'Es weideten aber weit weg eine Herde vieler Schweine.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 31, 'Die Dämonen aber baten ihn {sagend}: Wenn du uns austreibst, schicke uns (lass uns fahren) in die Herde der Schweine (Schweineherde).');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 32, 'Und er sagte ihnen: Geht (fort)! Und diese gingen aus und gingen in die Schweine; und siehe, die Herde stürmte (stürzte) ganz von dem Abhang hinab in das Meer und starb (kam um) in den Fluten (im Wasser).');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 33, 'Aber die Hirten flohen und gingen weg in die Stadt und erzählten (verkündeten, berichteten) alles und das der Besessenen.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 34, 'Und siehe, die ganze Stadt ging heran zur Begegnung dem Jesu (um Jesus zu begegnen, Jesu entgegen) und als sie ihn sahen baten sie ihn, dass er weggehe aus ihrem Gebiet (ihren Grenzen).');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 1, 'Und er stieg in ein Boot (ein) und fuhr an das andere Ufer (hinüber) und ging in seine eigene Stadt (die Stadt, in der er lebte).');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 2, 'Und siehe man brachte ihm einen Gelähmten (vorbei), der auf einer (Trag-) Bahre (Bett) lag. Und als Jesus seinen Glauben sah, sprach er zu dem Gelähmten: Sei guten Mutes (voller Mut, zuversichtlich, hab keine Angst) mein Kind, dir sind vergeben deine Sünden.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 3, 'Und siehe, einige der Schriftgelehrten sprachen bei sich: Dieser lästert (Gott).');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 4, 'Und als Jesus ihre Gedanken (Erwägungen, Überlegungen) bemerkte (durchschaute) sagte er: Warum (wozu) denkt (überlegt) ihr Böses (böse Gedanken) in eurem Herzen?');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 5, 'Denn was ist leichter (zu bewerkstelligen), zu sagen: Dir sind vergeben deine Sünden oder zu sagen: Auf! (Steh auf!) und gehe umher (führe dein Leben, gehe deinen Weg)?');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 6, 'Damit ihr aber wisst, daß der Sohn des Menschen (Menschensohn) (Voll-) Macht hat, auf der Erde Sünde zu vergeben - deshalb sagte er (zu) dem Gelähmten: Steh auf (auf!) nimm deine Bahre (Bett) und geh in dein Haus (nach Hause).');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 7, 'Und er stand auf und ging in sein Haus (nach Hause).');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 8, 'Und weil die (Volks-) Menge dies sah (erblickte) hatte sie Ehrfurcht (Angst) (fürchtete sich) und pries (lobpries, rühmte) Gott, daß er schenkte (gewährte) derartige (solche) (Voll-) Macht den Menschen.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 9, 'Und von dort weitergehend sah Jesus einen Menschen sitzend bei der Zollstelle (Zollhaus), genannt Matthäus, und spricht (sagt) zu ihm: Folge mir (nach)! Und er stand auf [und] folgte ihm.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 10, 'Und es war, als er sich (zu Tisch) niederlegte im (seinem) Haus, und siehe, viele Zöllner und Sünder kamen, um sich mit Jesus und seinen Jüngern niederzulegen (zusammen zu Tisch zu sein, am Essen teilzunehmen).');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 11, 'Und die Pharisäer, als sie es sahen, sprachen zu seinen Jüngern: Weshalb (warum) isst euer Lehrer mit den Zöllnern und Sündern?');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 12, 'Doch dieser hörte es, sprach: Nicht die Gesunden brauchen (haben nötig) einen Arzt, sondern die Kranken (die, denen es schlecht geht, die krank sind).');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 13, 'Geht aber hin (fort) und lernt was ist (heißt, bedeutet): Barmherzigkeit (Mitleid) möchte (will) ich und nicht Opfer; Denn ich bin nicht gekommen zu (be-) rufen die Gerechten, sondern die Sünder.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 14, 'Dann (zu der Zeit) kamen zu ihm (kamen hinzu, näherten sich ihm) die Jünger des Johannes und sagten: Warum fasten wir und die Pharisäer [viel, oft] aber deine Jünger fasten nicht?');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 15, 'Und es sagte ihnen Jesus: Können (vermögen) etwa die Söhne des Bautgemachs (die Hochzeitsgäste) zu klagen solange wie mit ihnen der Bräutigam ist? Es werden aber kommen Tage, wo entrissen wird von ihnen der Bräutigam, und dann werden sie fasten.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 16, 'Keiner aber setzt einen Flicken aus ungewalktem (neuem, frisch vom Webstuhl) Stoff (stück) auf ein altes Gewandt; denn sein flicken reißt ab vom Gewandt und es wird ein schlimmerer (schlechterer) Riss.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 17, 'Und (auch) nicht füllt man neuen Wein in alte Schläuche; Andernfalls (sonst) platzt der Schlauch und der Wein wird verschüttet und der Schlauch zerstört (vernichtet); Aber (statt dessen, nein,...) man muss füllen neuen Wein in neue (unbenutzte) Schläuche und beide bleiben erhalten (bewahrt, behütet).');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 18, 'Als er dies zu ihnen sagte, siehe, ein Herrscher (Mitglied der Behörde/Synagogenleitung) kam herzu und kniete vor ihm nieder (war sich nieder, betete an) und sagte: (daß) Meine Tochter stirbt jetzt (eben erst, eben); Doch (aber) komm herzu und lege deine Hand auf sie, da (dann) wird sie wieder leben.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 19, 'Und als Jesus aufstand folgte er ihm (begleitete er ihn) und seine Jünger ihn (mit seinen Jüngern).');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 20, 'Und siehe eine Frau, die seit zwölf Jahren an (schweren) Blutungen litt, kam herzu von hinten (hinten) [und] fasste (berührte) den Saum seines Gewandes;');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 21, 'Denn sie dachte bei sich (im Stillen): Wenn ich nur berühre sein Gewand, werde ich (von Krankheit) befreit (gesund werden).');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 22, 'Aber Jesus drehte (wendete) sich um (wendete sich hin) und als er sie sah sagte er: Sei guten Mutes (voller Mut, voller Zuversicht, hab keine Angst), [meine] Tochter; Dein Glaube hat dich errettet (bewahrt, geheilt, gesund gemacht) und es war gesund die Frau von dieser Stunde an.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 23, 'Und als Jesus kam in das haus des Herrschers und sah die Flötenspieler und die Menge, sie sich aufregte (in Unruhe war)');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 24, 'sagte er: geht weg (entfernt euch), denn das Mädchen ist nicht gestorben sondern es schläft. Und sie lachten ihn aus.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 25, 'Als (nachdem) aber er fortgejagt (weggetrieben) hatte die Volksmenge ging er hinein [und] ergriff ihre Hand und das Mädchen erwachte.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 26, 'Und es verbreitete sich die Kunde (Nachricht) davon in jenem ganzen Land (Gegend).');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 27, 'Und als er von dort weiterging folgten Jesus zwei Blinde, die riefen und sagten: Erbarme dich unser, Sohn Davids.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 28, 'Als er aber nach Hause kam, näherten (herzukamen) sich ihm die Blinden und es sagte ihnen Jesus: Glaubt ihr, dass ich kann (vermag) dies zu tun? Sie sagten (antworteten) ihm: Ja (gewiss, freilich), Herr.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 29, 'Da berührte er ihre Augen [und] sagte: gemäß (nach) eures Glaubens soll euch geschehen (wie ihr glaubt soll euch geschehen).');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 30, 'Und ihre Augen wurden geöffnet. Und Jesus fuhr sie an (schärfte ihnen ein, befahl mit aller Entschlossenheit): hütet euch, niemand soll es wissen.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 31, 'Und doch (aber) gingen sie heraus [und] verkündeten (erzählten, machten bekannt) sie dieses in jenem ganzen Land.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 32, 'Als sie aber herausgegangen waren, siehe, sie brachten herzu ein Mensch der stumm [und] (von Dämonen) besessen war.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 33, 'Und nachdem der Dämon ausgetrieben war konnte der Stumme reden. Und die Menge wunderte sich (staunte) und sagte: Niemals wurde solches sichtbar (hat man noch nie gesehen) in Israel.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 34, 'Die Pharisäer aber sagten: Durch (mit Hilfe von) dem Herrscher (dem Fürst) der Dämonen treibt er aus die Dämonen.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 35, 'und Jesus zog durch (ging herum) viele Städte und Dörfer [und] lehrte in ihren Synagogen und verkündete die frohe Botschaft (das Evangelium) des Königreichs (der Herrschaft) und heilte viele Krankheiten und viele Leiden (Gebrechen).');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 36, 'Als er aber die Volksmenge sah hatte er Mitleid mit ihnen, dass sie ermattet (müde, abgehetzt) und darniederliegend (am Boden liegend) waren: wie Schade, die keinen Hirten haben.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 37, 'Da sagte er seinen Jüngern: Zwar [ist] die Ernte groß, aber der Arbeiter sind wenig.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 38, 'Bittet nun den Herrn der Ernte (den Herrn, dem die Ernte gehört) dass er aussendet Arbeiter in seine Ernte.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 1, 'Und als er seine zwölf Jünger herbeirief verlieh (gab, schenkte) er ihnen (die) Vollmacht (Freiheit, Macht) der unreinen Geister damit (daß, damit) sie austreiben diese und heilen jede Art (jegliche, jede beliebige) Krankheiten und alle Leiden (Gebrechen).');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 2, 'Aber die Namen der zwölf Ausgesendeten sind diese: Als erster Simon, der genannt wird Petrus und Andreas, sein Bruder, und Jakobus der [Sohn] des Zebedäus und Johannes, sein Bruder');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 3, 'Philipus und Bartholomäus, Thomas und Matthäus, Jakobus, der [Sohn] des Alfaious und Thadäus,');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 4, 'Simon der Zelot (Kananäus) und Judas Iskariot, der ihn verriet.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 5, 'Diese Zwölf sandte Jesus aus und forderte sie auf (befahl ihnen) {sagend}:Auf dem Weg (hin zu dem Weg) der Heiden geht nicht und in keine Stadt der Samaritaner geht hinein (tretet ein)');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 6, 'geht aber noch lieber (mehr, eher) zu den Schafen, die verloren sind, (den verlorenen Schafen) des Hauses Israels');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 7, 'geht aber und verkündigt {sagend}, dass die Herrschaft der Himmel (das Himmelreich) nahe (herbeigekommen) ist.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 8, 'die, die krank (schwach) sind, heilt, die, die tot sind, weckt (richtet) auf, die Aussätzigen reinigt (säubert), Dämonen treibt aus; umsonst (habt ihr) empfangen, umsonst gebt (weiter).');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 9, 'Ihr sollt nicht erwerben (beschaffen) Gold und auch nicht Silber, nicht einmal Bronze (Kupfermünzen) in euren Gürteln,');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 10, 'keine Reisetasche (Ranzen) auf den Weg (für die Reise) zund auch nicht zwei Untergewänder (Hemden, Unterwäsche) und auch keine Sandalen und keinen (Wander-) Stab; denn ein gerechter Arbeiter ist seinen Lebensunterhalt wert.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 11, 'Wenn ihr in eine Stadt oder ein Dorf kommt, erforscht (untersucht) wer in dieser Gerecht ist; und (bei) diesen wohnt (bleibt) bist ihr fortgeht (weiter geht).');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 12, 'Wenn ihr aber in das Haus hineingeht sollt ihr grüßen.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 13, 'und wenn aber das Haus gerecht ist, soll Frieden über es kommen, wenn es aber nicht gerecht ist, soll euer Friede zu euch umkehren (zurückkehren).');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 14, 'und wenn man (wer auch immer) nicht einmal (auch nicht) euren Worten Gehör gibt, verlasst jenes Dorf oder Stadt (diesen Ort) und schüttelt den Staub von euren Füßenö.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 15, 'Amen (wahrlich) ich sage euch, es wird für die Gegend (Landschaft, Erde) Sodoms und Gomorras erträglicher sein am Tag des Gerichts als jener Stadt.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 16, '{Bedenkt wohl} ich sende euch wie Schafe inmitten (mitten unter die) der Wölfe; ihr sollt sein (seid) nun verständig (klug) wie die Schlangen und rein (lauter, ohne Falsch) wie die Tauben.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 17, 'Achtet aber auf (richtet den Sinn auf) die Menschen: Denn sie werden euch an die Lokalgerichte übergeben und euch in den Synagogen auspeitschen (strafen, züchtigen);');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 18, 'und vor die Herrscher {aber} und Könige bringen (führen) um meiner willen zum Zeugnis vor ihnen und vor den anderen Völkern.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 19, 'Wenn man euch aber ausliefert (übergibt) macht euch keine Sorgen, wie oder was ihr reden sollt; denn es wird euch (ein-) gegeben in jener Stunde was ihr reden sollt;');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 20, 'denn nicht (nicht so sehr) ist euer Reden, sondern (als vielmehr) der Geist eures Vaters ist es, der durch euch reden wird.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 21, 'Es wird aber ein Bruder einen (seinen) Bruder, und ein Vater ein (sein) Kind dem Tode (Henker) überliefern und es werden sich Kinder gegen ihre Eltern stellen und sie umbringen lassen.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 22, 'Und es wird Hass sein von jedem um meines Namens willen; Wer aber bis zuletzt bleibt, der wird errettet (gerettet, bewahrt) bleiben.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 23, 'Wenn man euch aber verfolgt in der (einen) Stadt, flieht in eine andere (die nächste); Amen (Wahrlich), denn ich sage euch ihr werdet nicht beenden (fertig sein) mit den Städten Israels bis kommt der Sohn des Menschen.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 24, 'Der Schüler (Jünger) ist nicht über (mehr als, steht nicht über) dem Lehrer oder der Knecht (Diener) über seinem Herrn.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 25, 'Es genügt dem Jünger (es ist ihm hinreichend), dass er ist wie sein Lehrer und dem Diener (Kencth) wie sein Herr. Wenn man den Hausherrn Beeltebuul nennt, wie viel mehr wird man das mit seinen Hausgenossen tun.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 26, 'Fürchtet sie also nicht: denn es ist auch nichts verborgen, was nicht offenbart (enthüllt) wird und nichts verborgen (geheim), was nicht bekannt wird.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 27, 'Was ich euch sage in der Dunkelheit (im dunklen, geheimen) {daß} sagt im Licht (am hellen Tag, in der Öffentlichkeit), und was ihr ins Ohr geflüstert bekommt, verkündet auf den Dächern.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 28, 'Und fürchtet euch nicht vor denen, die den Leib töten, aber die Seele nicht töten können; fürchtet aber mehr den, der die Seele dem Verderben preisgeben kann und den Leib tötet in der Hölle.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 29, 'Es werden nicht zwei Spatzen für ein paar Groschen zum Kauf angeboten? Und doch fällt kein einziger von diesen auf die Erde ohne euren Vater.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 30, 'Bei euch aber sind auch die Haare des Kopfes (auf dem Kopf) alle gezählt.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 31, 'Fürchtet euch nicht: Ihr seid viel wertvoller (besser, mehr) als die Spatzen.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 32, 'Jeder nun, der sich zu mir bekennt vor den Menschen, zu dem werde ich mich auch bekennen vor meinem Vater in [den] Himmeln.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 33, 'Wer auch immer mich leugnet vor den Menschen, den werde ich auch verleugnen vor meinem Vater in den Himmeln.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 34, 'Glaubt nicht, dass ich gekommen bin Frieden auf der Erde zu bringen; Ich bin nicht gekommen Frieden zu Bringen sondern ein Schwer.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 35, 'Denn ich bin gekommen zu trennen (entzweien) ein Sohn mit seinem Vater und eine Tochter mit ihrer Mutter und eine Braut mit ihrer Schwiegermutter.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 36, 'und ein Feind des Menschen wird seine Hausgemeinschaft sein.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 37, 'Wer seinen Vater oder seine Mutter mehr lieb (gern) hat als mich, ist meiner nicht wert (ist nicht wert mein Jünger zu sein) und wer seinen Sohn oder seine Tochter mehr lieb (gern) hat als mich, ist meiner nicht wert (ist nicht wert mein Jünger zu sein).');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 38, 'Und wer nicht sein Kreuz auf sich nimmt und mir nachfolgt (mein Jünger ist) ist meiner nicht wert.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 39, 'Wer sein Leben findet (festhalten will) wird es zerstören (verderben, vernichten, verlieren) und wer sein Leben zerstört um meiner Willen (wegen mir) wird es erlangen.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 40, 'Die euch aufnehmen, nehmen mich auf und die mich aufnehmen, nehmen den auf, der mich gesandt hat.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 41, 'Wer einen Propheten aufnimmt, weil er ein Prophet ist. wird den Lohn eines Propheten empfangen (bekommen) und wer einen Gerechten, weil er ein Gerechter ist, aufnimmt, wird den Lohn eines Gerechten bekommen.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 42, 'Und wer auch immer einen Becher kalten Wassers zu Trinken gibt einem der Geringsten im Namen eines Jüngers, wahrlich (Amen), ich sage euch, er wird seines Lohnes (auf keinen Fall) verlustig gehen (wird auf keinen Fall um seinen Lohn kommen).');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 1, 'Und es geschah, als Jesus vollendet hatte das Befehlen an seine zwölf Jünger, dass er weiterzog von dort, um zu lehren und zu predigen in ihren Städten.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 2, 'Der Johannes aber hörte in dem Gefängnis (von den) die Werke Christi [und] er sandte durch seine Jünger,');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 3, 'die sagten ihm: Bist du der kommen soll, oder sollen (müssen) wir auf einen anderen warten?');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 4, 'Und Jesus sagte ihnen antwortend (antwortete ihnen): Geht, um Johannes zu berichten, was ihr hört und seht:');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 5, 'Blinde können wieder sehen und Gelähmte können gehen, Aussätzige sind geheilt und Taube hören und Tote werden lebendig und Arme bekommen die gute Nachricht zu hören;');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 6, 'und glücklich (glückselig) ist, wer auch immer nicht an mir Anstoß nimmt (wer meinetwegen nicht zu Fall kommt).');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 7, 'Als diese aber gingen, fing Jesus an, der Menge über Johannes zu sagen (reden, erzählen): Was gingt ihr in die Wüste zu sehen (anzusehen) ein Schilfrohr, das vom Wind hin- und herbewegt wird?');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 8, 'Oder seid ihr gegangen zu sehen einen Mann in weicher (feine) Kleidung gekleidet (bestückt)? Nein (ihr wisst doch), die feine Kleidung tragen, sind in den Häusern der Könige (den königlichen Palästen).');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 9, 'Oder was seid ihr ausgezogen zu sehen? Einen Propheten? Ja (gewiss, freilich), ich sage euch, ihr habt gesehen, was sogar noch größer ist als ein Prophet.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 10, 'Dieser ist es, über den geschrieben ist:„ Siehe, ich sende meinen Engel (Boten) zu dir, der, welcher bereitet (instand setzt) deinen Weg vor dir.“');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 11, 'Amen (wahrlich) ich sage euch: nichts ist durch das Gebären von Frauen (unter von Frauen geborenen) größeres entstanden als Johannes der Täufer; aber der Kleinste im Königreich der Himmel (im Himmelreich) ist größer als er.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 12, 'Aber seit den Tagen Johannes des Täufers bis zum heutigen Tage (bis jetzt) bahnt sich das Königreich der Himmel mit Gewalt Bahn und Gewalttäter greifen es an (rauben es, ergfreifen es begierig.).');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 13, 'Denn alle Propheten und das Gesetz bis Johannes haben prophezeit;');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 14, 'Und ihr wollt gut heißen (gelten lassen) dies ist Elija, der kommen soll.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 15, 'Wer Ohren hat (wer hören kann), höre.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 16, 'Mit wem aber soll ich vergleichen das gegenwärtige Geschlecht? Es gleicht (es ist gleich) den Kindern, die auf den Marktplätzen sitzen (sich befinden, wohnen) und den anderen zurufen,');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 17, 'sie sprechen:„ Wir haben euch die Flöte gespielt, aber ihr tanzt nicht, wir haben ein Trauerlied angestimmt, aber ihr habt nicht getrauert.“');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 18, 'Denn Johannes kam weder essend noch trinkend und sie sagten: Er hat einen Dämonen (er ist von einem Dämonen besessen).');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 19, 'Und der Sohn des Menschen kam essend und trinkend und sie sagten: Siehe, ein (der) Mensch [ist] ein Fresser (Schlemmer) und ein Weintrinker (Säufer), ein Freund der Zöllner und der Sünder. Und die Weisheit ist gerechtfertigt durch ihre Werke.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 20, 'Darauf fing er an, die Städte zu beschimpfen, in denen er begann seine Wundertaten, denn sie waren nicht umgekehrt.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 21, 'Wehe dir, Chorazin, wehe dir, Betsaida: Denn wenn in Tyrus und Sidon die Wundertaten geschehen wären wie bei euch, schon lange hätten sie in Sack und Asche Buße getan.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 22, 'Aber ich sage euch: Für Tyrus und Sidon wird es erträglicher sein im himmlischen Gericht als euch.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 23, 'Und du, Kaphernaum, wirst du etwa bis zum Himmel erhoben werden? Bis zum Hades (zur Unterwelt) wirst du herabgestoßen werden. Denn wenn in Sodom die Wundertaten geschehen wären wie bei dir, wäre es bis zum heutigen Tag stehen geblieben.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 24, 'Aber ich sage euch, dass es dem Land (der Erde) Sodoms erträglicher sein wird an Tag des Gerichts als dir.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 25, 'In jener Zeit (zu jenem Zeitpunkt) ergriff Jesus das Wort [und] sprach: Ich preise dich, Vater, Herr des (über) des Himmels und der Erde, dass du verborgen hast dies (das alles) vor den Weisen und Verständigen (Klugen) und enthüllst (offenbarst) den kleinen Kindern (Unmündigen).');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 26, 'Ja (gewiss, freilich) Vater, denn was dir wohlgefällig [ist], ist geschehen.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 27, 'Alles ist mir ausgeliefert (anvertraut) von meinem Vater und keiner erkennt den Sohn außer dem Vater, auch keiner erkennt den Vater als der Sohn und jeder, dem wünscht der Sohn es aufzudecken (und jeder, dem es durch den Sohn enthüllt wird).');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 28, 'Kommt her (auf!) zu mir, alle die ihr euch abmüht (müde werdet) und mit Lasten beladen seid und ich (ich aber, ich selbst) will euch Ruhe gewähren (euch erquicken).');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 29, 'Nehmt (tragt, hebt) mein Joch auf euch selbst und lernt von mir, denn ich bin sanftmütig (freundlich, milde) und von Herzen (demütig, niedrig, bescheiden) und ihr werdet bekommen (finden, entdecken) Ruhe (Erquickung, das Aufhören) für eure Seele.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 30, 'Denn mein Joch ist (angenehm, gütig, leicht zu tragen, brauchbar, freundlich) und meine Last ist leicht.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 1, 'In jener Zeit ging Jesus am Sabbat durch die Saaten (Kornfelder); {aber} seine Jünger hatten Hunger und fingen an (begannen) Ähren auszuraufen (abzureißen) und zu essen.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 2, 'Als aber die Pharisäer [dies, es] sahen, sagten sie [zu] ihm: Siehe, deine Jünger tun etwas, das an einem Sabbat verboten (nicht erlaubt) ist.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 3, 'Aber er sagte ihnen: Habt ihr nicht gelesen, was David tat (machte), als er Hunger hatte und sie mit ihm (seine Begleiter),');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 4, 'wie (auf welche Weise) er in das Haus Gottes ging und aß die Brote der Aufstellung (die Schaubrote), was er und sie mit ihm nicht durften, vielmehr (sondern) nur die Priester?');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 5, 'Weder (oder) habt ihr nicht im Gesetz gelesen, dass am Sabbat die Priester im Tempel den Sabbat entweihen, noch (und doch, trotzdem) sind sie unschuldig?');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 6, 'Ich aber sage euch, dass (:) hier ist etwas (einer) Größeres als der Tempel.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 7, 'Wenn ihr verstanden (erkannt) hättet, was das bedeutet Barmherzigkeit (Erbarmen, Mitleid) will ich (begehre ich, will ich haben) und keine Opfer (Schlachtopfer), hättet ihr keine (nicht diese) Unschuldigen (Schuldlosen) verurteilt.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 8, 'Denn der Herr über den Sabbat ist der Sohn des Menschen.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 9, 'Und als er wegging von dort, ging er in ihre (die dortigen) Synagogen;');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 10, 'Und siehe [dort war] ein Mensch (eine Person), der eine gelähmte (vertrocknete, dürre) Hand hatte (der eine gelähmte Hand hatte). Und man fragte ihn (er wurde gefragt) {sagend}: Ist es erlaubt am Sabbat zu heilen? Um ihn anklagen zu können.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 11, 'Aber (und doch) er sagte ihnen: Wer von euch wird {ein Mensch} sein, der ein Schaf haben wird, das wenn (falls) es auch an diesem Sabbat in eine Grube hineinfällt, nicht es ergreifen (erfassen) wird und es herausziehen wird?');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 12, 'Wie viel demnach (also) unterscheidet sich der Mensch vom Schaf (Wie viel mehr wert ist der Mensch als ein Schaf). Es ist also erlaubt, das man am Sabbat Gutes tut (bewirkt, macht).');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 13, 'Dann (danach, darauf) sagte er dem Menschen: Strecke deine Hand aus. und er streckte sie aus. Und sie wurde geheilt (wiederhergestellt, in den richtigen Zustand versetzt), gesund (unversehrt) wie die andere.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 14, 'Die Pharisäer aber gingen heraus ergriffen (fassten) sie den Entschluss gegen ihn (hielten sie eine Beratung (Versammlung) gegen ihn), wie sie ihn umbringen (töten) konnten.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 15, 'Als aber Jesus [es, das] erkannte (erfuhr), ging er weg (entfernte er sich) von dort. Und es folgten (begleiteten, nachfolgen) ihm Viele und er heilte sie alle.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 16, 'Und er befahl ihnen streng (gebot, tadelte), ihn nicht bekannt (offenbar) zu machen.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 17, 'Damit erfüllt (vollendet, abgeschlossen) würde, was gesagt wurde durch Jesaja, den propheten, der da spricht:');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 18, 'Siehe (da ist, hier ist) mein Kind (Knecht, Diener), den ich erwählt habe, mein Geliebter, an ihm hat meine Seele (Herz) Wohlgefallen (Freude, sie ist zufrieden mit ihm); ich werde meinen Geist ihm zuweisen und er wird den Völkern Recht (Gerechtigkeit) verkünden.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 19, 'Er wird weder zanken (Streiten) noch brüllen (lärmen, schreien) noch wird jemand hören seine Stimme auf den breiten Wegen (Straßen).');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 20, 'Das Schilfrohr, das geknickt (zerstoßen, zerschlagen) wurde wird nicht (zer-, ge-) brochen werden und der glimmende Lampendocht wird nicht ausgelöscht werden, bis er führt zum Zieg das Recht (die Gerechtigkeit).');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 21, 'Und auf seinen Namen hoffen die Völker.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 22, 'Darauf (dann) brachte man ihm (wurde ihm gebracht, hinzugebracht) ein Besessener gebracht, der blind und stumm war und er heilte ihn, damit (so dass) der Stumme reden und sehen konnte.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 23, 'Und alle der Volksmenge gerieten außer sich (vor Erstaunen) und sagten: Ist dies etwa (am Ende doch) der Sohn Davids?');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 24, 'Als aber die Pharisäer [das] hörten, sagten sie: Dieser treibt die Dämone nicht aus, außer durch Beelzebul den Herrscher (Herrn, Machthaber) der Dämonen.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 25, 'Als er aber ihre Überlegungen durchschaute (erkannte, bemerkte) sagte er ihnen: Jedes Königreich, dass gegen sich selbst uneins ist (mit sich selbst entzweit ist) ist zerstört worden, und jede Stadt oder Familie, die gegen sich selbst uneins ist (mit sich selbst entzweit ist) wird keinen Bestand haben (wird nicht bestehen bleiben).');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 26, 'Und (selbst) wenn der Satan den Satan austreibt, entzweit er sich selbst (er teilt gegen sich selbst), wie wird es nun möglich sein, dass seine Herrschaft Bestand haben wird (bestehen bleiben wird)?');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 27, 'Und wenn ich durch Beelzebul den Dämon austreibe, durch wen (mit wessen Hilfe) triben eure Söhne (Schüler) aus? Darum (deshalb) werden sie selbst eure Richter sein.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 28, 'Wenn ich aber durch den Geist Gottes den Dämon austreibe, ist folglich (also) zu euch gekommen (hat euch erreicht) die Königsherrschaft Gottes.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 29, 'Oder wie geht jemand in das Haus des Mächtigen (Starken) und raubt sein Habe (Gerät, Gefäß), wenn er nicht erst den Starken gefangen setzt (bindet)? Und dann wird sein Haus ausgeraubt (geplündert).');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 30, 'Der, der nicht mit mir ist, ist gegen mich, und wer nicht mit mir sammelt (vereint, zusammenkommt), der zerstreut.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 31, 'Darum sage ich euch, alle Sünde und Verleumdung (Schmähung, Lästerung) wird er den Menschen vergeben (verzeihen) [können], außer aber des Geistes Lästerung wird er nicht vergeben.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 32, 'Und wer (auch immer) sagen (sprechen) wird ein Wort gegen den Menschensohn, ihm wird er vergeben [können]; Wer aber gegen den heiligen Geist sagen (sprechen) wird, ihm wird er nicht vergeben [können], weder in diesem Zeitalter, noch im Kommenden (Zukünftigen).');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 33, 'Entweder ist der Baum gut und seine Früchte auch oder der Baum ist faul (schlecht) und seine Früchte auch; denn aus der (an seiner) Frucht erkennt man den Baum.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 34, 'Schlangenbrut (Sprösslinge der Schlange), wie könnt ihr gut (gerecht, gütig) sprechen wo ihr doch böse seid? Denn aus dem Überfluss (Fülle) des Herzen spricht die Zunge (der Mund).');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 35, 'Der gute Mensch holt aus dem guten Schatz Gutes hervor und der schlechte Mensch holt aus dem schlechten Schatz Schlechtes hervor.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 36, 'Ich aber sage euch, dass (:) über jedes unnütze (nutzlose) Wort das sprechen werden die Menschen werden sie Rechenschaft ablegen müssen am (im) Tag des Gerichts;');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 37, 'Denn aufgrund (gemäß) deiner Worte wirst du gerechtfertigt werden (für gerecht erklärt werden) und aufgrund deiner Worte wirst du verurteilt werden.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 38, 'Dann antworteten (ergriffen das Wort) ihm einige der Schriftgelehrten und Pharisäer, indem sie sprachen: Lehrer (Rabbi), wir wollen (wünschen, begehren) von dir ein Zeichen sehen!');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 39, 'Da {aber} antwortete er {und sagte} ihnen: Eine schlechte und treulose (ehebrecherische) Generation verlangt (fordert, sucht) ein Zeichen, doch (und) kein Zeichen wird ihr gegeben werden außer dem Zeichen Jonas des Propheten.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 40, 'Denn wie Jona im Bauch (Inneren, Leib) des Seeungeheuers (großen Fisches) war drei Tage und drei Nächte, so wird der Sohn des Menschen (Menschensohn) sein im Inneren der Erde drei Tage und drei Nächte.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 41, 'Männer (Leute), Bewohner von Ninive („Niniveer“), werden auferstehen im Gericht gemeinsam mit dieser Generation und über sie urteilen (sie verurteilen), denn sie kehrten um zur Verkündigung (Ankündigung, Zeugnis) Jonas. Und siehe: Mehr als Jona [ist] hier.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 42, 'Die Königin des Südlandes (eine Königin aus dem Süden) wird auferweckt (auftreten) werden im Gericht gemeinsam mit dieser Generation und wird über sie urteilen (sie verurteilen), denn sie kam aus den Randregionen (den Enden) der Erde, um die Weisheit Salomos zu hören. Und siehe: Mehr als Salomo [ist] hier.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 43, 'Wenn (wann, dann) aber der unreine Geist den Menschen verlassen hat (von dem Menschen ausgefahren ist) durchzieht (irrt) er durch dürre (wasserlase) Orte (Plätze, Stellen) und sucht nach Ruhe (Erquickung, einem Ruheplatz) und (aber) findet keinen.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 44, 'Dann sagt er: In mein Haus werde ich zurückkehren (umkehren), von wo (woher) ich fortgegangen bin; und wenn er kommt wird er es finden leer, gepflegt (gefegt) und geschmückt (in Ordnung).');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 45, 'Dann geht er und nimmt mit sich selbst sieben andere Geister, schlimmer als er selbst, und sie treten ein und wohnen dort; und der spätere Zustand (das Ende) jenes (dieses) Menschen wird schlechter (schlimmer) sein als der frühere Zustand (Anfang). So wird es auch dieser bösen Generation (Geschlecht) zuteil werden (ergehen).');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 46, 'Als er noch sprach zur Volksmenge siehe, seine Mutter und seine Brüder standen (befanden) sich draußen und wollten ihn sprechen.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 47, '[Einer sagte aber: Siehe deine Mutter und deine Brüder stehen draußen und wollen dich sprechen.]');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 48, 'Er aber antwortet und sprach zu dem, der [dies] sagte: Wer ist meine Mutter und wer sind meine Brüder?');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 49, 'Und er streckte seine Hand auf seine Jünger (aus) [und] sagte: Siehe (hier sind) meine Mutter und meine Brüder.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 50, 'Denn wer auch immer tut den Willen meines Vater (der ist) in den Himmeln, er (dieser) ist mein Bruder und Schwester und Mutter.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 1, 'An diesem Tag ging Jesus aus dem Haus und setzte sich [zum Lehren] an das Ufer des Sees;');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 2, 'und es versammelte sich vor ihm eine große Volksmenge, so daß (derart das) er in ein Boot einstieg und sich setzte, und die ganze Volksmenge stand am Ufer (Strand)');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 3, 'und er erzählte (sagte) ihnen Vieles (viele Dinge) in Gleichnissen {sagend}: Siehe (hört zu), es ging der Bauer (Sämann) hinaus [aufs Feld] (um) zu säen.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 4, 'Und als (während) er säte fielen einige der Samenkörner auf den Weg (die Straße) und es kamen die Vögel und fraßen es auf.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 5, 'Andere aber fielen auf den felsigen Boden, (dort) wo sie nicht viel Erde hatten, und sofort gingen sie auf, weil sie keine tiefe Erde hatten;');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 6, 'als die Sonne aber aufging wurden sie verbrannt (versengt) und weil sie keine Wurzeln hatten, gingen sie ein (verdorrten, vertrockneten sie)');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 7, 'Andere aber fielen auf das Dorngewächs (unter die Dornen) und die Dornen gingen auf (wuchsen empor) und erwürgten (erstickten) sie.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 8, 'Andere aber fielen auf die gute Erde, und brachten Frucht, dass eine einhundert (-fach, Körner), dass andere sechzig (-fach, Körner), dass andere dreißig (-fach, Körner).');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 9, 'Wer Ohren hat (wer hören kann), der höre.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 10, 'Und die Jünger kamen hinzu und sagten ihm: Warum sprichst du zu ihnen in Gleichnissen?');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 11, 'Dieser aber antwortete ihnen: Weil euch gegeben ist das Geheimnis der Königsherrschaft der Himmeln, jenen (ihnen) ist es aber nicht gegeben.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 12, 'Denn wer hat, dem wird gegeben und überfließend zuteil gegeben werden (im Überfluss, der wird überreich gemacht werden); aber wer da nicht hat, dem wird, was er hat, auch noch genommen werden.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 13, 'Deshalb (darum) spreche ich zu ihnen in Gleichnissen, weil sie sehend nicht sehen und hörend nicht hören und nicht verstehen,');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 14, 'und es wird an ihnen offenbar (erfüllt, vollständig werden) das Prophetenwort (die Prophetie, Weissagung) Jesajas, der da sagt: Durch das Hören werdet ihr hören und nicht verstehen (ihr werdet immerfort hören, ihr sollt hören), und sehend werdet ihr sehen und nicht erkennen (erblicken, verstehen).');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 15, 'Denn das Herz dieses Volkes ist dick (unempfindlich, unempfänglich, stumpf) geworden und mit den Ohren haben sie schwer gehört und ihre Augen haben sie geschlossen, damit nicht (etwa) sie erkennen mit ihren Augen und mit den Ohren hören und mit dem Herzen verstehen (einsehen, begreifen) und sich umkehren (bekehren, umwenden, zurückkehren) und ich sie nicht heile (da dass ich sie heilen könnte).');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 16, 'Eure Augen aber sind glücklich (seelig) [zu preisen], dass sie sehen und eure Ohren, dass sie hören.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 17, 'Wahrlich (Amen) denn ich sage euch, dass viele Propheten und Gerechten verlangen (wünschen, begehren) zu sehen, was ihr gesehen, und nicht gesehen, und zu hören, was ihr gehört, und nicht gehört.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 18, 'Ihr hört nun das Gleichnis (seine Bedeutung) des Sämanns!');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 19, 'Wann immer (jedes mal wenn) jemand hört das Wort der Königsherrschaft (die Botschaft vom Reich Gottes) und nicht versteht es kommt das Böse und raubt (reißt, nimmt weg) das Gesäte in ihrem Herzen, dies ist der, der auf den Weg besät worden ist.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 20, 'Der aber, der auf den felsigen Grund besät wurde dies ist der das Wort hörende und aufrichtig mit Freude nimmt er es,');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 21, 'aber er hat keine Wurzeln in sich sondern ist vorübegehend (unbeständig, dem Augenblick hingegeben) und wenn aber Trübsale oder Verfolgung entstehen durch das Wort, wird er zur Sünde verführt (sich wieder abwenden).');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 22, 'Der aber, der in die Dornen (-gewächse) besät wurde, dies ist der das Wort hörende und (doch) die Sorge des (gegenwärtigen) Zeitalters (der Gegenwart) und die Verführung (Täuschung, Betrug) des Reichtums ersticken das Wort so dass (und) er keine Frucht bricht.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 23, 'Der aber, der auf die gute Erde besät wurde, dies ist der das Wort hörende und versteht, der (welcher) dann auch Frucht bringt und trägt das eine einhundert (-fach), das andere sechzig (-fach), das andere dreißig (-fach)');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 24, 'Er trug (legte) ihnen ein anderes Gleichnis vor {sagend}: Es gleicht die Königsherrschaft der Himmeln einem Menschen, der gesät hatte guten Samen in (auf) seinen Acker (Feld).');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 25, 'Zu der Zeit (als, während) es schliefen die Menschen kam sein Feind und säte dazwischen (dazu) Unkraut (Lolch) mitten hinein in (zwischen) das Getreide (den Weizen) und ging weg.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 26, 'Als aber sprossen die Getreidehalme (das Gras/Heu) und sie Frucht ansetzten, da kam zum Vorschein (wurde sichtbar) auch das Unkraut.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 27, 'Als aber die Diener (Knechte) des Hausherrn kamen, sagten sie zu ihm: Herr, hast du nicht guten Samen auf (in) deinem Feld gesät? Woher denn nun hat es Unkraut?');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 28, 'Und (aber) dieser sagte: Ein feindseliger Mensch (irgendein Feind) muss dies getan haben. Aber die Knechte sagten zu ihm: Sollen wir gehen und es ausreißen?');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 29, 'Er aber sprach: Nein, damit nicht (etwa) beim Zusammenlesen das Unkraut entwurzelt (ausreißt) das Getreide.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 30, 'Lasst zu, dass beides gemeinsam (zusammen) wächst bis zur Ernte, und in der Zeit der Ernte werde ich den Erntearbeitern (Schnittern) sagen: Sammelt zuerst das Unkraut und bindet es in Bündeln um es zu verbrennen, das Getreide (Weizen) aber sammelt in meiner Scheune.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 31, 'Er legte (trug) ihnen ein anderes Gleichnis vor {sagend}: Es ist die Königsherrschaft der Himmeln gleich einem Senfkorn, das von einem Menschen genommen wurde, der es säte in (auf) seinen Acker.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 32, 'Es ist das kleinste unter den Samenkörnern, wenn es aber hoch gewachsen ist, ist es größer als die anderen Kräuter (Gemüse, Gartenpflanzen) und es wird ein Baum derart, dass (so dass) es kommen die Vögel des Himmels und lassen sich nieder (nisten, wohnen) in seinen Zweigen (Ästen).');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 33, 'Ein anderes Gleichnis erzählte er ihnen: Es gleicht die Königsherrschaft der Himmeln einem Sauerteig, der war genommen worden und eine Frau tat einen halben Zentner Mehl hinein, bis der ganze Teig durchsäuert war.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 34, 'Dies alles erzählte Jesus in Gleichnissen der Volksmenge, und ohne Gleichnisse redete er er nicht zu ihnen,');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 35, 'damit erfüllt würde, was gesagt wurde durch den Propheten, der da spricht: Ich werde in Gleichnissen meinen Mund auftun, ich werde aussprechen (verkünden) Verborgenes (Unbekanntes) seit dem Anfang (Beginn, Grundlegung, Erschaffung) [der Erde].');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 36, 'Dann verlies er (schickte er weg) Volksmenge und ging ins Haus (nach Hause). Und es kamen zu ihm (traten herzu, näherten sich) seine Jünger und sagten: Erkläre (deute) uns das Gleichnis vom Unkraut des (auf dem) Ackers.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 37, 'Dieser aber antwortete: Der Mann, der den guten Samen sät, ist der Sohn des Menschen,');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 38, 'der Acker aber ist die Welt, der gute Samen aber, das sind die Söhne des Reiches (der Königsherrschaft); aber das Unkraut, (das) sind die Söhne des Schlechten (Bösen),');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 39, 'aber der Feind, der es gesät hat, ist der Teufel (Verleumder), aber die Ernte ist das Ende (die Vollendung) des Zeitalters (das Ende der Zeit), die Erntearbeiter (Schnitter) aber sind die Engel (Boten).');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 40, 'Geradeso wie (gleichwie) das Unkraut nun zusammengelesen (eingesammelt) wird und mit Feuer verbrannt wird, so wird es sein am Ende der Zeit;');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 41, 'Es wird aussenden der Sohn des Menschen seine Engel (Boten) und sie werden einsammeln aus seinem Reich (seiner Königsherrschaft) alle, die Verführen (die Ärgernisse, eine Falle machen, die anstößig sind) und die tun das Gesetzwidrige (das Gesetzlose) (die ein gesetzloses Leben führen)');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 42, 'und sie werden sie werfen in den Ofen des Feuers (den glühenden Ofen); Dort wird sein das (große) Weinen und das (große) Zähneknirschen (-klappern).');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 43, 'Dann werden die Gerechten (er-) strahlen ((auf- ((auf-) leuchten) wie die Sonne in dem Reiche ihres Vaters (Himmelreich). Wer ihren hat (wer hören kann), der höre.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 44, 'Das Himmelreich (die Königsherrschaft der Himmeln) gleicht einem Schatz, der verborgen (vergraben) war in einem Acker, welcher ein Mensch verbarg, als er ihn fand (entdeckte), und in seiner Freude ging er (hin) und verkaufte alles, was er hatte und kaufte jenen Acker.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 45, 'Wiederum gleicht das Himmelreich (die Königsherrschaft der Himmeln) einem Kaufmann, der schöne Perlen suchte (erstrebte);');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 46, 'als er aber eine kostbare (sehr wertvolle) Perle fand, ging er (hin) und verkaufte alles, was er hatte und kaufte sie.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 47, 'Wiederum gleicht das Himmelreich (die Königsherrschaft der Himmeln) einem (Schlepp-) Netz, das in das Meer (aus-) geworfen wurde und aus jeder Gattung (Art) fängt,');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 48, 'dieses, als (nachdem) es gefüllt (voll) war an das Ufer gebracht wurde, uns sie setzten sich (nahmen Platz) und sammelten die Guten in Gefäße, aber die Faulen (Schlechten) warfen sie weg.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 49, 'So wird es sein am Ende der Zeit: Die Engel werden ausgehen und die Schlechten aus der Mitte der Gerechten nehmen');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 50, 'und sie werden sie werfen in den Ofen des Feuers (den glühenden Ofen); Dort wird sein das (große) Weinen und das (große) Zähneknirschen (-klappern).');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 51, '[Jesus fragte sie:] Habt ihr verstanden dies alles? Sie sagten ihm: Ja!');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 52, 'Dieser aber sagte ihnen: Deshalb (also) ist jeder Schriftgelehrte, der dem Königreich der Himmeln nachfolgt (sein Jünger geworden ist) gleich einem Hausherrn, der aus seinem Schatz (-kammer) hervorbringt Neues und Altes.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 53, 'Und es geschah als (nachdem) Jesus diese Gleichnisse beendet hatte, das er von dort wegging.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 54, 'Und als er in seine Heimat (sein Vaterland) ging lehrte er sie in ihren Synagogen, derart, dass sie außer sich gerieten und sagten: Woher hat dieser diese Weisheit und die Wunderkräfte?');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 55, 'Ist dieser nicht eines Zimmermanns Sohn? Wird nicht seine Mutter Maria genannt (heißt nicht...) und seine Brüder Jakobus, {und} Josef und Simon und Judas?');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 56, 'Und wohnen nicht seine Schwestern alle unter uns? Woher nun hat dieser dies alles?');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 57, 'Und sie kamen durch in zu Fall. Aber Jesus sagte ihnen: Der Prophet ist nicht verachtet, außer in der Heimat und in seinem Haus.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 58, 'Und er machte dort keine zahlreichen (vielen) Wunder (taten) aufgrund ihres Unglaubens.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 1, 'In jener Zeit hörte Herodes der Tetrarch die Kunde (den Ruf, das Gerücht) von Jesus,');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 2, 'und sagte seinen Dienern: Dieser ist Johannes der Täufer; er stand auf von den Toten und darum (deshalb) sind in (durch) ihm solche Wunderkräfte wirksam.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 3, 'Denn Herodes hatte Johannes festnehmen (gefangennehmen) und fesseln (in Fesseln legen) und ins Gefängnis werfen (legen) lassen wegen Herodias, die Frau Philippus\', seines Bruders;');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 4, 'denn es hatte ihm Johannes gesagt: Es ist dir nicht erlaubt (steht dir nicht frei) sie zu haben [zur Frau].');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 5, 'Und er wünschte (wollte) ihn gerne töten [doch] er fürchtete die (Volks-) Menge, da (denn, weil) sie ihn für (als) einen Propheten hielten.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 6, 'Als aber der Geburtstag des Herodes gefeiert (begangen) wurde, tanzte die Tochter der Herodias in der Mitte (vor den Gästen) und gefiel dem Herodes,');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 7, 'deshalb (daher) sagte er mit einem Eid (Schwur) zu (versprach er ihr) alles zu geben, was (auch immer) sie sich wünschte,');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 8, 'und sie (diese) wurde von ihrer Mutter bedrängt (angestiftet): Gib mir, sagte (meinte) sie, hier (her) auf einer Platte den (Schüssel, Teller) den Kopf des Johannes des Täufers.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 9, 'Und es wurde traurig (betrübt) der König aber wegen des Schwurs und der anwesenden Gäste befahl er [ihr den Kopf] zu geben (ihr den Wunsch zu erfüllen),');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 10, 'und sandte hin (beauftragte) und lies enthaupten Johannes durch die Wache (Wachtposten)');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 11, 'und es wurde gebracht (getragen) sein Kopf auf einer Platte den (Schüssel, Teller) und es dem Mädchen gegeben und sie brachte [es] ihrer Mutter.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 12, 'Und als seine Jünger kamen, holten sie den Leichnam und begruben ihn und gingen [und] verkündeten es Jesus.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 13, 'Als aber Jesus [dies, es] hörte, zog er von dort ab (sich von dort zurück, ging weg), in einem Schiff an einen verlassenen (leeren, wüsten) Ort (Platz) für sich allein; und als die (Volks-) Menge es hörten, folgten sie ihm, zu Fuß (Land), aus den umliegenden Städten (Ortschaften).');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 14, 'Und als er [aus dem Boot] ausstieg (herauskam), sah er eine große Volksmenge (viel Volk), und er erbarmte sich über sie (hatte Mitleid mit ihnen) und er heilte die Kranken (Kraftlosen) von ihnen.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 15, 'Als es aber Abend geworden war (spät wurde), kamen seine Jünger zu ihm, und sagten: „Der Ort (Platz) ist öde (leer, wüst) und die Stunde ist schon verstrichen (die Zeit ist schon vorübergegangen, vorbei); Lass (Verabschiede) die (Volks-) Menge gehen, damit sie in die Dörfer gehen können und für sich Nahrungsmittel (zu Essen, Speise) kaufen.“');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 16, 'Der [Jesus] aber sagte ihnen: „Sie haben kein Bedürfnis (nicht nötig) zu gehen, gebt ihr ihnen zu essen.“');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 17, 'Die (diese) aber sagten ihm: „Wir haben nichts hier außer fünf Broten und zwei Fischen.“');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 18, 'Der (Dieser) aber sagte: „Bringt mir diese (sie) her.“');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 19, 'Und als er befahl, dass sich das Volk auf das Gras (Heu) niederlässt (niederlegt, niedersetzt), nahm er die fünf Brote und die zwei Fische, blickte in den Himmel [und] sagte Lob und Dank (sprach Lobpreis) und brach die Brote (in Stücke), gab sie den Jüngern, die Jünger aber der Volksmenge.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 20, 'Und alle aßen und alle wurden gesättigt (satt), und sie sammelten das übrig gebliebene der Brocken (das was an Stücken übrig war) (:, -) zwölf Körbe voll (ausgefüllt).');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 21, 'Die aber (und) aber, die gegessen hatten, waren an Männern wie (ungefähr) 5000, ohne (nicht mitgerechnet) Frauen und Kinder.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 22, 'Und alsbald (sofort, sogleich) nötigten (zwangen, forderten nachdrücklich auf) er die Jünger, dass sie in das Boot einsteigem und an das jenseitige [Ufer] (die andere Seite des Sees) vorausgehem (vorausfahrem) solange (während) er die Menge verabschiedete.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 23, 'Und als er die Menge verabschiedet hatte stieg er auf den Berg (einen Berg, in das Gebirge, Bergland) für sich allein um zu beten. Als es aber Abend geworden war, war er noch allein.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 24, 'Das Schiff aber war viele Stadien von der Erde (dem Ufer) entfernt, als es von den Wellen hart bedrängt (gequält) wurde, denn der Wind war entgegengesetzt (gegen (über-) stehend).');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 25, 'Aber in der vierten Nachtwache kam er zu ihnen, er ging (dabei) auf dem See.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 26, 'Als aber die Jünger ihn auf dem See gehend sahen, waren sie in Aufregung (Unruhe, Verwirrung) (hatten Sie Angst, gerieten sie in Schrecken), sagend (meinend, denkend), dass es eine Erscheinung (Gespenst) sei, und vor Furcht (Angst) schrien (riefen) sie.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 27, 'Da aber sagte [Jesus] ihnen {sagend}: Seid guten Mutes (voller Zuversicht; habt keine Angst), ich bin es, fürchtet euch nicht [länger].');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 28, 'Da antwortete ihm aber Petrus: Herr, wenn du es bist, befehle (ordne an) mir zu dir zu gehen auf dem Wasser.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 29, 'Er aber sagte: Komm! Und als er ausstieg aus dem Schiff, ging Petrus auf dem Wasser und ging (kam) zu Jesus.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 30, 'Als er aber den [starken] Wind sah, fürchtete er sich und fing an zu (ver-) sinken, sagend: Herr, hilf mir (rette mich)!');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 31, 'Da steckte Jesus aber seine Hand aus und e hielt ihn fest (ergriff ihn) und sagte ihm: Kleingläubiger (von schwachem Vertrauen), warum zweifelst du?');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 32, 'Und als die in das Boot einstiegen legte (wurde müde, lies nach) sich der Sturm.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 33, 'Die aber im Boot waren, warfen sich vor ihm nieder und sagten: Wahrlich (wirklich, wahrhaftig, tatsächlich), du bist Gottes Sohn.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 34, 'Und als (nachdem) sie herübergefahren waren kamen sie an Land nach Genesaret.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 35, 'Und als die Bewohner des Ortes sie erkannten, benachrichtigten (schickten nach) sie jene ganze Umgebung (Nachbarschaft) und man brachte ihm alle, die Krankheiten hatten.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 36, 'und baten ihn, dass er sie nur berühren (anfassen) dürften den Saum seines Gewandes; und so viele ihn berührten wurden gerettet (am Leben erhalten, geheilt).');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 1, 'Dann (da, darauf) kamen zu Jesus aus Jerusalem Pharisäer und Schriftgelehrte und sagten:');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 2, 'Warum missachten (übertreten) deine Jünger die Überlieferung der Alten (Vorfahren)? Denn sie waschen sich nicht [ihre] Hände, wenn sie Brot essen (eine Mahlzeit einnehmen, vor dem Essen).');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 3, 'Dieser aber antwortete ihnen: Warum missachtet (übertretet) ihr das Gebot Gottes eurer Überlieferung zuliebe (wegen)?');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 4, 'Denn Gott sagte: Ehre (schätze) den Vater und die Mutter, und: Wer schmäht (verflucht) Vater oder Mutter muss (auf jeden Fall) sterben.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 5, 'Ihr aber sagt: Wer auch immer sagt dem Vater oder der Mutter: Eine Opfergabe (eine Gott geweihte Gabe) sei alles, was du von mir als Nutzen (Unterstützung) hast,');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 6, 'der wird (muss) nicht ehren seinen Vater; und ihr setzt außer Kraft (erklärt für Ungültig) das Wort Gottes durch eure Überlieferung.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 7, 'Heuchler (Scheinheilige), richtig (zutreffend) hat prophezeit (prophetisch geredet) Jesaja über euch, der da spricht:');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 8, 'Dieses Volk durch Lippen mich ehrt, aber ihr Herz ist weit entfernt von mir.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 9, 'Vergeblich (umsonst) verehren sie mich weil sie vortragen als Lehren Gebote der Menschen.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 10, 'Und er rufte zu sich (herbei) die Volksmenge und sagte ihnen: Hört zu und versteht (begreift, seht ein):');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 11, 'Nicht was hineingeht in den Mund macht den Menschen unrein (verunreinigt ihn), sondern was hinausgeht (hinauskommt) aus dem Mund das macht den Menschen unrein.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 12, 'Dann (da, darauf) kamen die Jünger und sagten ihm: Weißt du, dass die Pharisäer, als sie dein Wort hörten, sich ärgerten (Anstoß nahmen, sich entrüsteten/empörten)?');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 13, 'Der aber antwortete ihnen {sagend}: Alle Pflanzen die nicht mein himmlische (im Himmel befindlicher) Vater angepflanzt hat wird er entwurzeln (ausreißen).');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 14, 'Lasst sie gewähren; Blinde sind Führer [der Blinden], wenn aber Blinde Blinde führen (leiten), werden beide in die Grube fallen.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 15, 'Es antwortete aber Petrus ihn {sagend} Erkläre (deute) und dieses Gleichnis.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 16, 'Der aber sagte: Auch ihr seid noch unverständig?');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 17, 'begreift (versteht, bemerkt) ihr nicht, dass alles, was in den Mund hineingeht (-kommt) in den Bauch hineingeht (hineingelangt, fortgeht) und in die Toilette (Klo) fallengelassen wird?');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 18, 'Was aber hinausgeht (hinauskommt) aus dem Bauch kommt aus dem Herzen, und jene (diese Dinge) machen den Menschen unrein.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 19, 'Denn aus dem Herzen kommen schlechte Gedanken (Überlegungen), Mord (Bluttaten, Mordtaten), Ehebrüche, Diebstähle, falsche Zeugnisse (Zeugenaussagen), Verleumdungen (Schmähungen, Lästerungen).');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 20, 'Das ist, was den Menschen unrein macht, aber mit ungewaschenen Händen essen macht den Menschen nicht unrein.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 21, 'Und als Jesus von dort ging, entfernte er sich (ging er weg) nach dem Gebiet von Tyros und Sidon.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 22, 'Und siehe, eine kanaanäische Frau aus jenem Gebiet kam und rief laut (schrie, brüllte): Erbarme dich über mich (hab Erbarmen mit mir), Herr, Sohn Davids; Meine Tochter ist schlimm (übel) von Dämonen besessen (geplagt).');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 23, 'Aber er antwortete nicht ihrem Wort. Und es kamen seine Jünger und baten ihn {sagend}: Verabschiede sie (lass sie gehen, schick sie weg), denn sie schreit hinter uns her.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 24, 'Der aber antwortete {sagend}: Ich bin nicht geschickt worden außer zu den verlorenen Schafen des Hauses Israels.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 25, 'Und (doch) diese kam und warf sich vor ihm nieder und sagte: Herr, hilf mir!');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 26, 'Der aber antwortete {sagend}: Es ist nicht recht, das Brot der Kinder zu nehmen und es vor die Hunde zu werfen.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 27, 'Sie aber sagte: Ja (gewiss, freilich), Herr, und doch fressen die Hunde aus (von) den Brocken (Brotkrumen) die fallen von dem Tisch ihres Herrn.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 28, 'Da (dann) antwortete Jesus und sprach (sagte) zu ihr: {Oh} Frau, groß ist dein Glaube: dir geschehe nach deinem Willen (wie du willst). Und ihre Tochter war geheilt (gesund) von jener Stunde an.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 29, 'Und als Jesus von dort wegging, kam er an den See Gennesaret und stieg (bestieg) auf den (einen) Berg und setzte sich dort (da) zum lehren.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 30, 'Und es kam eine große Volksmenge zu ihm, die bei sich hatten Lahme (Gelähmte), verkrüppelte (Verstümmelte), Stumme und viele andere [Kranke] und sie warfen sich vor seine Füße und er heilte sie.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 31, 'Damit (so daß) die Menge sich wunderte als sie sahen die Stummen sprechen, die Verkrüppelten gesund (geheilt) und Lahme umhergehen und Blinde sehend; und sie preisen (rühmten, ehrten) den Gott Israels.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 32, 'Aber Jesus rief seine Jünger zu sich und sagte: Ich habe Mitleid mit dieser Menge, denn sie sind schon drei Tage bei mir und sie haben nicht zu essen und ich will (möchte) nicht sie wegschicken, damit sie nicht auf dem Weg (unterwegs) schwach würden (ermatteten, zusammenrechen).');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 33, 'Und es sagten ihm die Jünger: Woher werden wir in der Wüste (Einöde) so viele Brote bekommen, so daß wir die Menge satt machen?');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 34, 'Und Jesus sagte ihnen: Wie viele Brote habt ihr? Die aber sagten: Sieben und wenige kleine Fische.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 35, 'Und er befahl (aufforderte, anweisen) der Volksmenge, sich niederzulegen (lagern, Platz zu nehmen) auf der Erde.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 36, 'Und er nahm die sieben Brote und die Fische und sagte Dank (ein Dankgebet, dankte Gott) und brach [in Stücke] und gab sie den Jüngern, die Jünger aber der Menge.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 37, 'und es aßen alle und wurden satt. Und was übrig war an Stücken sammelten sie sieben volle Körbe.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 38, 'Die aber aßen waren viertausend Männer ohne (nicht eingerechnet) Frauen und Kinder.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 39, 'Und als er die Menge entlassen hatte stieg er in das Boot und kam in das Gebiet von Magadan.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 16, 1, '{Und} Die Pharisäer und Sadduzäer kamen, [und] um ihn zu prüfen (auf die Probe zu stellen, herauszufordern), baten sie ihn, ihnen ein Zeichen aus dem Himmel zu zeigen (vorzuzeigen, vorzuführen, sehen zu lassen).');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 16, 2, 'Er aber antworte ihnen: „Wenn es Abend geworden ist, sagt ihr: »Heiteres (schönes) Wetter [wird es geben], denn feuerrot ist der Himmel.«');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 16, 3, 'Und früh [morgens]: »Heute [wird es] schlechtes Wetter [geben], denn feuerrot [und] bedrohlich (finster) ist der Himmel.« Das Aussehen des Himmels versteht ihr (richtig, sorgfältig) zu beurteilen, aber die Zeichen der Zeit vermögt ihr nicht (könnt ihr nicht) [zu beurteilen].');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 16, 4, 'Ein böses und ehebrecherisches (bundesbrüchiges) Geschlecht (Generation, Pack) sucht (verlangt, fordert) ein Zeichen, aber ein Zeichen wird ihr nicht gegeben werden, außer dem Zeichen Jonas.“Und er ließ sie zurück (stehen) und ging.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 16, 5, '{Und} als die Jünger an das jenseitige [Ufer] kamen, hatten sie vergessen, Brote mitzunehmen.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 16, 6, '{Aber} Jesus sagte ihnen: „Seht zu (gebt acht) und hütet euch (achtet auf) vor dem Sauerteig der Pharisäer und Sadduzäer!“');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 16, 7, 'Sie aber diskutierten [gerade] miteinander {sagend}: „Wir haben keine Brote mitgenommen!“');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 16, 8, 'Als aber Jesus das merkte, sagte er zu ihnen: „Was diskutiert ihr miteinander, Kleingläubige (von schwachem Vertrauen), dass (weil) ihr kein Brot habt?');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 16, 9, 'Begreift (versteht, erkennt) ihr noch nicht, und erinnert ihr euch nicht [mehr] an die fünf Brote der Fünftausend und [daran], wie viele Körbe ihr [zurück] bekommen habt?');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 16, 10, 'Und nicht an die sieben Brote der Viertausend und [daran], wie viele Körbe ihr [zurück] bekommen habt?');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 16, 11, 'Warum (wie) begreift (versteht, erkennt) ihr nicht, dass ich [gerade] nicht über Brote zu euch sprach? Nehmt euch {aber} in Acht vor dem Sauerteig der Pharisäer und Sadduzäer.“');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 16, 12, 'Da verstanden sie, dass er nicht meinte (sagte), sich vor dem Sauerteig {des Brotes} in Acht zu nehmen, sondern vor der Lehre der Pharisäer und Sadduzäer.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 16, 13, 'Als {aber} Jesus in das Gebiet von Cäsaräa Philippi gekommen war, fragte er seine Jünger {und sprach}: „Wer, sagen die Leute, dass ich - der Menschensohn! - (dass der Menschensohn) sei?“');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 16, 14, 'Sie aber sagten: „Die einen [sagen]: »Johannes der Täufer«, andere {aber} »Elija«, andere {aber} »Jeremia oder einer der Propheten«.“');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 16, 15, 'Er sagte zu ihnen: „Ihr aber, wer sagt ihr, dass ich sei?“');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 16, 16, 'Es antwortete {aber} Simon Petrus {und sprach}: „Du bist der Gesalbte, der Sohn des lebendigen [Gottes].“');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 16, 17, 'Jesus {aber} sagte zu ihm: „ [Wie] glücklich (selig, glückselig) bist du, Simon bar Jona, denn nicht Fleisch und Blut haben dir [das] offenbart (enthüllt), sondern mein Vater im Himmel.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 16, 18, 'Aber ich sage dir: Du bist Petrus (Fels), und auf dieses Gefels werde ich meine Kirche (er) bauen, und die Pforten des Hades werden nicht die Oberhand haben (erlangen) über sie (es).');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 16, 19, 'Ich werde dir die Schlüssel des Reiches des Himmels (der Himmel) geben, und was [auch immer] ([alles,] was) du binden wirst auf der Erde, wird gebunden sein im Himmel (in den Himmeln), und was [auch immer] ([alles,] was) du lösen wirst auf der Erde, wird gelöst sein im Himmel (in den Himmeln).“');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 16, 20, 'Dann befahl er (ordnete er an, schärfte er ein) den Jüngern, dass sie niemandem sagen sollten, dass er der Gesalbte sei.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 16, 21, 'Von da an begann Jesus, den Jüngern zu zeigen (darzutun, klarzumachen, hinzuweisen), dass er nach Jerusalem gehen und vieles von den Ältesten und Führern und Schriftgelehrten erleiden und getötet werden und am dritten Tage auferstehen müsse.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 16, 22, 'Und es nahm ihn beiseite (zu sich) Petrus und begann ihn anzufahren (zu tadeln, zurechtzuweisen) {sagend}: „Gott sei dir gnädig (wohlgesonnen, gütig gesinnt), Herr! Dies darf (soll) dir nicht geschehen (zustoßen)!“');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 16, 23, 'Der aber wandte sich um und sagte zu Petrus: „Geh hinter mich (geh weg von mir, lass mich in Ruhe), Satan! Eine Versuchung (Verführung, Falle) bist du mir, denn du denkst (meinst) nicht die Sache Gottes, sondern die Sache der Menschen.“');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 16, 24, 'Dann sagte Jesus seinen Jüngern: „Wenn jemand hinter mir gehen (mir nachfolgen) möchte, verleugne er sich selbst, nehme sein Kreuz auf (mit) und folge mir nach.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 16, 25, 'Denn wer auch immer (jeder, der) sein Leben retten möchte, wird es verlieren. Aber wer auch immer (jeder, der) sein Leben verliert um meinetwillen (wegen mir), wird es erlangen (gewinnen, finden).');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 16, 26, 'Denn was würde es einem Menschen helfen (nützen, fördern), wenn er die ganze Welt gewönne, ihm aber sein Leben (Seele) abhanden komme (er sein Leben einbüßte, sein Leben Schaden erlitte)? Oder was kann ein Mensch geben als Tauschmittel (Gegenwert) für sein Leben (seine Seele)?');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 16, 27, 'Denn der Sohn des Menschen wird mit seinen Engeln in der Herrlichkeit seines Vaters kommen, und dann wird er vergelten einem jeden nach seinem Tun.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 16, 28, 'Amen, ich sage euch: Einige von denen, die hier stehen, werden den Tod nicht schmecken (kennen lernen, erfahren) bis sie gesehen haben den Sohn des Menschen kommend in seine Herrschaft (Reich).“');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 17, 1, 'Und nach sechs tagen nahm Jesus Petrus und Johannes und Jakobus, seinen Bruder, und führte sie auf einen hohen Berg für sich allein (einsam, abseits).');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 17, 2, 'Und er wurde vor ihren Augen verwandelt (umgestaltet) und es leuchtete sein Gesicht (Antlitz, Erscheinung) wie die Sonne, sein Gewand (Kleid) aber wurde weiß wie das Licht (blendend/strahlend hell/weiß).');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 17, 3, 'Und siehe (plötzlich) erblickten (sahen, bemerkten) sie Moses und Elias, wie sie sich mit ihm besprachen (unterredeten).');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 17, 4, 'Als aber Petrus das Wort ergriff sagte er zu Jesus: Herr, es ist gut, dass wir hier sind; wenn du willst lass und hier bauen drei Zelte (Hütten), für dich eine und für Moses eine und für Elias eine.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 17, 5, 'Während (als) er noch redete, siehe (plötzlich), eine hell leuchtende (voller Licht) Wolke überschattete (warf ihren Schatten auf, bedeckte, verhüllte) sie und siehe (plötzlich), eine Stimme aus der Wolke sprach: Dies ist mein geliebter (einziger, erwählte) Sohn an ihm habe ich Wohlgefallen (Freude). Hört auf ihn! (Gehorcht ihm, schenkt ihm Gehör)');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 17, 6, 'Und als sie dies hörten fielen die Jünger nieder (warfen sich zu Boden) auf ihr Antlitz (Gesicht) und fürchteten sich sehr (heftig, gewaltig).');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 17, 7, 'Und Jesus ging (kam, trat) zu ihnen und berührte sie (fasste sie an) und sagte: Steht auf und fürchtet euch (nicht länger).');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 17, 8, 'Sie erhoben aber ihre Augen (sie blickten auf) und sahen niemanden außer Jesus allein.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 17, 9, 'Und als sie herabstiegen (herabkamen) von dem Berg befahl (gebietet) Jesus ihnen {sagend}: Sagt (erzählt) niemanden das Geschaute (Gesehene, das, was ihr gesehen habt) bis der Sohn des Menschen vom Tode aufersteht (auferweckt wird).');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 17, 10, 'Und es fragten ihn die Jünger {sagend}: Warum nun (denn) sagen die Schriftgelehrten, dass Elias zuerst kommen muss (es ist nötig, dass...)?');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 17, 11, 'Der aber (und dieser) antwortete ihnen {sagend}: Elias wird zwar kommen und wird alles wiederherstellen (in die richtige Ordnung/ Zustand versetze);');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 17, 12, 'ich aber sage euch, dass Elias schon (bereits) gekommen ist und sie haben ihn nicht erkannt sondern machten mit ihm was sie wollten; Dies muss auch der Sohn des Menschen von ihnen erleiden (erleben, erfahren).');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 17, 13, 'Da (dann) verstanden (sahen sie ein, begriffen sie) die Jünger, dass er von Johannes dem Täufer sprach.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 17, 14, 'Und als sie zu der (Volks-) Menge kamen (gingen), kam zu ihnen ein Mensch und warf sich auf die Knote vor ihnen (kniete nieder vor ihnen)');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 17, 15, 'und sagte: Herr, hab Erbarmen mit meinem Sohn (erbarme dich über meinen Sohn), denn er ist mondsüchtig und leidet schlimm (übel, furchtbar); Denn häufig fällt er in das Feuer und oft in das Wasser.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 17, 16, 'Und ich brachte ihn her zu (hin, dar) deinen Jüngern und sie konnten ihn nicht heilen.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 17, 17, 'Es antwortete ihm aber Jesus {sagend}: Oh du ungläubige (verdrehte) und verdrehte (verdorbene, verkehrtes) Generation (Geschlecht), bis wann werde ich mit (bei) euch sein? Wie lange soll ich euch (noch) ertragen? Bringt mir ihn her.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 17, 18, 'Und Jesus tadelte ihn (wies ihn zurecht, machte ihm Vorwürfe) und es ging aus ihm der Dämon (er fuhr aus) und es war geheilt das Kind von dieser Stunde an.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 17, 19, 'Da (darauf) kamen die Jünger zu Jesus und als sie mit ihm alleine waren sagten sie: Warum konnte wir ihn nicht austreiben?');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 17, 20, 'Dieser aber sagte ihnen: Wegen eures Kleinglaubens. Amen (wahrlich) denn ich sage euch, wenn ihr hättet Glauben wie ein Senfkorn, werdet ihr zu diesem Berg sagen: Geh weg von hier nach da, und er wird weggehen. Und ihr werdet nicht unvermögend (unfähig) sein (nichts wird euch unmöglich sein).');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 17, 21, '[Diese Gattung aber (kommt) fährt nicht aus; außer (nur) durch Gebet und Fasten.]');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 17, 22, 'Als sie aber in Galiläa zusammengekommen waren, sagte ihnen Jesus: Es wir der Sohn des Menschen in die Hände (Gewalt) der Menschen gegeben (überantwortet),');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 17, 23, 'und sie werden ihn töten und nach drei Tagen wird er aufweckt werden. Und sie wurden (waren) sehr traurig.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 17, 24, 'Als sie aber nach Kapernaum kamen, kamen die, die die Tempelsteuer einziehen (kassieren) zu Petrus und sagten: Euer Lehrer bezahlt die Tempelsteuer nicht?');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 17, 25, 'Er sagte: Ja (doch). Und als er in das Haus hineinging kam ihm Jesus zuvor und sagte: Was scheint dir [richtig], Simon? Die Könige der Erde erheben von wem Zoll (Steuern) oder Steuern, von ihren Söhnen oder von den fremden Menschen?');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 17, 26, 'Er sagte (ihm) aber: Von den fremden Menschen, es sagte ihm aber Jesus: Folglich sind frei (befreit) die Söhne.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 17, 27, 'Damit wir aber keinen Anstoß erregen (ärgern, empören) bei hnen, gehe hin zum (an den) See, werfe aus den Angelhaken und den ersten herauskommenden (heraufgezogenen) Fischen nehme und wenn du öffnest sein Maul wirst du ein Vierdrachmenstück (darin) finden; Dies nimm und gib ihnen für mich und für dich.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 1, 'In jener Stunde (Zeit) kamen die Jünger zu Jesus und sagten: Wer ist denn der größte in der Königsherrschaft der Himmeln?');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 2, 'Und nachdem er ein Kind herbeigerufen hatte stellte er es in ihre Mitte (auf)');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 3, 'und sagte: Amen (wahrlich) ich sage euch wenn ihr euch nicht umwendet (abwendet, bekehrt) und werdet wie die Kinder werdet ihr nicht hineingehen in die Königsherrschaft der Himmeln.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 4, 'Jeder, der sich also niedrig macht (demütigt, erniedrigt) wie dieses Kind, der wird der Größte in der Königsherrschaft der Himmeln.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 5, 'Und wer (jeder, der) aufnimmt ein solches Kind um meines namens willen, nimmt mich auf.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 6, 'Wer (auch immer) aber Anstoß gibt (zur Sünde verführt) das Kleine das glaubt an mich, für den ist es von Vorteil (besser), dass ihn ein Eselsmühlstein (großer Mühlstein, Mühlstein) um seinen Nacken (Hals) (an-) gehängt wird und er versenkt (ertränkt) würde in das tiefe Meer.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 7, 'Wehe der Welt wegen der Falle (Verführung): Denn es ist eine Notwendigkeit (es ist nötig), dass die Verführung kommt, doch (aber, jedoch) wehe den Menschen durch die die Verführung kommt.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 8, 'Wenn aber deine Hand oder dein Fuß dich zur Sünde verführen will, haue ihn ab und werfe ihn weg von dir: Es ist besser für dich verkrüppelt (verstümmelt) oder lahm (gelähmt) einzugehen in das Leben als (oder) zwei Hände oder zwei Füße habend in das ewige Feuer geworfen zu werden.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 9, 'Und wenn dein Auge dich zur Sünde verführt, nehme (reiße) es aus und werfe es von dir; Es ist besser für dich einäugig in das Leben einzugehen als zwei Augen habend in das ewige Feuer geworfen zu werden.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 10, 'Schaut (seht) zu, dass ihr nicht auf eines dieser kleinen herabseht (es gering achtet, verächtlich behandelt). Denn ich sage euch, dass ihre Engel in den Himmeln immer (beständig, jederzeit) sehen das Angesicht meines Vaters in den Himmeln.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 11, '');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 12, 'Was scheint euch (richtig)? Wenn einem Menschen hundert Schafe gehören und es geht in die irre (verirrt sich) eines aus ihnen, wird er nicht zurücklassen die Neunundneunzig auf den Bergen (den Bergland) und geht und sucht das verirrte?');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 13, 'Und wenn es sich ereignet, dass er es findet, Amen (wirklich, wahrlich) ich sage euch, dass er sich freut über dieses mehr als über die Neunundneunzig, die sich nicht verirrt haben.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 14, 'Ebenso ist es auch der Wille eures Vaters, der in den Himmeln [ist], dass nicht einer dieser kleinen verloren geht.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 15, 'Wenn aber sündigt [gegen dich] dein bruder, geh (und) bring es ans Licht (an den Tag, tue es dar, tadele ihn, stelle ihn zur Rede) nur zwischen dir und ihm (unter vier Augen). Wenn er dich hört (dir Gehör schenkt, dich anhört) so hast du deinen Bruder gewonnen.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 16, 'Wenn er aber nicht hören wird, nimm zwei oder drei mit dir, dass aufgrund der Aussage zweier Zeugen oder dreier die ganze Beschuldigung (Anschuldigung, Sache) feststehe (Bestand habe).');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 17, 'Wenn er nicht hört auf sie, sprich zur Kirche (Gemeinde); Wenn er aber auf die Gemeinde nicht hört, dann soll er in deinen Augen wie (geradeso wie, gleichwie) ein Heide oder Zolleintreiber (Zöllner) sein.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 18, 'Amen (wahrlich, wirklich) ich sage euch: Wie vieles auch immer (alles, was) ihr bindet auf der Erde wird gebunden sein im Himmel und alles was ihr löst auf der Erde wird gelöst sein im Himmel.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 19, 'Wiederum [amen] ich sage euch, dass wenn zwei aus euch einer Meinung sind (eins werden, übereinkommen, übereinstimmen) auf der Erde über jede (beliebige, irgendwelche) Sache (Angelegenheit) um die sie bitten, wird es ihnen Zuteil werden (gegeben werden) durch meinen Vater in den Himmeln.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 20, 'Denn wo sind zwei oder drei versammelt in meinem Namen, dort (da) bin ich in ihrer Mitte (mitten unter ihnen).');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 21, 'Da (dann) ging Petrus hinzu und sagte ihm: Herr, wie oft wird sündigen gegen mich mein Bruder und ich werde ihm vergeben? Bis zu siebenmal?');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 22, 'Es sagte ihm Jesus: Ich sage dir: ncht siebenmal, sondern siebenundsiebzigmal');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 23, 'Darum gleicht (es verhält sich mit... wie...) die Königsherrschaft der Himmel einem König, der abrechnen wollte mit seinen Dienern');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 24, 'als er aber begann (anfing) abzurechnen wurde ihm gebracht (vorgeführt) ein Schuldner zehntausender Talente.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 25, 'Aber er hatte nicht die Möglichkeit zu zahlen [und] der Herr befahl ihm, dass er verkauft würde und die Frau Frau und die Kinder und alles, was er hatte, und so die Schuld zu begleichen.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 26, 'Der Knecht nun fiel nieder und fiel nieder vor ihm {sagend}: Habe Geduld mit mir und alles werde ich dir wiedergeben (bezahlen).');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 27, 'Da hatter aber der Herr jenes Dieners Mitleid und gab ihn los (löste ihn) und erließ seine Darlehensschuld.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 28, 'Als aber jener Diener herausging traf er einen seiner Mitdiener, der ihm schuldig war einhundert Denare und er ergriff ihn, würgte ihn und sagte: Zahle mir alles, was du schuldest.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 29, 'Der Mitknecht nun fiel nieder und fiel nieder vor ihm {sagend}: Habe Geduld mit mir und alles werde ich dir wiedergeben (bezahlen).');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 30, 'Dieser (er) aber wollte nicht sondern ging und lies ihn in ein Gefägnis werfen bis er bezahlen würde die Schuld.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 31, 'Als nun seine Mitdiener sahen, was vorgefallen (geschehen) war. wurden sie traurig und gingen und erklärten (schilderte genau, meldeten) dem Herrn alles, was geschehen war.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 32, 'Da (dann) lies ihn sein Herr vorführen (kommen) und er sagte ihm: Du böser Diener, diese ganze Schuld habe ich dir erlassen, weil (da ja, denn) du mich gebeten hast;');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 33, 'hättest du nicht auch mit deinem Mitdiener Erbarmen haben müssen, wie auch ich mit dir Erbarmen hatte?');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 34, 'Und sein Herr war voller Zorn und übergab ihn dem Folterknecht bis er bezahlen würde die ganze Schuld.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 35, 'So wird auch mein himmlischer Vater handeln (behandelt, verfahren) mit euch wenn ihr nicht vergebt, ein jeder seinem Bruder von eurem Herzen (aufrichtig).');
