INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 27, '');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 28, 'Was meint ihr nun? Ein Mensch hatte zwei Kinder (Söhne). Und er trat an den ersten heran und sagte: Kind, geh [und] arbeite heute im Weinberg!');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 29, 'Er aber antwortete {und sprach}: Ich will nicht. Später aber bereute er es und ging hin.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 30, 'Er trat aber an den zweiten heran und sagte dasselbe (fragte, bat ebenso). Der aber antwortete {und sprach}: Zur Stelle, Herr!, und ging nicht hin.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 31, 'Wer von den beiden tat (erfüllte) den Willen des Vaters? Sie sagen: Der erste! Sagt Jesus zu ihnen: Amen, ich sage euch: Die Zöllner und die Prostituierten (Huren) gehen euch voran in das Reich Gottes.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 32, 'Denn Johannes kam zu euch auf dem Weg der Gerechtigkeit, und (aber) ihr habt ihm nicht geglaubt, die Zöllner und die Prostituierten (Huren) aber glaubten ihm. Ihr aber, obwohl ihr [es] saht, habt es nicht bereut, dass ihr danach (später) ihm geglaubt hättet.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 33, '');
