INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 36, '');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 37, '');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 38, '');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 39, '');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 40, '');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 41, '');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 42, 'Wacht also, denn Ihr wißt nicht, zu welcher Stunde Euer Herr kommt.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 43, 'Jenes aber wißt (versteht), daß, wenn der Hausherr wüßte, zu welcher Wache (Nachtwache) der Dieb kommt, [dann] würde er wachen und es nicht zulassen, daß [in] sein Haus eingebrochen wird.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 44, 'Deshalb seid (werdet) auch Ihr bereit, denn der Menschensohn (der Sohn des Menschen) kommt zu einer Stunde, in der Ihr es nicht glaubt (meint, erwartet).');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 45, 'Wer ist also der treue und verständige Knecht, den der Herr über sein Gesinde einsetzte, damit er ihnen zur rechten Zeit die Nahrung gebe?');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 46, 'Selig (Glücklich) jener Knecht, den sein Herr, wenn er kommt, antrifft (findet), während er so handelt.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 47, 'Amen (Wahrlich), ich sage Euch, daß er ihn über alle seine Besitztümer einsetzen wird.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 48, 'Wenn aber jener schlechte Knecht in seinem Herzen sagt: Mein Herr verzögert (verspätet) sich (läßt auf sich warten),');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 49, 'und beginnt seine Mitknecht zu schlagen, und mit den Betrunkenen (Trinkern; denen, die sich betrinken) ißt und trinkt,');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 50, '[dann] wird der Herr jenes Knechtes an einem Tag kommen, an dem er es nicht erwartet, und zu einer Stunde, zu der er es nicht weiß (die er nicht kennt),');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 51, 'und er wird ihn zweiteilen (zerschlagen, auspeitschen) und ihm seinen Teil (Platz) mit (bei) den Heuchlern zuweisen. Dort wird {das} Weinen und Zähneknirschen sein.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 1, 'Dann wird das Königreich der Himmel zehn Jungfrauen gleichen, welche, nachdem sie die Fackeln von ihnen ergriffen, hinausgingen zu der Begegnung des Bräutigams.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 2, 'Fünf aber aus diesen waren dumm und fünf vernünftig.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 3, 'Denn die Dummen nahmen die Fackeln von ihnen, nicht nahmen sie mit sich Öl.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 4, 'Die Vernünftigen nahmen aber Öl in den Gefäßen mit ihren Lampen.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 5, 'Aber wegen der Verzögerung des Bräutigams schliefen alle und ruhten.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 6, 'In der Mitte der Nacht entstand Geschrei: „Sieh, der Bräutigam! Geht ihr in seinem Entgegengehen!“');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 7, 'Dann standen alle Jungfrauen auf und ordneten die Fackeln von ihnen an.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 8, 'Die Dummen aber sagten den Vernünftigen: „Gebt uns aus eurem Öl, weil die Lampen von uns erlöschen.“');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 9, 'Die Vernünftigen antworteten aber, wobei sie sagten: „Niemals wird es dann für uns und euch reichen. Geht eher zu den Verkäufern und kauft es selbst!“');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 10, 'Nachdem sie aber gegangen sind zu kaufen, kam der Bräutigam und die, die bereit waren, gingen mit diesem hinein auf die Hochzeit und die Tür wurde geschlossen.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 11, 'Später aber kamen sie, und die übrigen Jungfrauen sagten: „Herr, Herr, öffne uns!“');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 12, 'Der aber, der antwortete sagte: „Amen sage ich euch, ich weiß nichts von euch.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 13, 'Seid wachsam jetzt, weil ihr nicht wisst, den Tag noch die Stunde.“');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 14, 'Denn es ist wie bei einem Menschen, der außer Landes reiste; Er rief seine eigenen Knechte und übergab ihnen seine Habe.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 15, 'Und dem einen gab er fünf Talente, dem anderen zwei, einem anderen eines, jedem nach seinen eigenen Fähigkeiten, und reiste bald darauf ab.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 16, 'Der aber fünf Talente bekam, ging hin und gewann weitere fünf, indem er mit denselben Geschäfte machte.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 17, 'Auf die selbe Weise (handelte) der, welcher zwei Talente (bekommen hatte), er gewann weitere zwei.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 18, 'Aber der, der das Eine bekommen hatte, (ging hin) vergrub (es) in die Erde und verbarg das Geld seines Herrn.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 19, 'Aber nach einer langen Zeit kommt der Herr jener Knechte und rechnete (die Angelegenheit) mit ihnen ab.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 20, 'Und es trat herbei, der die fünf Talente bekommen hatte, brachte weitere fünf Talente und sagte: Herr, fünf Talente hast du mir übergeben, siehe weitere fünf Talente habe ich gewonnen.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 21, 'Sein Herr sprach zu ihm: Recht so, du guter und treuer Knecht! Über weniges warst du treu, über vieles werde ich dich setzen. Gehe hinein in die Freude deines Herrn!');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 22, 'Aber es trat auch herzu der, der die zwei Talente (bekam) und er sprach: Herr, zwei Talente hast du mir übergeben, siehe weitere zwei Talente habe ich gewonnen.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 23, 'Sein Herr sprach zu ihm: Recht so, du guter und treuer Knecht! Über weniges warst du treu, über vieles werde ich dich setzen. Geh hinein in die Freude deines Herrn!');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 24, 'Aber es trat auch herzu der, der das eine Talent bekommen hatte und sprach: Herr, ich kenne dich: Du bist ein harter Mensch, denn du ernstes, wo du nicht gesät hast und sammelst, wo du nicht ausgestreut hast.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 25, 'und weil ich mich fürchtete, darum ging ich hin und verbarg dein Talent in der Erde. Siehe da hast du das deine (wieder).');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 26, 'Aber sein Herr antwortete ihm: Du schlechter und fauler Knecht! Du wusstest, dass ich ernte wo ich nicht gesät habe und sammle wo ich nicht ausgestreut habe?');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 27, 'Also hättest du mein Geld den Wechslern geben sollen und wenn ich wieder gekommen wäre hätte ich das meine mit Zinsen erhalten.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 28, 'Also, nehmt ihm das Talent weg und gebt es dem, der die zehn Talente hat,');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 29, 'denn jedem, der da viel hat, wird gegeben werden, und er wird im Überfluss haben. Aber von dem, der nicht hat, dem wird auch das, was er hat, weggenommen werden.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 30, 'Und dem unnützen Knecht werft in die äußerste Finsternis. Dort wird das Weinen und das Zähneklappern sein.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 31, '');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 32, '');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 33, '');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 34, '');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 35, '');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 36, '');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 37, '');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 38, 'Wann aber haben wir dich fremd gesehen und dich aufgenommen, oder nackt und haben dir etwas übergezogen?');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 39, 'Wann aber haben wir dich krank gesehen oder im Gefängnis und sind zu dir gegangen?');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 40, 'Und der König wird ihnen folgendermaßen antworten: „Amen, ich sage euch: wie viel ihr getan habt einem dieser meiner geringsten Brüder, [so viel] habt ihr mir getan.“');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 41, 'Dann wird er auch zu denen [auf] seiner Linken sagen: „Geht weg von mir, ihr Verfluchten, in des ewige Feuer, das [von] dem Teufel und seinen Boten [vor] bereitet ist.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 42, 'Denn ich war hungrig, und ihr habt mir nicht zu essen gegeben, ich war durstig und ihr habt mich nicht getränkt,');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 43, 'ich war fremd und ihr habt mich nicht aufgenommen, [ich war] nackt und ihr habt mir nichts übergezogen, [ich war] krank und im Gefängnis und ihr habt nicht nach mir geschaut.“');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 44, 'Dann werden sie antworten und sagen: „Herr, wann haben wir dich als Hungernden gesehen oder als Durstigen oder fremd oder nackt oder krank oder im Gefängnis und haben dir nicht gedient?“');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 45, 'Dann wird er ihnen folgendermaßen antworten: „Amen, ich sage euch: wie viel ihr nicht getan habt einem dieser Geringsten, [so viel] habt ihr auch nicht mir getan.“');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 46, 'Und sie werden weggehen, diese in die ewige Strafe, die gerechten aber ins ewige Leben.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 1, '');
