INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 32, 'Dieser wird groß sein und er wird Sohn des Allerhöchsten genannt werden und der Herr, Gott, wird ihm geben den Thron Davids, seines Vaters.');
