INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 45, '');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 46, 'Und Maria sprach: „Meine Seele (Ich) preist (macht groß, dankt) den Herrn “„');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 47, 'und mein Geist (Ich) jubelt (begann, zu jubeln) über Gott (dankt Gott), meinen Retter, “');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 48, 'denn (dafür, dass) auf die Armut (Niedrigkeit, Demut) seiner Sklavin (Magd) hat er geschaut (sich angenommen) - „ {siehe} von nun an halten für glücklich (werden mich für glücklich halten) mich alle Geschlechter (jeder)! - (:) “');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 49, '{denn (dafür, dass) } der Mächtige hat Großes an mir getan - „ {und (dessen) } heilig [ist (sei)] sein Name (er)! - “');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 50, '{und} seine Huld (Gnade, Erbarmen, Barmherzigkeit) [ist (währt, wird währen)] in Generationen und Generationen (alle Generationen, ewig) „ für jene, die ihn fürchten. “');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 51, '([So hat er begonnen, zu tun, Nun wird er tun]) Machttaten (Gewalt, (seine) Herrschaft) hat er getan (ausgeübt) mit seinem Arm (Macht): „ er zerstreute (machte zunichte) Hochmütige (Stolze) an der Gesinnung ihres Gemüts (Hochmütige);“');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 52, 'er stürzte Machthaber (Mächtige) von [ihren] Thronen [herab] „ und erhöhte Arme; “');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 53, 'Hungernde bereichert (füllt, sättigt) er mit Gutem (Gütern) „ und Reiche schickt er leer (mit leeren Händen) fort. “');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 54, 'Er hat sich Israel, seines Sklaven (Knaben, Knechtes) angenommen: „ er hat sich (gnädig) zugewandt (hat gedacht an) mit [seiner] Huld (huldvoll, was seine Huld angeht) - “');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 55, 'wie er es (ja auch) unseren Vätern (Vorfahren) gesagt hat (verheißen hat) - „ (für) Abraham und seinem Samen (seine Nachkommen) auf ewig (allen seinen Nachkommen, seiner ganzen Nachkommenschaft). “');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 56, '');
