INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 4, '');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 5, '');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 6, '');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 7, '');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 8, 'Aber als Simon Petrus [das] sah, fiel er vor Jesus auf die Knie und sagte: „Herr! Geh weg von mir, denn ich bin eine sündiger Mensch!“');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 9, 'Denn er erschrak (staunte), und mit ihm alle, die mit ihm waren, über ihren Fischfang,');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 10, 'dazu gehörten (ebenso) auch Jakobus und Johannes, die Söhne des Zebedäus, die Arbeitskollegen von Simon {waren}. Da sagte Jesus zu Simon: „Fürchte dich nicht! Von nun an sollst du Menschen fangen (lebendig fischen).“');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 11, 'Und sie brachten die Boote ans Land, ließen alles zurück und folgten ihm nach.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 12, '');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 13, '');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 14, '');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 15, '');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 16, '');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 17, 'Und es ereignete sich an einem der Tage, dass er auch lehrte. Und es saßen Pharisäer und Gesetzeslehrer da, die gekommen waren, aus vielen Dörfern Galiläas und Judäas und aus Jerusalem. Und die Kraft des Herrn zum Heilen war bei ihm.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 18, 'Und siehe, es waren Männer, die brachten einen Menschen auf einem Bett, der war gelähmt. Und sie begehrten ihn hineinzubringen und ihn vor ihn zu legen.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 19, 'Und als sie nicht fanden, wie sie ihn hineinbringen konnten wegen der Volksmenge, stiegen sie auf das Dach, um ihn durch die Dachziegel hinabzulassen zusammen mit dem Bett in die Mitte vor Jesus.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 20, 'Und als er ihren Glauben sah, sprach er: Mensch, vergeben sind dir deine Sünden.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 21, 'Und die Schriftgelehrten und die Pharisäer begannen zu diskutieren und sprachen: Wer vermag Sünden zu vergeben wenn nicht Gott allein?');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 22, 'Als aber Jesus merkte, was sie untereinander redeten, sagte er antwortend zu ihnen: Was beredet ihr in euren Herzen?');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 23, 'Was ist leichter zu sagen? Dir sind deine Sünden vergeben? Oder zu sagen: Steh auf und geh umher?');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 24, 'Damit ihr wisst, dass der Menschensohn Vollmacht hat, auf der Erde Sünden zu vergeben, sprach er zu dem Gelähmten: Dir sage ich: Steh auf und hebe dein Bett auf und geh in dein Haus.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 25, 'Und als er sogleich vor ihnen aufgestanden war und genommen hatte, worauf er gelegen hatte und ging Gott lobend in sein Haus.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 26, 'Und alle gerieten in Extase und sie priesen Gott und wurden von Furcht erfüllt und sagten: Wir haben Unglaubliches gesehen heute.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 27, 'Und danach ging er weg und sah den Zöllner Levi beim Zollhaus sitzend und sprach zu ihm: Folge mir nach.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 28, '');
