INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 33, '');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 34, '');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 35, '');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 36, 'Seid barmherzig, wie auch euer Vater barmherzig ist.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 37, 'Und richtet nicht, dann werdet auch ihr nicht gerichtet; und verurteilt nicht, dann werdet auch ihr nicht verurteilt. Lasst frei, dann werdet ihr freigelassen werden.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 38, 'Gebt, und euch wird gegeben. Ein Maß, gut, festgedrückt, gerüttelt [und] nach allen Seiten überfließend wird man in eure Tasche (in den Bausch eures Gewandes) geben (schenken). Denn mit dem Maß, mit dem ihr messt, wird euch wieder zugemessen werden.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 39, 'Er (sprach =) erzählte ihnen aber auch ein Gleichnis: kann etwa ein Blinder einen Blinden führen (anleiten, vgl. Apg. 8,31)? Werden sie nicht beide in [die] Grube fallen?');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 40, 'Der Schüler (ist =) steht nicht über dem Lehrer. Ganz vollendet aber, wird er wie sein Lehrer sein.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 41, 'Warum aber siehst du den Splitter {der} im Auge deines Bruders, den Balken aber im eigenen Auge bemerkst du nicht (nimmst du nicht wahr)?');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 42, 'Wie vermagst du zu sagen (kannst du sagen) zu deinem Bruder: Bruder, lass mich den Splitter {der} in deinem Auge herausziehen (entfernen), während du selbst den Balken in deinem Auge nicht siehst? Heuchler (Schauspieler), zieh (entferne) zuerst den Balken aus deinem Auge, und dann (wirst =) kannst du (scharf hinblicken =) genau zusehen, dass du den Splitter {den} im Auge deines Bruder ausziehst (entfernst).');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 43, '');
