INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 35, '');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 36, 'Es fragte (bat) ihn aber einer der Pharisäer, dass er mit ihm esse, und nachdem er ins Haus des Pharisäers hineingegangen war, legte er sich [zum Essen] nieder.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 37, 'Und siehe: [da war] eine Frau, die in der Stadt war (lebte), eine Sünderin, und als sie erfuhr, dass er im Haus des Pharisäers [zu Tisch] lag, brachte sie ein Gefäß mit Salböl herbei');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 38, 'und als sie sich hinter seine Füße gestellt hatte, begann sie weinend, seine Füße mit Tränen zu benetzen und mit den Haaren ihres Kopfes wischte sie [sie] ab (trocknete sie sie) und küsste seine Füße [immer wieder] und salbte [sie] mit Myrrhe.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 39, 'Als aber der Pharisäer das sah, der ihn eingeladen hatte, sprach er zu sich selbst (dachte er sich): „Wenn \'\'dieser\'\' ein Prophet wäre, wüsste er, wer und was für eine Frau [es ist], die ihn berührt: sie ist eine Sünderin.“');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 40, 'Und Jesus antwortete ihm: „Simon, ich habe dir etwas zu sagen.“Der aber sagte: „Lehrer, sprich!“');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 41, '„Zwei Schuldner [hatten Schulden bei] einem (irgendeinem) Geldverleiher. Der eine schuldete 500 Denare, der andere 50.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 42, 'Weil sie [ihre Schulden] nicht zurück zahlen konnten, erließ er beiden [die Schulden]. Wer nun von ihnen wird ihn mehr lieben?“');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 43, 'Simon antwortete: „Ich vermute: derjenige, dem mehr erlassen wurde.“Der (Jesus) aber antwortete ihm: „Recht (richtig) hast du geurteilt.“');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 44, 'Und als er sich der Frau zugewandt hatte, sagte er Simon: „Siehst du diese Frau? Als ich in dein Haus gekommen bin, hast du mir kein Wasser (über die Füße) gegeben; sie aber hat meine Füße mit Tränen benetzt und sie mit ihren Haaren abgewischt.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 45, 'Einen Kuss hast du mir nicht gegeben, sie aber, seit ich hereingekommen bin, hat nicht aufgehört, meine Füße zu küssen.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 46, 'Mit Salböl hast du meinen Kopf nicht gesalbt; sie aber hat meine Füße mit Myrrhe gesalbt.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 47, 'Deshalb, sage ich dir, sind ihre vielen Sünden erlassen, weil sie viel geliebt hat. Dem aber wird wenig erlassen, der wenig liebt.“');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 48, 'Er sprach aber zu ihr: „Deine Sünden sind dir erlassen.“');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 49, 'Und die zu Tisch Liegenden begannen, zu einander zu sagen: „Wer ist dieser, der Sünden erlässt?“');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 50, 'Er sprach aber zu der Frau: „Dein Glaube hat dich gerettet. Gehe in Frieden.“');
