INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 1, 'Er aber rief die Zwölf zusammen (versammelte die Zwölf), gab ihnen Macht (Kraft) und Autorität (Gewalt) über alle Dämonen (bösen Geister) und zum Heilen von Krankheiten,');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 2, 'und er sandte sie aus, das Königreich (die Herrschaft) Gottes zu predigen und die Kranken zu heilen,');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 3, 'und er sprach zu ihnen: „Nehmt nichts [mit] auf den Weg, weder Stab (Stock) noch Tasche, weder Brot noch Silber (Geld), weder soll einer zwei Hemden (Unterkleider) haben.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 4, 'Und wann immer (wenn) ihr in ein Haus hineingeht, dort bleibt, bis ihr von dort hinausgeht.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 5, 'Und wenn sie (die vielen) euch nicht empfangen (aufnehmen,willkommen heißen), geht aus dieser Stadt hinaus, schüttelt den Staub (die Erde) von euren Füßen als Zeugnis gegen sie.“');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 6, 'So gingen sie hinaus, durchzogen die Dörfer, verkündeten das Evangelium und heilten überall.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 7, '');
