INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 27, '');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 28, 'Es geschah aber ungefähr (wie) acht Tage nach diesen Worten (Reden) und Jesus nahm Petrus und Johannes und Jakob mit sich und stieg auf den Berg, um zu beten.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 29, 'Und es wurde, während er betete, das Aussehen seines Gesichts verändert (andersartig, verändert) und sein Gewandt glänzend weiß.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 30, 'Und sieh, zwei Männer sprachen mit ihm, welche Moses und Elias waren,');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 31, 'die in Herrlichkeit erschienen und seinen Ausgang besprachen (seinen/von seinem Ausgang sprachen), den er im Begriff war, in Jerusalem zu vollenden (den er in Jerusalem vollenden sollte).');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 32, '{Der} Petrus aber und die mit ihm waren mit Schlaf beschwert (von Schlaf bedrängt). Als sie aber vollends aufwachten (wach geworden waren), sahen sie seine Herrlichkeit und die zwei Männer, die bei ihm standen.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 33, 'Und es geschah, als sie sich von ihm trennten, [und] {der} Petrus sagte zu {dem} Jesus: Meister, es ist gut, dass wir hier sind, und wir werden drei Hütten (Zelte) machen (bauen, aufschlagen), eine (eines) für dich und eine (eines) für Moses und eine (eines) für Elias.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 34, 'Während er aber dies (diese Dinge) sagte, kam (entstand, wurde) eine Wolke und überschattete sie. Sie fürchteten sich aber, als sie in die Wolke hineinkamen.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 35, 'Und eine Stimme kam (entstand, wurde) aus der Wolke, die sagte: Dieser ist mein Sohn, der auserwählte, hört auf ihn.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 36, 'Und als die Stimme kam, wurde Jesus allein gefunden. Und sie schwiegen und berichteten niemanden in jenen Tagen {nichts} von dem, was sie gesehen hatten.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 37, '');
