INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 16, '');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 17, 'Die 70 [Jünger] aber kehrten zurück, und zwei [von ihnen] riefen (sprachen) mit Freuden: Herr, auch (sogar) die Dämonen gehorchen (unterwerfen sich, ordnen sich unter) uns in deinem Namen!');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 18, 'Sprach er {aber} zu ihnen: Ich sah den Satan wie einen Blitz aus dem Himmel fallen.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 19, 'Siehe, ich habe euch die (Voll) Macht (Freiheit, Fähigkeit, Befugnis, Amtsgewalt) gegeben, auf Schlangen und Skorpione zu treten (gehen, wandeln), und über alle Macht (Fähigkeit) des Feindes, und niemand wird euch (be) schädigen (verderben).');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 20, 'Jedoch (indessen) freut euch nicht darüber, dass euch die Geistwesen gehorchen (sich unterwerfen, sich unterordnen); freut euch aber, dass eure Namen im Himmel aufgeschrieben sind!');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 21, '');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 22, '');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 23, '');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 24, '');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 25, 'Und siehe: Irgendein Gesetzeskundiger trat hervor, um ihn auf die Probe zu stellen, indem er sagte: „Lehrer, was getan habend werde ich ewiges Leben erlangen?“');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 26, 'Der aber sagte zu ihm: „Im Gesetz, was ist [dort] geschrieben? Wie liest du?“');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 27, 'Er aber, antwortend, sagte: „»Du wirst den Herrn, deinen Gott, lieben, aus deinem ganzen Herzen und mit deiner ganzen Seele und mit deiner ganzen Kraft und mit deiner ganzen Vernunft, und deinen Nächsten wie dich selbst.«“');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 28, 'Er aber sagte ihm: „Du hast recht geantwortet. Tu dies und du wirst leben“.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 29, 'Er aber versuchte sich zu rechtfertigen und sagte zu Jesus: „Und wer ist mein Nächster?“');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 30, '[Es] aufnehmend sagte Jesus: „Irgendein Mann ging von Jerusalem nach Jericho hinab und fiel Räubern in die Hände, die ihn auch auszogen und ihm Schläge versetzten, bevor sie weggingen und ihn halbtot zurückließen');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 31, 'Zufällig aber ging irgendein Priester auf jenem Weg hinab und als er ihn gesehen hatte, ging er auf der gegenüberliegenden Straßenseite vorbei.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 32, 'Gleichermaßen kam zufällig auch an den Ort und als er ihn gesehen hatte, ging er auf der gegenüberliegenden Straßenseite vorbei.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 33, 'Aber irgendein reisender Samaritaner kam zu ihm und als er ihn gesehen hatte, empfand er Mitleid.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 34, 'Und als er hinzugetreten war, verband er seine Wunden und goss Öl und Wein darüber, und nachdem er ihn sein eigenes Reittier hatte besteigen lassen, brachte er ihn in eine Herberge und sorgte für ihn.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 35, 'Und am folgenden Tag, nachdem er [sie] herausgezogen hatte, gab er dem Herbergswirt zwei Dinare und sagte: »Sorge für ihn! Und das, was du zusätzlich aufwenden solltest, erstatte ich dir bei meiner Rückkehr.«');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 36, 'Wer von diesen dreien scheint dir der Nächste dessen geworden zu sein, der Räubern in die Hände gefallen war?“');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 37, 'Der aber sagte: „Der Barmherzigkeit an ihm geübt hat.“Jesus aber sagte zu ihm: „Geh und tu du gleichermaßen!“');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 38, '');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 39, '');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 40, '');
