INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 8, '');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 9, '');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 10, '');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 11, '');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 12, '');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 13, '');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 14, 'Und er trieb einen taubstummen Geist (Dämon) aus (warf hinaus, vertrieb). Es geschah, als der Geist (Dämon) hinausgegangen war, sprach der Taubstumme und die Leute wunderten sich (staunten, waren erregt).');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 15, 'Aber einigen von ihnen sprachen: Durch Beelzebul, den Herrscher der Geister (Dämonen) treibt er die Geister (Dämonen) aus.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 16, 'Andere, die [ihn] versuchten, forderten ein Zeichen aus dem Himmel von ihm.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 17, 'Er aber, da er ihre Gedanken (Absichten) kannte, sprach zu ihnen: Jedes Reich (Königreich, Herrschaftsbereich, Staatswesen), das in sich gespalten ist, wird verwüstet werden, und Haus fällt auf Haus.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 18, 'Wenn aber auch der Satan in sich gespalten ist, wie kann sein Reich (Königreich, Herrschaftsbereich, Staatswesen) betehen? Denn ihr sagt, dass ich durch Beelzebul die Geister (Dämonen) austreibe.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 19, 'Wenn ich durch Beelzebul die Geister (Dämonen) austreibe, durch wen treiben eure Anhänger [sie] aus? Deshalb werden sie Richter über euch sein.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 20, 'Aber wenn ich die Geister (Dämonen) durch den Finger Gottes austreibe, dann ist das Reich (Königreich, Herrschaftsbereich, Staatswesen) Gottes zu euch gekommen.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 21, 'Wenn der Starke bewaffnet seinen Hof bewacht, ist sein Besitz (Anwesen) in Frieden.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 22, 'Wenn aber ein Stärkerer als er kommt, wird er ihn besiegen. Er wird seine Ausrüstung (Rüstung, Bewaffnung) nehmen, auf die er vertraut hatte, und seine Beute verteilen.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 23, 'Wer nicht mit mir ist, ist gegen mich, und wer nicht mit mir versammelt, verstreut.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 24, '');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 25, '');
