INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 34, '');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 35, 'Eure Hüfte sei umgürtet und eure Lampen seien brennend.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 36, 'Und {ihr} [seid] wie Leute (Menschen), die ihren Herrn erwarten (auf ihn warten), wann er von der (einem) Hochzeit (Fest) zurückkehrt (zurück kommt), damit, wenn er kommt und klopft, sie ihm sofort [die Tür] öffnen [können].');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 37, 'Glücklich [sind] jene Sklaven (Knechte, Diener), die der Herr wachend (wach, wachsam) findet, wenn er kommt. Amen, ich sage euch: Er wird sich umgürten und sie [zu Tisch] hinlegen lassen und herbeikommen und ihnen dienen.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 38, 'Und wenn er in der zweiten oder in der dritten Nachtwache kommen und [sie] so finden wird, sind jene zu beglückwünschen (glücklich).');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 39, 'Dies aber erkennt: Hätte der Hausherr gewusst, zu welcher Stunde der Dieb kommt, hätte er den Einbruch in sein Haus verhindert');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 40, 'Auch ihr macht euch bereit, denn zu einer Stunde, zu der ihr es nicht denkt (meint), kommt der Menschensohn.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 41, '');
