INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 9, '');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 10, '');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 11, '');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 12, '');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 13, '');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 14, '');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 15, '');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 16, 'Er aber sagte zu ihm: Ein Mensch machte ein großes Festessen und er lud viele ein.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 17, 'Und er schickte seinen Knecht in der Stunde des Festessens, um denen, die eingeladen waren, zu sagen: Kommt, denn schon ist alles bereit.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 18, 'Und sie fingen einmütig an, sich zu entschuldigen. Er Erste sagte zu ihm: Ich habe einen Acker gekauft und habe die Notwendigkeit hinauszugehen, um ihn zu sehen. Ich bitte dich, halte mich für einen Entschuldigten.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 19, 'Und ein anderer sprach: Ich habe fünf Paare von Ochsen gekauft und ich gehe, sie zu untersuchen. Ich bitte dich, halte mich für einen Entschuldigten.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 20, 'Und ein anderer sprach: Ich habe eine Frau geheiratet und dadurch ist es mir nicht möglich zu kommen.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 21, 'Und als der Knecht zurückgekommen war, berichtete er seinem Herrn dieses. Dann, während der Hausherr zornig wurde, sprach er zu seinem Knecht: Geh schnell hinaus in die Straßen und Gassen der Stadt und bringe hierher die Armen und die Krüppel und die Blinden und die Lahmen.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 22, 'Und der Knecht sprach: Herr, es ist geschehen, wie du befohlen hast und es ist noch Platz.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 23, 'Und der Herr sagte zu seinem Knecht: Geh hinaus auf die Wege und Wälle und zwinge sie, hineinzukommen, damit mein Haus gefüllt wird.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 24, 'Ich aber sage euch, dass keiner jener Männer, die eingeladen waren, mein Festessen schmecken wird.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 25, '');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 26, '');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 27, '');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 28, '');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 29, '');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 30, '');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 31, '');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 32, '');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 33, '');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 34, '');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 35, '');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 1, 'Da waren aber alle Zöllner und Sünder, die sich ihm näherten, um ihm zuzuhören.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 2, 'Und die Pharisäer und Schriftgelehrten murrten laut und sprachen: Dieser nimmt Sünder an und isst mit ihnen!');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 3, 'Er erzählte ihnen aber dieses Gleichnis, indem er sprach:');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 4, '');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 5, '');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 6, '');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 7, '');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 8, '');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 9, '');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 10, '');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 11, 'Ein (irgendein) Mann (Mensch) hatte zwei Söhne.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 12, 'Und der jüngere von ihnen sagte zum Vater: Vater, gib mir den Teil des Vermögens, der mir zukommt. Er aber verteilte ihnen das Vermögen.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 13, 'Und nach einigen Tagen, als der jüngere Sohn alles zusammengesammelt hatte, reiste er in ein fernes Land und verstreute dort heillos lebend sein Vermögen.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 14, 'Als er aber alles aufgebraucht hatte, gab es eine große Hungersnot in jenem Land und er begann, selbst Mangel zu leiden.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 15, 'Und nachdem er herumgewandert war, schloss er sich einem Bürger jenes Landes an und der schickte ihn auf seine Felder, um die Schweine zu hüten.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 16, 'Und er wollte sich sättigen mit den Früchten des Johannisbrotbaums, von denen die Schweine aßen, und niemand gab ihm [etwas].');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 17, 'Und er begann, zu sich selbst zu sagen: Wie viele Tagelöhner meines Vaters haben Brot im Überfluss; ich aber komme hier vor Hunger um!');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 18, 'Wenn ich mich aufgemacht habe und zu meinem Vater reise, werde ich ihm sagen: Vater, ich habe mich gegen den Himmel versündigt und vor dir.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 19, 'Ich bin nicht länger würdig, dein Sohn genannt zu werden; mach mich zu einem deiner Tagelöhner!');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 20, 'Und er machte sich auf und ging zu seinem Vater. Als er aber noch weit entfernt war, sah ihn sein Vater und empfand Mitleid und warf sich im Rennen an seinen Hals und küsste ihn.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 21, 'Der Sohn aber sprach zu ihm: Vater, ich habe mich versündigt gegen den Himmel und vor dir; ich bin nicht länger würdig, dein Sohn genannt zu werden!');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 22, 'Der Vater aber sprach zu seinen Dienern: Bringt schnell das vornehmste Gewand und zieht ihn [damit] an und steckt ihm einen Ring an seine Hand und seine Füße in Sandalen!');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 23, 'Und bringt den jungen Stier, den gemästeten, schlachtet [ihn] und wir wollen essen und fröhlich sein!');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 24, 'Denn dieser, mein Sohn, war tot und ist wieder lebendig geworden, war verlorengegangen und wurde wiedergefunden. Und sie begannen, sich zu freuen.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 25, 'Sein älterer Sohn aber war auf dem Feld. Und als er nach Hause kam, hörte er Musik und Tanz');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 26, 'und er fragte ein Kind, das er herbeigerufen hatte, was denn dies sei.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 27, 'Und es sagte ihm, dass sein Bruder da sei und dass sein Vater den jungen Stier, den gemästeten, schlachte, weil er ihn als Gesunden zurückerhalten habe.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 28, 'Da zürnte er und wollte nicht hingehen, aber sein Vater kam heraus und lud ihn ein.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 29, 'Er aber antwortete und sprach zu seinem Vater: Siehe, so viele Jahre diene ich dir [schon] und habe niemals eine Anweisung von dir missachtet, und mir hast du niemals einen Ziegenbock gegeben, damit ich mit meinen Freunden fröhlich sei!');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 30, 'Als aber der Sohn von dir, der dein Vermögen mit Huren aufgezehrt hat, kam, hast du für ihn einen gemästeten Stier geschlachtet!');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 31, 'Da sagte er: Kind, du bist immer bei mir, und alles, was mein ist, ist dein.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 32, 'Es war aber nötig, sich zu freuen und fröhlich zu sein, denn dieser Bruder von dir war tot und ist wieder lebendig geworden, war verloren gegangen und wurde gefunden.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 1, '[Jesus] sprach zu seinen Jüngern: Es war ein reicher Mann, der hatte einen Manager (Verwalter). Dieser wurde bei ihm bezichtigt (beschuldigt), seinen Besitz zu verschleudern');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 2, '{Und} Er rief ihn herbei und sprach zu ihm: Was [ist] das, was ich von dir höre? Lege Rechenschaft ab über deine Buchführung, denn du kannst nicht mehr Manager (Verwalter) sein.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 3, 'Der Manager (Verwalter) sagte sich (sprach zu sich): Was soll ich tun? {Denn} Mein Herr wird mir die Verwaltung nehmen. (Zu graben =) Mit den Händen zu arbeiten vermag ich nicht, zu betteln schäme ich mich.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 4, 'Ich weiß, was ich tun werde, damit, wenn ich von der Verwaltung abgesetzt werde, sie mich gastlich in ihre Häuser aufnehmen!');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 5, 'Und er bestellte jeden einzelnen der Schuldner seines Herrn. {Und} Er sprach zum ersten: Wieviel schuldest du meinem Herrn?');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 6, 'Er {aber} sprach: Hundert Bat Öl. Er {aber} sprach zu ihm: Nimm deinen Schuldschein, setz dich gleich hin und schreibe: Fünfzig.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 7, 'Darauf sprach er zum nächsten: Wieviel {aber} schuldest du? Er {aber} sprach: Hundert Kor Weizen. Er spricht zu ihm: Nimm deinen Schuldschein und schreibe: Achtzig.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 8, '{Und} Der Herr lobte den ungerechten Manager (Verwalter), weil er klug gehandelt hatte: {Denn} die Kinder dieser Welt sind klüger als die Kinder des Lichts (in Bezug auf=) im Umgang mit ihresgleichen.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 9, '{Und} Ich sage euch: Schafft (macht) euch Freunde mit dem ungerechten Besitz (Vermögen, „Mammon“), damit, wenn er zu Ende ist, sie euch gastlich aufnehmen in die ewigen Behausungen.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 10, 'Wer im Geringsten verlässlich (treu) ist, ist auch im Großen verlässlich (treu), und wer im Geringsten unzuverlässig (unrecht, ungerecht) ist, ist auch im Großen unzuverlässig (unrecht, ungerecht).');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 11, 'Wenn ihr nun mit dem ungerechten Besitz (Vermögen, „Mammon“) nicht zuverlässig (treu) (seid =) umgeht, wer wird euch das, was wirklich zählt (das Wahre, das wahre Gut) anvertrauen?');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 12, 'Und wenn ihr mit dem (Fremden =), was euch nicht gehört, nicht zuverlässig (treu) (seid =) umgeht, wer wird euch das eure geben?');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 13, 'Kein Sklave kann zwei Herren gehorchen (dienen, untertan sein). Entweder wird er {nämlich} den einen hassen und den anderen (lieben =) mögen, oder an dem einen festhalten und den anderen gering schätzen. Ihr könnt nicht Gott dienen und dem Mammon (Besitz Vermögen).');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 14, '');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 15, '');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 16, '');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 17, '');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 18, '');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 19, '');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 20, '');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 21, '');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 22, '');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 23, '');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 24, '');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 25, '');
