INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 1, '');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 2, '');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 3, '');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 4, '');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 5, '');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 6, '');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 7, '');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 8, '');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 9, '');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 10, '');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 11, 'Und es begab sich, während er nach Jerusalem wanderte, da ging er mitten durch Samarien und Galiläa.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 12, 'Und als er in ein Dorf kam, begegneten ihm zehn lepröse (aussätzige) Männer, die blieben in der Ferne stehen');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 13, 'und {sie} (erhoben ihre Stimme =) riefen laut {und sprachen}: Jesus, Meister, erbarme dich unser!');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 14, 'Und als er sie sah, sprach er zu ihnen: Geht, zeigt euch den Priestern! Und es begab sich, als sie weggingen, da wurden sie (gereinigt, geheilt =) rein (heil).');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 15, 'Einer aber von ihnen, als er sah, dass er geheilt war, kehrte um und lobte Gott mit (gewaltiger Stimme =) lautem Schreien,');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 16, 'und fiel auf sein Angesicht bei seinen Füßen nieder und dankte ihm; und dieser (er) war ein Samaritaner.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 17, 'Da {antwortete aber und} sprach Jesus: Wurden nicht Zehn (gereinigt, geheilt =) rein (heil)? Aber die Neun {davon}, wo [sind sie]?');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 18, '(Erwiesen sie sich nicht als umkehrend =) Sind sie nicht umgekehrt, um Gott Ehre zu geben, (außer =) allein (nur) dieser Fremde (Fremdling)?');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 19, 'Und er sprach zu ihm: Steh auf und geh! Dein Glaube hat dich gerettet.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 20, 'Gefragt aber von den Pharisäern: „Wann kommt das Gottesreich?“antwortete er ihnen und sagte:„Nicht kommt es mit Beobachtung (mit Beobachtbarem).“');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 21, 'Und sie werden auch nicht sagen: „Siehe hier sei es, oder siehe dort, siehe das Reich Gottes ist mitten unter Euch (euch zur Verfügung).“');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 22, '');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 23, '');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 24, 'Denn wie der Blitz blitzend von einem Ende des Himmels zum anderen aufleuchtet, so wird der Menschensohn sein an seinem Tag.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 25, '');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 26, 'Und wie geschehen in den Tagen Noachs, so wird es sein in den Tagen des Menschensohns.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 27, 'Sie aßen, sie tranken, sie heirateten, sie wurden geheiratet bis zu dem Tag an dem Noach in die Arche ging und die Flut kam und alle vernichtete.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 28, 'Gleich (Ebenso) wie in den Tagen Lots (von Lot). Sie aßen, sie tranken, sie kauften, sie verkauften, sie pflanzten, sie bauten.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 29, '');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 30, 'Gemäß dieser Weise ist der Tag wenn (an dem) der Menschensohn offenbar werden wird.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 31, '');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 32, '');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 33, 'Wer sein Leben (Seele) sucht (eifert) zu erhalten, der wird es verlieren, wer es verliert wird es am Leben erhalten.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 34, 'Ich sage euch, zwei werden in dieser Nacht in einem Bett sein, einer wird hinweggenommen werden, der andere wird verworfen (zurückgelassen/vernichtet).');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 35, 'Zwei sind zusammen [Korn] mahlen, die eine wird hinweggenommen, die andere verworfen (zurückgelassen/vernichtet).');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 36, '');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 37, '');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 1, 'Er sprach aber ein Gleichnis zu ihnen über die Notwenigkeit, [dass] sie allezeit (stets) beten und nicht müde (mutlos) werden [sollen].');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 2, 'Er sagte: Ein (ein bestimmter) Richter war in einer (einer bestimmten) Stadt, der Gott nicht fürchtete und sich nicht [vor] Menschen scheute (schämte).');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 3, '[Auch] eine Witwe war in jener Stadt und sie kam wiederholt zu ihm, wobei sie ihn ansprach (wobei/indem sie sagte): Verschaffe mir Recht vor meinem Gegner (Ankläger, Widersacher)!');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 4, '(Und) er wollte über eine [längere] Zeit nicht [s davon wissen]; Aber nach diesem sprach er zu sich selbst: Wenn auch ich Gott nicht fürchte und ich mich vor keinem Menschen scheue (schäme; Angst habe),');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 5, 'weil diese Witwe mir wenigstens Mühe macht (anstrengt?; auf den Zeiger geht?), so will ich ihr Recht verschaffen, damit sie letztenendes nicht zu mir kommt und [so] mir ins Gesicht fahren (mich züchtigen, hart bestrafen) wird.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 6, 'Der Herr sprach aber: Hört [doch], was der ungerechte Richter spricht:');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 7, 'Sollte Gott aber nicht erst recht [für] die Strafe (Rache) seiner Erwählten, die am Tag als auch in der Nacht ihn laut anrufen, eintreten? Sollte er auch über sie lange Geduld haben (ausharren)?');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 8, 'Ich spreche zu euch, dass er ihre Strafe (Rache) unverzüglich machen (ausführen) wird. Doch wird der Sohn der Menschen, wenn er komm, [dann noch] den Glauben (Treue) auf der Erde finden?');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 9, 'Er sprach aber auch zu einigen [Leuten], die [voller] Selbstvertrauen sind, weil sie [meinten] gerecht zu sein, und die Übrigen gering schätzten, ein Gleichnis:');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 10, 'Zwei Menschen sind zum Tempel hinaufgegangen, [um] zu beten. Der eine war ein Pharisäer, der andere ein Zöllner.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 11, 'Der Pharisäer stand [selbstsicher] da und betete zu sich selbst dies: „Gott, ich danke dir, dass ich nicht so wie die anderen Menschen bin: kein Plünderer, kein Ungerechter, kein Ehebrecher, oder wie dieser Zöllner [dort].');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 12, 'Ich faste zweimal in der Sabbat [woche], [und] ich verzehnte alles, was ich erwerbe.“');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 13, 'Der Zöllner stand aber weit weg, und wollte nicht einmal die Augen zum Himmel erheben, sondern schlug sich [selbstsicher] auf die Brust und er sprach dabei: „Gott, sei mir Sünder gnädig!“');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 14, 'Ich sage euch: Dieser ging gerechtfertigt aus seinem Haus heraus, anstatt jener. [Denn] jeder, der sich selbst erhöht, wird erniedrigt (klein gemacht) werden; aber der, der sich [selbst] erniedrigt, wird erhöht werden.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 15, 'Sie brachten aber auch die kleinen Kinder zu ihm, damit er sich von ihnen berühren (anfassen) lassen kann. Als das aber [seine] Jünger sahen, wiesen sie [die Kinder umgehend] ab.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 16, 'Aber Jesus rief sie zu sich und sprach [zu ihnen]: „Lasst die Kinder zu mir kommen und hindert (halte) sie nicht [daran]! Denn solchen ist das Königreich Gottes!“');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 17, 'Amen, ich sage euch: „Wer (Der) das Königreich Gottes nicht wie ein Kind annehmen (klarmacht; sich be-/erweisen) kann, soll nicht in es hineinkommen.“');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 18, 'Und ein angesehener Mensch fragte ihn [Jesus]: „Guter Lehrer, was muss ich machen, um ewiges Leben [zu] erlangen (bekommen)?“');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 19, 'Jesus aber sprach zu ihm: „Was sprichst (nennst) du mich gut? Niemand ist gut, wenn nicht Gott allein!');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 20, 'Die Gebote kennst du [doch] \'Du sollst nicht ehebrechen; Du sollst nicht töten; Du sollst nicht stehlen; Du sollst nicht falsch reden (lügen); Ehre deinen Vater und deine Mutter.\'“');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 21, 'Der aber entgegnete: „Alle diese [Gebote] habe ich von Kindes Beinen auf bewahrt (befolgt).“');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 22, 'Als Jesus das hörte, sprach er zu ihm: „Eins fehlt dir noch: Alles an Reichtum, was du hast, verkaufe und gib [den Erlös] den Armen; und du sollst (wirst) einen Schatz in den Himmeln haben; nun (komm,) folge mir nach!“');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 23, 'Da er dies nun hörte, wurde sehr traurig [darüber], denn er besaß (hatte; wörtl.: war) viel Reichtum.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 24, 'Als Jesus ihn aber so traurig sah, sprach er: „Wie schwer ist es doch für die, die Besitz haben, in das Königreich Gottes zu gehen!');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 25, 'Denn leichter ist es [für] ein Kamel durch ein Nadelsteckloch zu gehen, als (oder) [für] einen Reichen ins Königreich Gottes hineinzukommen.“');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 26, 'Es fragten aber [nun] seine Zuhörer: „Und wer ist [nun] in der Lage (kann), errettet zu werden?“');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 27, 'Er aber entgegnete: „Die unmöglichen Dinge bei den Menschen sind die möglichen Dinge bei Gott.“');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 28, 'Aber Petrus sprach: „Siehe, [wir] haben alles, was wir besaßen, aufgegeben (verlassen) und sind dir nachgefolgt!“');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 29, 'Aber [Jesus] sprach zu ihnen: „Amen, ich sage euch: Es gibt (ist) Niemanden, der Haus, Frau, Geschwister, Eltern oder Kinder verlassen hat um des Königreiches Gottes willen,');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 30, 'der nicht [jetzt schon] vielfältigst in dieser Zeit und im kommenden Äon (Zeitalter, Ewigkeit) annehmen (empfangen) wird.“');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 31, '');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 32, '');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 33, '');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 34, '');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 35, '');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 36, '');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 37, '');
