INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 20, 'Wenn ihr dann aber seht, dass Jerusalem von einem Heer belagert wird, dann erkennt (wisst), dass seine Zerstörung bevorsteht,');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 21, 'dann sollen die in Judäa in die Berge fliehen und die in der Stadt [sind], fortgehen, und die auf dem Land nicht in die Stadt gehen,');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 22, 'denn das sind [die] Tage [der] Strafe (Vergeltung), damit alles, was geschrieben steht, erfüllt wird.');
