INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 31, '');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 32, '');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 33, 'Und als sie zu dem Ort kamen, der „Schädel“genannt wird, kreuzigten sie ihn dort und die Verbrecher (Übeltäter), den einen {von} rechts, den anderen {von} links.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 34, 'Jesus aber sprach: Vater, vergib ihnen, denn sie wissen nicht, was sie tun! Um seine Kleider unter sich aufzuteilen, warfen sie Würfel.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 35, 'Und das Volk war stehen geblieben (hatte sich hingestellt), um zuzuschauen. Es spotteten aber auch die Mächtigen (Anführer, Ratsmitglieder), indem sie sagten: Andere hat er gerettet. Wenn dieser der auswählte Messias (Gesalbte, Christus) Gottes ist, rette er sich selbst!');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 36, 'Auch die Soldaten schmähten ihn, die herbei kamen, indem sie ihm Essig herbeibrachten');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 37, 'und indem sie sprachen: Wenn du der König der Juden (Judäer) bist, rette dich selbst!');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 38, 'Es gab auch eine Inschrift bei ihm (über ihn): Dieses ist der König der Juden (Judäer).');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 39, 'Einer der gehängten Verbrecher (Übeltäter) lästerte ihn, indem er sagte: Bist du nicht der auserwählte Messias (Gesalbte, Christus)? Rette dich selbst und uns!');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 40, 'Der andere aber antwortete, herrschte ihn an und sagte: Fürchtest denn du keinen Gott (Gott nicht)? Du bist (stehst) doch unter demselben Urteil.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 41, 'Wir aber [sind es] gerechtermaßen, denn wir haben empfangen, was gerecht ist für das, was wir getan haben. Dieser aber hat nichts Unrechtes (Ungehöriges, Schlimmes) getan.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 42, 'Und er sprach: Jesus, erinnere dich an mich (kümmere dich um mich), wenn du in deine Herrschaft (Reich, dein Königtum) kommst!');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 43, 'Und er sprach zu ihm: Amen (wahrlich), ich sage dir, heute wirst mit (bei) mir im Paradies sein.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 44, 'Und es war schon um die sechste Stunde, und es wurde finster auf der ganzen Erde (im ganzen Land) bis zur neunten Stunde,');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 45, 'als die Sonne verschwunden war. Der Vorhang des Tempels zerriss (wurde zerrissen) in der Mitte.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 46, 'Und als er mit lauter Stimme (mit lautem Schrei) geschrien hatte, sprach Jesus: Vater, in deine Hände übergebe ich meinen Geist (deinen Händen vertraue ich meinen Geist an). Indem er dieses sagte, hauchte er [sein Leben] aus.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 47, 'Als der Centurio (Anführer der Hundertschaft) sah, was geschah, pries (verherrlichte) er Gott, indem er sprach: Dieser Mensch war wirklich ein Gerechter!');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 48, 'Und all die Leute, die zu diesem Schauspiel zusammengekommen waren, kehrten zurück (heim), nachdem sie die Geschehnisse gesehen hatten, indem sie sich [an] die Brust schlugen.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 49, 'Aber alle, die ihm bekannt waren, auch Frauen, die ihm von Galiläa gefolgt waren, standen von ferne, um dieses (diese Dinge) zu sehen.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 50, '');
