INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 30, '');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 31, '');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 32, '');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 33, '');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 34, '');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 35, '');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 36, 'Während sie dies erzählten, stand er selbst in ihrer Mitte und sprach zu ihnen: Friede sei mit euch!');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 37, 'Als solche, die erschreckt und in Angst versetzt worden waren, meinten sie aber, einen Geist zu sehen.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 38, 'Und er sagte ihnen: Warum seid ihr in Aufruhr (Unruhe) versetzt und warum steigen Bedenken (Zweifel, Gedanken) in eurem Herzen auf?');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 39, 'Seht meine Hände und meine Füße, dass ich es selbst bin. Berührt (befühlt, betastet) mich und seht. Denn ein Geist hat nicht Fleisch und Knochen, wie ihr seht, dass ich [sie] habe.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 40, 'Und während er dies sagte, zeigte er ihnen die Hände und die Füße.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 41, 'Da sie noch (immer) vor Freude ungläubig waren und sich wunderten (staunten), sprach er zu ihnen: Habt ihr etwas zu essen (Essbares) hier?');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 42, 'Sie gaben (übergaben) ihm ein Stück gebratenen Fisch.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 43, 'Und indem er es nahm, aß er vor ihnen.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 44, 'Er sprach aber zu ihnen: Diese Dinge (Ereignisse) sind meine Worte, die ich zu euch gesprochen habe, als ich noch bei euch war. Denn alles, was im Gesetz Moses und den Propheten und Psalmen über mich geschrieben ist, muss erfüllt werden.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 45, 'Dann öffnete er ihren Sinn (Verstand), die Schriften zu verstehen.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 46, 'Und er sprach zu ihnen: So ist es geschrieben, dass der Messias (Gesalbte, Christus) leidet und aufersteht von [den] Toten am dritten Tag.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 47, '');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 48, '');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 49, '');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 50, '');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 51, '');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 52, '');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 53, '');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 1, 'Am Anfang war das Wort, und das Wort war bei Gott, und das Wort war gott (Gott, göttlich).');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 2, 'Er (Dieser; Es) war am Anfang bei Gott.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 3, 'Alles ist durch ihn entstanden, und unabhängig von (ohne) ihm ist nicht ein [Ding] entstanden. Was');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 4, 'in ihm (durch ihn) entstanden war, war Leben, und das Leben war das Licht der Menschen –');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 5, 'und das Licht scheint in der Dunkelheit, und die Dunkelheit hat es nicht überwunden (verstanden, aufgenommen; kann es nicht überwinden).');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 6, 'Ein Mensch trat auf (Es war ein Mensch/gab einen Menschen), gesandt von Gott, namens Johannes,');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 7, 'der kam als (zum) Zeugnis, um (damit) als Zeuge über das Licht aufzutreten (auszusagen; Zeugnis zu geben; Zeuge zu sein), damit alle durch ihn (es) glauben werden.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 8, 'Er selbst (Jener, der Genannte) war nicht das Licht, vielmehr (sondern) [war es seine Aufgabe], {um} als Zeuge für das Licht aufzutreten (auszusagen über; Zeugnis zu geben; Zeuge zu sein).');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 9, 'Das (Es/da war das) wahre Licht, das alle Menschen beleuchtet (erleuchtet, erhellt), kam in (das ... kam) in die Welt.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 10, 'Er (es) war in der Welt, und die Welt ist durch ihn entstanden, aber (und) die Welt erkannte (erkannte an, kannte) ihn nicht.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 11, 'Er kam zu den Seinen (zu/in sein Eigentum), aber (und) die Seinen hießen ihn nicht willkommen (nahmen ihn nicht auf).');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 12, 'Aber denjenigen, die ihn aufnahmen (empfingen), gab er das Vorrecht (Erlaubnis, Vollmacht), Kinder Gottes zu werden: denen, die an seinen Namen glaubten (glauben),');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 13, 'die nicht von (aus) Blutes, noch von (aus) fleischlichem Willen, noch von (aus) menschlichem Willen, sondern von (aus) Gott geboren (gezeugt) sind.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 14, 'Und das Wort wurde Fleisch und lebte (wohnte) unter (bei) uns, und wir haben seine Herrlichkeit gesehen, Herrlichkeit wie (als) [die des] einzigartigen (einzigen, eingeborenen) [Sohnes], vom Vater, voller Gnade und Wahrheit.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 15, 'Johannes verbürgte sich für ihn (trat als sein Zeuge auf, bezeugte ihn) und rief die Worte (indem/als er sagte; sagend): „Der hier ist es, den ich meinte (von dem ich sagte): »Der nach mir gekommen ist (kommt), ist vor mich gekommen (wichtiger als ich geworden; vor mir entstanden/gewesen; mir voraus), denn er war vor mir.«“');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 16, 'Denn von seinem Reichtum (Überfluss, Fülle) haben wir alle [etwas] erhalten: Gnade über ((im Austausch ((im Austausch) für) Gnade!');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 17, 'Denn das Gesetz ist durch Mose gegeben worden, [doch] die Gnade und die Wahrheit sind durch Jesus [Wirklichkeit] geworden (entstanden).');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 18, 'Niemand hat Gott jemals gesehen. [Der] einzigartige (einzige) Gott (Sohn) ([Der] einzigartige [Sohn], Gott), der ganz nah (an der Seite, am Busen) des Vaters ist, der hat sich ([ihn]) gänzlich bekannt gemacht.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 19, 'Und dieses ist das Zeugnis des Johannes, als die Juden aus Jerusalem Priester und Leviten (zu ihm) die sandten, damit sie ihn fragen: „Du, wer bist Du?“');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 20, 'Und er bekannte und leugnete nicht, und bekannte {daß}: „Ich bin nicht der Christus.“');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 21, 'Und sie fragten ihn: „Was also? Bist Du Elija?“Und er sagt: „ [Der] bin ich nicht.“„Bist Du der Prophet?“Und er antwortete: „Nein.“');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 22, 'Sie sagten ihm also: „Wer bist Du? Damit wir Antwort geben denen, die uns gesandt haben. Was sagst Du über Dich selbst?“');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 23, 'Er sagte: „Ich bin eine Stimme, die in der Wüste (Einöde) ruft: \'Macht gerade den Weg des Herrn\', wie Jesaja der Prophet sagte.“');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 24, 'Und [einige] Abgesandte waren aus (von) den Pharisäern.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 25, 'Und sie fragten ihn und sagten ihm: „Was also taufst Du, wenn Du nicht der Christus bist, und nicht Elija und nicht der Prophet?“');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 26, '{Der} Johannes antwortet ihnen sagend: „Ich taufe mit (in) Wasser. Unter Euch steht [der], den Ihr nicht kennt,');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 27, 'der nach mir Kommende, dessen Schuhriemen (dessen Riemen der Sandale) zu lösen ich nicht wert bin.“');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 28, 'Dies geschah in Betanien, auf der anderen Seite des Jordan, wo {der} Johannes taufte.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 29, 'Am nächsten Tag sieht er {den} Jesus auf sich zukommen (zu ihm kommen) und sagt: „Sieh das Lamm Gottes, das wegnimmt (hinwegnimmt, trägt) die Sünde der Welt.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 30, 'Dieser ist es, über den ich gesagt habe: \'Nach mir kommt ein Mann, der mir voraus war, weil er vor mir war.\'');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 31, 'Auch ich kannte ihn nicht, aber damit er {dem} Israel bekannt (offenbart) werde, deshalb bin ich gekommen, mit (in) Wasser zu taufen.“');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 32, 'Und Johannes bezeugte {sagend daß}: „Ich habe den Geist wie eine Taube aus dem Himmel herabsteigen sehen, und er blieb (verweilte) auf ihm.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 33, 'Auch ich kannte ihn nicht, aber [der,] der mich gesandt hat, mit (in) Wasser zu taufen, {jener} sagte mir: \'Auf wen immer Du den Geist herabsteigen und verweilen (bleiben) siehst, dieser ist der mit (in) heiligem Geist Taufende.\'');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 34, 'Und ich habe gesehen und habe bezeugt, daß dieser der Erwählte (Sohn) Gottes ist.“');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 35, 'Am nächsten Tag stand {der} Johannes wiederum [da] und zwei seiner Jünger,');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 36, 'und wie er {den} Jesus entlanggehen sieht, sagt er: „Sieh das Lamm Gottes.“');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 37, 'Und seine (die) zwei (beiden) Jünger hörten ihn sprechen und folgten Jesus.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 38, 'Wie sich {der} Jesus aber umwended und sieht, daß sie ihm folgen, sagt er ihnen: „Was sucht ihr?“Die aber sagten ihm: „Rabbi – das heißt übersetzt Lehrer –, wo wohnst Du (hältst Du Dich auf)?“');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 39, 'Er sagt ihnen: „Kommt und seht.“Sie kamen also und sahen, wo er wohnt (sich aufhält), und blieben bei ihm jenen Tag (hielten sich jenen Tag bei ihm auf). Das war um die (ungefähr die) zehnte Stunde.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 40, 'Andreas, der Bruder des Simon Petrus, war einer von der beiden, die {von} Johannes gehört hatten und [Jesus] {ihm} gefolgt waren.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 41, 'Dieser findet zuerst den Bruder, den eigenen, Simon und sagt ihm: „Wir haben den Messias – das heißt übersetzt Christus – gefunden.“');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 42, 'Er führte ihn zu Jesus. Wie er ihn sieht, sagte Jesus: „Du bist Simon, der Sohn [des] Johannes; Du wirst Kephas – {was} übersetzt {wird} Petrus (Fels) – genannt werden (heißen).“');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 43, 'Am nächsten Tag wollte er nach Galiäa gehen (weggehen). Und er findet Philippus und {der} Jesus sagt ihm: „Folge mir.“');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 44, '{Der} Philippus aber war von Betsaida, aus der Stadt des Andreas und Petrus.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 45, 'Philippus findet den Nathanaël und sagt ihm: „Wir haben den gefunden, über den Mose im Gesetz geschrieben hat und die Propheten, Jesus, Sohn des Josef, den von Nazaret.“');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 46, 'Und Natanaël sagte ihm: „Aus Nazaret kann [(also)] etwas Gutes sein (kommen)?“{Der} Philippus sagt ihm: „Komm und sieh.“');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 47, '{Der} Jesus sah den Nathanaël auf sich zukommen und sagt über ihn: „Sieh, wahrhaftig ein Israelit, in dem keine Hinterlist (kein Betrug, nichts Unehrliches, nichts Falsches, keine Falschheit) ist.“');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 48, 'Nathanaël sagt ihm: „Woher kennst Du mich?“Jesus antwortete und sagte ihm: „Bevor Dich Philippus rief, habe ich Dich unter dem Feigenbaum gesehen (Dich gesehen, wie Du unter dem Feigenbaum warst).“');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 49, 'Nathanaël antwortete ihm: „Rabbi, Du bist der Sohn {des} Gottes, Du bist [der] König Israels.“');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 50, 'Jesus antwortete und sagte ihm: „Weil ich Dir gesagt habe, daß ich Dich unter dem Feigenbaum sah, glaubst Du? Du wirst größere Dinge als diese sehen.“');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 51, 'Und er sagt ihm: „Amen, Amen, (Wahrlich, wahrlich) sage ich Euch: Ihr werdet den Himmel geöffnet (offen) sehen und die Engel (Boten) Gottes auf den (über dem) Sohn des Menschen auf- und niedersteigen.“');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 2, 1, 'Und am dritten Tag fand eine Hochzeit in (zu) Kana in Galiläa (im galiläischen Kana) statt, und die Mutter Jesu war dort.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 2, 2, 'Aber auch (sowohl) {der} Jesus und (als auch) seine Jünger waren zur Hochzeit eingeladen (gerufen).');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 2, 3, 'Und als der Wein ausgegangen war, sagt die Mutter Jesu zu ihm: „Sie haben keinen Wein.“');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 2, 4, 'Und {der} Jesus sagt ihr: „Welche besondere Beziehung gibt es zwischen Dir und mir, Frau [, daß Du damit zu mir kommst]? Meine Stunde ist noch nicht gekommen.“');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 2, 5, 'Seine Mutter sagt den Dienern: „Was immer er Euch sagt, [das] tut.“');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 2, 6, 'Es standen (lagerten) aber dort – zum Zweck der (zur) Reinigung (für das Reinigungsritual) [(entsprechend dem Brauch)] der Juden – sechs steinerne Wasserkrüge, die jeder zwei oder drei Maß fassten.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 2, 7, 'Jesus sagt ihnen: „Füllt die Wasserkrüge mit Wasser.“Und sie füllten sie bis oben [an].');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 2, 8, 'Und er sagt ihnen: „Schöpft jetzt und bringt [das Geschöpfte] dem Tafelmeister (Verantwortlichen für das Festmahl, Vorsitzenden der Festtafel).“Die aber brachten [es ihm].');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 2, 9, 'Wie aber der Tafelmeister (Verantwortliche für das Festmahl, Vorsitzende der Festtafel) das Wasser, das Wein geworden war, kostete, und nicht wußte, woher es war (ist) – die Diener aber, die das Wasser geschöpft hatten, wußten [es] – ruft der Tafelmeister (Verantwortliche für das Festmahl, Vorsitzende der Festtafel) den Bräutigam');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 2, 10, 'und sagt ihm: „Jeder Mensch serviert zuerst den guten Wein, und wenn sie (die Gäste) betrunken sind, den schlechteren. Du aber hast den guten Wein bis jetzt zurückgehalten (aufbewahrt).“');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 2, 11, 'Diesen Anfang der Zeichen machte (setzte) {der} Jesus in (zu) Kana in Galiläa (im galiläischen Kana) und er offenbarte seine Herrlichkeit und seine Jünger glaubten an ihn.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 2, 12, 'Danach ging er nach Kafarnaum hinab, und [auch] seine Mutter und seine Brüder und Jünger, und dort blieben sie einige wenige Tage.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 2, 13, 'Und das Pascha (Paschafest) der Juden war nahe, und Jesus ging nach Jerusalen hinauf.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 2, 14, 'Und er fand im Tempel die Verkäufer von Rindern und Schafen und Tauben und die Geldwechsler dasitzen.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 2, 15, 'Und er machte eine Peitsche aus Stricken und warf alle aus dem Tempel heraus, und auch (ebenso) (sowohl) die Schafe und (wie) die Rinder, und das Wechselgeld der Geldwechsler schüttete er aus (auf den Boden) und die Tische warf er um.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 2, 16, 'Und denen, die die Tauben verkauften, sagte er: „Tragt (bringt) diese Dinge von hier weg, macht das Haus meines Vater nicht zu einem Kaufhaus (Haus eines Handelsplatzes).“');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 2, 17, 'Seine Jünger erinnerten sich, daß geschrieben ist (steht): „Der Eifer für Dein Haus wird mich verzehren.“');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 2, 18, 'Die Juden also antworteten und sagten ihm: „Welches Zeichen zeigst Du uns, da Du solche Dinge tust (das bestätigt, daß Du berechtigt bist, solche Dinge zu tun)?“');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 2, 19, 'Jesus antwortete und sagte ihnen: „Zerstört (löst) diesen Tempel und in drei Tagen werde ich ihn (wieder) aufrichten.“');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 2, 20, 'Sagten also die Juden: „ [In] sechsundvierzig Jahren wurde dieser Tempel erbaut, und Du wirst (willst) ihn in drei Tagen aufrichten (wiederaufrichten, wiedererrichten)?“');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 2, 21, 'Jener aber sprach über den Tempel seines Körpers.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 2, 22, 'Als er also von (aus) den Toten auferweckt worden (erstanden, auferstanden) war, erinnerten sich seine Jünger, daß er dieses gesagt hatte, und sie glaubten der Schrift und dem Wort, das Jesus gesagt hatte.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 2, 23, 'Als er aber in Jerusalem während des Paschas (Paschafestes), während des Festes war, kamen viele zum Glauben (glaubten viele) an seinen Namen, da sie die Zeichen sahen, die er tat.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 2, 24, 'Jesus selbst aber vertraute sich ihnen nicht an, da er alle kannte');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 2, 25, 'und weil er es nicht nötig hatte, daß einer Zeugnis gebe über den Menschen, selbst nämlich wußte (erkannte) er, was in dem Menschen war.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 1, 'Es war {aber} ein Mensch von (aus) den Pharisäern, Nikodemus war sein Name, [einer] der Mächtigen (Alten, Oberen) der Juden.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 2, 'Dieser kam nachts zu ihm und sagte zu ihm: Lehrer (Rabbi), wir wissen, dass du von Gott gekommen bist, ein Lehrer. Denn niemand kann diese Zeichen tun, die du tust, wenn nicht Gott mit ihm sei.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 3, 'Jesus antwortete und sagte zu ihm: Wahrlich, wahrlich, ich sage dir, wer nicht von neuem geboren wird, kann das Königreich Gottes nicht sehen.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 4, 'Nikodemus sagt zu ihm: Wie kann ein Mensch gezeugt (geboren) werden, wenn er ein Greis ist? Kann er etwa zum zweiten mal (erneut) in den Mutterleib hineingehen und geboren werden?');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 5, 'Jesus antwortete: Wahrlich, wahrlich, ich sage dir: Wenn jemand nicht aus Wasser und Geist geboren wird, kann er nicht in das Königreich Gottes eingehen.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 6, 'Das Gezeugte aus dem Fleisch ist Fleisch; und das Gezeugte aus dem Geist ist Geist.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 7, 'Wundere dich nicht, wenn ich dir sagte: Es ist nötig, dass ihr von neuem geboren werdet.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 8, 'Der Geist weht, wo er will, und seine Stimme hörst du zwar, aber du weißt nicht, woher er kommt und wohin er geht. So ist jeder aus dem Geist Geborene (Gezeugte).');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 9, 'Nikodemus antwortete und sagte zu ihm: Wie kann dies geschehen?');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 10, 'Jesus antwortete und sagte zu ihm: Du bist der Lehrer Israels und weißt dies nicht?');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 11, 'Wahrlich, wahrlich, ich sage dir: Das, was wir wissen, davon reden wir, und was wir gesehen haben, bezeugen wir, und unser Zeugnis nehmt ihr nicht an.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 12, 'Wenn ich euch das Irdische sage und ihr glaubt nicht, wie werdet ihr glauben, wenn ich euch das Himmlische sage?');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 13, 'Niemand ist hinaufgestiegen in den Himmel, als nur derjenige, der aus dem Himmel herabgekommen ist, nämlich der Sohn des Menschen.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 14, 'Und wie Mose die Schlange in der Wüste erhöhte, so ist es nötig, dass der Menschensohn erhöht wird,');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 15, 'damit jeder, der glaubt, in ihm das ewige Leben hat.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 16, 'So nämlich hat Gott die Welt geliebt, dass er seinen einzigen Sohn gab, damit jeder, der an ihn glaubt, nicht verloren geht, sondern ewiges Leben hat.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 17, 'Denn Gott hat den Sohn nicht in die Welt geschickt (gesandt), damit er die Welt richtet, sondern damit die Welt durch ihn gerettet wird.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 18, 'Wer an ihn glaubt, wird nicht gerichtet. Wer aber nicht glaubt, ist schon gerichtet, weil er nicht an den Namen des einzig geborenen (eingeborenen) Sohnes Gottes geglaubt hat.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 19, 'Dies aber ist das Urteil (das Gericht), daß das Licht in die Welt kam und die Menschen die Dunkelheit (Finsternis) mehr liebten als das Licht – ihre Werke waren nämlich böse (schlecht).');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 20, 'Jeder nämlich, der das Schlechte tut (zu tun pflegt), haßt das Licht und kommt nicht zum Licht, damit seine Werke nicht bloßgestellt (öffentlich gemacht und gerügt/verurteilt) werden.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 21, 'Wer aber die Wahrheit tut, kommt zum Licht, damit seine Taten offenbar (sichtbar, bekannt) werden, [und offenbar wird,] daß sie in Gott (mit Gottes Hilfe, nach Gottes Willen) getan (vollbracht, gewirkt) sind.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 22, 'Danach kamen {der} Jesus und seine Jünger in das Land Judäa, und dort verweilte er mit ihnen und taufte.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 23, 'Aber auch {der} Johannes taufte [damals] in Änon nahe Salims, weil es dort viel Wasser gab, und Leute kamen (hinzu) und ließen sich taufen (wurden getauft).');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 24, 'Johannes war (lag) nämlich noch nicht ins (im) Gefängniss geworfen (worden).');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 25, 'Es kam also zu einer Diskussion (einer Auseinandersetzung, einem Wortgefecht) ausgehend von (unter, zwischen) den Jüngern (einigen der Jünger) [des] Johannes und (mit) einem Juden über die Frage der (über die) Reinigung.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 26, 'Und sie kamen zu {dem} Johannes und sagten ihm: „Rabbi, der [Mann], der mit Dir auf der anderen Seite des Jordans war, über (für) den Du Zeugnis gegeben hast, sieh, dieser tauft und alle kommen zu ihm.“');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 27, 'Johannes antwortete und sagte: „Ein Mensch kann [sich] nichts (nicht einmal eine einzige Sache) nehmen, wenn es (sie) ihm nicht aus dem (vom) Himmel gegeben ist (wird).');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 28, 'Ihr selbst seid meine Zeugen (bezeugt mir), daß ich gesagt habe: »Nicht bin ich der Christus (Messias), sondern {daß} ein Bote (Gesandter) bin ich vor ihm (jenem).«');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 29, 'Wer die Braut hat, [der] ist der Bräutigam. Der Freund des Bräutigams aber, der dabeisteht (steht) und ihn hört, freut sich mit Freude wegen der Stimme des Bräutigams. Diese meine Freude ist also jetzt erfüllt (vervollständigt).');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 30, 'Jener muß wachsen, ich aber kleiner werden (abnehmen).“');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 31, 'Wer von oben kommt, steht (ist) über allen. Wer aus der Erde (irdisch) ist, ist aus der Erde (irdisch) und spricht aus der Erde (so spricht er auch, spricht irdisch). Wer aus dem Himmel kommt, steht (ist) über allen.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 32, 'Was er gesehen und gehört hat, dieses bezeugt er, und keiner nimmt sein Zeugnis an.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 33, 'Wer sein Zeugnis annimmt, [der] (hat) besiegelt (bestätigt, beglaubigt), daß Gott wahrhaftig ist.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 34, 'Der nämlich, den Gott gesandt hat, [der] spricht die Worte Gottes, denn er gibt den Geist nicht spärlich.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 35, 'Der Vater liebt den Sohn, und alles (alle Dinge) hat er in seine Hand gegeben.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 36, 'Wer an den Sohn glaubt, hat ewiges Leben. Wer aber dem Sohn nicht gehorcht, wird [das] Leben nicht sehen, sondern der Zorn Gottes bleibt auf ihm.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 1, 'Als Jesus erfuhr, dass die Pharisäer gehört hatten, dass er mehr Jünger gewann und taufte als Johannes –');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 2, 'obwohl er nicht selbst taufte, sondern seine Jünger –');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 3, 'verließ er Judäa und ging wieder nach Galiläa.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 4, 'Er musste aber durch Samarien hindurch reisen.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 5, 'Auf diesem Weg kommt er in eine Stadt Samariens, die Sychar heißt und nahe bei dem Land liegt, das Jakob seinem Sohn Josef gegeben hatte.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 6, 'Dort aber war der Jakobsbrunnen. Erschöpft von der Wanderung, setzte Jesus sich also an den Brunnen. Das war um die sechste Stunde.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 7, 'Da kam eine samaritische Frau, um Wasser zu schöpfen. Jesus sagte zu ihr: Gib mir zu trinken!');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 8, 'Denn seine Jünger waren weggegangen in die Stadt, um Lebensmittel zu kaufen.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 9, 'Da sagte die samaritische Frau zu ihm: Wieso erbittest du, der du doch ein Jude bist, von mir etwas zu trinken, die ich doch eine samaritische Frau bin? Denn die Juden verkehren nicht mit den Samaritern.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 10, 'Jesus antwortete und sagte ihr: Wenn du die Gaben Gottes kennen würdest und wer der ist, der zu dir sagt: Gib mir zu trinken, dann hättest du ihn gebeten, und er hätte dir lebendiges Wasser gegeben.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 11, 'Die Frau erwiderte ihm: Herr, Du hast kein Schöpfgefäß und der Brunnen ist tief. Woher willst du dann das lebendige Wasser nehmen?');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 12, 'Bist du etwa größer als unser Vater Jakob, der uns diesen Brunnen gab, aus dem er selbst, seine Söhne und auch sein Vieh getrunken haben?');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 13, 'Jesus antwortete und sprach zu ihr: Jeder, der von diesem Wasser trinkt, den wird wieder dürsten.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 14, 'Wer dagegen von dem Wasser trinkt, dass ich ihm geben werde, den wird in Ewigkeit nicht dürsten. Vielmehr wird das Wasser, das ich ihm geben werde, in ihm eine Quelle eines Wassers werden, das in das ewige Leben sprudelt.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 15, 'Da sagte die Frau zu ihm: Herr, gib mir dieses Wasser, damit mich nie wieder dürstet und ich nicht hierher kommen muss, um Wasser zu schöpfen!');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 16, 'Darauf forderte er sie auf: Geh, ruf deinen Mann und komm [dann] hierher.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 17, 'Da entgegnete ihm die Frau: Ich habe keinen Mann. Und Jesus spricht: Zu Recht hast du gesagt: Ich habe keinen Mann.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 18, 'Denn du hast fünf Männer gehabt und der, den du jetzt hast, der ist nicht dein Mann. Du hast die Wahrheit gesagt.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 19, 'Da sagte die Frau zu ihm: Herr, ich sehe, dass du ein Prophet bist.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 20, 'Unsere Väter haben auf diesem Berg angebetet. Und ihr [Juden] sagt, in Jerusalem ist der Ort, wo man anbeten muss.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 21, '[Darauf] sagte Jesus zu ihr: Glaube mir, Frau, die Stunde kommt, da ihr weder auf diesem Berg noch in Jerusalem den Vater anbeten werdet.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 22, 'Ihr betet an, was ihr nicht kennt; wir [dagegen] beten an, was wir kennen, denn das Heil kommt von den Juden.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 23, 'Aber es kommt die Stunde – und sie ist bereits da –, da die wahren Anbeter den Vater im Geist und in der Wahrheit anbeten werden. Denn der Vater sucht solche, die ihn so anbeten.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 24, 'Gott ist Geist und die ihn anbeten, müssen ihn im Geist und in der Wahrheit anbeten.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 25, 'Da sagte die Frau zu ihm: Ich weiß, dass der Messias kommen wird, der Christus genannt wird. Und wann auch immer er kommt, er wird uns alles verkünden.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 26, 'Da sagte Jesus zu ihr: Ich, der ich mit dir rede, bin es.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 27, 'Und darüber kamen seine Jünger und wunderten sich, dass er mit einer Frau sprach. Niemand jedoch sagte: Was fragst Du? oder Was redest du mit ihr?');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 28, 'Nun ließ die Frau ihren Krug stehen und ging in die Stadt und spricht zu den Leuten:');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 29, 'Kommt, seht einen Menschen, der mir alles gesagt hat, was ich getan habe, ob dieser nicht der Christus ist.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 30, 'Da gingen sie hinaus aus der Stadt und kamen zu ihm.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 31, 'Inzwischen baten die Jünger ihn und sprachen: Rabbi, iss!');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 32, 'Er aber sprach zu ihnen: Ich habe eine Speise zu essen, welche ihr nicht kennt.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 33, 'Da sprachen die Jünger zueinander: Ob ihm jemand zu essen gebracht hat?');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 34, 'Jesus entgegnete ihnen: Meine Speise ist, dass ich den Willen dessen tue, der mich gesandt hat und sein Werk vollende.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 35, 'Sagt ihr nicht, dass es noch vier Monate sind, bis die Ernte kommt? Ich sage euch: Hebt eure Augen auf und seht euch die die Felder an: Sie sind reif für die Ernte.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 36, 'Der, der erntet, empfängt Lohn und sammelt Frucht zum ewigen Leben, damit der Säende sich gemeinsam mit dem Erntenden freut.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 37, 'Denn darin ist der Spruch wahr, dass der eine der Säende ist und ein anderer der Erntende.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 38, 'Ich habe euch gesandt zu ernten, wo ihr nicht gearbeitet habt. Andere haben gearbeitet und euch ist ihre Arbeit zugute gekommen.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 39, 'Aus jener Stadt aber glaubten viele an ihn, wegen der Aussage der Frau, die bezeugte: Er hat mir alles gesagt, was ich getan habe.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 40, 'Als nun die Samariter zu ihm kamen, baten sie ihn, bei ihnen zu bleiben und er blieb dort zwei Tage.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 41, 'Und um vieles mehr glaubten sie aufgrund seiner Worte.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 42, 'Und sie sagten zu der Frau: Wir glauben nicht mehr wegen deiner Rede. Denn wir haben selbst gehört und wissen, dass dieser wahrhaftig der Retter der Welt ist.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 43, 'Und nach zwei Tagen ging er fort von dort nach Galiläa.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 44, 'Den Jesus selbst bezeugte, dass ein Prohpet in seinem eigenen Vaterland keine Ehre hat.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 45, 'Als er nun also nach Galiläa kam, nahmen ihn die Galiläer [freundlich] auf, die (weil sie, nachdem sie) alles gesehen hatten, was er in Jerusalem beim Fest getan hatte, dan auch sie waren zum Fest gekommen.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 46, 'Er kam nun wieder nach Kana in Galiläa, wo er das Wasser zu Wein gemacht hatte. Und es war ein königlicher [Beamter], dessen Sohn (Junge) krank war, in Kafarnaum.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 47, 'Dieser, als er gehört hatte, dass Jesus von Judäa nach Galiläa kommt, ging fort zu ihm und bat, dass er herab gehe und heile seinen Sohn (Jungen), denn er war im Begriff zu sterben.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 48, 'Nun sprach Jesus zum ihm: Wenn ihr nicht Zeichen und Wundertaten seht, glaubt ihr nicht.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 49, 'Der königliche [Beamte] spricht zu ihm: Herr, geh hinab bevor mein Kind (Junge) stirbt.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 50, 'Jesus spricht zu ihm: Geh fort, dein Sohn (Kind) lebt. Der Mensch glaubte (vertraute) dem Wort, das ihm Jesus sagte und ging fort.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 51, 'Noch als er hinab ging, kamen ihm seine Sklaven entgegen, wobei sie sagten: Das Kind (der Junge) lebt!');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 52, 'Er erfragte nun die Stunde von ihnen, zu der es ihm besser ging. Sie sagten ihm nun: Gestern zur siebten Stunde verließ ihn das Fieber.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 53, 'Da erkannte der Vater, dass es zu jener Stunde [gewesen war], zu der ihm Jesus gesagt hatte: Dein Sohn lebt. Und er kam zu Glauben (glaubte) – er selbst und sein ganzes Haus (seine ganze Hausgemeinschaft, seine ganze Familie).');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 54, 'Dieses tat Jesus wiederum als zweites Zeichen kommend von Judäa nach Galiläa.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 1, 'Danach (Nach diesen Dingen) war (gab es) (fand) ein Fest der Juden (statt) und Jesus ging (stieg) nach Jerusalem hinauf.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 2, 'Es gibt aber in Jerusalem beim Schafstor einen Teich, der auf hebräisch (auch) Betzata heißt (genannt wird) und der fünf Säulenhallen hat.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 3, 'In diesen lag eine Menge der Kranken, Blinden, Lahmen, Vertrockneten (Dürren, an Auszehrung Leidenden, Verkrüppelten).');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 4, '');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 5, 'Es war aber ein (irgendein) Mensch dort, der achtunddreißig Jahre hatte (an sich hatte, erlitt, innehatte) in seiner Krankheit;');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 6, 'als Jesus diesen liegen (krank da liegen) sah und wusste (erkannte), dass er [sie] schon (jetzt) lange Zeit hat, spricht (redet) er zu ihm: Willst du gesund werden?');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 7, 'Der Kranke antwortete ihm: Herr, ich habe keinen Menschen, der (daß er) mich in den Teich hinabläßt (bringt, wirft; hinablasse, bringe, werfe), wenn das Wasser aufgewühlt (bewegt) wird. Während aber ich selbst hingehe (komme), steigt ein anderer vor mir hinab.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 8, 'Jesus spricht zu ihm: Steh auf, nimm (hebe auf) dein Bett (Matte) und geh umher!');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 9, 'Und sofort wurde der Mensch gesund und nahm (hob auf) sein Bett (Matte) und ging umher. Es war aber Sabbat an jenem Tag.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 10, 'Die Juden sagten also dem Geheilten: Es ist Sabbat, und Dir ist nicht erlaubt, Deine Bahre (Matte, Dein Bett) zu tragen (aufzuheben, zu nehmen).');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 11, 'Der (Er) aber antwortete ihnen: [Der (Er),] der mich gesund gemacht hat, der (er, jener) hat mir gesagt: Nimm (trage, hebe) Deine Bahre (Matte, Dein Bett; auf) und geh (umher).');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 12, 'Sie fragten ihn: Wer ist der Mensch, der Dir sagte: Nimm (hebe auf, trage) und geh (umher)?');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 13, 'Der Geheilte aber wußte nicht, wer er (es) ist (war), denn {der} Jesus hatte sich zurückgezogen (entfernt, war entwichen), da eine große Menge an dem Ort war.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 14, 'Danach (Nach diesen Dingen) fand Jesus ihn im Tempel und sagte ihm: Sieh, gesund bist Du geworden; sündige nicht mehr, damit Dir nicht Schlimmeres geschieht.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 15, 'Der Mann (Mensch) ging weg und berichtete (meldete) den Juden, daß Jesus es (der) ist, der ihn gesund machte (gemacht hatte).');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 16, 'Und deshalb verfolgten die Juden den Jesus, weil er das (dies, diese Dinge) an einem Sabbat gemacht hatte (machte).');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 17, 'Er (Der) antwortete ihnen: Mein Vater arbeitet (wirkt) bis jetzt und auch Ich arbeite (wirke).');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 18, 'Deshalb also suchten (versuchten) die Juden [noch] mehr, ihn zu töten, weil er nicht allein den Sabbat brach, sondern auch {den} Gott den eigenen Vater nannte (sagte, Gott sei sein eigener Vater) und sich selbst [so] {dem} Gott gleich machte.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 19, '{Der} Jesus antwortete also und sagte ihnen: Amen, Amen, (Wahrlich, wahrlich,) ich sage Euch, der Sohn kann nichts von sich aus tun, wenn er nicht den Vater etwas tun sieht. Was (welche Dinge) immer nämlich jener tut, das (diese Dinge) tut gleicherweise auch der Sohn.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 20, 'Der Vater nämlich liebt den Sohn und zeigt ihm alles (alle Dinge), was (die) er selbst tut, und größere Werke als dies (diese) wird er ihm zeigen, damit ihr Euch wundert (staunt).');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 21, 'Wie nämlich der Vater die Toten auferweckt (erweckt, aufweckt) und lebendig macht, so macht auch der Sohn die lebendig, die er will.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 22, 'Und nicht nämlich richtet (verurteilt) der Vater irgend jemanden, sondern er gab das ganze Gericht dem Sohn,');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 23, 'damit alle den Sohn ehren, wie sie den Vater ehren. Wer den Sohn nicht ehrt, ehrt den Vater nicht, der ihn gesandt hat.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 24, 'Amen, Amen (Wahrlich, wahrlich), ich sage Euch: {daß} Wer mein Wort hört und dem glaubt (vertraut), der mich gesandt hat, hat ewiges Leben und kommt nicht ins (in ein) Gericht, sondern ist aus dem Tod in das Leben hinübergegangen.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 25, 'Amen, Amen (Wahrlich, wahrlich), ich sage Euch: {daß} Die Stunde kommt und ist jetzt [da], wenn die Toten die Stimme des Sohnes Gottes hören werden und diejenigen, die hören, werden leben.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 26, 'Wie nämlich der Vater das Leben in sich selbst hat, so auch gab er dem Sohn, Leben in sich selbst zu haben.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 27, 'Und er gab ihm Vollmacht, zu richten (zu urteilen, Gericht zu halten), weil er Menschensohn (Sohn eines Menschen, ein Menschensohn) ist.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 28, '(Ihr) Wundert Euch (Staunt, Ihr Staunt) nicht darüber, daß (denn) eine Stunde kommt, in der alle, die in den Gräbern [sind] seine Stimme hören werden');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 29, 'und herausgehen werden: diejenigen, die das Gute getan haben, hin zu einer Auferstehung des Lebens, diejenigen aber, die das Schlechte (die schlechten Dinge) zu tun pflegten (getan haben), zu einer Auferstehung des Gerichts. (?)');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 30, 'Von mir aus kann ich nichts tun. Wie ich [es] höre, [so] richte (urteile) ich und mein Urteil (Gericht) ist gerecht, weil ich nicht meinen Willen suche, sondern den Willen dessen, der mich gesandt hat.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 31, 'Wenn ich Zeugnis ablege über (für) mich, ist mein Zeugnis nicht wahr (wahrhaftig, echt, gültig).');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 32, 'Ein anderer ist es (derjenige), der Zeugnis über (für) mich ablegt, und ich weiß, daß das Zeugnis, das er über (für) mich ablegt (bezeugt), wahr (wahrhaftig, echt) ist.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 33, 'Ihr habt zu Johannes gesandt, und er hat Zeugnis abgelegt für die Wahrheit.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 34, 'Ich aber nehme von einem Menschen das Zeugnis nicht an, sondern ich sage das (diese Dinge), damit ihr gerettet werdet.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 35, 'Jener war die Lampe, die brennt (brannte, angezündet wird, verbrennt, verbrannte) und leuchtet (scheint, schien, leuchtete), Ihr aber wolltet Euch für eine (zu einer) Stunde in seinem Licht erfreuen.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 36, 'Ich aber habe ein (das) Zeugnis, [das] größer [ist] als das des Johannes. Die Werke nämlich, die mir der Vater gab, damit ich sie vollende (verwirkliche, vollbringe), diese Werke selbst, die ich tue, bezeugen (legen Zeugnis ab) über (für) mich, daß der Vater mich gesandt hat.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 37, 'Und der Vater, der mich gesandt hat, jener hat Zeugnis abgelegt für (über) mich. Und Ihr habt weder jemals seine Stimme gehört noch seine Gestalt (seine Erscheinung, seinen Anblick, seine Form) gesehen');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 38, 'und sein Wort habt Ihr nicht dauerhaft (bleibend) in Euch (wohnen), weil Ihr dem, den er (jener) gesand hat, nicht glaubt.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 39, 'Ihr erforscht (durchforscht) die Schriften, weil Ihr meint, in ihnen ewiges Leben zu haben. Und jene sind es, die Zeugnis ablegen über (für) mich.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 40, 'Und Ihr wollt nicht zu mir kommen, um (damit Ihr) Leben zu haben (habt).');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 41, 'Anerkennung (Preis, Ruhm, Ehre) von Menschen nehme ich nicht an,');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 42, 'aber ich habe {Euch} erkannt (Euch durchschaut, kenne Euch), daß Ihr die Liebe Gottes nicht in Euch habt.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 43, 'Ich bin im Namen meines Vaters gekommen, und ihr nehmt mich nicht an. Wenn ein anderer kommt im eigenen Namen, [dann] werdet Ihr jenen annehmen.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 44, 'Wie könnt Ihr glauben (zum Glauben kommen), wenn Ihr Anerkennung (Preis, Ruhm, Ehre) von einander annehmt, und die Anerkennung (den Preis, Ruhm, die Ehre) von dem einzigen (einen) Gott nicht sucht?');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 45, 'Denkt (Glaubt) nicht, daß ich Euch beim Vater anklagen werde. Derjenige, der Euch anklagt ist Mose, auf den Ihr hofft.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 46, 'Wenn Ihr nämlich Mose glauben würdet, würdet Ihr auch mir glauben. Über mich nämlich hat jener geschrieben.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 47, 'Wenn Ihr aber seinen Schriften (den Schriften jenes) nicht glaubt, wie werdet Ihr meinen Worten glauben?');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 1, 'Danach ging (fuhr?) Jesus weg über das Galiläische Meer, [den See] Tiberias.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 2, 'Es folgte ihm nun aber eine große Volksmenge (Menschenmasse, Menge), weil sie die Zeichen gesehen hatten, die er an den Kranken getan hatte.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 3, 'Es ging aber auf den Berg (stieg hinauf) Jesus, und dort setzte er sich (verweilte, hielt sich auf) mit seinen Jüngern (Schülern).');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 4, 'Es war aber nahe das Pascha, das Fest der Juden.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 5, 'Wie nun Jesus die Augen aufhebt und sieht, dass eine große Menge (Volksmenge, Menschenmasse) zu ihm gekommen war, sagt er zu Philippus: Woher werden wir Brote einkaufen, damit diese essen?');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 6, 'Dies aber sagte er, um ihn auf die Probe zu stellen; er nämlich wusste, was er tun wollte (vorhatte, im Begriff war zu tun).');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 7, 'Ihm antwortete Philippus: Brote im Wert von 200 Denaren genügen nicht für sie, damit jeder ein wenig bekommt.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 8, 'Sagt zu ihm einer seiner Jünger, Andreas, der Bruder von Simon Petrus:');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 9, 'Es ist hier ein Junge, der hat fünf Gerstenbrote und zwei Fische, aber das - was ist das für so viele?');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 10, 'Sprach Jesus: veranlasst (schafft), dass diese Menschen sich lagern (zu Tisch legen). Es war aber viel Gras an dem Ort. Es lagerten (legten sich zu Tisch) nun die Männer, deren Anzahl [war] etwa 5.000.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 11, 'Es nahm nun die Brote Jesus und, nachdem er Dank gesagt (gebetet) hatte, teilte er an die Tischgäste aus, ebenso (in gleicher Weise) auch von den Fischen, so viele wollten.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 12, 'Als sie nun aber satt waren, sagt er seinen Jüngern: sammelt die restlichen Brocken, damit nichts umkommt.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 13, 'Sie sammelten also und füllten zwölf Körbe mit Brocken von den fünf Gerstenbroten, die die Essenden übrig gelassen hatten.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 14, 'Da die Menschen das Zeichen sahen, das er getan hatte, sagten sie: Dieser ist wirklich (wahrhaftig) der Prophet, der in die Welt kommen soll.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 15, 'Da Jesus erkannte, dass sie vorhatten (wollten, im Begriff waren) zu kommen und ihn zu entführen (rauben), um ihn zum König zu machen, zog er sich wiederum auf den Berg zurück (kehrte... zurück), er allein.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 16, 'Als es nun Abend wurde, stiegen seine Jünger zum Meer hinab');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 17, 'und bestiegen ein Boot (Kahn) und fuhren über das Meer nach Kapernaum. Und die Dunkelheit war schon hereingebrochen und noch nicht war zu ihnen gekommen Jesus,');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 18, 'und das Meer wurde von einem stark (heftig) wehenden Wind erregt.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 19, 'Nachdem sie also 25 oder 30 Stadien gerudert waren, sehen sie Jesus, wie er auf dem Meer geht und nahe ans Schiff kommt, und sie fürchteten sich.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 20, 'Er aber spricht zu ihnen: Ich bin [\'s]. Fürchtet euch nicht!');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 21, 'Da wollten sie ihn ins Boot nehmen, und sofort (sogleich) war das Boot an Land, wohin sie aufgebrochen waren.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 22, 'Am nächsten Tag merkte (realisierte, erkannte, sah) die Menge, die [(noch)] auf der anderen Seite des Sees geblieben war (stand), daß dort kein anderes Boot [gewesen] war, außer einem, und daß Jesus nicht mit seinen Jüngern in das Boot eingestiegen war, sondern daß die Jünger alleine weggefahren waren.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 23, 'Von Tiberias her kamen andere Boote in die Nähe des Ortes, wo sie das Brot aßen (gegessen hatten), nachdem der Herr das Dankgebet gesprochen (dankgesagt, gedankt) hatte.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 24, 'Als die Menge also sah, daß Jesus nicht dort ist und auch seine Jünger nicht, stiegen sie in die Boote und kamen nach Kafarnaum und suchten Jesus (um Jesus zu suchen).');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 25, 'Und wie sie ihn auf der anderen Seite des Sees fanden, sagten sie ihm: Rabbi, wann bist du hierher gekommen?');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 26, '{Der} Jesus antwortet ihnen und sagte: Amen, Amen (Wahrlich, wahrlich), ich sage Euch, Ihr sucht mich nicht, weil Ihr Zeichen gesehen habt, sondern weil Ihr von den Broten gegessen habt und satt geworden seid.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 27, 'Arbeitet (Bemüht Euch) nicht für (um) die Nahrung, die vergeht, aber für (um) die Nahrung, die bis in das ewige Leben vorhält (ausreicht, bleibt) und die der Sohn des Menschen (der Menschensohn) Euch geben wird. Diesen nämlich hat der Vater, Gott bestätigt (besiegelt).');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 28, 'Sie sagten also zu ihm: Was sollen wir tun, damit wir für (uns um) die Werke Gottes arbeiten (bemühen, die Werke Gottes tun)?');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 29, '{Der} Jesus antwortete und sagte ihnen: Dieses ist das Werk Gottes, daß Ihr an den glaubt, den er (jener) gesandt hat.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 30, 'Sie sprachen daher (da) zu ihm: Welches Zeichen also wirkst (verrichtest, tust) du, damit wir [es] sehen und dir glauben? Was bewirkst (tust, machst, arbeitest, \'treibst\') du?');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 31, 'Unsere Väter aßen das Manna in der Wüste, wie geschrieben steht: Brot vom Himmel gab er ihnen zu essen.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 32, 'Da sprach Jesus zu ihnen: Amen, amen (wahrhaftig!), ich sage euch, nicht Mose hat euch das Brot vom Himmel gegeben, sondern mein Vater gibt euch das echte (wirkliche, wahrhaftige) Brot vom Himmel.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 33, 'Denn das Brot Gottes ist das, das vom Himmel kommt und das der Welt das Leben gibt.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 34, 'Da sprachen sie zu ihm: Herr, immer (stets, jederzeit) gib uns dieses Brot!');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 35, 'Jesus antwortete (sprach zu) ihnen: Ich bin das Brot des Lebens. Wer zu mir kommt, wird gewiss nicht hungern, und wer an mich glaubt, wird gewiss niemals dürsten!');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 36, 'Aber ich habe Euch gesagt: (daß) Und Ihr habt mich gesehen und doch glaubt Ihr nicht.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 37, 'Alles, was mir der Vater gibt, wird zu mir kommen, und wer zu mir kommt, [den] werde ich sicher nicht wegschicken (herauswerfen).');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 38, 'Denn ich bin vom Himmel heruntergestiegen (heruntergekommen), nicht damit ich meinen Willen verwirkliche (tue), sondern den Willen dessen, der mich gesandt hat.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 39, 'Dieses aber ist der Wille, dessen, der mich gesandt hat, daß ich nichts von allem, was er mir gegeben hat, verliere (vernichte), sondern daß ich es auferwecke am letzten Tag.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 40, 'Dieses nämlich ist der Wille meines Vaters, daß jeder, der den Sohn sieht und an ihn glaubt, ewiges Leben habe – und ich werde ihn auferwecken am letzten Tag.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 41, '[Es] murrten also die Juden über ihn, weil er gesagt hatte: Ich bin das Brot, das vom (aus dem) Himmel heruntergestiegen (heruntergekommen) ist,');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 42, 'und sie sagten: Ist dieser nicht Jesus, der Sohn Josefs, dessen Vater und Mutter wir kennen? Wie sagt er nun: {daß} Vom (aus dem) Himmel bin ich heruntergestiegen (herabgestiegen)?');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 43, 'Jesus antwortete und sagte ihnen: Murrt nicht untereinander (miteinander).');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 44, 'Keiner kann zu mir kommen, wenn nicht der Vater, der mich gesandt hat, ihn heranzieht (zieht) – und ich werde ihn auferwecken am letzten Tag.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 45, 'Es steht (ist) geschrieben in den Propheten: Und alle werden von Gott belehrt (Gottes Gelehrte) sein: Jeder der vom Vater gehört und gelernt hat (hört und lernt), kommt zu mir.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 46, 'Nicht, daß einer den Vater gesehen hat, außer dem, der von Gott ist – dieser hat den Vater gesehen.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 47, 'Amen, Amen (Wahrlich, wahrlich), ich sage Euch, wer glaubt, hat ewiges Leben.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 48, 'Ich bin das Brot des Lebens.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 49, 'Eure Väter haben in der Wüste das Manna gegessen und sind gestorben.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 50, 'Dieses ist das Brot, das vom (aus dem) Himmel herabkommt, damit man (einer) von ihm ißt und nicht stirbt.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 51, 'Ich bin das Brot, das lebendige, das vom (aus dem) Himmel herabgekommen ist: Wenn einer von diesem Brot ißt, wird er in {die} Ewigkeit leben – und das Brot aber, das ich geben werde, ist mein Fleisch für das Leben der Welt.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 52, '[Es] stritten also die Juden untereinander und sagten: Wie kann dieser uns das Fleisch zu essen geben?');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 53, '{Der} Jesus sagte also zu ihnen: Amen, Amen (Wahrlich, wahrlich), ich sage Euch, wenn Ihr nicht das Fleisch des Menschensohns (des Sohns des Menschen) eßt und sein Blut drinkt, habt Ihr kein Leben in Euch.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 54, 'Wer mein Fleisch verzehrt (ißt) und mein Blut drinkt, hat ewige Leben und ich werde ihn am letzten Tag auferwecken (aufwecken).');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 55, 'Denn mein Fleisch ist wahre Speise (wahrhaftiges Speisen) und mein Blut ist wahrer Trank (wahrhaftiges Trinken).');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 56, 'Wer mein Fleisch isst (kaut) und mein Blut trinkt, bleibt in mir und ich in ihm.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 57, 'Wie mich der lebendige Vater geschickt hat und ich durch den Vater lebe, wird auch jener, der mich isst (kaut) und trinkt, leben durch mich.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 58, 'Dies ist das Brot, das aus dem Himmel herabkam. Und nicht wie die Väter (Vorfahren, Vorväter) - sie aßen und starben (mussten sterben). Wer dieses Brot isst, wird leben in Ewigkeit.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 59, 'Dies sagte er in einer Synagoge, lehrend, in Kafarnaum.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 60, 'Viele von seinen Jüngern (Schülern), sagten, als sie es gehört hatten: Hart ist dieses Wort, wer kann es (ihn) anhören?');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 61, 'Jesus, der wusste, dass seine Jünger (Schüler) darüber murrten (tuschelten), sagte zu ihnen: Das regt euch auf?');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 62, '[Was wäre], wenn ihr nun den Menschensohn sehen würdet, der hinaufsteigt, wo er vorher war?');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 63, 'Der Geist (Wind, Atem) ist es, der lebendig macht. Das Fleisch [allein] nützt gar nichts. Die Worte (Rede, Lehre), die ich zu euch gesprochen habe, sind Geist und sind Leben.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 64, 'Doch es gibt einige von euch, die nicht glauben (vertrauen). Jesus wusste nämlich von Anfang an, welche die sind, die nicht glaubten, und welcher der ist, der ihn verriet');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 65, 'Und er sprach: Darum habe ich euch gesagt, dass keiner zu mir kommen kann, wenn es ihm nicht gegeben wäre vom Vater.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 66, 'Aus diesem Grund (Von da an) zogen sich viele seiner Jünger zurück und folgten ihm (begleiteten ihn) nicht mehr (zogen nicht mehr mit ihm umher).');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 67, 'Jesus sagte also zu den Zwölf: „Wollt (vielleicht, etwa) auch ihr weggehen?“');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 68, 'Simon Petrus antwortete ihm: „Herr, zu wem sollen wir gehen? Du hast Worte ewigen Lebens,');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 69, 'und wir glauben (haben geglaubt) und wissen (haben erkannt), daß Du der Heilige Gottes bist.“');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 70, 'Jesus antwortete ihnen: „Habe nicht ich Euch, die Zwölf, erwählt (ausgewählt)? Und [doch] ist einer von Euch ist ein Teufel (Satan, Verleumdner).“');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 71, 'Er meinte aber den Judas [, den Sohn] des Simon Iskariot. Dieser war nämlich im Begriff, ihn auszuliefern (zu veraten), einer von den Zwölf.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 1, 'Und danach (nach diesen Dingen) zog {der} Jesus in {dem} Galiläa umher. Er wollte nämlich nicht in {dem} Judäa umherziehen, weil die Juden versuchten (suchten), ihn zu töten.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 2, 'Es war aber nahe das Fest der Juden, das Laubhüttenfest.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 3, '[Es] sagten also zu ihm seine Brüder: Geh weg von hier und geh (weg) nach Judäa, damit auch Deine Jünger Deine Werke sehen (werden), die Du tust.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 4, 'Keiner nämlich tut etwas im Geheimen (Verborgenen), und versucht (sucht) selbst [dabei gleichzeitig] öffentlich bekannt zu sein. Wenn Du dies (diese Dinge) tust, zeige Dich der Welt.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 5, 'Nicht einmal (Auch) seine Brüder nämlich glaubten (nicht) an ihn.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 6, '{Der} Jesus sagt ihnen also: Meine Zeit ist noch nicht da, aber Eure Zeit ist immer bereit.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 7, 'Euch kann die Welt nicht hassen, mich aber haßt sie, weil ich über sie (von ihr) bezeuge, daß ihre Werke schlecht (böse) sind.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 8, 'Geht Ihr zum Fest hinauf! Ich gehe nichtzu diesem Fest hinauf, weil meine Zeit noch nicht erfüllt ist.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 9, 'Nachdem er dies gesagt hatte, blieb er in {dem} Galiläa.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 10, 'Als aber seine Brüder zum Fest hinaufgegangen waren, da ging auch er hinauf - nicht öffentlich, sondern wie im Geheimen.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 11, 'Die Juden also suchten ihn auf dem Fest und sagten: Wo ist er (jener)?');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 12, 'Und es gab (war) viel Gerede (Murren) über ihn unter den Massen (Mengen Menschenmengen, Menschenmassen). Die einen sagten: {daß} Er ist gut. Andere sagten: Nein, sondern er führt (verführt) die Masse (Menge) in die Irre.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 13, 'Keiner jedoch sprach offen (mit Offenheit, Freimut, öffentlich) über ihn wegen der (aus) Furcht der (vor den) Juden.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 14, 'Als aber das Fest schon halb vorbei war, (Zur Mitte des Festes aber) ging Jesus in den Tempel hinauf und lehrte.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 15, 'Die Juden wunderten sich also und sagten: Wie kennt dieser [(die)] Schriften ohne Ausbildung (gelernt zu haben)?');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 16, 'Jesus also antwortete ihnen und sagte: Meine Lehre ist nicht [die] meine, sondern [die] dessen, der mich gesandt hat.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 17, 'Wenn einer seinen Willen tun will, wird er erkennen, ob die Lehre von Gott ist oder ob ich von mir [aus] spreche.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 18, '[Derjenige,] der (Wer) von sich aus spricht, sucht die eigene Ehre (den eigenen Ruhm, Preis). [Derjenige] aber, der (Wer aber) die Ehre dessen sucht, der ihn gesandt hat, der (dieser) ist wahrhaftig und Unrecht (Ungerechtigkeit, Sünde) ist nicht in ihm.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 19, 'Hat nicht Mose Euch das Gesetz gegeben? Und keiner von Euch tut (erfüllt) das Gesetz. Warum versucht (sucht) Ihr mich zu töten?');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 20, 'Die Menge antwortete: Du hast einen Dämon (bist besessen). Wer versucht (sucht) Dich zu töten?');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 21, 'Jesus antwortete und sagte ihnen: Ein Werk habe ich getan und ihr alle wundert Euch.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 22, 'Deshalb hat Mose Euch die Beschneidung gegeben - nicht, daß [sie] auf Mose zurückgeht (aus dem Mose ist), sie stammt (ist) vielmehr (aber) von den Vätern - und [auch] an einem Sabbat beschneidet Ihr einen Menschen.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 23, 'Wenn ein Mensch [auch] an einem Sabbat beschnitten wird (eine Beschneidung erhält), damit das Gesetz des Mose nicht gebrochen (aufgehoben, gelöst) wird, seid Ihr [trotzdem] verärgert über mich, weil ich einen ganzen Menschen an einem Sabbat gesund gemacht habe?');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 24, 'Urteilt nicht nach dem Anschein (Aussehen, Blick), sondern urteilt (fällt) das (ein) gerechte (gerechtes) Urteil.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 25, 'Sagten also einige der (aus den) Jerusalemer (Jerusalemern): Ist dieser nicht der, den sie versuchen (suchen) zu töten?');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 26, 'Und sieh, offen (öffentlich, mit Offenheit, Freimut) redet er und sie sagen ihm nichts. Haben etwa die Führer wirklich erkannt, daß dieser der Christus ist?');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 27, 'Aber diesen kennen (von diesem wissen) wir, woher er ist (kommt). Wenn aber der Christus kommt, weiß keiner, woher er ist (kommt).');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 28, 'Jesus also rief (schrie) im Tempel, indem er lehrte und sagte: Und mich kennt ihr und wißt, woher ich bin! Und von mir selbst aus bin ich nicht gekommen, aber [der,] der mich gesandt hat und den Ihr nicht kennt, ist wahrhaftig.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 29, 'Ich kenne ihn, denn von ihm bin ich und er (jener) hat mich gesandt.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 30, 'Sie versuchten (suchten) also, ihn zu verhaften (ergreifen, festzunehmen), und keiner legte Hand an ihn, denn seine Stunde war noch nicht gekommen.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 31, 'Aus der Menge aber glaubten (kamen) viele (zum Glauben) an ihn und sagten: Wird der Christus (Messias), wenn er kommt, etwa größere Zeichen tun (verwirklichen) als dieser getan (verwirklicht) hat?');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 32, '[Es] hörten also die Pharisäer die Menge diese Dinge über ihn reden (tuscheln, murren) und die Hohenpriester und die Pharisäer schickten Diener (Gerichtsdiener), damit sie ihn verhaften (festnehmen, ergreifen).');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 33, '{Der} Jesus also sagte: [Nur] noch eine kleine Zeit bin ich bei (mit) Euch und [dann] gehe ich zu dem, der mich gesandt hat.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 34, 'Ihr werdet mich suchen und nicht finden, und wo ich bin (sein werde), [dorthin] könnt Ihr nicht kommen.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 35, '[Es] sagten also die Juden zueinander: Wohin will (ist; hat) dieser (im Begriff zu; vor zu) gehen, sodaß (daß) wir ihn nicht finden werden? Will (Ist; Hat) er etwa (vielleicht) (im Begriff; vor) in die Diaspora der Griechen (zu) gehen und die Griechen (zu) lehren?');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 36, 'Was bedeutet (ist) dieses Wort, das er gesagt hat: Ihr werdet mich suchen und nicht finden, und: Wo ich bin (sein werde), [dorthin] könnt Ihr nicht kommen?');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 37, 'Am letzten Tag aber, dem großen des Festes stand {der} Jesus auf (da) und rief (schrie) und sagte: Wenn einer Durst hat, komme er zu mir und trinke!');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 38, 'Wer an mich glaubt – wie die Schrift gesagt hat: Flüsse lebendigen Wassers werden aus seinem Innersten (Leib, seiner Leibeshöhle) fließen.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 39, 'Dieses aber sagte er über den Geist, den die Glaubenden im Begriff waren, zu empfangen (empfangen sollten). Es gab (war) nämlich noch keinen (kein) Geist [(da)], weil Jesus noch nicht verherrlicht war.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 40, '[Einige] aus der Menge also, die (als sie) diese Worte hörten, sagten: Dieser ist wirklich (tatsächlich, wahrhaftig) der Prophet.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 41, 'Andere sagten: Dieser ist der Christus (der Messias). Wieder andere (Die) aber sagten: Kommt der Christus (Messias) etwa aus Galiläa?');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 42, 'Hat (Sagt) nicht die Schrift gesagt, daß der Christus (Messias) aus der Nachkommenschaft (dem Samen) Davids und aus (von) Bethlehem, dem Dorf, wo David war, kommt?');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 43, 'Eine Spaltung (Meinungsverschiedenheit) also entstand (gab es, war) in der Menge wegen ihm.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 44, 'Einige aber von (aus) ihnen wollten ihn verhaften (festnehmen, ergreifen), aber keiner legte Hand (die Hände) an (auf) ihn.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 45, '[Es] kamen also die Diener (Gerichtsdiener) zu den Hohenpriestern und Pharisäern, und [es] sagten [zu] ihnen die letzteren (jene): Weshalb habt ihr ihn nicht gebracht?');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 46, 'Die Diener (Gerichtsdiener) antworteten: Niemals hat ein Mensch so gesprochen.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 47, 'Die Pharisäer also antworteten ihnen: Seid etwa auch ihr getäuscht (in die Irre geführt, verführt) worden?');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 48, 'Ist etwa einer der (aus den) Führer (Führern) zum Glauben an ihn gekommen oder einer der (aus den) Pharisäer (Pharisäern)?');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 49, 'Aber diese Menge, die das Gesetz nicht kennt – verflucht sind sie.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 50, 'Nikodemus, der früher [einmal] zu ihm gekommen war und einer von ihnen war, sagt zu ihnen:');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 51, 'Verurteilt etwa unser Gesetz den Menschen, wenn es nicht zuerst von ihm hört und weiß (erkennt, versteht), was er tut?');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 52, 'Sie antworteten und sagten ihm: Bist vielleicht (etwa) auch Du aus {dem} Galiläa? Forsche nach und sieh, daß aus {dem} Galiäa kein Prophet kommt (aufsteht)!');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 53, '');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 1, '');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 2, '');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 3, '');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 4, '');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 5, '');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 6, '');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 7, '');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 8, '');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 9, '');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 10, '');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 11, '');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 12, 'Wiederum also sprach Jesus zu ihnen sagend: Ich bin das Licht der Welt. Wer mir folgt (nachfolgt), wandelt nicht in der Finsternis (Dunkelheit), sondern wird das Licht des Lebens haben.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 13, '[Es] sagten ihm also die Pharisäer: Du legst Zeugnis ab (bezeugst) über (für) Dich selbst. Dein Zeugnis ist nicht wahr (wahrhaftig).');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 14, 'Jesus antwortete und sagte ihnen: Auch wenn ich Zeugnis ablege (bezeuge) über (für) mich selbst, ist mein Zeugnis wahr (wahrhaftig), weil ich weiß, woher ich gekommen bin und wohin ich gehe (weggehe). Ihr aber wißt nicht, woher ich komme und wohin ich gehe (weggehe).');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 15, 'Ihr richtet (urteilt, verurteilt) nach dem Fleisch, ich richte (beurteile, verurteile) niemanden.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 16, 'Und wenn ich aber [doch] richte (urteile, verurteile), ist mein Urteil wahr (wahrhaftig), weil ich nicht allein bin, sondern ich und der Vater, der mich gesandt hat [, zusammen sind].');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 17, 'Und im Gesetz aber, dem Euren, steht (ist) geschrieben, dass das Zeugnis von zwei Menschen wahr (wahrhaftig) ist.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 18, 'Ich bin der, der über (für) mich selbst Zeugnis ablegt (bezeugt) und es legt Zeugnis (bezeugt) über (für) mich ab der Vater, der mich gesandt hat.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 19, 'Sie sagten ihm also: Wo ist Dein Vater? Jesus antwortete: Weder mich kennt Ihr, noch meinen Vater. Wenn Ihr mich kennen würdet, würdet Ihr auch meinen Vater kennen.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 20, 'Diese Worte aber sagte er in (bei) der Schatzkammer, als er im Tempel lehrte. Und keiner ergriff ihn (nahm ihn fest), weil seine Stunde noch nicht gekommen war.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 21, 'Er sprach wiederum zu ihnen: „ich gehe (fort) und ihr werdet mich suchen und an (in) eurer Sünde werdet ihr sterben. Wohin ich (fort) gehe, könnt ihr nicht kommen.“');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 22, 'Da sprachen die Juden: „Er wird sich doch nicht selbst töten, weil er sagt: Wohin ich (fort) gehe, könnt ihr nicht kommen?“');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 23, 'Und er sprach zu ihnen: „Ihr seid von unten, ich aber bin von oben. Ihr seid von (aus) dieser Welt, ich bin nicht von dieser Welt.“');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 24, 'Er sprach also (daher) zu ihnen: „An (in) euren Sünden werdet ihr sterben. Denn wenn ihr (mir) nicht glaubt, dass ich es bin, werdet ihr an (in) euren Sünden sterben.“');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 25, 'Da sprachen sie zu ihm: „Wer bist du?“Jesus sprach zu ihnen: „Zunächst das, was ich euch auch sage.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 26, 'Viel habe ich über euch zu reden und zu (be) urteilen, aber der mich geschickt hat, ist wahrhaftig, und ich, was ich von ihm gehört habe, das sage ich der Welt.“');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 27, 'Sie wussten nicht, dass er zu ihnen vom Vater sprach.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 28, 'Sprach daher Jesus zu ihnen: „Wenn ihr den Menschensohn erhöhen werdet, dann werdet ihr erkennen, dass ich es bin, und von mir aus tue ich nichts, sondern wie mich der Vater gelehrt hat, das rede ich.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 29, 'Und der mich geschickt (gesandt) hat ist bei (mit) mir; er lässt mich nicht allein, weil ich immer das ihm Liebe tue.“');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 30, 'Als (nachdem) er dies gesagt hatte, glaubten viele an ihn.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 31, '[Es] sagte also {der} Jesus zu den Juden, die an ihn glaubten: Wenn Ihr in meinem Wort bleibt, seid Ihr wirklich (wahrhaftig) meine Jünger');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 32, 'und Ihr werdet die Wahrheit erkennen und die Wahrheit wird Euch befreien (frei machen).');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 33, 'Sie antworteten ihm: Wir sind Nachfahren (Same) Abrahams und wir haben [noch] nie jemanden (niemandem jemals) (als Sklaven) gedient. Wieso (Wie) sagst Du (kannst Du sagen): {Daß} Ihr werdet frei (Freie) sein (werden)?');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 34, '[Es] antwortete ihnen {der} Jesus: Amen, Amen (Wahrlich, wahrlich), ich sage Euch: {Daß} Jeder, der die Sünde tut (sündigt), ist Sklave (Diener, Knecht) der Sünde.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 35, 'Der Sklave (Diener, Knecht) aber bleibt nicht für immer (ewig; in die Ewigkeit) im Haus. Der Sohn bleibt für immer (ewig; in die Ewigkeit).');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 36, 'Wenn also der Sohn Euch befreit (frei macht), werdet Ihr wirklich frei (Freie) sein.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 37, 'Ich weiß, dass Ihr Nachkommen (Samen) Abrahams seid. Aber Ihr versucht (sucht) mich zu töten, weil mein Wort in Euch keinen Raum findet (hat).');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 38, 'Was ich beim Vater gesehen habe, sage ich. Und Ihr also (tut), was Ihr vom Vater gehört habt, tut! (.)');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 39, 'Sie antworteten ihm: unser Vater ist Abraham. {Der} Jesus sagt ihnen: Wenn Ihr Kinder {des} Abrahams seid (wäret), würdet ihr die Werke {des} Abrahams tun.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 40, 'Jetzt aber versucht (sucht) Ihr mich zu töten, einen Menschen, der ich Euch die Wahrheit gesagt habe, die ich von Gott gehört habe. Das (Dieses) hat Abraham nicht getan.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 41, 'Ihr tut die Werke Eures Vaters. Sie sagten ihm also: Wir sind nicht aus Unzucht geboren (gezeugt), einen Vater haben wir, Gott.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 42, 'Sagte Ihnen {der} Jesus: Wenn Gott Euer Vater wäre, würdet Ihr mich lieben; ich nämlich bin aus Gott hervorgegangen (ausgegangen, herausgegangen) und gekommen. Nicht nämlich von mir (aus) bin ich gekommen, sondern jener hat mich gesandt.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 43, 'Weshalb erkennt Ihr meine Rede nicht? Weil Ihr mein Wort nicht hören könnt.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 44, 'Ihr seid aus dem (vom) Vater, dem Teufel, (des Teufels) und die Begierden Eures Vaters wollt ihr tun (in die Tat umsetzen). Jener war ein Mörder (Menschenmörder) von Anfang an, und in der Wahrheit stand er nicht, weil Wahrheit in ihm nicht ist. Wenn er die Lüge spricht, spricht er aus dem Eigenen (aus den eigenen Dingen), weil er ein Lügner ist und ihr (sein) Vater.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 45, 'Ich aber: Weil ich die Wahrheit sage, glaubt Ihr mir nicht.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 46, 'Wer von (aus) Euch überführt mich einer Sünde? Wenn ich Wahrheit spreche ([die] Wahrheit sage), weshalb glaubt Ihr mir nicht?');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 47, 'Wer aus Gott ist, hört die Worte Gottes: Deshalb hört Ihr nicht, weil Ihr aus Gott nicht seid.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 48, '[Es] antworteten die Juden und sagten ihm: Sagen wir nicht schön (zu recht), dass Du ein Samariter bist und einen Dämon hast (besessen bist)?');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 49, '[Es] antwortete Jesus: Ich habe keinen Dämon (bin nicht besessen), aber ich ehre meinen Vater und Ihr ehrt mich nicht (verachtet mich).');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 50, 'Ich aber suche nicht meine Ehre (Herrlichkeit, mein Ansehen): Es gibt einen (den), der sucht und richtet (urteilt).');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 51, 'Amen, Amen (Wahrlich, wahrlich), ich sage Euch, wenn einer (jemand) mein Wort bewahrt (hält), wird er [den] Tod in Ewigkeit nicht schauen.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 52, 'Sagten ihm also die Juden: Jetzt wissen wir (haben wir erkannt), dass Du einen Dämon hast (besessen bist). Abraham ist gestorben und die Propheten, und Du sagst: Wenn einer mein Wort bewahrt (hält), wird er [den] Tod in Ewigkeit nicht erfahren (kosten).');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 53, 'Bist Du etwa größer als unser Vater Abraham, der gestorben ist? Auch die Propheten starben: Wen (Zu wem, Zu was) machst Du Dich selbst?');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 54, 'Jesus antwortete: Wenn ich mich selbst preise (ehre, verherrliche), ist mein Preis (meine Ehre, Herrlichkeit) nichts. Es ist mein Vater, der mich preist (ehrt, verherrlicht), von dem Ihr sagt, daß er Euer Gott ist,');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 55, '– und Ihr kennt (habt) ihn nicht (erkannt), ich aber kenne ihn. Und wenn ich sagen würde, daß ich ihn nicht kenne, wäre (werde) ich gleich Euch (ähnlich wie Ihr) ein Lügner (sein). Aber ich kenne ihn und sein Wort bewahre (halte) ich.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 56, 'Abraham, Euer Vater, jubelte, weil (dass) er meinen Tag sehen sollte, und er sah [ihn] und freute sich.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 57, '[Es] sagten also die Juden zu ihm: Fünfzig Jahre hast Du noch nicht (Du bist noch keine fünfzig alt) und Abraham hast Du gesehen?');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 58, 'Sagte ihnen Jesus: Amen, Amen (Wahrlich, wahrlich), ich sage Euch, bevor Abraham geworden ist (wurde), bin ich.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 59, 'Sie hoben also Steine auf, um [sie] auf ihn zu werfen. Jesus aber verbarg sich und ging aus dem Tempel (Heiligtum) heraus.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 1, 'Und im Vorbeigehen (beim Weitergehen) sah er einen von Geburt an blinden Mann (Menschen).');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 2, 'Und seine Jünger fragten ihn {sagend}: „Rabbi (Lehrer), wer hat [hier] gesündigt, der [Mann] (dieser) oder seine Eltern, sodass er blind geboren wurde?“');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 3, 'Jesus erwiderte: „Weder hat der [Mann] (dieser) gesündigt noch seine Eltern. [Er ist] vielmehr (sondern) [blind], damit Gottes Handeln (Wirken, Taten, Werke) an ihm sichtbar wird.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 4, 'Wir müssen das Handeln (Wirken, Taten, Werke) dessen ausführen (bewirken, tun), der mich gesandt hat, solange es Tag ist – [die] Nacht kommt, und dann (wenn) kann niemand mehr [etwas] tun (bewirken) kann.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 5, 'Wann immer (Solange) ich in der Welt bin, bin ich [das] Licht der Welt.“');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 6, 'Sobald (als, nachdem) er das gesagt hatte, spuckte er auf den Boden, {und} machte mit (aus) dem Speichel Matsch (Schlamm) und strich ihm den Matsch (Schlamm) auf die Augen.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 7, 'Und er sagte zu ihm: „Geh [und] wasche dich im Teich von Schiloach ab!“– das bedeutet „Gesandter“. Daraufhin (also) ging er weg, {und} wusch sich [das Gesicht] ab und kam sehend zurück.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 8, 'Da riefen (meinten, sagten) die Nachbarn und [solche], die ihn vorher als Bettler gesehen hatten: „Ist dieser [Mann] nicht derjenige, der [hier] saß und bettelte!“');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 9, 'Einige meinten (sagten): {dass} „Er ist es!“, andere riefen (sagten): „Nein, er ist ihm nur (aber, sondern) ähnlich!“Er selbst sagte: {dass} „Ich bin es.“');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 10, 'Da fragten (sagten) sie ihn: „Wie wurden dir denn dann die Augen geöffnet?“');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 11, 'Der Mann antwortete: „Der Mann (Mensch), der Jesus heißt, hat Matsch (Schlamm) gemacht und mir die Augen [damit] eingestrichen, und er sagte mir: »Geh zum [Teich] Schiloach und wasche dich ab!« Nachdem ich dann (also) hingegangen war und mich abgewaschen hatte, konnte ich sehen.“');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 12, 'Da (und) fragten (sagten) sie ihn: „Wo ist der Mann, [von dem du sprichst]?“Er sagte: „Ich weiß nicht.“');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 13, 'Sie brachten den vormals Blinden vor (zu) die Pharisäer.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 14, '{Allerdings (übrigens, nämlich) } Es war Sabbat an dem Tag, [an dem] Jesus den Matsch (Schlamm) machte und ihm die Augen öffnete.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 15, 'Auch die Pharisäer befragten ihn {nun} weiter (noch einmal, immer wieder), wie [es kam, dass] er [plötzlich] sehen konnte. Er {aber} antwortete (sagte) ihnen: „Er hat mir Matsch (Schlamm) auf die Augen getan, {und} ich habe gebadet, und [jetzt] sehe ich.“');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 16, 'Manche von (unter) den Pharisäern meinten (sagten) daraufhin: „Dieser Mensch (Mann) ist nicht von Gott, weil er den Sabbat nicht einhält (befolgt, bewahrt). Andere sagten (meinten): »Wie könnte ein sündiger Mensch solche (derartige) Zeichen (Wunder) tun?« Und es kam (war) unter ihnen zu einer Spaltung.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 17, 'Also fragten (sagten) sie den Blinden noch einmal: »Was sagst du über ihn – da er dir ja die Augen geöffnet hat?« Er {aber} sagte: {dass} »Er ist ein Prophet!«');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 18, 'Da glaubten die Juden nicht [mehr] {über ihn}, dass er blind (ein Blinder) [gewesen] war und [nun] sehen konnte, bis sie {seine} die Eltern des Geheilten herbeiriefen');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 19, 'und sie fragten {wobei sie sagten}: »Ist dieser [Mann] euer Sohn, von dem ihr sagt, dass er blind geboren wurde? Wie [kommt es] denn, [dass] er jetzt sehen kann (sieht)?');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 20, 'Da antworteten seine Eltern {und sagten}: »Wir wissen, dass er (dieser [Mann]) unser Sohn ist und dass er blind geboren wurde.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 21, 'Wie [es] aber [kommt, dass] er jetzt sehen kann (sieht), wissen wir nicht, auch (oder) wer ihm die Augen geöffnet hat, wissen wir nicht. Fragt ihn [doch] selbst, er ist erwachsen, er wird selbst für sich sprechen!«');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 22, 'Das sagten seine Eltern, weil sie die Juden fürchteten. Die Juden hatten sich nämlich (denn) schon [darüber] verständigt (geeinigt, abgestimmt, beschlossen), dass jeder, der ihn [öffentlich] als Messias (Christus) bezeichnete (bekannte), aus der Synagoge ausgeschlossen werden [sollte].');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 23, 'Aus diesem Grund sagten seine Eltern: {dass} »Er ist erwachsen, fragt ihn [doch] selbst!«');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 24, 'Daraufhin (also) riefen sie den Mann (Menschen) zum zweiten Mal, der blind (ein Blinder) [gewesen] war, und forderten ihn auf (sagten zu ihm): »Gib Gott Ehre! Wir wissen, dass dieser Mensch (Mann) ein Sünder (sündig) ist!«');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 25, 'Da antwortete der Mann (jener): »Ob er sündig ist, weiß ich nicht! Eines weiß ich: dass ich, der blind war (als Blinder), jetzt sehen kann (sehe).«');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 26, 'Darauf sagten sie zu ihm: »Was hat er mit dir gemacht? Wie hat er dir die Augen geöffnet?«');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 27, 'Er antwortete ihnen: »Ich habe [es] euch schon gesagt und ihr habt nicht zugehört. Warum wollt ihr es noch einmal hören? Wollt wohl (vielleicht) auch ihr seine Jünger werden?«');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 28, 'Da (und) beschimpften sie ihn {und sagten}: »Du bist sein Jünger, wir aber sind Moses Jünger!');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 29, 'Wir wissen, dass Gott zu Mose gesprochen hat, aber von diesem [Mann] wissen wir nicht, woher er ist.«');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 30, 'Der Mann (Mensch) antwortete {und sagte zu ihnen}: »Das ist ja merkwürdig (seltsam, erstaunlich), dass ihr nicht wisst, woher er ist, obwohl (und) er mir die Augen geöffnet hat.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 31, 'Wir wissen, dass Gott Sündern nicht zuhört. Vielmehr hört er gerade demjenigen zu, [der] gottesfürchtig (fromm) ist und seinen Willen tut.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 32, 'Von jeher ist es nicht gehört worden, dass jemandem die Augen geöffnet wurden, der blind (als Blinder) geboren war.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 33, 'Wenn dieser [Mann] nicht von Gott wäre, könnte er nichts [dergleichen] tun!«');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 34, 'Sie antworteten {und sagten} ihm »Du wurdest ganz in Sünden geboren und du belehrst uns?« und warfen ihn hinaus.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 35, 'Jesus hörte, dass sie ihn hinausgeworfen hatten, und sagte, nachdem er ihn gefunden hatte: »Glaubst du an den »Sohn des Menschen« (»Menschensohn«, »Menschen«)?«');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 36, 'Der Mann (jener) erwiderte {und sagte}: »Und wer ist es, Herr, damit ich an ihn glauben kann?«');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 37, 'Jesus sagte zu ihm: » {und} Du hast ihn gefunden: {und} Der mit dir spricht, ist es!«');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 38, 'Da (und) rief (sprach) der [Mann] »Ich glaube, Herr!« und betete ihn an.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 39, 'Und Jesus sagte: »Zur Scheidung (Gericht) bin ich in diese Welt gekommen, damit die nicht Sehenden sehen können (sehen) und die Sehenden blind werden.«');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 40, 'Das hörten diejenigen von den Pharisäern, die bei (mit) ihm waren, und sagten zu ihm: »Aber wir gehören nicht zu den Blinden, oder?«');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 41, 'Jesus entgegnete (sagte zu) ihnen: »Wenn ihr blind wäret, [dann] hättet ihr keine Sünde. Aber jetzt sagt ihr: {dass} »Wir sehen!«, [und] eure Sünde bleibt.« «“');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 1, '„Wahrlich, wahrlich (Amen, amen), ich sage euch: Wer nicht durch den Eingang (die Tür) in das Gehege (den Hof) der Schafe gelangt (eintritt), sondern auf anderem Wege hineinsteigt, der ist ein Dieb und ein Räuber!');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 2, 'Wer aber durch das Gatter (den Eingang, die Tür) eintritt (hineinkommt), ist [der] Hirte der Schafe.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 3, 'Diesem öffnet der Türhüter, und die Schafe hören seine Stimme, und er ruft seine eigenen Schafe beim Namen und führt sie hinaus.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 4, 'Wenn er alle seine eigenen [Schafe] hinausgebracht (hinausgetrieben) hat, geht er vor ihnen her, und die Schafe folgen ihm, denn sie kennen seine Stimme.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 5, 'Doch einem anderen würden (werden) sie niemals folgen, sondern ihm davonlaufen (fliehen, weichen), denn sie kennen die Stimmen anderer [Menschen] nicht.“');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 6, 'Dieses Gleichnis (Sprachbild) erzählte ihnen Jesus, aber sie wussten nicht, was es war, über das er mit ihnen gesprochen hatte.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 7, 'Darum sprach (redete, erzählte) Jesus weiter (noch einmal, erneut): „Wahrlich, wahrlich (Amen, amen), ich sage euch: {dass} Ich bin das Gatter (der Eingang, die Tür) [für] die Schafe (Schafgatter).');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 8, 'Alle, die vor mir gekommen sind, sind Diebe und Räuber, aber die Schafe haben ihnen nicht zugehört.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 9, 'Ich bin das Gatter (der Eingang, die Tür): Wenn jemand durch mich eintritt, wird er gerettet werden, und er wird ein- und ausgehen und Weideland finden.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 10, 'Der Dieb kommt nur, um zu stehlen, {und} zu schlachten (töten) und zu zerstören. \'\'Ich\'\' bin gekommen, damit sie Leben haben, und Überfluss (Fülle, Mehr) haben.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 11, 'Ich bin der gute Hirte, der gute Hirte stellt (setzt, legt) seine Seele für die Schafe.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 12, 'Wer bezahlter Arbeiter und nicht Hirte ist, wer die Schafe nicht hat, sieht den Wolf kommen und verlässt die Schafe und flieht - und der Wolf raubt und zerstreut [sie] -');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 13, 'weil er ein bezahlter ist und sich nicht um die Schafe kümmert.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 14, 'Ich bin der gute Hirte; und ich kenne die Meinen, und mich kennen die Meinen,');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 15, 'wie der Vater mich kennt, kenne auch ich den Vater und ich setze (stelle, lege) mein Leben für die Schafe.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 16, 'Und ich habe andere Schafe, die nicht von diesem Hof sind; auch diese muss ich (es ist mir nötig diese zu) bringen, und sie werden meine Stimme hören, und es wird eine Herde, ein Hirte.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 17, 'Deshalb liebt mich der Vater, weil ich mein Leben einsetze (hingebe), um es wieder zu nehmen.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 18, 'Keiner nimmt es von mir (weg), sondern ich setze (gebe) es von mir selbst aus ein (hin). Vollmacht (Macht) habe ich, es einzusetzen (hinzugeben), und Vollmacht (Macht) habe ich, es wieder zu nehmen. Dieses Gebot (diesen Befehl) habe ich von meinem Vater bekommen (erhalten).');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 19, 'Eine Spaltung entstand wiederum unter den Juden wegen dieser Worte.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 20, 'Es sagten aber viele von (aus) ihnen: Einen Dämon hat er (Er ist besessen) und er ist von Sinnen. Was (Warum) hört ihn an (ihm zu, auf ihn)?');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 21, 'Andere sagten: Diese Worte sind nicht [die] eines (von einem Dämon) Besessenen. Kann ein Dämon etwa Augen von Blinden öffnen?');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 22, 'Es war (fand) damals (dann) das Fest der Tempelweihe in Jerusalem (statt). Es war Winter (winterliches Wetter)');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 23, 'und Jesus wandelte (ging) im Tempel in der Säulenhalle Salomos (auf und ab, umher).');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 24, 'Es umringten ihn also die Juden und sagten ihm: Bis wann hältst Du unsere Seele [hin, im Ungewissen]? Wenn Du der Christus (Messias) bist, sag [es] (sprich) uns offen (mit Offenheit).');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 25, 'Antwortete ihnen {der} Jesus: Ich habe [es] Euch gesagt (gesprochen) und Ihr glaubt nicht. Die Werke, die ich tue (vollbringe) im Namen meines Vaters, diese geben Zeugnis (zeugen) über (für) mich.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 26, 'Aber Ihr glaubt nicht, weil Ihr nicht von (aus) meinen Schafen seid (zu meinen Schafen gehört).');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 27, 'Meine Schafe hören auf meine Stimme und ich kenne (erkenne) sie und sie folgen mir');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 28, 'und ich gebe (schenke) ihnen ewige Leben und sie sollen in Ewigkeit nicht zugrunde (verloren) gehen und keiner (nicht) wird (einer) sie aus meiner Hand reißen (rauben).');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 29, 'Was mein Vater (Mein Vater – was er) mir gegeben hat, ist größer als alles und keiner kann [es] aus der Hand des Vaters reißen (rauben).');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 30, 'Ich und der Vater sind eins.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 31, 'Die Juden hoben wieder (wiederum) Steine auf, um ihn zu steinigen.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 32, '{Der} Jesus antwortete ihnen: Viele gute (schöne) Werke aus dem (vom) Vater (her) habe ich Euch gezeigt. Wegen welchem {Werk} von ihnen steinigt Ihr mich?');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 33, '[Es] antworteten ihm die Juden: Wir steinigen Dich nicht wegen eines guten (schönen) Werks, sondern wegen (einer) Gotteslästerung (Lästerung), und weil Du, obwohl (der) Du ein Mensch bist, Dich selbst Gott machst.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 34, 'Antwortete ihnen Jesus: Steht (ist) nicht geschrieben in Eurem Gesetz: {Daß} Ich habe gesagt: Götter seid Ihr?');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 35, 'Wenn er (es) diejenigen Götter nannte, an die das Wort Gottes erging, und die Schrift nicht aufgelöst (gelöst) werden kann,');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 36, '[weshalb] sagt Ihr [dann von mir (dem),] den der Vater geheiligt hat und in die Welt gesandt hat: {Dass} Du lästerst (Gott), weil ich gesagt habe: Sohn Gottes bin ich?');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 37, 'Wenn ich die Werke meines Vaters nicht tue (verwirkliche, vollbringe), glaubt mir nicht!');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 38, 'Wenn ich [sie] aber tue (verwirkliche, vollbringe), und Ihr mir nicht glaubt, glaubt [(doch, wenigstens)] den Werken, damit ihr erkennt und wißt, dass in mir der Vater [ist] und ich im Vater [bin].');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 39, 'Sie versuchten (suchten) wieder (wiederum) ihn zu ergreifen (gefangen zu nehmen), und er ging aus (entzog sich) ihrer Hand heraus.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 40, 'Und er ging wieder (wiederum) fort auf die andere Seite des Jordan, an den Ort, wo Johannes zuerst getauft hatte (taufen war) und er blieb (verweilte) dort.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 41, 'Und viele kamen zu ihm und sagten: [Daß] Johannes hat zwar keine Zeichen getan (gewirkt), alles (alle Dinge) aber, was (die) Johannes gesagt hat über diesen, war (waren) wahr.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 42, 'Und viele glaubten (kamen zum Glauben) an ihn dort. “');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 1, '{Nun (Aber) } Es war jemand krank [geworden], Lazarus aus Betanien, aus dem Dorf von Maria und ihrer Schwester Marta.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 2, 'Es war {übrigens (nun, aber) } Maria, die den Herrn [mit] Salböl gesalbt (übergossen, eingerieben) und [dann] seine Füße [mit] ihren Haaren abgetrocknet hatte, deren Brüder Lazarus krank war.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 3, 'Die Schwestern schickten also [eine Nachricht] zu ihm und ließen ihm ausrichten: „Herr, {schau}, der, den du lieb hast, ist krank!“');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 4, 'Als Jesus das hörte, sagte er: „Diese Krankheit führt nicht zum Tod, sondern [dient] zur Verherrlichung (Ehre, Herrlichkeit) Gottes, damit der Sohn Gottes durch sie verherrlicht wird.“');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 5, 'Jesus hatte (liebte) Marta, {und} ihre Schwester und Lazarus jedoch sehr lieb.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 6, 'Als er dann hörte, dass [Lazarus] krank war, da blieb er noch zwei weitere Tage an dem Ort, wo er war.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 7, 'Danach sagte er zu den Jüngern: „Gehen wir wieder nach Judäa!“');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 8, 'Die Jünger wandten ein (sagten) {zu ihm}: „Rabbi (Lehrer), die Juden haben gerade erst versucht dich zu steinigen, und du möchtest wieder (zurück) dorthin gehen?“');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 9, 'Jesus erwiderte: „Sind [in] einem Tag nicht zwölf Stunden? Wenn man (Wer) sich tagsüber (während des Tages) fortbewegt (umhergeht), stößt (stolpert) man sich nirgends an, weil man das Licht dieser Welt sieht.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 10, 'Wenn man (Wer) sich aber nachts (während der Nacht) fortbewegt (umhergeht), stößt (stolpert) man sich an, weil das Licht nicht in einem ist.“');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 11, 'Dies (Diese Dinge) sagte er, und danach sagt er ihnen: Lazarus, unser Freund ruht (schläft, ist eingeschlafen, hat sich schlafen gelegt) aber ich gehe, um ihn aufzuwecken.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 12, 'Es sagten ihm also die Jünger: Herr, wenn er ruht (schläft, eingeschlafen ist, sich schlafen gelegt hat), wird er bewahrt (gerettet) werden.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 13, 'Jesus aber hatte über seinen Tod gesprochen. Sie (Jene) aber meinten, daß er über das Ruhen (Schlafen) des Schlafes spricht.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 14, 'Dann also sagte ihnen Jesus offen (mit Offenheit, mit Freimut): Lazarua ist gestorben,');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 15, 'und ich freue mich Euretwegen (wegen Euch), daß ich nicht dort war, damit ihr glaubt (damit Ihr glaubt, weil ich nicht dort war). Aber laßt uns zu ihm gehen.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 16, 'Thomas, der Zwilling genannt wird, sagte also den Mitjüngern: Laßt auch uns gehen, damit wir mit ihm sterben.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 17, '{Der} Jesus ging und fand ihn also (, nachdem er) schon vier Tage im Grab liegen (gelegen war).');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 18, 'Betanien war aber nahe bei Jerusalem, etwa 15 Stadien weit.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 19, 'Viele aber von (aus) den Juden waren zu {der} Marta und Maria gekommen, um sie über ihren Bruder zu trösten.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 20, '{Die} Marta also, wie sie hörte, daß Jesus kommt, ging ihm entgegen. Maria aber saß in dem Haus.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 21, 'Da (nun) sagte Marta zu Jesus: „Herr, wenn du hier gewesen wärest, dann wäre mein Bruder nicht gestorben!');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 22, 'Auch (und) jetzt weiß ich, dass Gott dir alles, worum du ihn bittest, geben wird.“');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 23, 'Jesus sagte zu ihr: „Dein Bruder wird auferstehen!“');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 24, 'Marta meinte (sagte) {zu ihm}: „Ich weiß, dass er bei (während) der Auferstehung am letzten (jüngsten) Tag auferstehen wird.“');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 25, 'Jesus sagte zu ihr: „Ich bin die Auferstehung und das Leben. Wer an mich glaubt (auf mich vertraut), wird leben, auch wenn er stirbt!');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 26, 'Und jeder, der lebt und an mich glaubt (auf mich vertraut), wird sicher nicht für immer sterben. Glaubst du das?“');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 27, 'Sie rief (sagte): „Ja, Herr, ich glaube daran, dass du der Messias (Christus) bist, der Sohn Gottes, der in die Welt kommen soll (kommt)!“');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 28, 'Und nachdem sie dies gesagt hatte, ging sie hin (weg) und rief heimlich Maria, ihre Schwester (herbei), indem sie [ihr] sagte: Der Lehrer ist hier (da) und ruft Dich.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 29, 'Jene aber, wie sie [es] hörte, stand schnell auf und ging (kam) zu ihm.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 30, '{Der} Jesus aber war noch nicht in das Dorf gegangen (gekommen), sondern er war noch an dem Ort, wo Marta ihm entgegengekommen war.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 31, 'Die Juden also, die mit ihr in dem Haus waren und sie trösteten, folgten ihr, als sie Maria schnell aufstehen und weggehen sahen, weil sie meinten, daß sie zu dem Grab geht, um dort zu weinen (klagen).');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 32, 'Maria, als sie [dorthin] kam, wo Jesus war, und ihn sah, warf sie sich (fiel) sie vor seine Füße und sagte zu ihm: „Herr, wenn du hier gewesen wärest, dann wäre mein Bruder nicht gestorben!“');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 33, 'Als Jesus daraufhin sah, wie (dass) sie laut weinte (trauerte, klagte), und wie (dass) die [bei] ihr ([um] sie) versammelten Juden laut weinten (trauerten, klagten), war er innerlich ([im] Geist) sehr aufgebracht (wütend, erregt) und erschüttert (aufgewühlt, tief bewegt)');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 34, 'und sagte: „Wo habt ihr ihn hingelegt?“Sie antworteten (meinten, sagten) ihm: „Herr, komm [mit] und sieh!“');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 35, 'Jesus musste weinen (kamen die Tränen, begann zu weinen; weinte).');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 36, 'Da (daraufhin, darum) sagten die Juden: „Schaut, wie lieb er ihn hatte.“');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 37, 'Aber manche von ihnen meinten (sagten): „Er, der die Augen des Blinden geöffnet hat, konnte nichts tun, damit [Lazarus] nicht sterben musste?“');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 38, 'Jesus also – ein weiteres Mal innerlich (in sich) sehr aufgebracht (wütend, erregt; aufbrausend, schnaubend, seufzend) – kommt zu dem Grab: Es war aber eine Höhle und ein Stein lag auf ihm (ihr).');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 39, '{Der} Jesus sagt: Nehmt den Stein weg. Die Schwester des Gestorbenen, Marta, sagt ihm: Herr, er stinkt (riecht) schon – er ist nämlich schon vier Tage [tot] (viertägig).');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 40, '{Der} Jesus sagt ihr: Habe ich Dir nicht gesagt: {daß} Wenn Du glaubtst, wirst du die Herrlichkeit Gottes sehen?');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 41, 'Da (also) hoben (entfernten, nahmen) sie den Stein weg. {und (aber) } Jesus richtete seine Augen nach oben und sprach (sagte): „Vater, ich danke dir, dass du mich erhört hast.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 42, 'Ich wusste ja, dass du mich immer erhörst, aber ich sage es (habe gesagt) es wegen der beistehenden Leute, damit sie glauben, dass du mich gesandt hast.“');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 43, 'Und nachdem er das gesagt hatte, rief er [mit] lauter Stimme: „Lazarus, komm heraus!“');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 44, 'Der Verstorbene kam heraus, an Füßen und Händen mit Binden gebunden (umwickelt, gefesselt), und sein Gesicht war mit einem Tuch (Gesichtstuch) umwickelt worden. Jesus sagte zu ihnen: „Befreit ihn, dann (und) lasst ihn gehen!“');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 45, 'Viele also von (aus) den Juden, die zu {der} Maria gekommen waren und gesehen hatten, was er getan hatte, glaubten (kamen zum Glauben) an ihn.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 46, 'Einige aber von (aus) ihnen gingen (weg, hin) zu den Pharisäern und sagten ihnen, was Jesus getan hatte.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 47, 'Die Hohenpriester und die Pharisäer versammelten also ein Synedrium (brachten also eine Sitzung des Hohen Rates zusammen) und sagten: Was tun (machen, verwirklichen) wir, da dieser Mensch viele Zeichen tut (macht, verwirklicht; denn dieser Mensch tut viele Zeichen)?');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 48, 'Wenn wir ihn so lassen, werden alle an ihn glauben, und die Röme werden kommen und (von) uns sowohl den Ort (den Tempel, Jerusalem) wie das Volk wegnehmen (nehmen).');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 49, 'Doch einer, von ihnen, ein gewisser Kajaphas, der in jenem Jahr Hoherpriester war, sagte ihnen: „Ihr wisst doch überhaupt nichts,');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 50, 'und ihr versteht nicht, dass es besser (vorteilhaft) für euch wäre, wenn (dass) ein Mann (Mensch) anstelle (für, zugunsten) des Volkes stirbt, als dass (und nicht) das ganze [jüdische] Volk (Nation) untergeht (vernichtet wird, verloren geht).“');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 51, 'Das sagte er aber nicht von sich aus, sondern weil er in jenem Jahr Hoherpriester war, machte er die Prophezeiung (prophezeite, sagte voraus), dass (denn) Jesus anstelle (für, zugunsten) des [jüdischen] Volkes (Nation) sterben würde (musste),');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 52, 'und nicht nur anstelle (für, zugunsten) des [jüdischen] Volkes (Nation) allein, sondern um die verstreuten Kinder Gottes zu einem [Volk] (an einem [Ort]) zusammenzuführen (zu versammeln).');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 53, 'Von jenem Tag an also überlegten (beratschlagten, beschlossen) sie, ihn zu töten.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 54, '{Der} Jesus also zog nicht mehr öffentlich (in [der] Öffentlichkeit) unter den Juden umher, sondern er ging weg von dort in die Gegend nahe der Wüste (Einöde), in eine Stadt, die Efraim heißt (genannt wird), und dort blieb (verweilte) er mit den Jüngern.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 55, 'Es war aber nahe das Paschafest (Pascha) der Juden und viele aus dem Land (der Gegend) stiegen (gingen) vor dem Paschafest (Fest, Pascha) nach Jerusalem hinauf, um sich zu reinigen.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 56, 'Sie suchten also {den} Jesus und sagten zueinander (redeten miteinander), wie sie im Tempel standen: Was meint Ihr (scheint Euch)? Daß er vielleicht (gewiß) nicht zu dem Fest kommt?');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 57, 'Es hatten aber die Hohenpriester und die Pharisäer befohlen (Befehle gegeben), daß, wenn jemand (einer) erfährt (weiß), wo er sich aufhält (ist), er [(ihn, es)] anzeige (verrate), damit sie ihn festnehmen (ergreifen) [können].');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 1, '{Der} Jesus also kam sechs Tage vor dem Paschafest (Pascha) nach Betanien, wo sich Lazarus aufhielt (war, weilte), den Jesus von (aus) den Toten erweckt hatte.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 2, 'Sie veranstalteten (bereiteten, machten) also dort für ihn (ihm) ein Mahl (Abendmahl), und {die} Marta diente, Lazarus aber war einer von denen, die mit ihm zu Tisch lagen (saßen).');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 3, '{Die} Maria also nahm ein Pfund Salböl – echtes (reines), kostbares Nardenöl – und salbte [damit] die Füße Jesu {des Jesus} und trocknete mit ihren Haaren seine Füße. Das Haus aber wurde von (aus) dem Duft (Geruch) des Salböls erfüllt.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 4, 'Judas {der} Iskariot, einer seiner Apostel, (der,) der im Begriff war, ihn auszuliefern (der ihn ausliefern sollte, wollte), sagt aber:');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 5, 'Weshalb wurde dieses Salböl nicht für 300 Denare verkauft und den Armen gegeben?');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 6, 'Er sagte das aber nicht, weil es ihm um die Armen ging, sondern weil er ein Dieb war und – da er den Geldbeutel (die Kasse) hatte (verwaltete; als Kassenwart) – das, was [in ihn (sie)] gelegt (geworfen) wurde, wegtrug (wegnahm, stahl).');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 7, '{Der} Jesus sagte also: Lass sie, damit sie es für (in den) Tag meiner Beerdigung bewahre.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 8, 'Die Armen nämlich habt Ihr immer bei (mit) Euch, mich aber habt Ihr nicht immer.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 9, 'Es erfuhr (erkannte) also die große (viele) Menge der (von, aus den) Juden, daß er dort ist und sie kamen, nicht allein wegen Jesus, sondern um auch {den} Lazarus zu sehen, den er von (aus) den Toten erweckt hatte.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 10, 'Die Hohenpriester beschlossen (beratschlagten) aber, auch {den} Lazarus zu töten,');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 11, 'weil viele der Juden seinetwegen weggingen (hingingen, gingen) und zum Glauben an Jesus kamen (an Jesus glaubten).');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 12, 'Am nächsten Tag, als die große (viele) Menge, die zu dem Fest gekommen war, hörte (hörten), daß {der} Jesus nach Jerusalem kommt,');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 13, 'nahmen sie die Zweige der Dattelpalme (Palmzweige) und gingen heraus ihm entgegen und schrien (riefen): Hosanna! Gelobt (Gesegnet) [sei] der, der im Namen [des] Herrn kommt, der König Israels.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 14, '{Der} Jesus aber fand einen Jungesel und setzte sich auf ihn, wie geschrieben steht (ist):');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 15, 'Fürchte Dich nicht, Tochter Zion. Sieh, Dein König kommt, sitzend auf einem Jungen (Füllen) einer Eselin (eines Esels.)');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 16, 'Dies (diese Dinge) erkannten (verstanden) seine Jünger zuerst nicht, aber als Jesus verherrlicht worden war, erinnerten sie sich, daß dies (diese Dinge) über ihn geschrieben war (waren) und sie dies (diese Dinge) für ihn (ihm) getan hatten.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 17, 'Es bezeugte (verkündete, bekannte, pries) also die Menge, die mit ihm gewesen war, als er den Lazarus aus dem Grab rief und ihn von den Toten auferweckte [, was er getan hatte].');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 18, 'Deshalb ging ihm auch die Menge entgegen, weil sie hörten, daß er dieses Zeichen getan hatte.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 19, 'Die Pharisäer also sprachen zueinander: Ihr seht, daß Ihr nichts nützt (zustande bringt). Sieh, die Welt geht hinter (folgt) ihm her (hin, weg).');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 20, '[Es] waren aber einige Griechen unter (aus) denen, die hinaufgegangen waren, um am Fest (während des Festes) anzubeten.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 21, 'Diese also kamen zu Philippus,den von Betsaida in (des, von) Galiläa (aus dem galiläischen Betsaida), und fragten ihn, indem sie sagten: Herr, wir wollen {den} Jesus sehen.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 22, '{Der} Philippus geht (kommt) und sagt [es] {dem} Andreas. Andreas geht (kommt) und [auch] Philippus und sie sagen [es] {dem} Jesus.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 23, '{Der} Jesus aber antwortet ihnen, indem er sagt: Die Stunde ist gekommen, dass der Menschesohn (der Sohn des Menschen) verherrlicht wird.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 24, 'Amen, Amen (Wahrlich, wahrlich), ich sage Euch, wenn das Korn (Samenkorn) des Weizens nicht in die Erde fällt und stirbt, bleibt es allein. Wenn es aber stirbt, bringt (trägt) es viel Frucht.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 25, 'Wer sein Leben (seine Seele) liebt, verliert es (sie), und wer sein Leben (seine Seele) in dieser Welt haßt, wird es (sie) in\'s ewige Leben bewahren.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 26, 'Wenn mir jemand (einer) dient, folge er mir (nach), und wo ich bin, dort wird auch mein Diener sein. Wenn jemand (einer) mir dient, wird ihn der Vater ehren.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 27, 'Jetzt ist meine Seele erregt (verwirrt, erschüttert; worden), und was soll ich sagen? Vater, retter mich aus dieser Stunde! Aber deswegen bin ich in diese Stunde gekommen.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 28, 'Vater, verherrliche Deine Namen! Es kam also eine Stimme aus dem Himmel: {Und} Ich habe [ihn] verherrlicht, und werde [ihn] wieder verherrlichen.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 29, 'Die Menge also, die dabeistand (dastand) und hörte, sagte: Es hat gedonnert (Ein Donner ist geschehen). Andere sagten: Ein Engel hat (mit, zu) ihm gesprochen (geredet).');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 30, 'Jesus antwortete und sagte: Nicht wegen mir (meinetwegen) ist diese Stimme geschehen, sondern wegen Euch (Euretwegen).');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 31, 'Jetzt ist Gericht dieser Welt, jetzt wird der Herrscher dieser Welt hinausgeworfen werden.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 32, 'Und ich, wenn ich von (aus) der Erde erhöht werde, werde ich alle zu mir (an mich) ziehen.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 33, 'Dieses aber sagte er, um anzuzeigen (indem er anzeigte), welche Art von (welchen) Tot er im Begriff war zu sterben (sterben sollte.)');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 34, 'Es antwortete ihm also die Menge: Wir haben aus dem Gesetz gehört, daß der Christus (Messias) in {die} Ewigkeit bleibt, und wie kannst Du sagen (sagst Du), daß es notwendig ist, daß der Menschensohn (der Sohn des Menschen) erhöht wird? Wer ist dieser, der Menschensohn (der Sohn des Menschen)?');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 35, 'Es sagte also ihnen {der} Jesus: Noch eine kleine Zeit ist das Licht bei (in) Euch. Geht umher, solange (wie) Ihr das Licht habt, damit die Dunkelheit (Finsterniss) Euch nicht ergreift (in Besitz nimmt) – und der, der in der Dunkelheit (Finsterniss) umhergeht, weiß nicht wohin er geht.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 36, 'Solange (wie) Ihr das Licht habt, glaubt an das Licht, damit Ihr Söhne des Lichts werdet (um Kinder von Licht zu sein). Dies (Diese Dinge) sagte Jesus, und er ging weg und verbarg sich vor ihnen.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 37, 'Obwohl er aber so große (viele) Zeichen vor ihnen tat, glaubten sie nicht an ihn,');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 38, 'damit das Wort des Profeten Jesaja erfüllt werde, das er sagte: Herr, wer glaubte unserer Botschaft? Und der Arm des Herrn, wem wurde er offenbart?');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 39, 'Deshalb konnten sie nicht glaubten, weil Jesaja wiederum sagte:');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 40, 'Er machte ihre Augen blind (blendete sie) und verhärtete (verstockte) ihr Herz, damit sie mit den Augen nicht sehen und mit dem Herzen [nicht] verstehen und [nicht] umkehren, und ich werde sie heilen (und ich sie [nicht] heile).');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 41, 'Dies (diese Dinge) sagte Jesaja, weil er seine Herrlichkeit (Ehre) sah, und er sprach (redete) über ihn.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 42, 'Gleichwohl jedoch glaubten (kamen) auch von (aus) den Führern viele (zum Glauben) an ihn, aber wegen der Pharisäer bekannten sie [es, sich] nicht, um nicht aus der Synagoge ausgeschlossen (aus der Synagoge Ausgeschlossene) zu werden;');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 43, 'sie liebten nämlich die Ehre der (bei den; den Preis von) Menschen mehr als die Gottes (bei Gott, den Preis von Gott).');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 44, 'Jesus aber rief (schrie) und sagte: Wer an mich glaubt, glaubt nicht an mich, sondern an den, der mich gesandt hat,');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 45, 'und wer mich sieht, sieht den, der mich gesandt hat.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 46, 'Ich bin als Licht in die Welt gekommen, damit jeder, der an mich glaubt, nicht in der Dunkelheit (Finsterniss) bleibt.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 47, 'Und wenn einer meine Worte hört und [sie] nicht bewahrt, richte (verurteile) nicht ich ihn (ich ihn nicht), denn ich bin nicht gekommen, damit ich die Welt richte (verurteile), sondern damit ich die Welt rette.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 48, 'Wer mich zurückweist und meine Worte nicht annimmt, hat denjenigen, der ihn richtet (verurteilt): Das Wort, das ich gesprochen (geredet) habe, richtet (verurteilt; wird) ihn am letzten Tag (richten, verurteilen),');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 49, 'weil ich nicht aus mir gesprochen (geredet) habe, sondern der, der mich gesandt hat, er hat mir ein Gebot gegeben, was ich sagen und reden soll.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 50, 'Und ich weiß, daß sein Gebot ewiges Leben ist. Was ich also rede – wie [es] mir der Vater gesagt hat, so rede ich.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 1, '{aber} Vor dem Passafest, weil Jesus wusste, dass seine Zeit (Stunde) gekommen war, aus dieser Welt zum Vater hinüberzugehen (zu verlassen), und weil er die liebte, die in der Welt zu ihm gehören, zeigte er seine Liebe für (liebte) sie, bis zum Ende (zur Vollendung).');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 2, 'Und während [das] Abendessen stattfand, als der Teufel (Verleumder) Judas Simon Iskariot bereits [den Plan] ins Herz gegeben (gelegt) hatte, [Jesus] zu verraten (auszuliefern),');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 3, 'und da er sich bewusst war (wusste), dass ihm der Vater alles in die Hände gegeben hatte und dass er von Gott aus gekommen war und zu Gott gehen würde,');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 4, 'stand er vom Abendessen auf, {und} legte seine Obergewänder ab und nahm ein Handtuch, [das] er sich um die Hüfte band.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 5, 'Dann (danach) goss er Wasser in ein Becken und fing an, die Füße der Jünger zu waschen und mit dem Handtuch abzutrocknen, das er umgebunden hatte.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 6, 'Schließlich kam er zu Simon Petrus. Der sagte zu ihm: „Herr du wäschst mir die Füße?“');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 7, 'Jesus erwiderte {und sagte zu ihm}: „Was ich mache (tue), verstehst (weißt) du jetzt noch nicht, aber hinterher (später) wirst du es begreifen (verstehen, erfahren, wissen).“');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 8, '[Da] rief (sagte) Petrus {zu ihm}: „Du wirst (sollst) mir \'\'niemals\'\' die Füße waschen!“Jesus entgegnete {ihm}: „Wenn ich dich nicht wasche, hast du keinen Anteil an (Erbe, Gemeinschaft mit, Platz bei) mir!“');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 9, '[Da] meinte (sagte) Simon Petrus: „Herr, [dann wasche] mir nicht nur die Füße, sondern auch die Hände und den Kopf!“');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 10, 'Jesus sagte zu ihm: „Wer gebadet hat, braucht sich abgesehen von den Füßen nicht zu waschen, sondern ist ganz sauber. Auch ihr seid sauber, wenn auch nicht alle.“');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 11, 'Er kannte nämlich (ja, denn) denjenigen, der ihn verraten (ausliefern) würde. Deswegen sagte er: {dass} „Nicht alle [von euch] sind sauber.“');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 12, 'Nachdem er {nun (also, dann) } ihre Füße gewaschen, {und} seine Obergewänder angezogen (an sich genommen) und wieder Platz genommen hatte, fragte (sagte, meinte) er sie: „Wisst (versteht, erkennt) ihr, was ich [für (mit, an)] euch getan habe?');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 13, 'Ihr nennt mich »Lehrer« und »Herr«, und das sagt ihr mit Recht (zurecht, gut, richtig), denn (ja) das bin ich.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 14, 'Wenn ich euch also (nun, darum) die Füße gewaschen habe, [euer] Herr und Lehrer, dann seid auch ihr dazu verpflichtet, einander die Füße zu waschen!');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 15, 'Ich habe euch nämlich (ja, denn) ein Vorbild (Beispiel) gegeben, damit, genau wie ich [für (mit, an)] euch gehandelt (gemacht) habe, auch ihr handelt (macht).');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 16, 'Wahrlich, wahrlich (Amen, amen), ich sage euch: Ein Sklave ist nicht (Es gibt keinen) größer (besser) als sein Herr, und genauso wenig [ist] ein Abgesandter größer (besser) als sein Auftraggeber.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 17, 'Wenn ihr das versteht (wisst), seid ihr glücklich zu nennen (beneidenswert (glücklich)), sofern ihr es auch tut (macht, handelt).');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 18, 'Ich meine (spreche von/bezüglich) nicht euch alle, [wenn ich sage]: Ich weiß, welche ich mir ausgesucht (erwählt) habe, sondern damit die Schrift erfüllt wird: »Der mein Brot isst«, hat »seine Ferse gegen mich« erhoben (sich gegen mich gewandt).');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 19, 'Ich sage euch [das] schon jetzt, bevor [es] geschieht (passiert), damit ihr glaubt (vertraut, Glauben/Vertrauen habt), sobald (wenn) [es] geschieht (passiert), dass (denn) ich bin.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 20, 'Wahrlich, wahrlich (Amen, amen), ich sage euch: Wer denjenigen aufnimmt (annimmt), den ich senden werde, der nimmt mich auf (an), und (aber) wer mich aufnimmt (annimmt), der nimmt meinen Auftraggeber (denjenigen, der mich gesandt hat) an.“');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 21, 'Als Jesus das sagte, war er [im] Geist erschüttert und bekannte ihnen offen (bezeugte, machte eine Zeugenaussage) {und sagte}: „Wahrlich, wahrlich, ich sage euch: {dass} Einer von euch wird mich verraten!“');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 22, 'Die Jünger blickten [von einem] zum anderen (einander an) und waren verwirrt [darüber], von wem er sprach.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 23, 'Einer von seinen Jüngern lag (saß) an der Brust Jesu, [derjenige], den Jesus liebte.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 24, 'Diesem signalisierte (gab zu verstehen, winkte) {nun} Simon Petrus zu fragen, wer es war, von dem er gesprochen hatte.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 25, 'Also (da) lehnte der (jener) sich so an die Brust Jesu, [dass] er ihn fragen (zu ihm sagen) [konnte]: „Herr, wer ist es?“');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 26, 'Jesus antwortete: „Es ist derjenige (jener), dem (für den) ich das Stück Brot eintunken und [dann] geben werde.“Daraufhin tunkte er das Stück Brot ein, nahm es und gab es Judas, [dem Sohn von] Simon Iskariot (Judas Iskariot, [dem Sohn] Simons).');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 27, 'Und nach dem Stück Brot fuhr der Satan in ihn (jenen). Deshalb (also, da) sagte Jesus zu ihm: „Was du tust, tu schnell (bald)!“');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 28, 'Aber keiner von den zu Tisch Liegenden wusste, warum er das zu ihm sagte;');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 29, 'manche (einige) glaubten (meinten) nämlich, weil Judas die Geldtasche hatte, dass Jesus zu ihm sagte: „Kaufe ein, was wir für das Fest benötigen“oder dass er den Armen etwas geben sollte.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 30, 'Als der Angesprochene (jener) das Stück Brot angenommen hatte, ging er sofort hinaus. Es war {aber} Nacht.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 31, 'Als er also herausgegangen war, sagt Jesus: „Jetzt ist der Sohn des Menschen (der Menschensohn) verherrlicht, und Gott ist in ihm verherrlicht.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 32, 'Wenn Gott in ihm verherrlicht ist, wird Gott auch ihn in sich verherrlichen, und bald wird er ihn verherrlichen.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 33, 'Kinder (Kindlein), noch eine kleine Weile bin ich mit Euch. Ihr werdet mich suchen, und wie ich den Juden sagte: {daß} »Wohin ich gehe, dorthin könnt Ihr nicht kommen«, sage ich [das] jetzt auch Euch.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 34, 'Ein neues Gebot gebe ich Euch, daß Ihr einander liebt, wie ich Euch geliebt habe, damit Ihr auch einander liebt.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 35, 'Daran (in diesem) werden alle erkennen, dass ihr meine Jünger seid, wenn ihr Liebe habt zueinander (untereinander).“');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 36, 'Sagt ihm Simon Petrus: „Herr, wohin gehst Du?“Jesus antwortete ihm: „Wohin ich gehe, [dahin] kannst Du mir jetzt nicht folgen – Du wirst mir aber später folgen.“');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 37, 'Sagt ihm {der} Petrus: „Herr, weshalb kann ich Dir jetzt nicht folgen? Mein Leben werde ich für Dich einsetzen (hergeben).“');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 38, '');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 1, 'Euer Herz werde nicht bestürzt (unruhig, verwirrt): Glaubt an (vertraut auf) Gott und glaubt an mich (vertraut mir)!');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 2, 'Im Hause meines Vaters sind viele Aufenthaltsorte (Bleiben, Wohnungen). Wenn [es] aber nicht [so wäre], hätte ich euch dann gesagt „Ich gehe, um euch einen Ort vorzubereiten“?');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 3, 'Und wenn ich gehe und euch einen Ort vorbereite, komme ich wieder und nehme euch zu mir (bei mir auf), damit auch ihr seid, wo ich bin.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 4, 'Und wohin ich mich begebe - ihr kennt den Weg.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 5, 'Thomas spricht zu ihm: Herr, wir wissen nicht, wohin du dich begibst. Wie können wir den Weg wissen?');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 6, '{Der} Jesus sagt zu ihm: Ich bin der Weg, {und} die Wahrheit und das Leben. Niemand kommt zu dem Vater außer durch mich.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 7, 'Wenn Ihr mich erkannt habt, werdet Ihr auch meinen Vater erkennen. Von jetzt an erkennt Ihr ihn und Ihr habt ihn gesehen.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 8, 'Philippus sagt ihm: Herr, zeig uns den Vater, und es genügt uns.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 9, '{Der} Jesus sagt ihm: Soviel Zeit bin ich [schon] bei (mit) Euch und Du hast mich nicht erkannt, Philippus? Wer mich gesehen hat, hat den Vater gesehen. Wie sagst (kannst) Du (sagen): Zeig uns den Vater?');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 10, 'Glaubst Du nicht, daß ich in dem Vater und der Vater in mir ist? Die Worte, die ich Euch sage, sage ich nicht von mir (mir selbst) aus, der Vater aber, der in mir bleibt, tut (verwirklicht) seine Werke.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 11, 'Glaubt mir, daß ich in dem Vater [bin] und der Vater in mir [ist]. Wenn aber nicht, glaubt wegen der Werke selbst.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 12, 'Amen, Amen (Wahrlich, wahrlich), ich sage Euch, wer an mich glaubt, auch der (jener) wird die Werke, die ich tue (verwirkliche), tun (verwirklichen), und größere als diese wird er tun (verwirklichen), weil ich zum Vater gehe.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 13, 'Und alles, was ihr bittet in meinem Namen, dies werde ich tun, damit der Vater verherrlicht (gepriesen) wird im Sohn.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 14, 'Wenn Ihr mich [um] etwas bittet in meinem Namen, werde ich [es] tun.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 15, 'Wenn Ihr mich liebt, werdet Ihre meine Gebote halten.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 16, 'Und ich werde den Vater bitten und einen anderen Helfer (Beistand, Tröster) wird er Euch geben, damit er in Ewigkeit mit Euch sei,');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 17, 'den Geist der Wahrheit, den die Welt nicht empfangen kann, weil sie ihn nicht sieht und nicht kennt (erkennt). Ihr kennt (erkennt) ihn, weil er bei Euch bleibt und in Euch sein wird.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 18, 'Nicht werde ich zurücklassen euch als Waisen, ich komme zu Euch.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 19, 'Noch ist es kurz und die Welt (der Kosmos) sieht mich nicht mehr, ihr aber seht mich, weil ich lebe und ihr leben werdet.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 20, 'An jenem Tag werdet Ihr erkennen (verstehen, wissen), daß ich in meinem Vater und Ihr in mir und ich in Euch.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 21, 'Wer meine Gebote hat und sie hält, jener ist [der], der mich liebt. Wer aber mich liebt, [der] wird von meinem Vater geliebt werden, und ich werde ihn lieben und ich mich ihm zeigen (offenbaren).');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 22, 'Sagt ihm Judas, nicht der Iskariot: Herr, was ist geschehen, daß Du im Begriff bist, Dich selbst uns zu zeigen (offenbaren; warum willst Du Dich selbst uns offenbaren) und nicht der Welt?');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 23, 'Jesus antwortete und sagte ihm: Wenn einer mich liebt, wird er mein Wort halten und mein Vater wird ihn lieben und wir werden zu ihm kommen und (Wohnung, Aufenthalt) bei ihm wohnen (machen).');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 24, 'Der mich nicht liebt, hält nicht meine Worte: Und das Wort, das ihr hört, ist nicht von mir, sondern vom Vater, der mich geschickt (gesandt) hat.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 25, 'Dies habe ich euch gesagt als ich bei euch blieb (ausharrte).');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 26, 'Aber der Paraklet, der heilige Geist, den schicken wird der Vater in meinem Namen, jener wird euch lehren alles und euch erinnern an alles, was ich euch gesagt habe.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 27, 'Frieden hinterlasse ich Euch, meinen Frieden gebe ich Euch. Nicht wie die Welt gibt, gebe ich Euch. Euer Herz lasse sich nicht in Aufregung versetzen (werde nicht bestürzt, unruhig, verwirrt) und fürchte sich nicht!');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 28, 'Ihr habt gehört, daß ich Euch gesagt habe: Ich gehe weg und komme [wieder] zu Euch. Wenn Ihr mich lieben würdet, würdet Ihr Euch freuen, weil ich zum Vater gehe; denn der Vater ist größer als ich.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 29, 'Und jetzt habe ich Euch das gesagt, bevor es geschieht, damit Ihr, wenn es geschieht, glaubt.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 30, 'Viel (viele Dinge) werde ich mit Euch nicht mehr sprechen, es kommt nämlich der Herrscher der Welt. Und in (an) mir hat er nichts,');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 31, 'aber [das geschieht,] damit die Welt erkennt, daß ich den Vater liebe und so handle, wie mir der Vater geboten hat. Steht auf, laßt uns weggehen von hier.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 1, 'Ich bin der wahre Weinstock und mein Vater ist der Weinbauer (Bauer, Winzer).');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 2, 'Jede Rebe, die an (in) mir keine Frucht bringt, {die} entfernt er (nimmt er ab), und (aber) jede, die Frucht bringt, {die} säubert (beschneidet, reinigt) er, damit sie noch mehr Frucht bringt (bringen kann).');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 3, 'Ihr seid schon sauber durch die Dinge, die ich zu euch gesprochen habe.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 4, 'Bleibt an (in) mir, dann [bleibe] auch ich an (in) euch. Genau wie die Rebe von sich aus keine Frucht bringen kann, wenn sie nicht am (im) Weinstock bleibt, so auch ihr nicht, wenn ihr nicht an (in) mir bleibt.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 5, 'Ich bin der Weinstock, ihr seid die Reben. Wer an (in) mir bleibt und dann ich an (in) ihm, der bringt viel Frucht, denn ohne mich könnt ihr gar nichts tun.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 6, 'Wenn jemand (Wer) nicht an (in) mir bleibt, wird (wurde) er hinausgeworfen wie die Rebe und vertrocknet, und [die Leute] sammeln [sie] und werfen [sie] ins Feuer, und sie verbrennen.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 7, 'Wenn ihr an (in) mir bleibt und meine Worte in (an) euch bleiben, [dann] bittet um alles, was ihr wollt, und es wird [für] euch Wirklichkeit werden (geschehen).');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 8, 'Darin wird mein Vater verherrlicht, damit ihr viel Frucht bringt und meine Jünger werdet.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 9, 'Genau wie mich der Vater geliebt hat, [so] habe ich euch geliebt. Bleibt in meiner Liebe!');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 10, 'Wenn ihr meine Gebote haltet (bewahrt), bleibt ihr in meiner Liebe, genau wie ich die Gebote meines Vaters gehalten (bewahrt) habe und in seiner Liebe bleibe.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 11, 'Das habe ich euch gesagt, damit meine Freude in euch bleibt und eure Freude vollständig (vollkommen, voll) wird.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 12, 'Das ist mein Gebot: Dass ihr einander lieben sollt, genau wie ich euch geliebt habe.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 13, 'Niemand hat eine größere (bessere) Liebe {als diese}, [als] dass jemand sein Leben für seine Freunde gibt.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 14, 'Ihr seid meine Freunde, wenn ihr macht (tut), was ich euch aufgetragen (geboten) habe.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 15, 'Ich nenne euch nicht mehr Sklaven (Diener), denn der Diener weiß (versteht) nicht, was sein Herr tut (macht). Vielmehr nenne ich euch Freunde, denn alles, was ich von meinem Vater gehört habe, habe ich an euch weitergegeben (mitgeteilt).');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 16, 'Nicht ihr habt mich ausgesucht (auserwählt), sondern ich habe euch ausgesucht (auserwählt) und dazu bestimmt (ernannt, ausgesucht, gemacht), dass ihr hingeht und Frucht bringt und eure Frucht Bestand hat (bleibt), damit (sodass) alles, worum (was immer) ihr den Vater in meinem Namen bittet, er euch geben wird.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 17, 'Dies trage ich euch auf: dass (damit) ihr einander liebt.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 18, 'Wenn die Welt Euch haßt, wißt, daß sie mich vor Euch gehaßt hat.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 19, 'Wenn Ihr aus der Welt wäret, dann würde die Welt das eigene lieben. Weil Ihr aber nicht aus der Welt seid, sondern ich Euch aus der Welt auserwählt (ausgewählt, herausgenommen) habe, deswegen haßt Euch die Welt.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 20, 'Erinnert Euch an das Wort, das ich Euch gesagt habe: Ein Knecht ist nicht größer als sein Herr. Wenn sie mich verfolgt haben, werden sie auch Euch verfolgen. Wenn sie mein Wort gehalten (bewahrt) haben, werden sie auch Eures halten (bewahren).');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 21, 'Aber all dies (alle diese Dinge) werde sie Euch wegen meines Namens antun, weil sie nicht den kennen, der mich gesandt hat.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 22, 'Wenn ich nicht gekommen wäre und nicht [zu] ihnen gesprochen hätte, dann hätten sie keine Sünde. Nun aber habe sie keinen Vorwand (keine Entschuldigung, keinen Grund) für ihre Sünde.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 23, 'Wer mich haßt, haßt auch meinen Vater.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 24, 'Wenn ich nicht {die} Werke bei (unter) ihnen getan (gewirkt, vollbracht) hätte, die kein anderer getan (gewirkt, vollbracht) hat, hätten sie keine Sünde. Nun aber haben sie [die Werke] gesehen und hassen (haben) sowohl mich als auch meinen Vater (gehaßt).');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 25, 'Aber [das geschieht], damit das Wort, das in ihrem Gesetz geschrieben steht, erfüllt werde {, daß}: Sie hassten mich ohne Grund.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 26, 'Wenn der Helfer (Fürsprecher) kommen wird, den ich euch senden werde vom Vater, der Geist der Wahrheit, der vom Vater ausgeht, wird jener Zeugnis ablegen von mir (über mich).');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 27, 'Und auch ihr werdet Zeugen sein, weil ihr von Anfang an bei mir seid.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 1, 'Dies habe ich euch gesagt, damit ihr nicht abfallt (zur Sünde verleitet werdet).');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 2, 'Sie werden euch aus der Synagoge ausschließen. Ja, es wird sogar die Zeit kommen, dass jeder, der euch tötet, meint, Gott einen Dienst zu leisten (darzubringen).');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 3, 'Und das werden sie tun, weil sie weder den Vater kennen noch mich.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 4, 'Jedoch (indessen) habe ich euch dies gesagt, damit, wenn die Zeit dafür kommt, ihr euch daran erinnert, dass ich es euch sagte. Dies habe ich euch am Anfang nicht gesagt, weil ich bei euch war.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 5, 'Jetzt aber gehe ich (hin, weg) zu dem, der mich gesandt hat, und keiner von (aus) Euch fragt mich: Wohin gehst Du (weg)?');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 6, 'Aber weil ich dies (diese Dinge) Euch gesagt habe, hat die Trauer Euer Herz erfüllt.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 7, 'Aber ich sage Euch die Wahrheit: Es nützt Euch, daß ich weggehe. Denn wenn ich nicht weggehe, wird der Tröster (Mahner, Beistand) nicht zu Euch kommen. Wenn ich aber gehe, werde ich ihn zu Euch senden.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 8, 'Und wenn er (jener) gekommen ist (kommt), wird er die Welt bloßstellen (überführen, zurechtweisen) in Bezug auf (über) Sünde und in Bezug auf (über) Gerechtigkeit und in Bezug (über) auf [das] Gericht.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 9, 'In Bezug auf (Über) Sünde {zwar}, weil sie nicht an mich glauben.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 10, 'In Bezug auf (Über) Gerechtigkeit aber, weil ich zum Vater gehe (weggehe, hingehe) und Ihr mich nicht mehr seht.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 11, 'In Bezug auf (Über) [das] Gericht aber, weil der Herrscher dieser Welt gerichtet (worden) ist.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 12, 'Noch viel (viele Dinge) habe ich Euch zu sagen, aber jetzt könnte Ihr es (sie) nicht ertragen (tragen).');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 13, 'Wenn aber jener (er aber) kommt (gekommen ist), der Geist der Wahrheit, wird er Euch in der ganzen Wahrheit führen, nicht nämlich er wird von sich [aus] sprechen, sondern was (wieviele Dinge) er hören wird, wird er sprechen, und was kommen wird (die Dinge, die kommen werden), wird er Euch verkündigen (ankündigen).');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 14, 'Jener (Er) wird mich verherrlichen, weil er von (aus) dem Meinen nehmen und Euch verkündigen wird.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 15, 'Alles, was (Alle Dinge, die) der Vater hat, ist mein (sind meine). Deshalb habe ich gesagt, daß er von (aus) dem Meinen nimmt und Euch verkündigen wird.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 16, 'Ein wenig (ein kurzes) und ihr seht mich nicht, und wieder ein wenig und ihr werdet mich sehen.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 17, 'Es sagten also [einige] von (aus) seinen Jüngern zueinander: Was bedeutet (ist) das (dieses), was er uns sagt? Eine kleine Weile (ein wenig, ein kurzes) und Ihr seht mich nicht, und noch (wieder) eine kleine Weile (ein wenig, ein kurzes) und Ihr werdet mich sehen? Und: {Daß} Ich (Denn ich) gehe (weg, hin) zum Vater?');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 18, 'Sie sagten also: „Was bedeutet (ist) das (dieses), was er sagt: »eine kleine Weile (ein wenig, ein kurzes) « Wir verstehen (wissen) nicht, was er sagt.“');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 19, 'Jesus erkannte (merkte, wußte), daß sie ihn fragen wollten, und er sagte ihnen: Über das (dieses) denkt (forscht) Ihr miteinander nach, daß ich gesagt habe: Eine kleine Weile (ein wenig, ein kurzes) und Ihr seht mich nicht, und noch (wieder) eine kleine Weile (ein wenig, ein kurzes) und Ihr werdet mich sehen?');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 20, 'Amen, Amen (Wahrlich, wahrlich), ich sage Euch: {daß} Ihr werdet weinen und klagen (wehklagen, jammern), die Welt aber wird sich freuen. Ihr werdet trauern, aber Eure Trauer wird in Freude verwandelt werden (zu Freude werden).');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 21, 'Die Frau, die gebiert hat Trauer (Angst, Schmerzen), weil gekommen ist ihre Stunde, wenn aber das Kind geboren ist, micht mehr erinnert sie sich der Bedrängnis, wegen der Freude, weil ein Mensch in der Welt (im Kosmos) geworden ist.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 22, 'Und ihr habt nun zwar Schmerz (Angst, Trauer), ich werde Euch aber wiedersehen und es wird sich freuen euer Herz und eure Freude wird niemand von Euch nehmen.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 23, 'Und an jenem Tag werdet Ihr mich nichts fragen (bitten). Amen, Amen (Wahrlich, wahrlich), ich sage Euch, wenn Ihr etwas den Vater in meinem Namen bittet, wird er [es] Euch geben.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 24, 'Bis jetzt habt Ihr nichts in meinem Namen erbeten. Bittet und Ihr werdet empfangen, damit Eure Freude vollständig sei.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 25, 'Dies (Diese Dinge) habe ich Euch in verhüllter Rede (Rätselreden, Sprichwörtern) gesagt (geredet). Es kommt eine Stunde, in der (wann, da) ich nicht mehr in verhüllter Rede (Rätselreden, Sprichwörtern) zu Euch sprechen (reden), sondern Euch offen (freimütig, mit Offenheit, mit Freimütigkeit) über den Vater berichten (verkündigen) werde.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 26, 'An jenem Tag werdet Ihr in meinem Namen bitten, und ich sage Euch nicht, daß ich den Vater für (über) Euch bitten (fragen) werde.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 27, 'Der Vater selbst nämlich liebt Euch, weil Ihr mich geliebt habt und geglaubt habt, daß ich von Gott ausgegangen (herausgekommen) bin.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 28, 'Ich bin vom Vater ausgegangen (herausgekommen) und in die Welt gekommen. Wiederum verlasse ich die Welt und gehe zum Vater.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 29, 'Seine Jünger sagen: Sieh, jetzt redest Du offen (freimütig, in Offenheit, in Freimütigkeit) und keine verhüllte Rede (Rätselrede, Sprichwort) sprichst (redest) Du.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 30, 'Jetzt wissen wir, daß Du alles (alle Dinge) weißt und es nicht nötig hast, daß einer Dich fragt (bittet). Deshalb (Darin) glauben wir, daß Du von Gott ausgegangen (herausgekommen) bist.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 31, 'Jesus antwortete ihnen: Jetzt glaubt Ihr?');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 32, 'Sieh, es kommt eine Stunde, und sie ist gekommen, in der (dass) ihr zerstreut werdet, jeder in das Eigene, und mich allein laßt. Aber (Und) ich bin nicht allein, weil der Vater mit mir ist.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 33, 'Dies (Diese Dinge) habe ich Euch gesagt, damit Ihr in mir Frieden habt. In der Welt habt Ihr Kummer (Leid, Bedrängnis), aber seid zuversichtlich (guten Muts), ich habe die Welt besiegt.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 17, 1, 'Dies (Diese Dinge) sagte Jesus, und indem er seine Augen zum (in den) Himmel erhob, sprach er: Vater, die Stunde ist gekommen. Verherrliche Deinen Sohn, damit der Sohn Dich verherrlicht.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 17, 2, 'Wie (Sowie) Du ihm Vollmacht (Macht, Gewalt) über alles Fleisch (allen Fleisches) gegeben hast, damit er allen, die (jeden, den) Du ihm gegeben hast, ewiges Leben {ihnen} gebe.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 17, 3, 'Dies aber ist das ewige Leben, daß sie Dich, den einzigen wahren Gott kennen (erkennen) und den Du gesandt hast, Jesus Christus.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 17, 4, 'Ich habe Dich auf der Erde verherrlicht, indem ich das Werk vollendet habe, das Du mir gegeben hast, damit ich es tue.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 17, 5, 'Und jetzt verherrliche Du mich, Vater, bei Dir selbst mit der Herrlichkeit (Ehre), die ich bei Dir hatte, bevor die Welt war.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 17, 6, 'Ich habe Deinen Namen den Menschen offenbar gemacht, die Du mir aus der Welt gegeben hast. Dein waren sie und mir hast Du sie gegeben, und Dein Wort haben Sie bewahrt.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 17, 7, 'Jetzt haben sie erkannt (wissen sie), daß alles, was Du mir gegeben hast, von Dir ist.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 17, 8, 'Denn die Worte, die Du mir gegeben hast, habe ich ihnen gegeben, und sie nahmen [sie] an und erkannten wahrhaftig (wirklich), daß ich von Dir ausgegangen bin, und sie haben geglaubt, daß Du mich gesandt hast.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 17, 9, 'Ich bitte für sie: Nicht für die Welt bitte ich, sondern für die, die Du mir gegeben hast, weil sie Dein sind,');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 17, 10, 'und alles, was mein [ist], Dein ist, und das Deine mein, und ich in ihnen verherrlicht (worden) bin.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 17, 11, 'Und nicht mehr bin ich in der Welt, und sie sind in der Welt, und ich gehe (komme) zu Dir. Heiliger Vater, bewahre sie in Deinem Namen, den Du mir gegeben hast, damit sie eins sind wie wir.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 17, 12, 'Solange ich in mit ihnen war, habe ich sie in dem Namen bewahrt, den Du mir gegeben hast, und ich habe gewacht ([sie] beschützt), und keiner von (aus) ihnen ging verloren (zugrunde), außer dem Sohn der Verlorenheit (des Verderbens), damit die Schrift erfüllt werde.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 17, 13, 'Jetzt aber komme (gehe) ich zu Dir, und dies (diese Dinge) sage ich in der Welt, damit sie meine Freude in sich vollkommen (erfüllt) haben.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 17, 14, 'Ich habe ihnen Dein Wort gegeben, und die Welt hat sie gehaßt, weil sie nicht aus (von) der Welt sind, wie [auch] ich nicht aus (von) der Welt bin.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 17, 15, 'Nicht bitte ich [darum], daß Du sie aus der Welt nimmst, sondern daß Du sie bewahrst vor (aus) dem Bösen (Schlechten).');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 17, 16, 'Aus (Von) der Welt sind sie nicht, wie ich nicht aus (von) der Welt bin.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 17, 17, 'Heilige sie in der Wahrheit: Dein Wort ist Wahrheit.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 17, 18, 'Wie Du mich in die Welt gesandt hast, [so] habe auch ich sie in die Welt gesandt.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 17, 19, 'Und für sie heilige ich mich selbst, damit auch sie in Wahrheit geheiligt seien.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 17, 20, 'Ich bitte dich nicht nur für sie, sondern auch für [alle], die aufgrund (wegen, durch) ihres Wortes an mich glauben,');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 17, 21, '[und zwar darum,] dass sie alle eins sind, so wie du, Vater, in mir [bist] und ich in dir, damit (so dass; [darum,] dass) die Welt [daran] glaubt, dass \'\'du\'\' mich gesandt hast!');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 17, 22, 'Und die Herrlichkeit, die du mir gegeben hast, habe ich ihnen [weiter] gegeben, [weil ich möchte,] dass (damit) sie eins sind, so wie wir eins [sind].');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 17, 23, 'Ich [bin] in ihnen und du [bist] in mir, [weil ich möchte,] dass (damit) sie auf (zu) einem [Ziel (Zweck; einer Einheit)] hin vollendet werden (sind), damit (sodass) die ganze Welt erkennt (weiß), dass \'\'du\'\' mich gesandt hast und sie genau so geliebt hast, wie du mich geliebt hast.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 17, 24, 'Vater, der du [sie] mir gegeben hast, ich möchte, dass {auch} diese [Menschen] (jene) bei mir sind, [egal] wo ich bin, so dass (damit) sie meine Herrlichkeit sehen, die du mir gegeben hast, weil du mich [schon] vor [der] Erschaffung [der] Welt geliebt hast!');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 17, 25, 'Gerechter Vater, und die Welt hat dich nicht erkannt (gekannt), doch ich habe dich gekannt (erkannt), und [auch] diese [Männer] haben erkannt, dass \'\'du\'\' mich gesandt hast.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 17, 26, 'Und ich habe ihnen deinen Namen bekannt gemacht und werde [ihn weiter] bekannt machen, [weil ich möchte,] dass (damit) die Liebe, [mit] der du mich geliebt hast, in ihnen ist und [auch] ich in ihnen bin.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 1, 'Nachdem (als) Jesus das gesagt hatte, ging er mit seinen Jüngern hinaus, auf die andere Seite (über, durch) des Kidrontals, wo ein Olivenhain (Garten) war, in den er und seine Jünger hineingingen.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 2, 'Aber auch Judas, derjenige, der ihn verriet (auslieferte) (der Verräter), kannte den Ort, weil Jesus sich dort häufig mit seinen Jüngern traf.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 3, 'Judas hatte {darum} die Kohorte ([eine] Einheit, Abteilung [Soldaten der römischen Garnison]) sowie (und) Tempelwachen (Dienern) von den obersten (führenden) Priestern und {von} den Pharisäern geholt (genommen; holte, führte) und kam [mit ihnen] dorthin, mit Fackeln, {und} Laternen und Waffen.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 4, 'Aber (da) Jesus wusste alles, was auf ihn zukam. Deshalb verließ er [den Garten] (ging er hinaus) und sagte zu ihnen: Wen sucht ihr?');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 5, 'Sie antworteten {ihm}: Jesus den Nazoräer (von Nazaret)! Er sagte {zu ihnen}: [Der] bin ich. {aber} Judas, derjenige, der ihn verriet (auslieferte) (der Verräter), stand auch bei ihnen.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 6, 'Als er nun zu ihnen sagte: [Der] bin ich!, [da] wichen sie zurück und stürzten (fielen) zu Boden.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 7, 'Da fragte er sie noch einmal (wieder): Wen sucht ihr? Sie {aber} sagten: Jesus den Nazoräer (von Nazaret)!');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 8, 'Jesus erwiderte (antwortete): Ich habe euch gesagt, dass ich [es] bin. Wenn ihr {also} [nur] mich sucht, [dann] lasst (erlaubt) diese [Männer] gehen!');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 9, '[Das sagte er,] damit sein Ausspruch (Wort, Vorhersage) erfüllt wurde: „Von denen, die du mir gegeben hast, habe ich keinen einzigen verloren.“');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 10, 'Doch Simon Petrus, der ein Schwert dabeihatte, zückte es und schlug [nach] dem Sklaven (Diener) des Hohenpriesters und schnitt ihm das rechte Ohr ab. Der Name des Sklaven (Dieners) war {übrigens} Malchus.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 11, 'Da sagte Jesus zu Petrus: Stecke das Schwert [zurück] in die Scheide! Soll (muss) ich den Kelch, den mir der Vater gegeben hat, {ihn} etwa nicht trinken?');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 12, 'Da ergriffen die Kohorte und [ihr] Offizier (Kommandant, Trbun, Oberst, Chiliarch) und die Tempelwachen (Diener) der Juden Jesus, {und} fesselten ihn');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 13, 'und führten ihn zuerst vor (zu) Hannas. Denn er war [der] Schwiegervater des Kajaphas, der in jenem Jahr Hoherpriester war.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 14, 'Kajaphas war {übrigens} derjenige, der den Juden geraten hatte, dass es die bessere Lösung (besser, nützlich, vorzuziehen) sei, [wenn] ([dass]) \'\'ein\'\' Mann (Mensch) anstelle (für) des Volkes stirbt.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 15, '[Es] folgte aber dem Jesus Simon Petrus und ein anderer Jünger. Jener Jünger aber war dem Hohenpriester bekannt und ging zusammen mit {dem} Jesus in den Hof des Hohenpriesters.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 16, '{Der} Petrus aber stand draußen bei der Tür. [Es] kam also der andere Jünger, der Bekannte des Hohenpriesters, heraus und sprach [mit] der Türhüterin und führte {den} Petrus hinein.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 17, 'Die Magd, die Türhüterin sagt also zu {dem} Petrus: Bist nicht (etwa) auch Du einer der Jünger (aus den Jüngern) dieses Menschen? Sagt jener: [Das] bin ich nicht.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 18, '[Es] standen [da] aber die Knechte und Diener, die ein Kohlfeuer gemacht hatten, weil es kalt war, und wärmten sich. [Es] stand aber auch {der} Petrus bei (mit) ihnen und wärmte sich.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 19, 'Der Hohepriester also fragte {den} Jesus über seine Jünger und über seine Lehre.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 20, 'Jesus antwortete ihm: Ich habe öffentlich (offen, mit Offenheit) zur Welt gesprochen (geredet). Ich habe immer in einer Synagoge und im Tempel gelehrt, wo alle {die} Juden zusammenkommen, und im Geheimen (Verborgenen) habe ich nichts gesprochen (geredet).');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 21, 'Was (weshalb) fragst Du mich? Frage diejenigen, die gehört haben, was ich [zu] ihnen gesagt (gesprochen, geredet) habe. Sieh, diese wissen, was ich gesagt habe.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 22, 'Als er aber dies (diese Dinge) gesagt hatte, gab einer der Diener, die dabeistanden, {dem} Jesus eine Ohrfeige (einen Backenstreich), wobei er sagte: So antwortest Du dem Hohenpriester?');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 23, 'Jesus antwortete ihm: Wenn ich schlecht (böse) gesprochen habe, gib Zeugnis über (bezeuge) das Schlechte (Böse). Wenn aber gut (schön, recht) – weshalb (was) schlägst (prügelst) Du mich?');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 24, '{Der} Hannas schickte ihn also gebunden (weg) zu Kajafas, dem Hohenpriester.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 25, 'Simon Petrus aber stand [da] und wärmte sich. Sie sagten im also: Bist nicht (etwa) auch Du [einer] von (aus) seinen Jüngern? Jener leugnete und sagte: [Das] bin ich nicht.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 26, '[Da] sagt einer der Knechte (aus, von den Knechten) des Hohenpriesters, der ein Verwandter dessen war, dem Petrus das Ohr abgeschlagen hatte: Habe ich Dich nicht in dem Garten mit ihm gesehen?');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 27, 'Wieder (wiederum) also leugnete Petrus. Und sogleich krähte (tönte) ein Hahn.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 28, 'Sie führen also {den} Jesus von {dem} Kajafas in das Prätorium. Es war aber frühmorgens (früh). Und sie gingen nicht in das Prätorium hinein, damit sie sich nicht verunreinigten, sondern das Pascha essen konnten (könnten).');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 29, '[Es] kam also {der} Pilatus heraus zu ihnen und sagt: Welche Anklage bringt Ihr gegen diesen Menschen vor?');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 30, 'Sie antworteten und sagten ihm: Wenn dieser nicht ein Übeltäter wäre (einer wäre, der Böses tut), hätten wir ihn Dir nicht übergeben.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 31, '[Es] sagte ihnen also {der} Pilatus: Nehmt Ihr ihn und richtet (verurteilt) ihn nach Eurem Gesetz. [Es] sagten ihm die Juden: Uns ist es nicht erlaubt, jemanden zu töten.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 32, 'Damit das Wort Jesu (des Jesus) erfüllt würde, das er sagte um anzudeuten (anzuzeigen; andeutend, anzeigend), (durch) welchen Tod er im Begriff war, zu sterben (sterben sollte).');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 33, '[Es] ging also {der} Pilatus wieder (wiederum) in das Prätorium und rief {den} Jesus und sagte ihm: Du bist der König der Juden?');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 34, 'Jesus antwortete: Sagst Du das von Dir aus, oder haben andere zu Dir über mich gesprochen (Dir [das] über mich gesagt)?');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 35, '{Der} Pilatus antwortete: Bin ich etwa ein Jude? Dein Volk und die Hohenpriester haben Dich mir übergeben. Was hast Du getan?');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 36, 'Jesus antwortete: \'\'Mein\'\' Königreich (Königtum, Reich) ist nicht aus dieser Welt. Wenn \'\'mein\'\' Königreich (Königtum, Reich) aus dieser Welt wäre, hätten (würden) \'\'meine\'\' Diener gekämpft (kämpfen), damit ich nicht den Juden übergeben würde. Nun aber ist \'\'mein\'\' Königreich (Königtum, Reich) nicht von hier.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 37, '[Es] sagte ihm also {der} Pilatus: Folglich bist Du also ein König? {Der} Jesus antwortete: Du sagst, dass ich ein König bin. Ich bin dazu geboren und dazu in die Welt gekommen, dass ich für die Wahrheit Zeugnis ablege. Jeder, der aus der Wahrheit ist, hört meine Stimme.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 38, '{Der} Pilatus sagt ihm: Was ist Wahrheit? Und nachdem er das gesagt hatte, ging er zurück (wieder) zu den Juden und sagt ihnen: Ich finde keine Schuld in ihm.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 39, 'Es ist (gibt) aber (einen) Brauch bei Euch, dass ich Euch einen am Paschafest (Pascha) freilasse. Wollt Ihr also, dass ich den König der Juden freilasse?');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 40, 'Sie schrien also wieder (wiederum), indem sie sagten: Nicht diesen sondern {den} Barabbas. [Es] war aber {der} Barabbas ein Räuber.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 1, 'Dann also nahm {der} Pilatus {den} Jesus und ließ ihn geißeln (ließ ihn auspeitschen; geißelte ihn, peitschte ihn aus).');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 2, 'Und die Soldaten flochten eine Krone (einen Kranz) aus Dornen und setzten sie (ihn) auf sein Haupt (seinen Kopf), und sie legten (warfen) ihm einen purpurnen Mantel (ein purpurnes Gewandt) an (um),');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 3, 'und sie kamen zu ihm und sagten: Sei gegrüßt, {der} König der Juden. Und sie gaben ihm Ohrfeigen (Backenstreiche).');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 4, 'Und wieder (wiederum) ging (kam) {der} Pilatus heraus (hinaus) und sagt ihnen: Sieh (Seht) ich bringe Euch ihn heraus, damit Ihr erkennt (wißt), dass ich keine Schuld in ihm finde.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 5, '[Es] kam also {der} Jesus heraus, angetan mit der Dornenkrone (dem Dornenkranz) und dem purpurnen Mantel (Gewandt) (und trug die Dornenkrone und den purpurnen Mantel). Und er sagt ihnen: Sieh (Seht), der Mensch!');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 6, 'Als ihn also die Hohenpriester und die Diener sahen, schrien sie und sagten: Kreuzige, kreuzige! {Der} Pilatus sagt ihnen: Nehmt Ihr ihn und kreuzigt [ihn], ich nämlich finde in ihm keine Schuld.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 7, '[Es] antworteten ihm die Juden: Wir haben ein Gesetz und nach dem Gesetz muß er sterben, weil er sich Sohn Gottes gemacht hat.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 8, 'Als also {der} Pilatus dieses Wort hörte, fürchtete er sich mehr');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 9, 'und ging wieder (wiederum) in das Prätorium hinein und sagt zu (dem) Jesus: Woher bist Du? {Der} Jesus aber gab ihm keine Antwort.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 10, '[Es] sagt ihm also {der} Pilatus: Mit mir sprichst Du nicht? Weißt Du nicht, dass ich Macht (Vollmacht) habe, Dich freizulassen, und Macht (Vollmacht), Dich zu kreuzigen?');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 11, '[Es] antwortete ihm Jesus: Du hättest keine Macht (Vollmacht) über mich, wenn es Dir nicht von oben gegeben worden wäre. Deshalb hat der, der mich Dir übergeben (überliefert) hat, größere Schuld (Sünde).');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 12, 'Aus diesem [Grund] (deshalb, von da an) versuchte (suchte) {der} Pilatus ihn freizulassen. Die Juden aber schrien und sagten: Wenn Du diesen freiläßt, bist Du kein Freund des Kaisers (Caesars). Jeder, der sich (zum) König macht, handelt gegen den (widersteht, widerspricht dem) Kaiser (Caesar).');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 13, 'Als Pilatus also diese Worte gehört hatte (hörte), führte er {den} Jesus heraus, und setzte sich (ihn) auf den Richtstuhl auf einem (an einen) Platz, der Lithostrotos genannt wird, auf Hebräisch aber Gabbata.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 14, 'Es war aber Rüsttag des Pascha, es war ungefähr die sechste Stunde. Und er spricht zu den Juden: Siehe, euer König!');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 15, 'Jene schrien folglich (aber): Trag weg, trag weg! Kreuzige ihn! Pilatus spricht zu ihnen: Euren König soll ich kreuzigen? Die Hohenpriester antworteten: Wir haben keinen König außer [dem] Kaiser.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 16, 'Dann also übergab er ihn ihnen, damit er gekreuzigt würde. Sie übernahmen also {den} Jesus.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 17, 'Und das Kreuz selbst (allein) tragend ging er hinaus zu dem Ort, der Schädelstätte genannt wird – was auf Hebräisch Golgotha heißt,');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 18, 'wo sie ihn kreuzigten, und mit ihm andere zwei auf der einen und der anderen Seite (von dort und von dort), inmitten (in der Mitte) aber {den} Jesus.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 19, '[Es] schrieb (ließ aber) {der} Pilatus aber auch eine Aufschrift (schreiben) und befestigte (setzte) [sie] an dem (auf das) Kreuz (befestigen; setzen). Es war aber geschrieben: Jesus der Nazoräer, der König der Juden.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 20, 'Diese Aufschrift also lasen viele der Juden, weil der Ort, wo Jesus gekreuzigt wurde, nahe der Stadt war. Und es war geschrieben in Hebräisch, Römisch, Griechisch.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 21, '[Es] sagten also die Hohenpriester der Juden zu {dem} Pilatus: Schreib nicht: Der König der Juden, sondern, dass jener behauptete (sagte), König der Juden zu sein (bin ich).');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 22, 'Pilatus antwortete: Was ich geschrieben habe, habe ich geschrieben.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 23, 'Die Soldaten also, als sie {den} Jesus gekreuzigt hatten, nahmen seine Kleider (Obergewänder) und machten vier Teile, einem jedem Soldaten einen Teil, und das Untergewand. Das Untergewand war aber ohne Naht von oben an als Ganzes (ganz durch) gewebt.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 24, 'Sie sagten also zueinander: Laßt uns es nicht zerteilen, sondern durch Los über es bestimmen (über es losen), wem es gehören wird (wessen es sein wird). Damit die Schrift erfüllt werde, die sagt: Sie verteilten meine Kleider (Obergewänder) unter sich und über meine Kleidung warfen sie ein Los. Die Soldaten also taten das (machten diese Dinge).');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 25, '[Es] standen aber bei dem Kreuz Jesu seine Mutter und die Schwester seiner Mutter, Maria, die des Klopas und Maria (die) Magdalena.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 26, 'Als Jesus also die Mutter und dabeistehend den Jünger, den er liebte, sah, sagt er der Mutter: Frau, sieh Deinen Sohn.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 27, 'Darauf sagt er dem Jünger: Sieh, Deine Mutter. Und von jener Stunde an nahm der Jünger sie zu sich (in sein Eigenes).');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 28, 'Danach, da Jesus wußte, daß schon alles vollendet war, sagt er, damit die Schrift erfüllt würde: Ich habe Durst (dürste).');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 29, 'Ein Gefäß stand [da] gefüllt mit Essig. Sie steckten also einen Schwamm gefüllt mit dem Essig auf einen Ysop und näherten [ihn] seinem Mund.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 30, 'Als also Jesus den Essig genommen hatte, sagte er: Es ist vollendet, und, indem er das Haupt neigte, übergab er den Geist.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 31, 'Die Juden also, da Rüsttag war, [und] damit die Körper nicht auf dem Kreuz an dem Sabbat blieben – es war nämlich jener Tag des Sabbats bedeutend (groß) – baten den Pilatus, daß man (sie) ihre Beine zerschlage (zerschlagen) und [sie dann] wegnehme (wegnehmen).');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 32, '[Es] kamen also die Soldaten und sie zerschlugen zwar die Beine des ersten und [die] des anderen, der mit ihm gekreuzigt worden war;');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 33, 'als sie aber zu [dem] Jesus kamen und sahen, daß er schon gestorben war, zerschlugen sie seine Beine nicht,');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 34, 'aber einer der Soldaten stach (stieß) mit einer Lanze [in] seine Seite und sogleich kam Blut und Wasser heraus.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 35, 'Und der [es] gesehen hat, hat [es] bezeugt, und sein Zeugnis ist wahr, und jener weiß, dass er Wahres (wahre Dinge) sagt, damit auch ihr glaubt.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 36, 'Es geschah (geschahen) nämlich dies (diese Dinge), damit die Schrift erfüllt würde.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 37, 'Und wieder (wiederum) sagt eine andere Schrift: Sie werden auf den sehen, den sie durchbohrten.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 38, 'Nach diesen Dingen aber (Danach aber) bat (fragte) Josef von Arimatäa, der ein Jünger Jesu (des Jesus) war, aber ein geheimer (versteckter) wegen der Furcht vor den (der) Juden, {den} Pilatus, den Körper (Leib) Jesu (des Jesus) zu holen (wegzunehmen). Und Pilatus überließ ihn (ließ es zu). Er kam also und holte (nahm) seinen Körper (Leib).');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 39, '[Es] kam aber auch Nikodemus, der zuerst nachts zu ihm gekommen war, und brachte eine Mischung von Myrrhe und Aloe, ungefähr hundert Pfund.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 40, 'Sie nahmen also den Körper (Leib) Jesu (des Jesus) und wickelten (banden) ihn (zusammen) mit den wohlriechenden Gewürzen in (mit) Leinenbinden, wie es Brauch ist bei den Juden bei Bestattungen (um zu bestatten).');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 41, 'Es gab (war) aber an dem Ort, wo er gekreuzigt worden war, einen (ein) Garten, und in dem Garten ein neues Grab, in dem noch niemand begraben worden war.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 42, 'Dort also – wegen des Vortags der Juden, weil das Grab nahe war – begruben sie [den] Jesus.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 1, '{aber} Am ersten [Tag] der Woche kam Maria Magdalena (die Magdalenerin) früh, als es noch dunkel war, zum Grab und sah, dass der Stein vom Grab entfernt worden war.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 2, 'Da (darum) rannte sie {und kam} zu Simon Petrus und zu dem anderen Jünger, den Jesus liebte, und sagte zu ihnen: „Sie haben den Herrn aus dem Grab geholt (weggebracht), und wir wissen nicht, wo sie ihn hingebracht haben!“');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 3, 'Da (darum) machten sich Petrus und der andere Jünger auf und liefen zum Grab.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 4, 'Dabei rannten die beiden gemeinsam, und der andere Jünger rannte schneller als Petrus voraus und kam als erster beim Grab an');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 5, 'und indem (als) er sich vorbeugte, sah er die Leinentücher daliegen, ging allerdings nicht hinein.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 6, 'Dann (da) kam auch Simon Petrus an, der ihm gefolgt war, und betrat (ging hinein in) das Grab, und er sah sich die daliegenden Leinentücher an,');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 7, 'und das Tuch (Gesichtstuch), das auf seinem Kopf [gelegen hatte], lag nicht bei den Leinentüchern, sondern für sich (gesondert) aufgerollt (gefaltet) an einer [anderen] Stelle.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 8, 'Daraufhin ging {dann} auch der andere Jünger hinein, der zuerst zum Grab gekommen war, und er sah und glaubte.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 9, 'Denn bis dahin (noch nicht) hatten sie die Schrift (Schriftstelle) noch nicht verstanden (gekannt), wonach es nötig war, dass er von den Toten auferstand.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 10, 'Die Jünger gingen dann wieder zurück nach Hause.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 11, 'Doch Maria stand draußen beim Grab und weinte. Als sie {nun} weinte, beugte sie sich vor zum Grab');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 12, 'und erblickte zwei Engel in weiß, die, einer beim Kopf und einer bei den Füßen, [dort] saßen, wo Jesu Leichnam (Körper) gelegen hatte.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 13, '{und} Diese sagten zu ihr: „Frau, warum weinst du?“Sie meinte (sagte) {zu ihnen, dass}: „Sie haben meinen Herrn weggebracht, und ich weiß nicht, wo sie ihn hingebracht (hingelegt) haben!“');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 14, 'Als (während) sie das sagte, wandte sie sich nach hinten um und sah (erblickte) [dort] Jesus stehen, aber sie wusste (erkannte) nicht, dass es Jesus war.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 15, 'Jesus fragte (sagte) sie: „Frau, warum weinst du? Wen suchst du?“Sie dachte, dass er der Gärtner war, [und] sagte {zu ihm}: „Herr, wenn du ihn weggetragen hast, sag mir, wo du ihn hingebracht (hingelegt) hast, dann werde ich ihn holen (fortbringen)!“');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 16, 'Jesus sagte zu ihr: „Maria“, diese wandte sich um und sagte zu ihm auf Hebräisch: „Rabbuni!“, das heißt „Lehrer“.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 17, 'Jesus sagte zu ihr: „Halte mich nicht fest (Lass mich los, Berühre mich nicht), ich bin nämlich (denn, ja) noch nicht zum Vater hinaufgegangen. Geh {aber} zu meinen Brüdern und sage ihnen: »Ich gehe hinauf zu meinem Vater und eurem Vater, {und (nämlich) } meinem Gott und eurem Gott.«“');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 18, 'Maria ging und erzählte (berichtete) den Jüngern {dass}: „Ich habe den Herrn gesehen!“, und [dass] er ihr Folgendes gesagt hatte.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 19, 'Es war Abend [an] jenem Tag, dem ersten [Tag] der Woche und die Türen [der Örtlichkeit], wo sich die Jünger aufhielten, waren aufgrund ihrer Furcht [vor] den Juden abgeschlossen. Jesus kam und trat in die Mitte [des Raumes] und sprach zu ihnen: „Friede [sei] mit euch!“');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 20, '{und} Als er das gesagt hatte (während er das sagte), zeigte er ihnen die [seine] Hände und die [seine] Seite. Da freuten sich die Jünger, weil (als) sie den Herrn sahen.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 21, 'Da sagte Jesus noch einmal zu ihnen: „Friede [sei] mit euch! So, wie mich der Vater gesandt hat, so sende ich euch!“');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 22, 'Und nachdem er das gesagt hatte, hauchte (pustete, blies) er sie an und sagte: „Empfangt [den] Heiligen Geist!');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 23, 'Welchen ihr die Sünden vergeben werdet, [denen] werden [sie] vergeben, welchen ihr [sie] behaltet, [denen] werden sie behalten.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 24, 'Aber Thomas, einer von den Zwölfen, der »Zwilling« (Didymos) genannt wird, war nicht bei ihnen, als Jesus kam.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 25, 'Die anderen Jünger erzählten (sagten) ihm nun (darum): »Wir haben den Herrn gesehen!« Er aber sagte zu ihnen: »Wenn ich ihn nicht in (auf) seinen Händen die Spuren (Male, Narben) der Nägel sehe und meine Hand in (an) seine Seite lege, werde ich bestimmt nicht glauben!«');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 26, 'Und nach acht Tagen waren seine Jünger wieder drinnen und Thomas [war] bei ihnen. Jesus kam [herein], obwohl (nachdem) die Türen verschlossen waren, {und} trat in die Mitte und sprach (sagte): »Friede [sei] mit euch!«');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 27, 'Dann sagt er zu Thomas: »Reiche deinen Finger hierher, und schau meine Hände an, und reich deine Hand und führe (lege) sie an meine Seite, und sei nicht (zeige dich nicht als) ungläubig, sondern gläubig!«');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 28, 'Thomas erwiderte (antwortete) {und sagte zu ihm}: »Mein Herr und mein Gott!«');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 29, 'Jesus sagt (spricht) zu ihm: »Weil du mich gesehen hast, glaubst du jetzt (hast du geglaubt). (?) Glücklich zu nennen (beneidenswert/wie glücklich) sind diejenigen, die nicht sehen und [doch] glauben.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 30, 'Jesus hat {nun} vor [den Augen] (in Gegenwart) seiner Jünger noch viele weitere Zeichen (Wunder) getan, die nicht in diesem Buch niedergeschrieben sind.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 31, 'Diese wurden niedergeschrieben, damit ihr glaubt, dass Jesus der Messias (Christus) der Sohn Gottes ist, und damit ihr [als] Glaubende (durch den Glauben) Leben in seinem Namen habt. «“');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 21, 1, 'Danach (später) zeigte sich (gab sich zu erkennen) Jesus den Jüngern noch einmal am See Tiberias. Und so zeigte er sich (gab er sich zu erkennen):');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 21, 2, 'Simon Petrus und Thomas, der Didymus (Zwilling) genannt wird, sowie (und) Nathanael aus Kana [in] Galiläa und die [Söhne] des Zebedäus und zwei weitere (andere) von seinen Jüngern waren zusammen (beisammen).');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 21, 3, 'Simon Petrus sagte ihnen: „Ich gehe fischen.“[Die anderen] entgegneten (sagten) {ihm}: „ {Auch} Wir kommen mit dir!“Sie brachen auf (gingen hinaus) und bestiegen das Boot (gingen hinaus zum Boot und legten ab), aber (und) in dieser (jener) Nacht fingen sie nichts.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 21, 4, 'Als es aber schon (früher) Morgen wurde (war, geworden war), stand Jesus am Ufer, die Jünger wussten (erkannten) aber (allerdings) noch nicht, dass es Jesus war.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 21, 5, 'Dann (also, nun) rief (sagte) er ihnen zu: „Männer (Kinder), ihr habt keinen Happen (Fisch) zu essen, oder (Habt ihr zufällig/vielleicht einen Happen zu essen)?“Sie riefen zurück (antworteten, entgegneten): „Nein!“');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 21, 6, 'Da (aber) rief (sagte) er ihnen zu: „Werft euer Netz [doch einmal] auf der rechten Seite des Bootes aus, dann (und) werdet ihr fündig {werden}!“Also warfen sie [es dort] aus, und sie konnten (vermochten, waren nicht stark genug) es wegen der Masse [an] Fischen nicht mehr einholen.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 21, 7, 'Daraufhin (da, darum) sagte (rief) der Jünger, den Jesus liebte, zu Petrus: „Es ist der Herr!“Als Simon Petrus hörte, dass es der Herr war, da band er sich das Obergewand hoch (wickelte ... um sich) – er war nämlich (denn) nackt –, und stürzte sich ins Meer (in den See),');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 21, 8, 'während (aber) die anderen Jünger [mit] dem Boot (kleinen Boot) kamen. Sie waren nämlich (denn) nicht weit vom Land (Ufer) entfernt, nur etwa 200 Ellen. Dabei zogen sie das Netz [mit] den Fischen [hinter sich] her.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 21, 9, 'Als sie dann an Land (ans Ufer) kamen (anlegten), sahen sie ein vorbereitetes Kohlenfeuer, und ein Fisch war daraufgelegt und Brot.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 21, 10, 'Jesus sagte zu ihnen: „Holt [doch einige] von den Fischen, die ihr gerade gefangen habt!“');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 21, 11, 'Da stieg Simon Petrus [ins Boot] (kam an Land) und zog das Netz an Land, angefüllt [mit] 153 großen Fischen, und obwohl es so viele waren, wurde das Netz nicht zerissen.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 21, 12, 'Jesus sagte zu ihnen: „Kommt, frühstückt!“Und keiner [von] den Jüngern traute sich (wagte), ihn zu fragen: „Wer bist du?“, weil (obwohl) sie wussten, dass es der Herr war.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 21, 13, 'Jesus kam und nahm das Brot und gab es ihnen, und den Fisch genauso.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 21, 14, 'Das war schon das dritte Mal, [dass] Jesus sich den Jüngern zeigte (sich zu erkennen gab), nachdem er von den Toten auferweckt worden war. Das war schon das dritte Mal, [dass] Jesus sich den Jüngern zeigte, nachdem (seit) er von den Toten auferstanden war.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 21, 15, 'Als sie dann gefrühstückt hatten, sagte Jesus zu Simon Petrus: „Simon, [Sohn] von Johannes, liebst du mich mehr [als] die hier (diese)?“Er entgegnete (sagte) {zu ihm}: „Ja, Herr, du weißt, dass ich dich lieb habe.“[Jesus] erwiderte (sagte) {zu ihm}: „Füttere (Weide) meine Lämmer!“');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 21, 16, 'Er sagte wiederum (noch einmal), ein zweites Mal, zu ihm: „Simon, [Sohn] von Johannes, liebst du mich?“Er entgegnete (sagte) {zu ihm}: „Ja, Herr, du weißt, dass ich dich lieb habe.“[Jesus] erwiderte (sagte) {zu ihm}: „Hüte meine Schafe!“');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 21, 17, 'Er sagte zum dritten Mal: „Simon, [Sohn] von Johannes, hast du mich lieb?“Petrus wurde traurig, weil er zum dritten Mal zu ihm gesagt hatte: „Hast du mich lieb?“, und er erwiderte (sagte) {zu ihm}: „Herr, du weißt alles, du weißt (erkennst), dass ich dich lieb habe.“Jesus entgegnete (sagte) {zu ihm}: „Füttere (Weide) meine Schafe!');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 21, 18, 'Wahrlich, wahrlich (Amen, amen), ich sage dir: Als du jünger warst, konntest du dich selbst anziehen (einen Gürtel anlegen) und bist gegangen, wohin du wolltest. Doch wenn du alt bist, wirst du deine Hände ausstrecken, und jemand anderes wird dich anziehen (dir einen Gürtel anlegen) und dich bringen (tragen) wohin du nicht [gehen] willst.“');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 21, 19, 'Das sagte er {aber}, um anzudeuten, [mit] welcher Todesart er Gott verherrlichen (ehren) würde. Und nachdem er das gesagt hatte, sagte er: „Folge mir (folge mir nach)!“');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 21, 20, 'Als er sich umwandte, sah Petrus, dass der Jünger, den Jesus liebte, [ihnen] folgte (hinter [ihnen] lief/war), derjenige, der auch beim Abendessen an seiner Brust gelegen (gesessen) und gesagt hatte: „Herr, wer ist dein Verräter?“');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 21, 21, 'Als Petrus also diesen Jünger sah, fragte (sagte zu) er Jesus: „Herr, und was [ist mit] ihm?“');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 21, 22, 'Jesus entgegnete (sagte) {zu ihm}: „Wenn ich will, dass er bleibt, bis ich komme, was [geht] dich [das] an (was [hat das] mit dir [zu tun])? Du folge mir nach (folge mir)!“');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 21, 23, 'Diese Äußerung (Satz, Aussage, Wort) verbreitete sich (erreichte) im Folgenden (dann) unter (zu) den Jüngern: dass der erwähnte (jener) Jünger nicht sterben würde – aber Jesus hatte nicht zu [Petrus] gesagt, dass er nicht sterben würde, sondern: „Wenn ich will, dass er bleibt, bis ich komme, was [geht] dich [das] an (was [hat das] mit dir [zu tun])?“');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 21, 24, 'Dies ist der Jünger, der diese [Ereignisse] bezeugt und der sie aufgeschrieben hat, und wir wissen, dass sein Zeugenbericht wahr ist.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 21, 25, 'Es gibt aber noch vieles mehr, das Jesus getan hat, [und] wenn es [alles] im Detail (einzeln, ausführlich) aufgeschrieben würde, [dann] könnte, [so] meine ich, selbst die Welt die zu schreibenden Bücher nicht fassen.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 1, 1, 'Das erste Buch {zwar} habe ich (gemacht =) verfasst von allem, (o) lieber Theophilos, was Jesus {begann} tat und lehrte,');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 1, 2, 'bis zu dem Tag, als er entrückt (in die Höhe genommen, aufgenommen) wurde, nachdem er den Aposteln, die er ausgewählt hatte, durch den heiligen Geist Anweisungen gab (befahl).');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 1, 3, 'Ihnen erwies er sich {auch} als lebendig (Lebender) nach seinem Sterben durch viele Beweise. Während vierzig Tagen erschien er ihnen und sprach zu ihnen über das (König) Reich Gottes.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 1, 4, 'Und während (als) er mit ihnen (zusammensaß) zusammen aß, befahl er ihnen, nicht von Jerusalem fortzugehen, sondern die Verheißung des Vaters zu erwarten, „die ihr von mir gehört habt.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 1, 5, 'Denn Johannes hat {zwar} mit Wasser getauft, ihr aber werdet mit heiligem Geist getauft werden (nicht lange nach diesen Tagen =) in wenigen Tagen“.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 1, 6, 'Die {zwar} nun zusammengekommen waren, fragten ihn {und sprachen}: „Herr, wirst du (zu dieser Zeit =) jetzt die Königsherrschaft für Israel wiederherstellen?“');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 1, 7, 'Er aber sprach zu ihnen: „Euch ist nicht [gegeben], die Zeiträume oder Zeitpunkte zu kennen, die der Vater in seiner (Voll) Macht festgelegt hat,');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 1, 8, 'aber (sondern) ihr sollt (werdet) die Kraft (Macht) des heiligen Geistes empfangen, der über euch kommen wird, und ihr sollt (werdet) meine Zeugen sein sowohl in Jerusalem als auch in ganz Judäa und Samarien und bis zum fernsten Land (Ende der Erde) “.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 1, 9, 'Und nachdem er dies gesagt hatte, sahen sie, wie (dass) er aufgehoben wurde und eine Wolke ihn vor ihren Augen verbarg.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 1, 10, 'Und während sie gespannt in den Himmel blickten, wohin er gegangen war, da, (siehe =) plötzlich, standen zwei Männer bei ihnen in weißer Kleidung (weißen Gewändern),');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 1, 11, 'die {auch} sprachen: „Ihr Galiläer, was steht ihr da und schaut zum Himmel? Dieser Jesus, der von euch in den Himmel aufgenommen wurde, wird so [wieder] kommen, (auf welche Weise =) wie ihr ihn in den Himmel gehen saht“.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 1, 12, 'Dann kehrten sie nach Jerusalem zurück vom Berg, der Ölberg genannt wird, der ist nahe bei Jerusalem, einen Sabbatweg.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 1, 13, 'Und als sie hineinkamen, stiegen sie zum Obergemach hinauf, wo sie sich gewöhnlich aufhielten, Petrus {und}, Johannes {und}, Jakobus und Andreas, Philippus und Thomas, Bartholomäus und Matthäus, Jakobus Alphaios, Simon, der Zelot (Eiferer) und Judas, [der Sohn] des Jakobus.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 1, 14, 'Diese alle blieben beharrlich beim Gebet mit den Frauen und Maria, der Mutter Jesu, und seinen Brüdern.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 1, 15, 'Und in jenen Tagen stellte sich Petrus in die Mitte der Brüder [und] sprach – es war {auch} die Menge der Namen (Personen) [in der] Gemeinschaft (?, beisammen) ungefähr 120 –:');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 1, 16, 'Liebe Brüder, es musste die Schrift erfüllt werden, die der Heilige Geist vorhersagte (im voraus sagte) durch den Mund Davids über Judas, der zum Führer der Häscher (Greifer) Jesu wurde,');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 1, 17, 'denn er gehörte zu uns und empfing den Lohn dieses Dienstes.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 1, 18, 'Dieser nämlich kaufte einen Acker vom (Lohn der Ungerechtigkeit =) ungerechten Lohn, und als er vornüber stürzte, zerbarst er krachend in der (Leibes) Mitte, und seine Eingeweide quollen heraus (ergossen sich).');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 1, 19, '{Und} das wurde allen Bewohnern Jerusalems bekannt, sodass jener Acker in ihrer eigenen Sprache „Akeldamach“genannt wird, das bedeutet Blutacker.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 1, 20, 'Denn es steht im Psalmbuch {geschrieben}: „Sein Gehöft soll wüst werden und (es soll keiner sein, der in ihm wohnt =) keiner mehr in ihm wohnen“, und: „sein Aufsichtsamt soll ein anderer empfangen“.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 1, 21, 'Es muss nun von allen den Männern, die mit uns gegangen sind in all der Zeit, in der ausging und einging bei uns der Herr Jesus,');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 1, 22, 'angefangen von der Taufe des Johannes bis zu dem Tag als er von uns weg aufgenommen wurde, einer von diesen (muss) Zeuge seiner Auferstehung mit uns werden.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 1, 23, 'Und sie stellen zwei, Joseph der Barnabas genannte, der den Beinamen Justus hat, und Matthias.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 1, 24, 'Und nachdem sie gebetet hatten, sprachen sie: Du Herr, der Herzenskenner aller, zeige von diesen zweien einen, den du ausgewählt hast.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 1, 25, 'damit er in Empfang nimmt das Amt dieses Dienstes und das Apostelamt von dem Judas zur Seite getreten ist um zu seinem eigenen Ort zu gehen.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 1, 26, 'Und sie gaben ihnen Lose und das Los fiel auf Matthias und wurde inmitten der elf Apostel hinzugestellt.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 1, 'Und als sich der Tag des Wochenfests erfüllte (zu Ende ging), waren alle zusammen [als] Gemeinschaft (?, beisammen).');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 2, 'Und plötzlich kam (entstand; ereignete sich) vom Himmel her ein Geräusch (Lärm) wie das Wehen eines heftigen Windes und füllte das ganze Haus, in dem sie [gerade] saßen');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 3, 'und ihnen erschienen sich verteilende (teilende) Zungen wie [von] Feuer und sie setzten sich auf einen jeden von ihnen');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 4, 'und alle wurden mit heiligen Geist erfüllt und begannen, [so] [in] anderen Zungen zu sprechen, wie der Geist ihnen zu prophezeien (äußern) eingab.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 5, 'Es hielten sich [gerade] auf (wohnten) {aber} Juden in Jerusalem, fromme Männer aus allen Völkern unter dem Himmel,');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 6, '[und] als {aber} dieses Getön entstand, kam die Menge zusammengelaufen und war bestürzt (verstört, verwirrt), denn ein jeder hörte sie in der eigenen Sprache sprechen.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 7, 'Sie (Alle) waren {aber} außer sich (fassungslos, erstaunt) und wunderten (erstaunten) sich, [indem sie] sagten: „Siehe! Sind nicht alle diese Sprechenden Galiläer?');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 8, 'Und wie hören wir [sie dann] jeder in unserer eigenen Sprache, in der wir geboren wurden?');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 9, '[Wir sind ja] Parther und Meder und Elamiter und die Bewohner von Mesopotamien, vom Judäischen und auch Kappadozien, von Pontus und Asien,');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 10, 'von Phrygien und auch Pamphylien, von Ägypten und den Gebieten Lybiens um Zyrene, und die sich [hier] aufhaltenden Römer,');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 11, 'Juden und auch Proselyten, Kreter und Araber - wir hören sie in unseren Zungen die Großtaten Gottes rühmen!“');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 12, 'Alle waren {aber} außer sich (fassungslos, erstaunt) und ratlos, [indem] sie zueinander sagten: „Was mag dies sein!?“');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 13, 'Andere aber sagten spottend: „Mit Traubensaft (Wein?) sind sie voll (angefüllt)!“');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 14, 'Petrus jedoch stellte sich mit den [anderen] Elf hin, erhob seine Stimme und prophezeite (äußerte) ihnen: „ [Liebe] Judäer (Juden) und all [ihr] euch in Jerusalem Aufhaltenden (all [ihr] Wohnenden)! Dies sei euch bekannt, {und} vernehmt meine Worte!');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 15, 'Diese sind nämlich nicht, wie ihr annehmt, betrunken – es ist ja (nämlich) [erst] die dritte Stunde des Tages –,');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 16, 'sondern: Dies ist das durch den Propheten Joel Vorhergesagte:');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 17, '»»Und es wird sein in den Letzten Tagen:« – sagt Gott – »Ich werde ausgießen [etwas] von meinem Geist auf alles Fleisch,Und prophezeien werden eure Söhne und eure Töchter Und eure jungen [Menschen] werden Visionen sehenUnd eure alten [Menschen] werden durch Träume träumen.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 18, 'Und auch (selbst) auf meine Sklaven und auf meine Sklavinnen werde ich in jenen Tagen [etwas] von meinem Geist ausgießenUnd sie werden prophezeien.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 19, 'Und ich werde darbieten Wunder im Himmel drobenUnd Zeichen auf der Erde drunten:Blut und Feuer und Rauchqualm.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 20, 'Die Sonne wird verwandelt werden zu FinsternisUnd der Mond zu BlutVor dem Kommen des Tags des Herrn, des großen und sichtbaren (prachtvollen).');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 21, '{Und es wird sein:} Jeder, der den Namen des Herrn anruft, wird gerettet werden.««');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 22, '[Liebe] Israeliten, hört diese Worte: Jesus, den Nazoräer, einen von Gott für euch beglaubigten (bestellten) Mann durch [die] Machttaten und Wunder und Zeichen, welche Gott durch ihn in eurer Mitte vollbracht hat – wie ihr [ja selbst] wisst –');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 23, 'diesen [euch] – wegen dem beschlossenen (festgesetzten) Plan und dem Vorauswissen Gottes! – Ausgelieferten habt ihr getötet, indem [ihr ihn] durch Hände Gesetzloser [ans Kreuz] geschlagen [habt];');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 24, '[ihn,] den Gott auferstehen ließ, indem er die Geburtswehen (Fesseln?) des Todes löste, weil es nicht möglich war, dass er unter ihm gehalten wurde.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 25, 'Denn David sagt über ihn: »Ich hatte den Herrn vor mir vor Augen durch alle [Zeit],Weil er zu meiner Rechten ist, damit ich nicht wanken werde.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 26, 'Darum freute sich mein HerzUnd jubelte meine ZungeUnd noch dazu wird mein Fleisch sich niederlassen (zelten) aufgrund [meiner] Zuversicht (Hoffnung),');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 27, 'Weil du meine Seele nicht dem Hades überlassen (im Hades zurücklassen) wirstUnd nicht zulassen wirst, dass dein Heiliger Verwesung erfährt.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 28, 'Du hast mir die Wege des Lebens kundgetan,Du wirst mich erfüllen mit Freude vor deinem Gesicht.«');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 29, '[Liebe] Brüder, man kann mit Freimut (Offenheit) zu euch über den Patriarchen David sprechen – [nämlich darüber,] dass er sowohl starb als auch begraben wurde, und [dass] seine Grabstätte bis zu diesem Tage bei uns ist.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 30, 'Weil er nun ein Prophet war und wusste, dass Gott ihm mit einem Eid geschworen hatte, [jemanden] aus der Frucht seiner Lende auf seinen Thron zu setzen,');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 31, 'sprach er im Vorhinein über die Auferstehung des Christus – [nämlich,] dass er weder dem Hades überlassen werden würde (im Hades zurückgelassen werden würde) noch sein Fleisch Verwesung erfahren würde.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 32, 'Diesen Jesus hat Gott auferstehen lassen, wofür wir alle Zeugen sind.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 33, 'Nachdem er nun zur Rechten (durch die rechte Hand) Gottes erhöht worden war und auch den verheißenen Heiligen Geist (die Verheißung des Heiligen Geistes) vom Vater empfangen hatte, goß er diesen aus, was (den) ihr sowohl seht als auch hört.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 34, 'Denn nicht David ist in den Himmel hinaufgestiegen; stattdessen sagt er selbst: »Es sagte der Herr zu meinem Herrn: »Sitze (Setze dich) zu meiner Rechten,');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 35, 'bis ich deine Feinde zum Schemel für deine Füße mache!««');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 36, 'Mit Sicherheit sei nun dem ganzen Haus Israel bekannt, dass Gott ihn sowohl zum Herrn als auch zum Christus gemacht hat – diesen Jesus, den ihr gekreuzigt habt!');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 37, 'Als sie {aber} [dies] hörten, wurden sie im Herz durchbohrt. Sie sagten auch zu Petrus und den übrigen Aposteln: »Was sollen wir tun, [liebe] Brüder?«');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 38, 'Petrus {aber} [antwortete] ihnen: »Denkt um!«, {sagt[e] er,} »und es lasse sich taufen ein jeder von euch auf den Namen Jesu Christi zur Vergebung der Sünden von euch! Und ihr werdet empfangen das Geschenk, [das] der Heilige Geist [ist].');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 39, '\'\'Euch\'\' nämlich gilt die Verheißung und euren Kindern, und allen, die fern [sind], wie viele auch hinzurufen mag der Herr, unser Gott.«');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 40, 'Auch mit anderen weiteren Worten legte er Zeugnis ab und mahnte sie {indem er sagte}: »Lasst euch retten aus diesem verkehrten Geschlecht!«');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 41, 'Diejenigen nun, die seine Rede annahmen, ließen sich taufen und so wurden an jenem Tag etwa 3000 Seelen hinzugefügt.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 42, 'Sie hielten {aber} [beständig sehr] fest an der Lehre der Apostel und an der Gemeinschaft, (dem gemeinschaftlichen Brotbrechen) dem Brotbrechen und den Gebeten.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 43, '[Und] es war (da entstand) {aber} Ehrfurcht (Furcht) in allen Seelen; es geschahen sowohl viele Wunder als auch Zeichen durch die Apostel.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 44, '{Aber} alle Glaubenden {waren} [als] Gemeinschaft (?, zusammen) {und} sie hatten alles gemeinsam:');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 45, '{Und} [immer wieder] verkauften sie die Habe und die Besitztümer und verteilten sie an alle, wie jemand Bedarf hatte.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 46, 'Indem sie sich täglich einmütig (einträchtig) im Tempel aufhielten und im Haus Brot brachen, nahmen sie Speise in Jubel und Schlichtheit des Herzens (jubelnd und mit lauterem Herzen) zu sich;');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 47, 'sie lobten Gott und hatten Ansehen beim (waren gefällig dem) ganzen Volk. [Und] der Herr {aber} fügte täglich Gerettete hinzu zur Gemeinschaft (?, zusammen?). “');
