INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 1, '');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 2, '');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 3, '');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 4, '');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 5, '');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 6, '');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 7, '');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 8, 'Da sprach Petrus, erfüllt mit heiligem Geist, zu ihnen: Oberste des Volkes und Älteste!');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 9, 'Wenn wir heute über die Wohltat an einem kranken Menschen geprüft werden, durch welches er gerettet worden ist,');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 10, 'so sei euch allen und dem ganzen Volk Israel bekannt: Im Namen Jesu Christi, des Nazoräers, den ihr gekreuzigt habt, den Gott auferweckt hat aus den Toten - in diesem Namen steht er vor euch gesund.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 11, 'Das ist der Stein, der, von euch, den Bauleuten, verachtet, zum Eckstein geworden ist.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 12, 'Und es ist in gar keinem anderen das Heil, denn auch kein anderer Name ist unter dem Himmel, gegeben den Menschen, in den wir gerettet werden müssen.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 13, 'Als sie aber die Kühnheit des Petrus und Johannes sahen und bemerkten, dass es ungelehrte Menschen seien und ungebildet, verwunderten sie sich und sie erkannten von ihnen, dass sie mit Jesus gewesen waren.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 14, 'Und als sie den Menschen, der geheilt worden war, bei ihnen stehen sahen, hatten sie nichts dagegen zu sagen.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 15, '');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 16, '');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 17, '');
