INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 28, '');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 29, '');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 30, '');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 31, '');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 32, 'Die Menge der Glaubenden aber was ein Herz und eine Seele und nicht einer sagte, etwas von dem Verhandenen sei sein Eigen, sondern es war ihnen alles gemeinsam.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 33, 'Und mit großer Kraft legten die Apostel das Zeugnis der Auferstehung des Herrn Jesus ab und große Gnade war mit ihnen allen.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 34, 'Es war nämlich nicht einer bedürftig bei ihnen. Denn es befanden sich soviele Grund- oder Hausbesitzer unter ihnen. Nahcdem sie verkauft hatten, brachten sie die Verkaufssumme des Verkauften.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 35, '');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 36, '');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 37, '');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 1, 'Da war ein Mann namens Hananias und seine Frau Saphira. Er verkaufte ein Grundstück');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 2, 'und behielt etwas von dem Erlös für sich und seine Frau wusste davon. Dann nahm er den [übrigen] Teil und gab ihn den Aposteln.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 3, 'Da sagte Petrus: „Hananias, warum hat der Satan dein Herz erfüllt, den Heiligen Geist zu belügen und einen Teil von dem Erlös des Feldes für dich zu behalten?');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 4, 'Ist es nicht so, dass es dir gehören würde, wenn du es nicht verkauft hättest? Und [selbst] als du es verkauft hattest, stand [das Geld] nicht dir zur Verfügung? Wieso hast du dir diese Sache {in deinem Herzen} vorgenommen? Du hast nicht Menschen belogen, sondern Gott!“');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 5, 'Als Hananias das hörte, fiel er um und starb. Alle, die davon hörten, hatten große Angst.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 6, '');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 7, '');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 8, '');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 9, '');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 10, '');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 11, '');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 12, 'Durch aber die Hände der Apostel geschahen viele Zeichen und Wunder unter (in) dem Volk. Und einmütig waren alle [zusammen (versammelt)] in der Säulenhalle (Stoa) Salomos.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 13, 'Von den übrigen aber wagte keiner, sich ihnen anzuschließen, aber das Volk pries sie.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 14, 'Darüber hinaus (Mehr noch) aber (: es) wurden Gläubige dem Herrn hinzugefügt, eine Menge von Männern und Frauen,');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 15, 'so dass sie auch auf (in) die Plätze (Straßen) die Kranken hinaustrugen und sie auf Betten und Bahren (Pritschen) legten, damit, wenn Petrus kommt, wenigstens (und wenn auch [nur]) der Schatten einen von ihnen beschatte.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 16, 'Es kam aber auch die Menge der umliegenden Städte Jerusalems (der um Jerusalem liegenden Städte) und brachte Kranke und von unreinen Geistern Bedrängte, welche alle geheilt wurden.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 17, '');
