INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 6, 7, '');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 6, 8, 'Stephanus aber, angefüllt mit Gnade und Kraft, tat große Wunder und Zeichen im volk.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 6, 9, 'Es standen aber einige auf aus der sogenannten der Libertiner und Kyrener und Alexandiner und aus Kilikien und Asien, um mit Stephanus zu streiten (oder Beiordnung: und stritten mit Stephanus)');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 6, 10, 'Aber sie konnten der Weisheit und dem Geist, mit dem er sprach, nicht widerstehen.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 6, 11, 'Dann stifteten sie Männer an zur Aussage: Wir haben gehört, wie du gesagt hast blasphemische (gotteslästerliche/lügenhafte) Worte gegen Mose und Gott.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 6, 12, 'Und sie hetzten das Volk auf und die Ältesten und die Schriftgelehrten und als sie hinzugetreten waren, packten sie ihn und führten in vor den Hohen Rat (Synhedrion).');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 6, 13, 'Und sie stellten falsche Zeugen auf, die sagen: Dieser Mensch hört nicht auf, Worte zu sagen gegen diesen heiligen Ort und das Gesetz.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 6, 14, 'Wir haben nämlich gehört, wie er sagte: Dieser Jesus von Nazareth wir diesen Ort zerstören und verändern die Bräuche, die uns Mose gegeben hat.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 6, 15, 'Und als alle, die im Hohen rat (Synhedrion) saßen, ihn anschauten, sahen sie sein Gesicht wie das Gesicht eines Engels.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 1, '');
