INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 25, '');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 26, 'Der (ein) Engel des Herrn aber sprach zu Philippus {folgendermaßen}: „Steh auf und geh nach Süden auf dem Weg, der herabkommt von Jerusalem nach Gaza; er ist menschenleer.“');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 27, 'Und er stand auf und ging [los]. {Und} sieh da!, ein äthiopischer Mann, ein Eunuch, Hofbeamter (fürstlicher Beamter) der Kandake, der Königin der Äthiopier, der über alle ihre Schätze [gesetzt] war, der nach Jerusalem gekommen war, um anzubeten,');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 28, '{und} war auf dem Rückweg und saß auf seinem Wagen und las den Propheten Jesaja.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 29, 'Der [Heilige] Geist aber sprach zu Philippus: geh hin (trete hinzu) und hänge dich an (folge dicht) diesen Wagen.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 30, 'Als Philippus {aber} hingegangen war, hörte er, wie er (dass er) den Propheten Jesaja las und sprach: „Verstehst du denn auch, was du liest?“');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 31, 'Der aber sprach (antwortete): Wie soll ich [dazu] in der Lage sein, wenn mich keiner anleitet? Und er bat Philippus, aufzusteigen und sich zu ihm zu setzen.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 32, 'Der Abschnitt der Schrift, den er las, war dieser: „Wie ein Schaf wurde er zur Schlachtung gebracht (geführt), und so, wie ein Lamm vor dem Scherer stumm [ist] (verstummt), so öffnet er seinen Mund nicht.“');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 33, 'In seiner Erniedrigung wurde das Urteil gegen ihn aufgehoben. Wer von seinem Geschlecht wird davon erzählen? Denn sein Leben ist von der Erde weggenommen.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 34, 'Der Eunuch aber antwortete Philippus {und sprach}: Ich bitte dich, von wem sagt der Prophet das? Von ihm selbst, oder von einem anderen?');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 35, 'Philippus aber öffnete seinen Mund und begann von dieser Schrift [stelle] aus, ihm Jesus zu evangelisieren (verkündigen).');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 36, 'Wie sie aber den Weg entlangfuhren (weiterzogen), kamen sie an ein Wasser, und der Eunuch sprach: Sieh mal, Wasser! Was verbietet, dass du mich taufst?');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 37, '');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 38, 'Und er befahl den Wagen zu stoppen (anzuhalten), und beide stiegen ins Wasser, Philippus und {auch} der Eunuch, und er taufte ihn.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 39, 'Als er aber aus dem Wasser stieg (auftauchte), entführte (entrückte) der Geist des Herrn den Philippus, und der Eunuch sah ihn nicht mehr. Er reiste (zog) aber seinen Weg freudig.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 40, 'Philippus aber wurde in Asdod gefunden. Und er zog durch alle Städte und evangelisierte (verkündigte), bis er nach Cäsarea kam.');
