INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 1, 'Es geschah aber, während Apollos in Korinth war, dass Paulus die höher gelegenden Gegenden durchziehend [herab] kam nach Ephesus und einige Schüler (Jünger) fand.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 2, 'Und er sprach zu ihnen: Habt ihr heiligen Geist empfangen, als ihr gläubig wurdet? Die aber zu ihm: Wenn wir doch aber nicht gehört haben, dass es heiligen Geist gibt?');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 3, 'Und er sprach: Auf was wurdet ihr denn getauft? Die aber sprachen: Auf die Taufe des Johannes.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 4, 'Paulus aber sprach: Johannes taufte eine Taufe der Buße (Umkehr) dem Volk sagend, dass sie an den nach ihm Kommenden glauben sollten, dieses ist an Jesus.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 5, 'Hörend aber (Als sie es aber aber hörten) wurden sie getauft auf den Namen des Herren Jesu.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 6, 'Und als ihnen Paulus die Hände auflegte, kam der heilige Geist auf sie und sie begannen zu reden in Zungen und prophetisch zu reden.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 7, 'Es waren aber alle Männer ungefähr zwölf.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 8, '');
