INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 23, '');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 24, '');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 25, 'Denn ich möchte nicht, Brüder, dass euch dieses Geheimnis unbekannt ist, damit ihr euch nicht selbst für klug haltet, nämlich dass Israel zu einem Teil Verstockung widerfahren ist, bis die Fülle der Völker eingegangen ist.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 26, 'Und so wird ganz Israel gerettet werden, wie geschrieben steht: Aus Zion wird kommen der Retter, der die Gottlosigkeiten von Jakob abwenden wird.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 27, 'Und dies ist für sie der Bund von mir, wenn ich ihre Sünden wegnehme.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 28, 'Was das Evangelium betrifft, sind sie zwar Feinde um euretwillen, aber was die Erwählung betrifft, sind sie Geliebte um der Väter willen.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 29, 'Denn unwiderruflich sind die Gnadengaben und die Berufung Gottes.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 30, 'Denn wie ihr zuvor Gott ungehorsam wart, jetzt aber Erbarmen gefunden habt infolge ihres Ungehorsams,');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 31, 'so sind sie jetzt infolge des Erbarmens, das ihr gefunden habt, ungehorsam geworden, damit jetzt auch sie Erbarmen finden.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 32, 'denn Gott hat alle eingeschlossen in den Ungehorsam, damit er sich aller erbarme.');
