INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 12, 21, 'Nicht lasse dich besiegen (unterwerfen, bezwingen, überwinden) von dem Bösen (Schlechten), sondern besiege (unterwerfe, bezwinge, überwinde) in dem (durch das, mit dem) Guten das Böse (Schlechte).');
