INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 14, 7, 'Denn niemand von uns lebt für sich selbst und niemand stirbt für sich selbst.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 14, 8, 'Denn sei es, dass wir leben, leben wir für den Herrn, sei es, dass wir sterben, sterben wir für den HERRN. Sei es, dass wir leben, sei es, dass wir sterben, wir gehören dem HERRN.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 14, 9, 'Denn dazu ist Christus gestorben und wieder lebendig geworden, damit er sowohl über die Toten, wie über die Lebenden herrscht.');
