INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 21, '');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 22, 'Darum (deshalb) bin ich auch viele Male (oft, häufig) (daran) gehindert worden, zu euch zu kommen;');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 23, 'Da ich nun aber keinen Wirkungsraum mehr in dieser Gegend (Landstrich) habe [und] Sehnsucht (Verlangen) habe zu euch zu kommen seit vielen Jahren,');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 24, 'wenn (falls) ich nach Spanien Reisen werde; Denn ich hoffe, wenn ich hindurchgehe (hindurchreise, auf der Durchreise bin) euch zu sehen und von euch zur (Weiter-) Reise ausgesendet (ausgestattet, ge- bzw. begleitet) zu werden, nachdem (wenn) ich mich an euch zuerst einigermaßen erfreut (gestärkt, genossen) habe.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 25, 'Nun aber reise ich nach Jerusalem, um den Heiligen zu dienen (helfen, unterstützen).');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 26, 'Denn es haben Wohlgefallen (beschlossen) Mazedonien und Achaia eine gewisse (bestimmte) Gemeinschaft (Spende, Beitrag) durchzuführen (zu leisten) für die Armen der (unter den) Heiligen in Jerusalem.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 27, 'Denn sie haben j auch beschlossen, euer Schuldner zu sein (in eurer Schuld zu stehen): denn wenn die Völker an eurem Geistlichen Anteil haben (erhalten, nehmen), sind sie auch schuldig in dem Fleischlichen euch zu dienen.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 28, 'Wenn ich dies nun zum Abschluss bringe (beende) und ihnen diese Frucht versiegelt habe werde ich über euch nach Spanien gehen (reisen).');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 29, 'Ich weiß aber, dass wenn ich zu euch komme ich mit der Fülle des Segens Christi kommen werde.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 30, 'Ich bitte (ermahne, ermutige, bestärke, fordere auf) euch aber, [Brüder], durch unseren Herrn Jesus Christus und durch die Liebe des Geistes gemeinsam mit mir zu kämpfen in eure Gebet für mich (mit mir) vor Gott,');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 31, 'dass ich erretet (bewahrt) werde vor den [Nachstellungen der] Ungehorsamen in Judäa und [dass] mein Dienst in Jerusalem von den Heiligen gut aufgenommen wird,');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 32, 'dass ich mit Freude zu euch komme wenn Gott es will und mich bei (mit) euch ausruhen kann.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 33, 'Sei aber der Gott des Friedens mit euch allen, Amen.');
