INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 6, 3, '');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 6, 4, 'Wenn ihr nun Fälle des alltäglichen Lebens zu entscheiden habt, dann setzt die Übergangenen in der Gemeinde ein, diese und nicht die Ungläubigen!');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 6, 5, '');
