INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 6, 20, '');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 1, 'Zu dem, was ihr schriebt, es ist gut für einen Mann, eine Frau nicht zu berühren');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 2, 'Um der Unzucht willen soll jeder [Mann] seine eigene Frau haben und jede [Frau] ihren eigenen Mann.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 3, 'Der Mann soll seine Pflicht der Frau gegenüber erfüllen, ebenso (in gleicher Weise) die Frau dem Mann gegenüber.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 4, 'Die Frau verfügt nicht (hat keine Verfügungsgewalt) über ihren {eigenen} Körper, sondern der Mann, ebenso (in gleicher Weise) verfügt der Mann nicht (hat keine Verfügungsgewalt) über seinen {eigenen} Körper, sondern die Frau.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 5, 'Entzieht euch nicht einander, außer in gegenseitigem Einvernehmen (nach Übereinkunft) für einen begrenzten Zeitraum (für den gegenwärtigen Augenblick), um euch dem Gebet zu widmen und dann wieder zusammen zu sein, damit euch der Satan nicht versucht durch eure Geilheit (Zügellosigkeit).');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 6, 'Dies aber sage ich als Zugeständnis, nicht als Befehl.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 7, 'Ich wollte {aber}, dass alle Menschen (Männer?) wie ich wären; aber jeder hat seine eigene Gabe von Gott, der eine so, der andere so.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 8, 'Den Unverheirateten und den Witwen sage ich, dass es gut wäre, wenn sie blieben wie ich.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 9, 'Wenn sie aber nicht enthaltsam sein können, sollen sie heiraten, denn es ist besser, zu heiraten als zu brennen.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 10, 'Den Verheirateten aber befehle {ich,} nicht ich, sondern der Herr, dass eine Frau sich vom Mann nicht scheiden soll');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 11, '- falls sie aber geschieden ist, soll sie unverheiratet bleiben oder sich mit dem Mann aussöhnen -, und der Mann soll die Frau nicht verstoßen');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 12, 'Den übrigen aber sage ich, nicht der Herr: Wenn ein Bruder eine nichtgläubige Frau hat, und (diese) sie willigt ein, mit ihm (ehelich) zusammenzuleben, soll er sie nicht verstoßen.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 13, 'Und die Frau, wenn sie einen nichtgläubigen Mann hat, und (dieser) er willigt ein, mit ihr (ehelich) zusammenzuleben, soll sie ihn nicht verstoßen.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 14, 'Denn der nichtgläubige Mann wird durch die Frau geheiligt, und die nichtgläubige Frau durch den Bruder; denn sonst sind demnach ihre Kinder unrein, jetzt aber sind sie heilig.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 15, 'Wenn aber der Nichtgläubige sich scheiden will, soll er sich scheiden. Der Bruder oder die Schwester ist in diesem Fall nicht [dem Eheversprechen] unterworfen. Gott hat euch zum (im) Frieden berufen.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 16, 'Denn {was} weißt du, Frau, ob du den Mann retten wirst? Oder {was} weißt du, Mann, ob du die Frau retten wirst?');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 17, 'Doch (Sondern) jeder soll so leben (wandeln), wie der Herr es ihm zugeteilt, jeder, wie der Herr ihn berufen hat. {Und} so ordne ich es in allen Gemeinden an.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 18, 'Wer als Beschnittener berufen wurde, soll nicht die Vorhaut überziehen; wer als Unbeschnittener berufen wurde, soll sich nicht beschneiden lassen.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 19, 'Die Beschneidung ist nichts und die Unbeschnittenheit ist nichts, sondern die Beachtung der Gebote Gottes.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 20, 'Jeder soll in der Berufung (dem Beruf) bleiben, in der er berufen wurde (in dem ihn der Ruf Gottes traf).');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 21, 'Du wurdest als Sklave berufen; das soll dich nicht kümmern. Aber wenn du auch Freiheit erlangen kannst, gebrauche sie (die Sklaverei? die Freiheit?) um so mehr.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 22, 'Denn der Sklave, der durch den (im) Herrn berufen wurde, ist ein Freigelassener des Herrn, wie (in gleicher Weise) der Freie, der berufen wurde, ein Sklave Christi ist.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 23, 'Ihr seid bar bezahlt worden (wurdet gegen Barzahlung erworben); werdet nicht Sklaven von Menschen.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 24, 'Jeder soll darin bleiben, Brüder, worin er von Gott berufen wurde.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 25, 'Über die Jungfrauen {aber} besitze ich kein Gebot des Herrn. Ich bin aber der Meinung, dass ich ein Vertrauensmann bin, weil ich vom Herrn begnadigt wurde (Erbarmen fand).');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 26, 'Ich meine nun, dies sei gut (dass dies gut sei) wegen der bevorstehenden Not, dass es für den Menschen gut ist, wenn er bleibt, wie er ist.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 27, 'Wurde dir eine Frau gegeben, suche nicht die Scheidung (Trennung); hast du dich von einer Frau getrennt (frei gemacht), suche keine Frau.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 28, 'Wenn du aber heiratest, sündigst du nicht, und wenn die Jungfrau heiratet, sündigt sie nicht. Leibliche Bedrängnis werden diese aber (haben =) erleben, ich aber schone euch (= würde euch gern schonen?).');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 29, 'Dies aber sage ich, Brüder, die Zeit ist zusammengedrängt (beschränkt). Hinfort (zukünftig) sollen die Frauen haben sein, als hätten sie keine,');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 30, 'und die weinen, als weinten sie nicht, und die sich freuen, als freuten sie sich nicht, und die kaufen, als besäßen sie nicht,');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 31, 'und die die Welt gebrauchen, als missbrauchten sie sie nicht, denn diese Welt selbst (die Gestalt, das Wesen dieser Welt) vergeht.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 32, 'Ich möchte aber, dass ihr sorglos (sorgenfrei) seid. Der Unverheiratete sorgt für (trägt Sorge für) die Angelegenheiten des Herrn, wie er dem Herrn gefallen (zu Gefallen sein) kann.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 33, 'Der Verheiratete aber sorgt sich um (trägt Sorge um) die Welt, wie er der Frau gefallen (zu Gefallen sein) kann,');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 34, 'und ist in sich gespalten. Und die Frau, die Unverheiratete und die Jungfrau, sorgt für (trägt Sorge für) die Angelegenheiten des Herrn, damit sie heilig ist sowohl körperlich als auch geistig (geistlich). Aber die Verheiratete sorgt sich um (trägt Sorge um) die Welt, wie sie dem Mann gefallen (zu Gefallen sein) kann.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 35, 'Dies aber sage ich zu eurem eigenen Vorteil (Nutzen), nicht, um euch eine Schlinge überzuwerfen, sondern damit ihr ungestört (nicht abgelenkt) anständig und beharrlich im Herrn [seid].');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 36, 'Wenn aber einer glaubt, sich unanständig gegenüber seiner Jungfrau zu benehmen (sich seiner Jungfrau gegenüber schämen zu müssen), wenn er überreif ist und so geschehen muss, was er tun will, sündigt er nicht; sie sollen heiraten.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 37, 'Wer aber in seinem Herz fest steht, ohne Zwang, aber Macht hat über seinen Willen und dies in seinem Herzen beschließt, seine Jungfrau zu bewahren (= unberührt zu lassen), tut recht [daran].');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 38, 'So tut auch recht, wer seine Jungfrau heiratet, aber wer nicht heiratet, tut Besseres.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 39, 'Eine Frau ist (gegeben =) gebunden, solange ihr Mann lebt; wenn aber der Mann entschlafen ist, ist sie frei, zu heiraten, wen sie will, allein [dass es] im Herrn [geschieht].');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 40, 'Glücklicher (seliger) aber ist sie, wenn sie so bleibt, meiner Meinung nach. Ich meine aber, dass auch ich den Geist Gottes habe.');
