INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 9, 13, '');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 9, 14, '');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 9, 15, '');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 9, 16, '');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 9, 17, '');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 9, 18, '');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 9, 19, 'Denn weil (obwohl) ich frei bin allen gegenüber, habe ich mich allen zum Sklaven gemacht, damit ich möglichst viele gewinne.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 9, 20, '[Das heißt:] für die Juden bin ich wie ein Jude geworden, damit ich [die] Juden gewinne; für die unter dem Gesetz [des Mose] bin ich wie einer unter dem Gesetz geworden – auch wenn ich selbst nicht unter dem Gesetz bin – damit ich die unter dem Gesetz gewinne;');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 9, 21, 'für die ohne Gesetz wie einer ohne Gesetz – auch wenn ich nicht ohne Gesetz Gottes bin, sondern [ich bin] im Gesetz Christi – damit ich die ohne Gesetz gewinne;');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 9, 22, 'für die Schwachen bin ich schwach geworden, damit ich die Schwachen gewinne; für alle [diese] bin ich alles geworden, damit ich von allen welche errette.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 9, 23, 'Alle diese Dinge tue ich um des Evangeliums willen, damit auch ich Anteil am Evangelium habe.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 9, 24, 'Wisst ihr [denn] nicht, dass zwar alle Athleten am Wettkampf teilnehmen, aber nur einer den Siegeskranz bekommt?');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 9, 25, 'Jeder aber, der kämpft, übt sich in Verzicht (Selbstbeherrschung) in allen [Lebensbereichen]. Die Athleten tun es, damit sie einen Siegeskranz bekommen, der doch vergänglich ist; wir aber für einen unvergänglichen.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 9, 26, '[Das gilt] auch für mich: Ich laufe nicht wie einer, der ziellos umherirrt, ich boxe nicht wie einer, der wild um sich haut;');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 9, 27, 'sondern ich führe einen harten Kampf gegen mich selbst und zwinge meinen Körper, mir zu gehorchen, damit ich nicht an dem, was ich anderen gepredigt habe, selbst untauglich werde (scheitere).');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 1, 'Ich will nämlich nicht, dass ihr nicht wisst (versteht), dass eure Väter alle unter der Wolke waren und alle durch das Meer zogen');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 2, 'und alle auf (in) {den} Moses (hinein) getauft wurden in der Wolke und in dem Meer');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 3, 'und alle dieselbe geistliche Nahrung aßen');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 4, 'und alle denselben geistlichen Trank tranken: Sie tranken nämlich aus einem geistlichen Felsen, der nachfolgte, der Fels aber war {der} Christus.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 5, 'Aber Gott fand nicht an (in) den meisten von ihnen Wohlgefallen, denn sie wurden in der Wüste getötet (niedergestreckt).');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 6, '');
