INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 23, 'Ich nämlich nahm in Empfang von dem Herrn, was ich auch euch übergeben (weitergeben) habe, dass der Herr Jesus in der Nacht, in der er übergeben (ausgeliefert) wurde, [das] Brot (in die Hand) nahm (ergriff),');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 24, '{und} dankte (Dank sagte) und [es (das Brot)] brach und sprach: Dies ist mein Leib (Körper), der für (zum Vorteil von) euch [ist], dies tut zur Erinnerung an mich.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 25, 'In gleicher Weise (ebenso) auch das Becherchen (Kelchlein, Trinkgefäßchen) nach dem Essen (Speisen) und sagte: Dieses Becherchen ist das neue Testament (Vertrag, Bund) in meinem Blut. Dies tut so oft ihr trinkt zur Erinnerung an mich.');
