INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 1, 'Über die der Geistgaben, Brüder, will ich euch nicht im Unwissen lassen.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 2, 'Ihr wisst, dass, als ihr Heiden wart, ihr schon zu den stummen Götzenbildern weggeführt wurdet, dass ihr schon geführt wurdet.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 3, 'Deshalb offenbare ich euch, dass niemand im Geist Gottes schwätzend sagt: „Verflucht [sei] Jesus“, und keiner ist fähig zu sagen: „Herr ist Jesus“, wenn nicht im Heiligen Geist.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 4, 'Es gibt Zuteilungen aber der Gnadengaben, der Geist aber ist derselbe;');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 5, 'Und es gibt Unterscheidungen der Diakonie, und der Herr ist derselbe;');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 6, 'Und es gibt Unterscheidungen in der Wirkung, der Gott aber ist derselbe, der wirkt alles in allen.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 7, 'Jedem ist es gegeben, die Offenbarung des Geistes zusammenzutragen.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 8, 'Denn nämlich dem einen ist durch den Geist gegeben das Wort der Weisheit, dem anderen aber das Wort der Erkenntnis gemäß demselben Geist,');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 9, 'Dem einen der Glaube in demselben Geist, dem anderen aber die Gabe der Heilung in dem einen Geist,');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 10, 'Dem anderen aber die Wirkungen der Kräfte, dem anderen aber die Prophetie, dem anderen aber die Unterscheidung der Geister, einem anderen die Sprache der Zungen, einem anderen aber die Auslegung der Zungen;');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 11, 'Alles aber wirkt der eine Geist, der zuteilt einem jeden Einzelnen, genau wie er will.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 12, '');
