INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 2, 13, '');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 2, 14, 'Aber Dank [sei] {dem} Gott, der uns zu allen Zeiten (immer) im Triumphzug herumführt (triumphieren lässt; bekannt macht) in (durch) Christus und den Duft (Geruch) seiner Kenntnis (Wissen, Erkenntnis) bekannt macht (sichtbar macht; sehen lässt; zeigt) durch uns an jedem Ort;');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 2, 15, 'denn wir sind der Wohlgeruch (liebliche Duft) Christi, [der zu] Gott [aufsteigt] unter (bei) denen, die gerettet werden und unter (bei) denen, die verloren gehen,');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 2, 16, '[für] die einen ein Geruch (Duft) vom Tod zum Tod („ [der] zum Tod [führt] “), [für] die anderen ein Geruch (Duft) vom Leben zum Leben („ [der] zum Leben [führt] “). Und wer [ist] ([wäre]) für diese [Dinge] (dafür) geeignet (zulänglich, würdig)?');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 2, 17, 'Denn wir sind nicht wie die vielen, die Geschäfte machen (Handel treiben) mit dem Wort Gottes, sondern als [Menschen] aus Lauterkeit (Aufrichtigkeit, reiner Gesinnung), {sondern} als von Gott vor Gott in Christus verkünden wir [es] (sprechen wir).');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 3, 1, '');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 3, 2, '');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 3, 3, 'Es ist offenbar gemacht (vor aller Augen sichtbar, deutlich, öffentlich, bekannt), dass ihr ein Brief Christi seid, durch unser Dienen (Dienen durch uns), geschrieben nicht [mit] Tinte sondern [mit] Geist des lebenden (lebendigen) Gottes, nicht auf (in) Tafeln aus Stein (steinerne Tafeln, Steintafeln) sondern auf (in) fleischerne Tafeln aus Herzen.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 3, 4, 'Dieses Vertrauen {aber} haben wir durch {den} Christus zu {dem} Gott.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 3, 5, 'Nicht, dass von uns selbst imstande (tüchtig, geeignet, fähig, hinreichend) sind, etwas [anderes] als [etwas] aus uns zu begreifen (anzurechnen, überlegen, anzuerkennen) sondern die Tüchtigkeit ist von (aus) {dem} Gott.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 3, 6, 'Der auch (sogar) uns geschickt (fähig, tüchtig) gemacht hat zu Dienern des neuen Bundes, nicht des Buchstabens (der Schrift, des Dokuments) sondern des Geistes, denn (nämlich) der Buchstabe (die Schrift, das Dokument) tötet, aber der Geist macht lebendig.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 3, 7, '');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 3, 8, '');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 3, 9, '');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 3, 10, '');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 3, 11, '');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 3, 12, '');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 3, 13, '');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 3, 14, '');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 3, 15, '');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 3, 16, '');
