INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 1, '');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 2, '');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 3, '');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 4, '');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 5, '');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 6, '');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 7, '');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 8, 'Ihr wart einst Finsternis, jetzt aber seid ihr Licht im Herrn; lebt als Kinder des Lichts');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 9, '- denn die Frucht des Lichts [ist, besteht in] lauter (größte, höchste, völlige) Rechtschaffenheit und Gerechtigkeit und Wahrheit -');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 10, 'und erwägt, was dem Herrn gefällt,');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 11, 'und habt keinen Anteil an den fruchtlosen (unfruchtbaren) Werken der Finsternis, vielmehr {aber auch, sogar} bringt sie an den Tag.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 12, 'Denn ihre heimlichen Taten auch nur zu erwähnen, ist eine Schande.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 13, 'Alles aber, was an den Tag kommt, wird vom Licht sichtbar gemacht,');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 14, 'denn alles Sichtbare ist Licht. Darum heißt es „Wach auf, Schläfer, und steh auf von den Toten, und Christus wird dir leuchten (aufgehen, erscheinen) “.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 15, 'Achtet (seht, beobachtet) darum (also) sorgfältig (genau) [darauf], wie ihr lebt (euer Leben führt, wandelt): Nicht wie (als) Unweise, sondern wie (als) Weise,');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 16, 'indem (wobei, und) ihr die Zeit nutzt (jede Gelegenheit nutzt; die Zeit kauft), denn die Tage sind böse (schlimm).');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 17, 'Deshalb werdet (seid) nicht gedankenlos (leichtsinnig, unverständig, töricht), sondern begreift (erkennt), was der Wille des Herrn [ist]!');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 18, 'Und betrinkt euch nicht [mit] Wein, in dem (denn das ist) ein maßloser (wilder/selbstzerstörerischer) Lebensstil (Ausschweifung) ist, sondern werdet (lasst euch) durch (mit, im) [den] Geist angefüllt (erfüllt),');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 19, 'wobei (indem, sodass, damit, während) ihr zu einander mit (in) Psalmen (Lobliedern) und Lobliedern (Lobgesängen) und geistlichen Liedern sprecht, so dass (wobei, indem, und) ihr [in] eurem Herzen dem Herrn singt und lobsingt (Psalmen singt; spielt),');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 20, 'jederzeit für alles Gott dem Vater dankt im Namen des unseres Herrn Jesus Christus');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 21, 'und euch einander in der Furcht [vor] Christus unterordnet,');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 22, 'die Frauen den eigenen Männern wie (als) dem Herrn,');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 23, 'denn [der] Mann ist [das] Haupt (der Kopf; „steht über“) der Frau, wie auch Christus [das] Haupt der Gemeinde [ist], er, [der] Retter des Körpers ([wobei] er selbst [der] Retter des Körpers [ist]).');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 24, 'So (sondern) wie die Gemeinde sich {dem} Christus unterordnet, so [sollen sich] auch die Frauen [ihren] Männern in allem [unterordnen].');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 25, '{die} Männer, liebt [eure] Frauen, wie auch {der} Christus die Gemeinde geliebt hat und sich selbst für sie (um ihretwillen, an ihrer Stelle) ausgeliefert (übergeben, hingegeben, sein Leben gegeben) hat:');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 26, 'um (damit er) sie zu heiligen, indem (nachdem) er [sie] [mit dem] ([durch das], [im]) Wasserbad durch [das] (im, mit [dem]) Wort reinigte (reinigt);');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 27, 'um so (damit er) selbst die Gemeinde [als] herrlich (wunderbar; angesehen, geehrt) vor (für) sich hinzustellen (sich zu präsentieren, für sich zu schaffen/aufzustellen), die keinen Fleck oder eine Runzel (Falte) oder etwas Derartiges (dergleichen, Ähnliches) hat, sondern so, dass (damit, um) sie heilig und fehlerlos (makellos, tadellos) ist.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 28, 'So sollen (müssen, sind verpflichtet) auch die Männer ihre Frauen wie (als) ihren eigenen Körper lieben. Wer seine Frau liebt, [der] liebt sich selbst.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 29, 'Denn (ja, nämlich) niemand hat je sein eigenes Fleisch gehasst, im Gegenteil (sondern, vielmehr, aber, nein) ernährt und versorgt (pflegt) [man es], genau wie auch Christus die Gemeinde [ernährt und versorgt],');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 30, 'weil wir Glieder (Körperteile) seines Körpers sind.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 31, 'Deshalb verlässt (lässt zurück; wird verlassen) ein Mann (Mensch) {den} Vater und {die} Mutter und vereint sich (tut sich zusammen) mit (zu) seiner Frau, und die beiden werden (sind; werden sein) zu einem Fleisch.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 32, 'Dieses Geheimnis ist groß; ich aber spreche über (beziehe/deute [es] auf) Christus und über die Gemeinde.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 33, 'Jedenfalls (doch, nun, wie dem auch sei) sollt auch ihr, {die} jeder einzelne [von euch], seine eigene Frau so lieben wie sich selbst, und (aber) [jede] Frau {dass} soll [ihren] Mann respektieren (mit Achtung begegnen, fürchten).');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 1, '');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 2, '');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 3, '');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 4, '');
