INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 18, '');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 19, '');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 20, '');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 21, '');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 22, '');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 23, '');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 24, '');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 1, 'Paulus und Timotheus, Sklaven Christi Jesu, allen Heiligen in Christus Jesus, die in Philippi sind, mit den Bischöfen (urspr.: Aufseher) und Diakonen (urspr.: Diener, Helfer),');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 2, 'Gnade [sei] mit euch und Friede von Gott, unserem Vater, und [vom] Herrn Jesus Christus.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 3, 'Ich danke meinem Gott (bei aller Erinnerung an euch =) so oft ich euer gedenke');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 4, 'immer (stets) in jedem meiner Gebete (jeder Bitte) für euch alle, wobei ich mit Freude (n) das Gebet (tue =) verrichte,');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 5, 'wegen (für) eurer Gemeinschaft für das (am) Evangelium vom ersten Tag bis jetzt,');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 6, 'überzeugt davon (gewiss darin), dass der, der bei euch begonnen hat (den Anfang machte) [das] gute Werk, [es] zu Ende bringen (beendigen, vollenden) wird bis zum Tage Christi Jesu.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 7, 'So ist es (für mich =) in meinen Augen recht (richtig, billig), dies über euch alle zu denken, weil ich euch im Herzen habe, in meinem Gefängnis und auch in der Verteidigung und Befestigung (festen Begründung) des Evangeliums; ihr seid alle Teilhaber (Genossen) meiner Gnade.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 8, 'Denn Gott ist mein Zeuge, wie ich mich nach euch allen sehne in der Liebe (Zuneigung) Christi Jesu.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 9, 'Und dies erbitte (bitte) ich, damit eure Liebe mehr und mehr wachse in der Erkenntnis und in aller Erfahrung');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 10, 'damit ihr das, worauf es ankommt (das Wesentliche), prüft, damit ihr lauter und tadellos seid für den (am) Tag Christi,');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 11, 'erfüllt von der Frucht der Gerechtigkeit, die durch Jesus Christus [geschaffen ist] zu Ehre und Lob Gottes.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 12, 'Wissen lassen will ich euch aber, Geschwister, dass meine Angelegenheiten eher zur Förderung des Evangeliums ausgeschlagen sind');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 13, 'weil nämlich (sodass) meine Gefangenschaft durch Christus bekannt wurde im ganzen Prätorium und bei allen übrigen');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 14, 'und die meisten der Geschwister im Herrn, weil sie durch meine Gefangenschaft überzeugt waren, hatten in stärkerem Maße (stärker) den Mut (wagten), furchtlos das Wort zu predigen (verkündigen).');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 15, 'Einige (Manche) {zwar} verkündigen Christus auch durch Neid und Streit (Hader), einige (manche) {aber} auch durch guten Willen.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 16, 'Die einen aus Liebe, weil sie wissen, dass ich zur Verteidigung des Evangeliums bestimmt (eingesetzt) bin,');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 17, 'die anderen verkündigen Christus aus Selbstsucht (Eigennutz), nicht lauter (unlauter), weil sie meinen (denken) [mir] in meiner Gefangenschaft Trübsal (Kummer) zu bereiten.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 18, 'Was denn? Außer dass auf jede Weise, sei es unter einem Vorwand, sei es in Wahrheit, Christus verkündigt wird, und darüber freue ich mich. Aber ich werde mich auch freuen,');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 19, 'denn ich weiß, dass mir dies zur Rettung (Heil, Erlösung) ausschlagen wird durch eure Bitten und [durch] Unterstützung des Geistes Jesu Christi,');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 20, 'gemäß (entsprechend) meiner sehnsüchtigen Erwartung und Hoffnung, dass ich in keiner Weise (in nichts) beschämt (zuschanden) werde, sondern frei (offen, in aller Öffentlichkeit), wie immer, so auch jetzt Christus durch meinen Leib verherrlicht wird, sei es durchs Leben, sei es durch den Tod.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 21, 'Denn für mich [ist] zu leben Christus, und zu sterben Gewinn.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 22, 'Wenn es aber das Leben im Fleisch [ist], [ist, bedeutet] dies für mich Frucht der Arbeit (= Arbeitsertrag), und was ich vorziehe, weiß ich nicht.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 23, 'Von beiden [Seiten] aber werde ich angefochten (gequält), ich habe Verlangen, aufzubrechen (abzuscheiden) und mit Christus zu sein, [wie] viel besser {nämlich} [wäre das]!');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 24, 'Aber das Bleiben im Fleisch ist nötiger euretwegen.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 25, 'Und dies weiß ich gewiss, dass ich bleibe und bleiben werde bei euch allen zu eurer Förderung und [zur] Freude des Glaubens,');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 26, 'damit das, was zu eurem Ruhm gesagt wird (wörtl.: das Loblied), in Christus Jesus im Überfluss vorhanden ist durch mich, (durch meine Anwesenheit wiederum bei euch =) dadurch, dass ich wiederum zu euch komme.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 27, 'Nur (bloß) führt euer Leben würdig des Evangeliums Christi, damit ich, ob ich komme und euch sehe, oder abwesend von euch höre, {dass} ihr in einem Glauben steht, einmütig zusammen für den Glauben des Evangeliums streitet');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 28, 'und euch nicht einschüchtern lasst in nichts (in keiner Hinsicht) von den Widersachern, was ihnen ein Anzeichen (Beweis) des Verderbens, euch aber der Rettung ist, und das von Gott.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 29, 'Denn euch wurde geschenkt das für Christus nicht allein an ihn Glauben, sondern auch das für ihn Leiden.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 30, 'Ihr habt den selben Kampf zu bestehen, wie ihr ihn an mir seht und nun von mir hört.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 1, 'Wenn nun Trost (Ermahnung, Zuspruch) in Christus etwas gilt, {wenn} Zuspruch (Erleichterung) der Liebe {etwas gilt}, {wenn} Gemeinschaft des Geistes (Geistgemeinschaft) {etwas gilt}, {wenn} Erbarmen {etwas gilt},');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 2, 'dann macht meine Freude [dadurch] vollkommen, dass ihr (dasselbe denkt =) einmütig seid, die selbe Liebe besitzt, einträchtig, auf das Eine bedacht seid,');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 3, 'niemals streitsüchtig (rechthaberisch), niemals ruhmbegierig (eingebildet), sondern zieht einander dadurch vor (stellt einer den anderen über sich selbst), dass ihr euch an Demut übertrefft,');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 4, 'und seht jeder nicht auf das Seine, sondern vor allem {alle} auf das der anderen.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 5, 'Hegt diese Gesinnung untereinander, die ihr auch (in Christus Jesus =) als Glieder Christi [hegen müsst],');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 6, 'Der, obwohl er in Gestalt Gottes war nicht als Geschenk des Zufalls (Glücksfund; Beute) sah er an das Gleichsein mit Gott,');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 7, 'sondern entblößte (entleerte, beraubte) sich selbst, indem er die Gestalt eines Knechtes (Sklaven) annahm, und (sich in Gestalt der Menschen befand =) menschenähnlich war und seinem Aussehen nach als Mensch erschien.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 8, 'Er erniedrigte sich selbst und wurde gehorsam bis zum Tod, und zwar zum (Tod des Kreuzes =) Kreuzestod.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 9, 'Deshalb hat ihn auch Gott hoch erhoben und ihm aus Gnade den Namen geschenkt, der über alle Namen ist,');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 10, 'damit (in dem Namen Jesu =) beim Erklingen des Namens Jesu jedes Knie sich beuge der Himmlischen (himmlischen Wesen) und der Irdischen (irdischen Wesen) und Unterirdischen (unterirdischen Wesen),');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 11, 'und jede Zunge wird anerkennen (bekennen), dass Herr [ist] Jesus Christus zur Ehre Gottes des Vaters.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 12, 'Daher (also) erarbeitet euch, meine Lieben (Geliebten), eure Rettung (euer Heil) mit Furcht und Zittern, wie ihr mir immer (jederzeit) gehorcht habt, nicht wie [etwas, das] allein bei meiner Anwesenheit [geschehen würde], sondern jetzt noch viel mehr bei meiner Abwesenheit.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 13, 'Denn Gott ist es, der in euch bewirkt sowohl das Wollen als auch das wirksam Sein (das sich Betätigen) über den guten Willen hinaus.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 14, 'Alles tut ohne Murren und Bedenken (Zweifel),');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 15, 'damit ihr untadelig und unverdorben seid, Gottes untadelige Kinder inmitten einer krummen (verkehrten) und verdorbenen (verkehrten) Zeit (Generation, Geschlecht), in der ihr scheint (leuchtet) wie Sterne (Gestirne) am Himmel (Weltraum),');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 16, 'die das Wort des Lebens festhalten, zu meinem Ruhm für den Tag des Christus (= des Messias), dass ich nicht vergebens (umsonst, erfolglos) gelaufen bin noch mich vergebens (umsonst, erfolglos) gemüht habe.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 17, 'Aber wenn ich auch geopfert werde beim Opfer und Opferdienst eures Glaubens, freue ich mich und freue mich mit euch allen.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 18, 'In gleicher Weise freut auch ihr euch und freut euch mit mir!');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 19, 'Ich hoffe aber im Herrn Jesus, Timotheus bald zu euch zu schicken, damit auch ich guten Mutes werde, wenn ich eure Lage erfahre.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 20, 'Denn ich habe keinen, der derart [mit euch] solidarisch wäre, dass er aufrichtig besorgt um eure Lage ist.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 21, 'Denn alle verfolgen ihre Angelegenheiten (ihre Sache), nicht die Jesu Christi.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 22, 'Ihr wisst aber, dass er etwas taugt (wörtl.: ihr kennt ihn als erprobt), denn wie ein Kind dem Vater, [so] hat er mit mir dem Evangelium gedient.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 23, 'Diesen nun hoffe ich, zu euch zu schicken, sofort, sowie ich meine Lage überblicken kann.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 24, 'Ich vertraue aber im Herrn darauf (baue darauf), dass ich auch selbst bald kommen werde.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 25, 'Ich habe es aber für notwendig angesehen, Epaphroditus, meinen Bruder, Mitarbeiter und Mitstreiter, {aber} euren Boten und der, dessen Dienst meinen Mangel behob, zu euch zu schicken,');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 26, 'da er nach euch allen Sehnsucht hatte und in Unruhe darüber war, dass ihr gehört hattet, er sei krank.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 27, '{Und} er war auch krank, dem Tode nah. Aber Gott erbarmte sich seiner, nicht nur seiner allein, sondern auch meiner, damit ich nicht Kummer über Kummer hätte.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 28, 'Besonders eilig habe ich ihn nun geschickt, damit, wenn ihr ihn seht, ihr wieder froh seid und auch ich sorgenfrei bin.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 29, 'Nehmt ihn nun auf im Herrn mit aller Freude und haltet Leute wie ihn (wörtl.: solche) in Ehren,');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 30, 'weil er um des Werkes Christi willen dem Tode nahegekommen war und sein Leben auf\'s Spiel gesetzt hat, um eure Abwesenheit im Dienst für mich zu vertreten.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 3, 1, 'Weiterhin, meine Geschwister, freut euch im Herrn. Euch das selbe zu schreiben ist mir {zwar} nicht langweilig, euch aber [gibt es größere] Gewissheit.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 3, 2, 'Hütet euch (nehmt euch in acht, seht euch vor) vor den Hunden, hütet euch vor den schlechten Arbeitern, hütet euch vor der Zerschneidung!');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 3, 3, 'Denn wir sind die Beschneidung, die wir im Geist (oder: durch den Geist) Gott dienen und uns in Christus Jesus rühmen und nicht auf das Fleisch vertrauen,');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 3, 4, 'obwohl ich Zuversicht habe auch auf das Fleisch. Wenn ein anderer meint, er könne auf\'s Fleisch vertrauen, ich um so mehr!');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 3, 5, 'Am achten Tag beschnitten, aus dem Volk Israel, Stamm Benjamin, Hebräer von (Hebräern =) hebräischen Eltern, was [meine Stellung zum] Gesetz betrifft (dem Gesetz nach) Pharisäer,');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 3, 6, 'was meinen Eifer betrifft (dem Eifer nach) Verfolger der Gemeinde, was die Gerechtigkeit, die im Gesetz gewährt wird, betrifft (der Gerechtigkeit ... nach), tadellos (untadelig).');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 3, 7, 'Aber das, was für mich Gewinn war, das sah ich um Christi willen als Verlust (Nachteil) an.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 3, 8, 'Aber noch vielmehr sehe ich auch [jetzt] alles Verlust (Nachteil) an wegen der alles übertreffenden [Größe der] Erkenntnis Christi Jesu, meines Herrn, um dessentwillen ich mich um das alles bringen ließ, und halte es für Dreck (Abfall, Unrat, Mist, Kot), damit ich Christus gewönne');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 3, 9, 'und in ihm gefunden werde, damit ich nicht meine Gerechtigkeit aus dem Gesetz habe, sondern die durch den Glauben an Christus, die Gerechtigkeit von Gott auf Grund des Glaubens,');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 3, 10, 'damit ich ihn kennen lerne (kenne, erkenne) und die Macht seiner Auferstehung und die Gemeinschaft seiner Leiden, seinem Tod gleichgestaltet,');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 3, 11, 'ob ich vielleicht irgendwie die Auferstehung von den Toten erlange (erreiche).');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 3, 12, 'Nicht, dass ich [Christus] schon (geistig oder seelisch) erfasst (in mich aufgenommen) hätte oder schon vollendet wäre; ich eile (renne) aber, ob ich [ihn] auch ergreife, weil ich {auch} ergriffen wurde von Christus Jesus.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 3, 13, 'Geschwister, ich sehe mich selbst nicht an, [ihn] ergriffen zu haben. Eins aber [tue ich]: was hinten liegt {zwar} vergesse (vernachlässige) ich, nach dem aber, was vor mir liegt, strecke ich mich aus.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 3, 14, 'Ich laufe nach dem Ziel um den Kampfpreis der Berufung von oben durch Gott in Christus Jesus.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 3, 15, 'Soweit wir nun Eingeweihte [sind], lasst uns darauf bedacht sein (das im Sinn haben). Und wenn ihr etwas anderes wollt (im Sinn habt), wird Gott euch auch das offenbaren.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 3, 16, 'Nur, was wir erreicht haben: lasst uns an das selbe halten.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 3, 17, 'Ahmt mit mir zusammen [Christus] nach, Geschwister und blickt auf die, die so (wandeln =) handeln (leben), wie ihr uns als Vorbild habt.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 3, 18, 'Denn viele (wandeln =) leben, von denen ich euch oft gesprochen habe, nun aber spreche ich mit Tränen über die Feinde des Kreuzes Christi,');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 3, 19, 'deren Ziel Verderben [ist], deren Gott der Bauch [ist] und deren Ehre (Ruhm) (in ihrer Schande =) in dem, was ihnen Schande macht, [besteht], die auf irdische Dinge bedacht sind.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 3, 20, 'Denn unser Gemeinwesen (Staat) befindet sich im Himmel, von wo wir auch als Retter erwarten den Herrn Jesus Christus,');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 3, 21, 'der umgestalten (verwandeln) wird unseren Niedrigkeitsleib gleichgestaltet seinem Herrlichkeitsleib auf Grund der wirksamen Kraft, die ihn befähigt, sich ihm alles zu unterwerfen.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 1, 'Daher (Deshalb, Also), meine geliebten und herbeigesehnten Geschwister, meine Freude und Schmuck, auf solche Weise steht fest im Herrn, Geliebte.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 2, 'Euodia bitte ich und Syntyche {bitte ich}, einnmütig zu sein (dasselbe zu denken) im Herrn.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 3, 'Ja, ich bitte auch dich, rechter („waschechter“) Gefährte (Genosse), steh ihnen bei (hilf ihnen), die mit mir zusammen im Evangelium gekämpft haben mit Clemens und meinen übrigen Mitarbeitern, deren Namen im Buch des Lebens [sind, stehen].');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 4, 'Freut euch immer (stets) im Herrn! Aufs neue (Nochmals, Wiederum) werde ich sagen: freut euch!');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 5, 'Eure Güte lasst alle Menschen erfahren. Der Herr [ist] nahe!');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 6, 'Um nichts sorgt euch, sondern in jedem Gebet und [jeder] Bitte sollen eure Anliegen (Bitten) mit Danksagung Gott kundgetan (zur Kenntnis gebracht) werden.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 7, 'Und der Friede Gottes, der alle Vernunft übertrifft, bewahre (beschütze, behüte) eure Herzen und Gedanken in Christus Jesus.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 8, 'Im übrigen (Außerdem, Weiterhin, Endlich), Geschwister, was wahr ist, was ehrbar (ehrwürdig), was gerecht, was rein, was angenehm (beliebt, wohlgefällig), was wohltuend (glückverheißend, löblich, anziehend, ansprechend), ob irgendeiner Tugend [hat] und ob irgendeiner Lob [verdient], das bedenkt.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 9, 'Und was ihr bei mir gelernt und [von mir] übernommen und gehört und gesehen habt, das tut. Und der Gott des Friedens sei mit euch.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 10, 'Ich freute mich aber sehr im Herrn, weil (dass) ihr endlich einmal aufgeblüht seid, was eure Fürsorge für mich betrifft, denn ihr dachtet [an mich], fandet aber keine Gelegenheit.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 11, 'Nicht, dass ich bedürftig wäre, ich habe nämlich gelernt, wo (= bei wem) ich bin, genügsam zu sein.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 12, 'Ich bin einerseits imstande (ich verstehe), mich zu kasteien, andererseits {bin ich imstande}, es mir gut gehen zu lassen (Überfluss zu haben). Ich bin durchaus (in allem, in jeder Beziehung) und in jeder Hinsicht (in allen Stücken) eingeweiht, sowohl satt sein (satt werden), als auch hungern, sowohl Überfluss haben wie Mangel leiden.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 13, 'Alles vermag ich durch den, der mich stark macht.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 14, 'Jedoch (indessen) habt ihr gut gehandelt, dass ihr an meiner Bedrängnis Anteil genommen habt.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 15, 'Aber auch ihr Philipper wisst, dass am Beginn des Evangeliums, als ich von Mazedonien loszog (auszog), mir keine Gemeinde Anteil gewährte in Abrechnung des Gebens und Nehmens (der Ausgaben und Einnahmen) als ihr allein,');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 16, 'weil ihr mir auch nach Thessaloniki (ein- bis zweimal =) ein paarmal eine Zusendung machtet, um meinem Mangel abzuhelfen.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 17, 'Nicht, dass ich die (Gabe =) Zinsen suche, sondern ich wünsche (die Frucht in ihrer reichlichen Fülle =) den Profit, zu euren Gunsten verrechnet (auf euer Konto gebucht).');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 18, 'Ich habe aber alles empfangen und lebe im Überfluss. Mir sind die Hände gefüllt, nachdem ich von Epaphroditus eure Gabe empfangen habe, ein wohlriechender Opferduft, ein angenehmes Opfer, wohlgefällig dem Herrn.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 19, 'Mein Gott aber fülle all euren Mangel (Bedarf, Not) aus entsprechend seines Reichtums in der Herrlichkeit in Christus Jesus.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 20, 'Unserem Gott und Vater aber sei Ehre bis in die fernste Ewigkeit. Amen.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 21, 'Grüßt jeden Heiligen in Christus Jesus. Es grüßen euch die Geschwister, die bei mir sind.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 22, 'Es grüßen euch alle Heiligen, am meisten aber die Kaisersklaven.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 23, 'Die Gnade des Herrn Jesus Christus [sei] mit eurem Geist.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 1, 'Paulus, Apostel [von] Christus Jesus durch den Willen Gottes, und Timotheus der Bruder');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 2, '[an] die Heiligen in Kolossä, {und} die treuen (gläubigen) Geschwister (Brüder [und Schwestern]; Brüder) in Christus (an Christus Glaubenden) (die heiligen und treuen Geschwister; die Heiligen, {und} die treuen Geschwister... in Kolossä). Gnade [sei mit] euch und Frieden von Gott, unserem Vater.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 3, 'Wir danken Gott, dem Vater unseres Herrn Jesus Christus, jedes Mal (immer wieder, ständig), wenn wir für euch beten (für euch, wenn wir beten),');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 4, 'weil wir [von] eurem Glauben (Vertrauen) in (an) Christus Jesus gehört haben und [von] der Liebe, die ihr gegenüber (zu) allen Heiligen habt,');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 5, 'aufgrund (wegen) der (durch die) Hoffnung, die im Himmel [auf] euch wartet (für euch bereit/vorhanden/reserviert ist), [von] der ihr schon zuvor (vorher) durch das (im) Wort (die Botschaft) der Wahrheit, das Evangelium (wahre Wort des Evangeliums) gehört habt,');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 6, 'das zu euch gekommen ist, [das Evangelium], wie es auch auf (in) der ganzen Welt Frucht bringt und sich verbreitet, so wie [es ja] auch unter (in) euch [geschieht] seit dem Tag, [als] ihr [es] gehört und die Gnade Gottes wirklich (in Wahrheit) verstanden (erkannt) ([als] wahr erkannt) habt –');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 7, '[das Evangelium], wie ihr [es] von unserem geliebten Mitsklaven Epaphras gelernt habt, der ein treuer Diener Christi an unserer Stelle (für euch) ist,');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 8, 'der [es] auch [war, der] uns eure Liebe durch [den] (im) Geist deutlich gemacht (aufgezeigt, offenbart) hat.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 9, '');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 10, '');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 11, '');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 12, '');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 13, '');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 14, '');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 15, '');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 16, '');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 17, '');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 18, '');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 19, '');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 20, '');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 21, 'und [auch] euch: ihr mögt [ja] früher (einmal) Fremde (entfremdet) und innerlich (in eurer Gesinnung, Denkweise, Geisteshaltung) Feinde aufgrund (in) [eures] bösen Verhaltens (Taten, Werken) gewesen sein,');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 22, 'aber jetzt wurdet ihr (hat [er euch]) kraft (mittels, anhand, durch, mit, in) seines fleischlichen Körpers durch den Tod versöhnt, um euch in seinen Augen (vor sich) [als] heilig und fehlerlos (makellos, tadellos) und unbescholten (makellos, ohne Anklage) zu präsentieren (zu machen, vor sich hinzustellen),');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 23, 'wenn (sofern) ihr denn weiter im Glauben bleibt, auf einem festen Fundament (fest gegründet) und sicher, und nicht von der Hoffnung des Evangeliums abgebracht werdet, das ihr gehört habt, [des Evangeliums], das in [der] ganzen Schöpfung unter dem Himmel verkündet wurde (wird), dem ich, Paulus, [zum] Diener geworden bin.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 24, 'Jetzt freue ich mich in den Leiden für euch und ergänze [stellvertretend für euch], was an den Drangsalen Christi noch fehlt, an meinem Körper für seinen Leib, das ist die Gemeinde,');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 25, 'deren Diener ich geworden bin nach dem Auftrag (Amt, Heilsplan) Gottes, den er mir gegeben hat, bei euch das Wort Gottes zur Fülle zu bringen,');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 26, '[nämlich] das Geheimnis, das verborgen gewesen ist seit Ewigkeiten und Generationen – jetzt aber wurde es seinen Heiligen offenbart,');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 27, 'denen Gott kundtun (offenbaren) wollte, was der Reichtum der Herrlichkeit dieses Geheimnisses bei den Völkern ist, das ist Christus in (bei, unter) euch, die Hoffnung der Herrlichkeit,');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 28, 'den wir verkündigen, indem wir jeden Menschen ermahnen (zurechtweisen, ans Herz legen) und jeden Menschen lehren in aller Weisheit, damit wir jeden Menschen vollkommen (vollendet, reif, eingeweiht) in Christus präsentieren (darstellen, erweisen);');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 29, 'worum ich mich auch bemühe und mich abkämpfe, getragen von seiner Wirksamkeit, die in mir wirksam ist in Kraft (kräftig wirksam ist).');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 2, 1, 'Ich will {nämlich}, dass ihr wisst, welchen Kampf ich für euch und die [Geschwister] in Laodizea [zu bestehen, auszufechten] habe und [für] alle, die mein Angesicht nicht leiblich gesehen haben (= die mich nicht persönlich kennen),');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 2, 2, 'damit ihre Herzen getröstet werden und sie zusammengehalten werden in Liebe und zur ganzen Fülle (Reichtum) der Gewissheit, [wie sie] die Einsicht (das Verständnis) [verleiht], zur Erkenntnis des Geheimnisses Gottes: Christus.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 2, 3, 'In ihm sind alle Schätze der Weisheit und Erkenntnis verborgen.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 2, 4, 'Dies sage ich, damit keiner von euch betrogen wird durch Vorspiegelung falscher Tatsachen (Überredungskunst).');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 2, 5, 'Denn wenn ich auch körperlich abwesend bin, bin ich doch im Geiste bei euch. Ich freue mich und achte auf (sehe) den Zustand (die Beschaffenheit) und die Stärke eures Glaubens an Christus.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 2, 6, 'Da ihr nun Christus Jesus, den Herrn, angenommen (empfangen) habt, lebt (gestaltet eurer Leben, wandelt) in ihm,');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 2, 7, 'indem ihr fest wurzelt in und aufbaut auf ihm und befestigt (bestärkt) seid im Glauben, wie ihr gelehrt wurdet, und euch durch Dankbarkeit hervortut.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 2, 8, 'Achtet darauf (seht zu, passt auf), dass keiner euch zur Beute macht (raubt) durch die Philosophie und (inhalts) leeren (bedeutungslosen) (Be) Trug (Täuschung, Verführung) gemäß den Lehren der Menschen (Menschensatzungen), gemäß den Elementen der Welt (Weltelemente) und nicht gemäß Christus.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 2, 9, 'Denn in ihm wohnt die ganze Fülle der Gottheit leibhaftig,');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 2, 10, 'und ihr seid in ihm (durch ihn) Erfüllte, der das (Ober) Haupt jeder [himmlischen] Obrigkeit und Macht ist.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 2, 11, 'In ihm wurdet ihr auch beschnitten mit einer nicht mit Händen gemachten (= geistlichen) Beschneidung durch das Ablegen des fleischlichen (= todverfallenen, irdischen) Leibes, durch die Beschneidung Christi.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 2, 12, 'Ihr seid mit ihm zusammen begraben in der Taufe, in der ihr auch mit (auf) erstanden seid durch den Glauben an die wirkende Kraft (das Eingreifen) Gottes, der ihn von den Toten auferweckte.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 2, 13, 'Auch euch, obwohl ihr tot wart durch die Übertretungen und die Unbeschnittenheit eures Leibes (Fleisches), hat er mit ihm zum Leben erweckt (zusammen lebendig gemacht) und uns alle Übertretungen verziehen (vergeben).');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 2, 14, 'Er hat den gegen uns [gerichteten] Schuldschein mit seinen Forderungen (Vorschriften), der uns feindlich (widersprechend, zuwider) war, ausgestrichen (beseitigt) und ihn vernichtet, indem er ihn ans Kreuz nagelte.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 2, 15, 'Er entwaffnete die [himmlischen] Obrigkeiten und Mächte und stellte sie öffentlich bloß (machte sie öffentlich zum Gespött), indem er sie in ihm im Triumph einherführte.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 2, 16, 'Es soll euch also keiner kritisieren (schlecht machen) wegen Speise und {wegen} Trank, oder wegen Festfeier oder Neumonden oder Sabbaten.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 2, 17, 'Das sind Schatten (bilder) des Kommenden (Zukünftigen), die Sache selbst aber ist Christus.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 2, 18, 'Niemand soll euch den Kampfpreis aberkennen (disqualifizieren), der sich in Demut gefällt und Engelskult, was er in der Ekstase geschaut hat, grundlos aufgeblasen in seiner fleischlichen Gesinnung,');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 2, 19, 'und nicht am Haupt festhaltend, durch das der ganze Leib, durch Gelenke und Bänder unterstützt und zusammengehalten, in göttlichem Wachstum wächst.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 2, 20, 'Wenn ihr mit Christus {von} den Weltelementen gestorben seid, warum lasst ihr euch Vorschriften machen wie solche, die in der Welt leben:');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 2, 21, '„Rühr (= iss; fass) [das] nicht an, probier (koste) [das] nicht, berühr [das] nicht!“-');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 2, 22, 'was doch alles zur Vernichtung durch Gebrauch bestimmt ist -, nach den Geboten und Lehren der Menschen (wie menschliche Geboten und Lehren lauten, gemäß menschlicher Gebote und Lehren)?');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 2, 23, 'Das ist eine Aussage (Rede, Lehre), die zwar Weisheit besitzt durch selbstgemachte Religion und Demut und Härte (Schonungslosigkeit) gegen den Körper, sie ist aber nichts wert, weil sie der Befriedigung leiblicher Bedürfnisse [dient].');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 3, 1, '');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 3, 2, '');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 3, 3, '');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 3, 4, '');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 3, 5, '');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 3, 6, '');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 3, 7, '');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 3, 8, '');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 3, 9, '');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 3, 10, '');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 3, 11, '');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 3, 12, 'So kleidet euch, als die Auserwählten Gottes, die Heiligen und Geliebten, in herzliche Barmherzigkeit, Güte, Demut, Sanftmut und Geduld.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 3, 13, 'Ertragt euch gegenseitig, und schenkt einander [Vergebung], wenn einer gegen den anderen einen Vorwurf hat. So wie der Herr euch [Vergebung] geschenkt hat, so [vergebt] auch ihr!');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 3, 14, 'Über dies alles aber [zieht an] die Liebe, was das Band (der Gürtel) der Vollkommenheit ist.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 3, 15, 'Und der Friede Christi lenke (regiere) in euren Herzen – [der Frieden], zu dem ihr auch berufen seid in einem Leib. Und werdet dankbare [Menschen]!');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 3, 16, 'Das Wort Christi wohne reichlich (vielfach) unter (in) euch, in aller Weisheit lehrt und warnt (ermahnt) einander (euch gegenseitig) mit Psalmen, Hymnen (Lobliedern), geistlichen (geisterfüllten) Liedern, in Dank (Gnade, Anmut) singt in euren Herzen Gott.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 3, 17, 'Und alles, was ihr tut, mit Worten oder mit Werken, das tut alles im Namen des Herrn Jesus, und dankt so Gott, dem Vater, durch ihn.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 3, 18, '');
