INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 2, 13, 'Und deshalb danken wir Gott auch unablässig, dass ihr, das Wort der Predigt von Gott von uns empfangend, es nicht annahmt als Wort der Menschen, sondern, genauso wie es wahr ist, als Wort Gottes, das wirksam ist bei euch, die ihr glaubt.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 2, 14, 'Ja ihr, Brüder und Schwestern, seit zu Nachahmern der Gemeinden Gottes, die in Judäa in Christus Jesus sind, geworden, weil ihr dasselbe von euren eigenen Mitbürgern erlitten habt, wie diese von den Juden,');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 2, 15, 'die sowohl den Herrn Jesus und die Propheten getötet haben, uns verfolgt haben und Gott nicht gefallen und allen Menschen feindlich sind,');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 2, 16, 'die uns abhalten den Völkern zu sagen, dass sie gerettet sind, so dass sie ihre Sünden allezeit angehäuft haben: Es ist aber bereits über sie der Zorn Gottes für immer gekommen.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 2, 17, '');
