INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 3, 1, '');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 3, 2, '');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 3, 3, '');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 3, 4, '');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 3, 5, '');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 3, 6, '');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 3, 7, 'Deshalb wurden wir, Brüder, in all unsrer Not und Bedrängnis getröstet über Euch durch Euren Glauben,');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 3, 8, 'denn jetzt leben wir, wenn Ihr (fest) im Herrn steht.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 3, 9, 'Denn welchen Dank können wir dem Herrn zurückgeben für Euch, für all die Freude, in der wir uns durch Euch (euretwegen) vor unserem Gott freuen?');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 3, 10, 'Wobei wir Nacht und Tag über alle Maßen darum bitten, Euch von Angesicht (Euer Angesicht) zu sehen und die Mängel Eures Glaubens auszugleichen (zu korrigieren, zu ergänzen),');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 3, 11, 'und [darum], daß unser Gott und Vater selbst und unser Herr Jesus unseren Weg zu Euch lenke.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 3, 12, 'Euch aber möge der Herr wachsen lassen und überreich machen in der Liebe zueinander und gegenüber allen, wie auch wir gegenüber Euch [voller Liebe sind],');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 3, 13, 'um Eure Herzen [so] zu stärken, daß sie in Heiligkeit fehlerfrei vor unserem Gott und Vater [seien] bei der Ankunft unseres Herrn Jesus mit allen seinen Heiligen, Amen.');
