INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 3, 1, 'Des weiteren (im übrigen): betet für uns, Brüder (Geschwister), damit das Wort des Herrn flott vorankommt und gepriesen (gerühmt) werde, so wie bei euch.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 3, 2, 'Und damit wir errettet werden von den unsittlichen und verkommenen Menschen. Denn der Glaube ist nicht aller (jedermanns) [Sache]');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 3, 3, 'Treu aber ist der Herr, der euch fest machen (befestigen) wird und bewahren wird vor dem Bösen.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 3, 4, 'Wir vertrauen aber im Herrn auf euch, dass, was wir anordnen (befehlen) ihr auch tut und tun werdet');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 3, 5, 'Der Herr aber lenke eure Herzen auf die Liebe Gottes und auf die Erwartung (od. Geduld) Christi.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 3, 6, '');
