INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 3, 14, 'Dies schreibe ich in der Hoffnung (hoffend) bald zu dir zu kommen,');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 3, 15, 'wenn ich (mich) aber (ver) zögere, sollst du wissen wie man sich im Haus Gottes bewegen (verhalten, benehmen) soll, das ist die Kirche (Versammlung, Gemeinde) des lebendigen Gottes, Säule (Pfeiler) und Träger (Fundament) der Wahrheit.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 3, 16, 'Und bekanntermaßen groß ist das Geheimnis der Gottesfurcht (der Frömmigkeit, des Glaubens): Der (er wurde) sichtbar (geoffenbart) wurde im Fleisch (Leib, Körper) freigesprochen (gerechtfertigt, gerecht gesprochen) im Geist, erschienen (geschaut von den) den Engeln, verkündet (gepredigt) den Völkern geglaubt (vertrauend angenommen) in der Welt. aufgenommen (emporgehoben) in die (den) Herrlichkeit (Glanz).');
