INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 1, 1, 'Vielfältig (mannigfaltig) und [auf] vielerlei Weise hat [der] Gott ehemals (in alten Zeiten, einst) [zu] den Vätern in (durch) die Propheten geredet,');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 1, 2, 'In diesen letzten Tagen hat er zu uns geredet in (durch) (den) Sohn, welchen er eingesetzt hat als Alleinerbe durch den er auch die Ewigkeiten gemacht hat.');
