INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 4, 13, 'und kein Geschöpf ist verborgen vor ihm, alles aber [ist] nackt (bloß, unverhüllt) und offengelegt [vor] seinen Augen, mit (in Hinblick auf) welchem wir es zu tun haben');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 4, 14, 'Weil wir nun haben einen großen Hohepriester, der hindurchgegangen ist [durch] die Himmel, Jesus den Sohn {des} Gottes, können wir [nun] stark sein in dem Bekenntnis.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 4, 15, 'Denn wir haben nicht einen Hohepriester, der nicht mitempfindet mit der Schwäche von uns, der geprüft wurde in Allem, in Gleichheit ohne Sünde.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 4, 16, 'Lasst uns nun mit Freimütigkeit schreiten zum Thron der Gnade, damit wir in Empfang nehmen [können] Erbarmen und Gnade finden [können] in der rechtzeitigen Hilfe.');
