INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 11, '');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 12, '');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 13, '');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 14, '');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 15, 'Und deshalb ist er der Vermittler eines neuen Testamentes (Bundes), damit, nachdem er gestorben war zur Erlösung von den zur Zeit des ersten Testamentes (Bundes) [begangenen] Übertretungen, die zum ewigen Erbe Berufenen die Verheißung empfangen.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 16, 'Denn wo ein Testament [vorliegt], muss notwendigerweise der Tod des Erblassers beigebracht werden.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 17, 'Denn ein Testament ist bei den Toten (im Todesfall) rechtsgültig, da es noch nicht gilt, wenn der Erblasser lebt.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 18, 'Weshalb auch der Erste [Bund, Testament] nicht ohne Blut geweiht wurde.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 19, 'Denn nachdem durch Mose dem Volk [Israel] jedes Gebot nach dem Gesetz gesagt (aufgezählt, genannt) worden war, nahm er das Blut der (Bullen) Kälber und Böcke mit Wasser und scharlachroter Wolle und Ysop und besprengte sowohl das Buch selbst als auch das ganze Volk.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 20, 'Er sprach: Dies ist das Blut des Bundes, den Gott euch auferlegt (angeordnet, vorgeschrieben) hat.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 21, 'Und das Zelt, aber auch alle Gottesdienstgeräte (Geräte zum Gottesdienst) besprengte er in gleicher Weise mit Blut.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 22, '{Und} fast alles wird nach dem Gesetz durch Blut gereinigt, und ohne Blutvergießen geschieht keine [Sünden] Vergebung.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 23, 'Ist es nun notwendig, {zwar} die Abbilder der [Dinge] in dem Himmeln (= der himmlischen Dinge) mit diesen [Mitteln] zu reiningen, [dann] {aber} das Himmlische selbst durch größere Opfer als diese.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 24, 'Denn Christus ging nicht in das mit Händen gemachte Heilige hinein, das Abbild der wahrhaften [Dinge] (= des wahrhaftigen), sondern in den Himmel selbst, um jetzt vor dem Angesicht Gottes für uns einzutreten (zu erscheinen)');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 25, 'Nicht, damit er sich selbst viele Male darbringt, wie der Hohepriester jährlich mit fremdem Blut in das Heilige hineingeht,');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 26, 'da hätte er seit Anbeginn der Welt ja viele Male leiden müssen. Jetzt aber ist er einmal (ein für allemal) am Ende der Zeiten zur Aufhebung der Sünden durch sein Opfer erschienen (hat sich offenbart).');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 27, 'Und in dem Maße, wie es den Menschen bestimmt ist, einmal (ein für allemal) zu sterben, danach aber [kommt] das Gericht,');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 28, 'so wurde auch Christus einmal (ein für allemal) dargebracht, um sich die Sünden der Vielen aufzuladen. Zum zweiten Mal wird er ohne Sünden denen erscheinen, die ihn zu [ihrer] Rettung erwarten.');
