INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 34, '');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 35, 'Werft also nicht eure Zuversicht weg, welche eine große Belohnung hat.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 36, 'Geduld nämlich habt ihr nötig, damit ihr den Willen Gottes tut und ihr die Verheißung erhaltet.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 37, 'Denn noch eine kleine Weile, der Kommende wird da sein und er wird nicht zögern:');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 38, 'Mein Gerechter aber wird aus Glauben leben, und wenn er feige zurückweicht, ist meine Seele nicht zufrieden mit ihm.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 39, 'Wir aber sind nicht zurückhaltend zum Verderben, sondern glaubend zur Bewahrung der Seele (Leben).');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 1, 'Es ist aber der Glaube eine Verwirklichung dessen, was gehofft wird (was man hofft), und ein Beweis (Überführung) der Dinge, die nicht gesehen werden.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 2, '');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 3, 'Durch Glauben erkennen wir, dass die Welt geschaffen wurde durch das Wort Gottes, damit nicht aus dem Erscheinenden (Erscheinungswelt) das Sichtbare entstand (geworden ist).');
