INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 1, '');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 2, '');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 3, '');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 4, '');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 5, '');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 6, '');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 7, '');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 8, 'Jesus Christus [ist] derselbe gestern und heute und in alle Ewigkeit.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 9, '');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 10, '');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 11, '');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 12, 'Darum hat auch Jesus, um das Volk zu heiligen durch sein eigenes Blut, gelitten außerhalb des Tores.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 13, 'Deshalb lasst uns hinausgehen zu ihm, außerhalb des Lagers, und seine Schmach tragen.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 14, 'Denn wir haben hier keine bleibende (fortbestehende) Stadt, sondern wir suchen nach der zukünftigen (begehren die zukünftige).');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 15, '');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 16, '');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 17, '');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 18, '');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 19, '');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 20, 'Der Gott aber des Friedens, der herausgeführt hat aus den Toten den großen Hirten der Schafe im (durch) Blut des ewigen Bundes, unseren Herrn Jesus,');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 21, '');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 22, '');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 23, '');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 24, '');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 25, '');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 1, 'Jakobus, ein Sklave (Knecht, Diener) Gottes und des Herrn Jesus Christus, an die zwölf Stämme in der Zerstreuung (Diaspora). Grüße!');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 2, 'Haltet es für ganze (nichts als) Freude (Haltet es für nichts anderes denn als einen Grund zur Freude), meine Brüder (Geschwister), wenn (wann immer) ihr in verschiedenste (vielfältige) Prüfungen (Versuchungen) fallt,');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 3, 'da ihr [ja] wisst (im Wissen, wisst!), dass die Erprobung (die Bewährung) eures Glaubens (das Erprobte an eurem Glauben) Standhaftigkeit (Ausharren, Geduld, Ausdauer, Standhaftigkeit) hervorbringt (bewirkt).');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 4, 'Die Standhaftigkeit {aber} soll ein vollkommenes Werk (vollkommenes Handeln) [zur Folge] haben (zu einem vollkommenen Werk führen), damit (:) ihr vollkommen und vollständig und (indem, wenn, weil ihr) in nichts mangelhaft seid.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 5, 'Wenn es [dafür] aber (Wenn es {aber}) einem (jemandem) von euch an Weisheit mangelt, soll er [sie] von Gott, der allen großzügig (vorbehaltlos) und ohne Vorwürfe gibt, erbitten - und sie wird ihm gegeben werden.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 6, 'Er soll (Man muss) {aber} im Glauben [darum] bitten [und dabei] keinesfalls zweifeln (keinerlei Bedenken haben): Denn wer zweifelt, gleicht einer Meereswoge, die vom Wind bewegt und hin- und hergetrieben wird.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 7, 'Jener (So ein, ein solcher) Mensch soll nämlich nicht meinen, dass er etwas vom Herrn erhalten wird,');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 8, '[er ist] ein Mann (Mensch) geteilten Herzens, wankelmütig auf allen seinen Wegen');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 9, 'Stattdessen soll (darf) sich der geringe (demütige, arme) Bruder seiner hohen Stellung (Erhöhung) rühmen,');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 10, 'der reiche [Bruder] aber seiner Erniedrigung, denn er wird wie eine Grasblüte vergehen.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 11, 'Denn die Sonne geht (ging) mit dem heißen Wind auf und vertrocknet (vertrocknete) das Gras und seine Blüte fällt (fiel) ab, und die Schönheit ihres Aussehens vergeht (verging). Genau so wird auch der Reiche auf seinen Reisen (in seinem Lebenswandel) verwelken (dahinschwinden).');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 12, 'Glücklich [ist] der Mensch (Mann), der eine Bewährungsprobe (Prüfung, Versuchung) [standhaft] erträgt, denn wenn (weil, indem) er sich [darin] bewiesen hat (bewährt), wird er den Siegeskranz des Lebens empfangen, den [Gott (Christus)] denen verheißen hat, die ihn lieben.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 13, 'Niemand soll in einer Bewährungsprobe (niemand, der [gerade] versucht (geprüft) wird) sagen, {dass}: Ich werde von Gott auf die Probe gestellt (geprüft, versucht)! – denn Gott kann nicht vom Bösen auf die Probe gestellt (versucht) (zum Bösen versucht) werden; er stellt selbst auch niemanden auf die Probe (versucht selbst auch niemanden).');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 14, 'Vielmehr wird jeder auf die Probe gestellt (versucht), indem (weil, während, wenn) er von der eigenen Begierde fortgerissen und verlockt wird.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 15, 'Daraufhin, wenn die Begierde schwanger geworden ist, gebiert sie Sünde; und die Sünde, wenn sie ans Ziel gelangt (erwachsen geworden) ist, gebiert Tod.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 16, 'Lasst euch nicht täuschen, meine geliebten Geschwister!');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 17, 'Jede gute Gabe und jedes vollkommene Geschenk kommt {herab} (ist) von oben, vom Vater der Lichter, bei dem es weder Veränderung noch Verfinsterung (Schatten) durch eine (nach einer) Wende gibt.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 18, 'Aus [freiem] Willen (Weil er [es so] wollte) hat er uns [durch] das Wort der Wahrheit geboren, damit (um) wir gewissermaßen die Erstlingsgabe seiner Geschöpfe sind.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 19, 'Denkt daran (Wisst [dies], Ihr wisst), meine geliebten Geschwister: Jeder Mensch soll schnell [dazu bereit] sein zuzuhören, [aber] langsam [bereit] zu sprechen [und] langsam [bereit] zum Zorn.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 20, 'Denn [der] Zorn eines Menschen bewirkt nicht [die] Gerechtigkeit vor Gott.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 21, 'Deshalb legt alle Unsauberkeit und übermäßige Schlechtigkeit ab [und] nehmt das eingepflanzte Wort, das eure Seelen zu retten vermag, in Bescheidenheit auf.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 22, 'Aber werdet Täter [des] Wortes und nicht nur [seine] Hörer, die sich selbst betrügen!');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 23, 'Denn wenn jemand Hörer [des] Wortes ist, aber nicht [sein] Täter, gleicht dieser einem Mann, der sein natürliches Gesicht in einem Spiegel betrachtet –');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 24, 'denn er betrachtet sich und geht weg und vergisst sofort, wie er aussah.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 25, 'Wer sich aber in [das] vollkommene Gesetz der Freiheit vertieft und dabei bleibt, indem er kein vergesslicher Hörer, sondern ein Täter des Werkes [Gottes] wird, der wird durch sein Tun (in seinem Tun) selig sein.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 26, 'Wenn jemand gottesfürchtig (fromm) zu sein scheint (meint), aber [dabei] seine Zunge nicht im Zaum hält, sondern sein Herz betrügt, dessen Gottesverehrung [ist] wertlos.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 27, 'Reine und unbefleckte Gottesverehrung vor [unserem] Gott und Vater besteht darin, Waisen und Witwen in ihrer bedrängten Lage zu besuchen [und] sich selbst vor der Welt unbefleckt (fehlerlos, makellos, untadelig) zu bewahren.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 1, 'Meine Geschwister (Brüder, Brüder [und Schwestern]), habt den Glauben [an] unseren Herrn der Herrlichkeit, Jesus Christus, nicht in Parteilichkeit!');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 2, 'Denn wenn in eure Synagoge ein Mann mit goldenen Ringen an den Fingern in prächtiger Kleidung kommt, {es kommt} aber auch ein Armer in schmutziger Kleidung,');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 3, 'und (doch) ihr kümmert euch um denjenigen, der die prächtige Kleidung trägt, und sagt: Setze du dich hier auf den guten Platz!, doch (und) zu dem Armen sagt ihr: Stelle du dich [dorthin] oder setze dich da unten [auf] meinen Fußschemel!,');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 4, 'habt ihr da nicht in eurem Inneren (in eurem Herzen; untereinander) unterschieden und seid Richter [mit] böser Gesinnung geworden?');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 5, 'Hört, meine geliebten Geschwister (Brüder, Brüder [und Schwestern]): Hat (Erwählt nicht) Gott sich nicht die [in den Augen] der Welt Armen [dazu] erwählt, [um] Reiche im (durch den) Glauben und Erben des Reiches [zu sein], das er denen verheißen hat, die ihn lieben?');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 6, 'Doch ihr habt den Armen verachtet (verächtlich behandelt). Unterdrücken (Behandeln... gewalttätig) euch nicht die Reichen, und schleppen [nicht] sie euch vor Gericht?');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 7, 'Lästern nicht [gerade] sie den guten Namen, der über euch ausgerufen wurde?');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 8, 'Wenn ihr wirklich [das] königliche Gesetz gemäß der Schrift erfüllt, „Liebe deinen Mitmenschen (Nächsten) wie dich selbst!“, [dann] handelt ihr gut (richtig).');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 9, 'Wenn ihr aber bestimmte Menschen bevorzugt („parteiisch handelt/urteilt“, „die Person anseht“), begeht ihr Sünde, indem ihr vom Gesetz als Übertreter überführt werdet.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 10, 'Denn wer das ganze Gesetz einhält (bewahrt), aber in einem [einzigen Punkt (Gebot)] strauchelt, ist [dadurch an] allen [Geboten] schuldig geworden.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 11, 'Denn derjenige, der sagte: „Brich die Ehe nicht!“, der sagte auch: „Morde nicht!“Wenn du aber [jetzt zwar] keinen (nicht) Ehebruch begehst, aber mordest, bist du [dadurch] ein Gesetzesbrecher geworden.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 12, 'Sprecht {so} und handelt {so} wie [Menschen] (als [solche]), die einmal nach dem Gesetz der Freiheit gerichtet (werden wollen).');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 13, 'Denn das Gericht [ist] („ [soll ... sein] “, „ [wird ... sein] “) unbarmherzig [gegenüber] demjenigen, der keine Barmherzigkeit geübt hat – [die] Barmherzigkeit triumphiert über [das] Gericht.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 14, 'Was nützt es, meine Geschwister, wenn jemand Glauben zu haben behauptet, aber keine Werke hat? Vermag der Glaube etwa, ihn zu retten?');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 15, 'Wenn ein Bruder oder eine Schwester nackt (dürftig gekleidet) sind und ihnen die tägliche Nahrung fehlt,');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 16, 'aber einer von euch zu ihnen sagt: „Geht hin in Frieden, wärmt euch und esst euch satt!“, aber ihr gebt ihnen nicht, was für den Leib erforderlich ist, was nützt das?');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 17, 'So ist auch der Glaube, wenn er keine Werke [zur Folge] hat, für sich allein tot.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 18, 'Aber jemand wird sagen: Du hast Glauben und ich habe Werke – zeige mir deinen Glauben ohne Werke, und ich werde dir aus meinen Werken meinen Glauben zeigen.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 19, 'Du glaubst, dass es [nur] einen Gott gibt – Du hast recht! Auch die Dämonen glauben [das] und zittern (schaudern)!');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 20, 'Willst du [wohl] einsehen, o törichter Mensch, dass der Glaube ohne Werke nutzlos ist?');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 21, 'Wurde nicht Abraham, unser Vater, aufgrund [seiner] Werke für gerecht erklärt (freigesprochen), als er Isaak, seinen Sohn, auf dem Altar [als Opfer] darbrachte?');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 22, 'Du siehst, dass der Glaube mit seinen Werken zusammenwirkte und durch die Werke der Glaube zur Vollendung gelangte,');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 23, 'und die Schrift wurde erfüllt, die besagt: „Abraham {aber} glaubte Gott, und es wurde ihm als Gerechtigkeit angerechnet“, und er wurde „Freund Gottes“genannt.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 24, 'Ihr seht, dass [der] Mensch aufgrund seiner Werke für gerecht erklärt (freigesprochen) wird und nicht aufgrund [des] Glaubens allein.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 25, 'Wurde {aber} nicht genauso auch die Prostituierte Rahab aufgrund von Werken für gerecht erklärt (freigesprochen), als sie die Boten gastlich aufnahm und [auf] einem anderen Weg hinausführte?');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 26, 'Denn genau wie der Körper ohne Geist tot ist, so ist auch der Glaube ohne Werke tot.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 3, 1, 'Nicht viele [von euch sollen] Lehrer werden, meine Geschwister, denn ihr wisst, dass wir [Lehrer] ein strengeres Urteil empfangen werden.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 3, 2, 'Denn wir alle straucheln (stoßen an) vielfach (in vieler Hinsicht). Wenn jemand beim Reden nicht strauchelt, [ist] er ein vollendeter (reifer, erwachsener) Mensch (Mann), fähig, auch den ganzen Körper zu zügeln (in Zaum zu halten).');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 3, 3, '{aber} Wenn wir den Pferden {das} Zaumzeug (Zügel) ins Maul legen, damit sie uns gehorchen, dann lenken wir ihren ganzen Körper.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 3, 4, 'Seht (Siehe) auch die Schiffe: Obwohl sie so groß sind und von rauen Winden getrieben werden, werden sie von einem winzigen Steuerruder gelenkt, wohin die Absicht (Drang, Eifer, Trachten) des Steuermanns wünscht.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 3, 5, 'So ist auch die Zunge ein kleines Glied und prahlt [doch mit] großen [Dingen]. Seht (Siehe), welch kleines Feuer welch großen Wald (Holz) anzündet!');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 3, 6, 'Auch die Zunge [ist] ein Feuer: [Als] die Welt des Unrechts steht die Zunge unter unseren Gliedern da; sie, die den ganzen Körper beschmutzt und das Rad des Werdens in Brand setzt, wird [selbst] von der Hölle in Brand gesetzt.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 3, 7, 'Jede Art [der] Säugetiere wie auch [der] Vögel, [der] Kriechtiere wie auch [der] Meerestiere wird gezähmt und ist [durch] die menschliche Art (Natur) gezähmt worden,');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 3, 8, 'aber die Zunge vermag kein Mensch zu bändigen, [das] ruhelose (unruhige, unkontrollierte, wankelmütige) Übel, voller tödlichen (todbringenden) Gifts.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 3, 9, 'Mit ihr loben (reden wir gut von) wir den Herrn und Vater, und mit ihr verfluchen die Menschen, die nach der Ähnlichkeit (Gleichheit, Übereinstimmung. Klassisch: Bild, Ebenbild) Gottes erschaffen sind:');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 3, 10, 'aus demselben Mund kommt Segen und Fluch. Es darf nicht sein, meine Geschwister, [dass] dies so geschieht!');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 3, 11, 'Lässt etwa die Quelle aus derselben Öffnung süßes und bitteres [Wasser] quellen?');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 3, 12, 'Meine Geschwister, kann etwa ein Feigenbaum Oliven hervorbringen, oder ein Weinstock Feigen? Auch eine salzige [Quelle] [kann] kein Süßwasser hervorbringen.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 3, 13, 'Wer [ist] weise und kundig (verständig, gebildet) unter euch? Er soll durch {die} gute Lebensführung seine Werke in (durch) Bescheidenheit (Demut, Sanftmut) [aus] Weisheit erweisen (muss erweisen)!');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 3, 14, 'Aber wenn ihr bittere Eifersucht und Selbstsucht in eurem Herzen habt, rühmt euch nicht und lügt [nicht] wider die Wahrheit!');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 3, 15, 'Dies ist nicht die Weisheit, die von oben herabkommt, sondern [ist] irdisch, weltlich, natürlich [und] dämonisch.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 3, 16, 'Denn wo [immer es] Eifersucht und Selbstsucht [gibt], dort [gibt es] Unordnung (Unruhe) und jede [Art von] gemeinem (niederem, schlimmem) Tun (Sache, Tat; Rechtsstreit).');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 3, 17, 'Doch die Weisheit, [die] von oben [kommt], ist {zwar} zuerst rein, dann friedfertig, gütig (nachgiebig, milde), folgsam (belehrbar, gehorsam), voller Barmherzigkeit und guter Früchte, unparteiisch [und] ohne Heuchelei.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 3, 18, 'Und (aber) [die] Ernte [der] Gerechtigkeit wird in Frieden gesät für jene, die Frieden stiften.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 4, 1, 'Woher [kommen] denn die Kämpfe (Kriege, Streitereien), und woher der Streit unter euch? [Kommen sie] nicht von euren Gelüsten, die [ständig] in euren Gliedern streiten?');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 4, 2, 'Ihr begehrt und habt [doch] nicht, ihr mordet (tötet; beneidet) und seid eifersüchtig und könnt [doch] nichts erreichen; ihr kämpft (streitet, zankt) und führt Kriege (kämpft); ihr habt nicht, weil ihr nicht (nichts) für euch bittet (fordert);');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 4, 3, 'ihr bittet und erhaltet [doch] nichts, weil ihr [in] böser [Absicht] für euch bittet (fordert), um (damit) [es] für eure Gelüste auszugeben.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 4, 4, '[Ihr] Ehebrecher, wisst ihr nicht, dass die Freundschaft (Liebe) [zur] Welt Feindschaft [mit] Gott ist? Also erweist (macht) sich jeder, der ein Freund der Welt sein will, [als] Feind Gottes.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 4, 5, 'Oder meint ihr, dass die Schrift umsonst sagt: Eifersüchtig verlangt [es] ihn [nach] dem Geist, den er in uns wohnen ließ,');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 4, 6, 'aber er gibt umso größere Gnade? Deswegen sagt sie [auch]: „Gott stellt sich den Hochmütigen entgegen, den Geringen (Unbedeutenden; Demütigen) aber gibt er Gnade.“');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 4, 7, 'Also ordnet [euch] Gott unter, doch widersteht dem Teufel, dann (und) er wird von euch fliehen;');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 4, 8, 'nähert euch Gott, dann (und) nähert er sich euch. Reinigt [eure] Hände, [ihr] Sünder, und läutert (reinigt, heiligt) [eure] Herzen, [ihr] Zweisinnigen!');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 4, 9, 'Seid bedrückt (wehklagt), {und} klagt (trauert) und weint! Euer Lachen soll sich in Trauer verwandeln und eure Freude in Niedergeschlagenheit!');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 4, 10, 'Demütigt (erniedrigt) euch vor [dem] Herrn, dann (und) wird er euch erhöhen!');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 4, 11, '[Hört auf], einander zu verleumden (schlecht zu machen, schlecht über einander zu reden) (Verleumdet einander nicht), Geschwister! Wer [seinen] Bruder verleumdet oder seinen Bruder verurteilt, der verleumdet [das] Gesetz und verurteilt [das] Gesetz — wenn du aber [das] Gesetz verurteilst, bist du nicht Täter [des] Gesetzes, sondern [sein] Richter.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 4, 12, 'Einer ist der Gesetzgeber und Richter, der die Macht hat (vermag, kann) zu retten und zu vernichten. Du aber, wer bist du, der [du deinen] Mitmenschen (Nächsten) verurteilst?');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 4, 13, 'Jetzt zu euch, die ihr sagt: „Heute oder morgen wollen wir in die oder die (diese oder jene) Stadt gehen und dort ein Jahr verbringen, {und} Handel treiben und Gewinn machen“;');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 4, 14, 'die ihr ([als] solche, die) nicht wisst, wie euer Leben morgen [sein wird] — ihr seid nämlich Dampf (Rauch), der [nur] kurze Zeit sichtbar ist (sichtbar wird) und dann (danach) verschwindet.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 4, 15, 'Dagegen (stattdessen) [sollt] ihr sagen: „Wenn der Herr will, dann werden wir leben und dieses oder jenes tun.“');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 4, 16, 'Nun (jetzt) aber rühmt ihr euch in euren Prahlereien. Alles (jede Art) deartige (solche) Rühmen ist böse!');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 4, 17, 'Also (nun) ist es [für den], der weiß (versteht), [was] Gutes zu tun [ist] (Gutes zu tun weiß) und es nicht tut, {ihm} Sünde.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 5, 1, 'Wohlan nun, [ihr] Reichen, weint [und] heult über eure Nöte (Elende, Mühsale. Alternativ: „über euren Nöten“), die [euch] bevorstehen.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 5, 2, 'Euer Reichtum ist vermodert und eure Gewänder sind [von] Motten zerfressen {worden}.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 5, 3, 'Euer Gold und Silber sind verrostet und ihr Rost (Gift) wird [gegen] euch zum Beweis (Zeugnis) sein und euer Fleisch wie Feuer fressen. Ihr habt in den letzten Tagen [Reichtümer] gesammelt.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 5, 4, 'Seht (Siehe), der Lohn der Arbeiter, die eure Felder abmähen, der [ihnen] von euch vorenthalten wurde, schreit, und die Schreie der Erntearbeiter sind zu den Ohren [des] Herrn Zebaot hingekommen.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 5, 5, 'Ihr habt geschwelgt auf der Erde und üppig gelebt, ihr habt eure Herzen am Schlachttag gemästet (ernährt, gefüttert),');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 5, 6, 'ihr habt den Gerechten verurteilt [und] ermordet (getötet), er leistet euch keinen Widerstand.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 5, 7, 'Deshalb (Nun) wartet geduldig, Geschwister, bis zur Wiederkunft des Herrn. Seht (Siehe), der Bauer erwartet die kostbare Frucht der Erde, indem er geduldig auf sie wartet, bis sie den Früh- und den Spätregen empfangen hat.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 5, 8, 'Auch ihr, wartet geduldig, stärkt eure Herzen, weil die Wiederkunft des Herrn nahe {gekommen} ist!');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 5, 9, 'Murrt nicht gegen einander, Geschwister, damit ihr nicht verurteilt werdet; seht (siehe), der Richter steht [schon] vor den Türen.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 5, 10, 'Nehmt euch, Geschwister, im Leiden und im Ausharren die Propheten [zum] Vorbild (Beispiel), die im Namen des Herrn sprachen.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 5, 11, 'Seht (Siehe), wir preisen jene glücklich, die durchgehalten haben: Ihr habt [vom] Durchhalten (Ausdauer, Standhaftigkeit) Hiobs gehört und das [vom] Herrn [herbeigeführte] Ende gesehen, dass der Herr voller Erbarmen und mitleidig ist.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 5, 12, 'Vor allen [Dingen] aber, meine Geschwister, schwört weder beim Himmel, noch bei der Erde, oder bei irgendeinem anderen Eid. Vielmehr soll euer Ja ein Ja und euer Nein ein Nein sein, damit ihr nicht dem Gericht verfallt.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 5, 13, 'Erleidet einer von (unter) euch ein Unglück, soll er beten; ist einer guten Mutes, soll er Loblieder singen;');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 5, 14, 'Ist einer von (unter) euch krank (schwach), soll er die Ältesten der Gemeinde herbeirufen und sie sollen über ihn (für ihn) beten [und] ihn [mit] Öl im Namen des Herrn salben.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 5, 15, 'Und das Gebet [im] Glauben wird den Kranken (Ermüdeten) retten und der Herr ihn aufrichten; und wenn er Sünden begangen hat, wird ihm vergeben werden.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 5, 16, 'Also bekennt einander [eure] Sünden und betet für einander, dass (damit) ihr geheilt werdet. [Das] wirksame Gebet (Bitte) eines Gerechten vermag viel.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 5, 17, 'Elija war ein Mensch von gleicher Art [wie] wir, und er betete inständig, dass es nicht regnen würde, und es regnete drei Jahre und sechs Monate nicht auf der Erde (auf die Erde);');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 5, 18, 'und er betete wieder, und der Himmel ließ es regnen und die Erde brachte ihre Frucht hervor.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 5, 19, 'Meine Geschwister, wenn einer von (unter) euch von der Wahrheit abirrt (in die Irre geht) und jemand ihn [wieder] auf den rechten Weg bringt,');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 5, 20, 'soll er wissen, dass derjenige, der einen Sünder von seinem Irrweg auf den rechten Weg zurückgeführt hat, seine Seele (Leben) vom Tod erretten und eine Menge Sünden zudecken wird.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 1, 'Petrus, Apostel Jesu Christi, an die Erwählten Fremden [die] in der Zerstreuung in Pontus, Galatien, Kappadozien, Asien und Bithynien [leben],');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 2, 'nach der Vorherbestimmung (Vorsehung) Gottes des Vaters in der Heiligung durch den Geist zum Gehorsam und zur Besprengung mit dem Blut Jesu Christi, Gnade sei mit euch, und Friede wachse (vermehre sich = in Fülle).');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 3, 'Gelobt sei der Gott und Vater unseres Herrn Jesus Christus, der uns wegen seiner großen Barmherzigkeit wieder gezeugt hat zu einer lebendigen Hoffnung durch die Auferstehung Jesu Christi von den Toten,');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 4, 'zu einem unvergänglichen, reinen und unverwelklichen (unvergänglichen) Heilsbesitz (Erbe), für euch im Himmel aufbewahrt,');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 5, 'die ihr durch Gottes Macht (Kraft) bewahrt seid durch den Glauben zur Rettung, die bereitet ist, um zur letzten Zeit (Endzeit) offenbart zu werden.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 6, 'In ihr jubelt ihr, die ihr jetzt ein wenig, wenn es sein soll, betrübt werdet durch mannigfache Prüfungen (Erprobungen),');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 7, 'damit die Echtheit eures Glaubens, die viel wertvoller ist als das vergängliche Gold, das doch durch das Feuer geprüft wird, (gefunden =) erwiesen wird zu Lob und Ruhm und Ehre bei der Offenbarung Jesu Christi.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 8, 'Ihn liebt ihr, obwohl ihr ihn nicht seht; an ihn glaubt ihr, ohne ihn jetzt zu sehen, doch jubelnd mit unaussprechlicher und verklärter Freude,');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 9, 'weil ihr das Ziel eures Glaubens erreicht, die Rettung eures Lebens.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 10, '');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 11, '');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 12, '');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 13, 'Darum umgürtet die Lenden eurer Gesinnung, seid nüchtern und hofft ganz auf die Gnade, die euch in der Offenbarung Jesu Christi angeboten wird.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 14, 'Als Kinder des Gehorsams gleicht euch nicht den Begierden von früher aus der Zeit der Unwissenheit an,');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 15, 'sondern wie der, der euch berufen hat, heilig ist, so seid auch ihr heilig in eurer ganzen Lebensweise!');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 16, 'Denn es steht geschrieben: Seid Heilige, weil ich heilig bin!');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 17, 'Und wenn ihr den als Vater anruft, der jeden ohne Ansehen der Person nach seinen Taten richtet, so führt euer Leben, während eures Aufenthalts in der Fremde, in Gottesfurcht.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 18, 'Ihr wisst, dass ihr nicht mit Vergänglichem, mit Silber oder Gold, erlöst worden seid aus eurer nichtigen, von den Vorfahren übernommenen Lebensweise,');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 19, 'sondern mit dem kostbaren Blut Christi als eines unschuldigen und makellosen Lammes.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 20, 'Er war schon vorher ausersehen worden – vor der Grundlegung der Welt, aber offenbar geworden ist er am Ende der Zeiten – um euretwillen.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 21, 'Die ihr durch ihn zum Glauben gekommen seid an Gott, der ihn auferweckt hat von den Toten, der ihm Herrlichkeit gab, damit euer Glaube auch Hoffnung ist auf Gott.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 22, '');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 23, '');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 24, '');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 25, '');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 1, 'Legt nun ab alle Schlechtigkeit und alle List und Heucheleien und Neid und allerlei Verleumdung (üble Nachrede).');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 2, 'Wie neugeborene Kinder verlangt nach geistiger, unverfälschter (reiner) Milch, damit ihr durch sie zunehmt (wachst) zum Heil (Rettung, Bewahrung, Erlösung),');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 3, 'wenn ihr „schmecktet, dass der Herr gütig ist“(Psalm 34,9).');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 4, 'Geht zu ihm, dem lebendigen Stein, von [den] Menschen zwar verworfen, bei Gott aber erwählt [und] wertvoll,');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 5, 'und selbst wie lebendige Steine (werdet erbaut =) lasst euch erbauen zu einem geistigen (geistlichen) Haus, zu einer heiligen Priesterschaft, um geistige (geistliche) Opfer darzubringen, die Gott willkommen sind durch Jesus Christus.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 6, 'Deshalb steht in der Schrift: „Schau (siehe), ich lege in Zion einen Eckstein, [einen] erwählten, wertvollen, und wer an ihn glaubt, wird nicht zuschanden (beschämt) werden.“(Jesaja 28,16)');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 7, 'Für euch nun, die Gläubigen, [ist er ein] Wert, für [die, die] nicht glauben aber [ist er] „ein Stein, den die Bauleute verwarfen, dieser wurde zum Eckstein“(Psalm 118,22),');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 8, 'und „ein Stein des Anstoßes und ein Fels, über den man zu Fall kommt“(Jesaja 8,14). Sie stoßen sich [an ihm], weil sie dem Wort ungehorsam sind, wozu sie auch [von Gott] bestimmt wurden.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 9, 'Ihr aber [seid] ein erwähltes Geschlecht (Volk), ein Königshaus, eine Priesterschaft, ein heiliges Volk (Stamm), ein Volk zum Eigentum (Besitz), damit ihr die guten Taten (Wunder) dessen weit hinaus verkündigt, der euch aus der Finsternis in sein wunderbares Licht gerufen hat.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 10, 'Die ihr einst „kein Volk“(Nicht-Volk, Hosea 1,6.9) [wart], jetzt aber Volk Gottes [seid], die „kein Erbarmen fanden“(Nicht-Erbarmen, Hosea 2,25), jetzt aber Erbarmen finden.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 11, '');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 12, '');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 13, '');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 14, '');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 15, '');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 16, '');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 17, '');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 18, '(Die =) Ihr Sklaven, gehorcht den Herren (in aller Furcht =) mit großem Respekt, nicht allein den guten und milden, sondern auch den (krummen, verdrehten =) schlechten.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 19, 'Dies nämlich ist [die] Gnade, wenn jemand (durch Bewusstsein Gottes =) der sich Gottes bewusst ist, Kümmernisse erträgt - wenn er ungerechterweise leidet.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 20, 'Denn welcher Ruhm [liegt darin], dass ihr ertragt, für Verfehlungen misshandelt zu werden? Dass ihr aber ertragt, für Rechtschaffenheit zu leiden, das ist Gnade von Gott.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 21, 'Denn dazu nämlich seid ihr berufen. Denn auch Christus hat für euch gelitten und euch ein Vorbild hinterlassen, damit ihr seinen Fußtapfen nachfolgt.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 22, 'Der keine Sünde (tat =) beging, \'\'noch wurde List (Betrug) in seinem Mund gefunden\'\'.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 23, 'Der, obwohl er beschimpft (geschmäht) wurde, nicht zurückschimpfte (zurückschmähte), obwohl er litt, nicht drohte, sondern [es] dem übergab, der gerecht richtet.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 24, 'Der \'\'unsere Sünden selbst hinauftrug\'\' an (in) seinem Körper (Leib) auf das Holz, damit wir, weil wir den Sünden gestorben sind, durch die (für die) Gerechtigkeit leben. \'\'Durch seine Strieme seid ihr geheilt\'\'.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 25, 'Denn ihr \'\'irrtet herum wie Schafe\'\', aber jetzt seid ihr zurückgekehrt (umgekehrt) zum Hirten und Beschützer (Aufseher) eures Lebens.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 1, '');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 2, '');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 3, '');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 4, '');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 5, '');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 6, '');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 7, '');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 8, '');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 9, 'und vergeltet nicht Böses (Schlechtes) mit (für, anstelle von) Bösem oder Schmähung (Beschimpfung) mit Schmähung, im Gegenteil aber segnet, weil ihr dazu berufen wurdet, damit ihr Segen erbt!');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 10, '');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 11, '');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 12, '');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 13, '');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 14, '');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 15, '');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 16, '');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 17, '');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 18, 'Denn auch Christus hat ein für allemal (einmal) für die Sünden gelitten, ein Gerechter für Ungerechte, um euch Zugang bei Gott zu verschaffen. Er wurde zwar leiblich (im Leib) getötet, aber geistlich (im Geist) lebendig gemacht.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 19, 'Wobei er auch zu den Geistern im Gefängnis ging und ihnen verkündigte,');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 20, 'die einst ungehorsam waren, als Gottes Langmut (Geduld) abwartete (wartete) in den Tagen Noahs, als die Arche gebaut wurde, in der wenige, das heißt acht Personen (Menschenleben), durch das Wasser hindurch gerettet wurden.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 21, 'Es ist das Gegenbild der Taufe, die auch euch heute (jetzt) rettet, nicht durch die Entfernung des körperlichen Drecks (Schmutzes), sondern als Zusage einer (guten =) festen Bindung an Gott durch die Auferstehung Jesu Christi,');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 22, 'der zur Rechten Gottes ist, nachdem er in den Himmel gelangt ist und ihm Engel und Mächte und Gewalten unterworfen wurden.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 4, 1, '');
