INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 3, 2, '');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 3, 3, '');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 3, 4, '');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 3, 5, '');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 3, 6, '');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 3, 7, '');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 3, 8, 'In diesem aber soll euch nicht verborgen sein, ihr Lieben (Geliebte), dass ein Tag bei Gott wie tausend Jahre [ist] und tausend Jahre wie ein Tag.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 3, 9, 'Nicht verzögert der Herr die Verheißung, was einige für Verzögerunng halten, sondern er hat Großmut (Langmut/Geduld) mit euch, nicht will er, dass einige verloren werden, sondern [er will] alle zur Umkehr führen.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 3, 10, 'Der Tag des Herrn aber wird kommen wie ein Dieb, am dem die Himmel mit lautem Geräusch kaputt gehen, die Elemente aber werden brennen und werden aufgelöst ((ein ((ein) geschmolzen) werden und die Erde und die Werke (Arbeit) auf ihr werden gefunden.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 3, 11, 'Wenn sich dies alles auflöst, welcher Art ist es notwendig, dass ihr wandelt in heiligem Lebenswandel und Frömmigkeit,');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 3, 12, 'dass ihr erwartet und beschleunigt (vorantreibt) die Wiederkehr des Tages Gottes durch den Himmel brennend aufgelöst werden und die Elemente brennend schmelzen.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 3, 13, '');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 3, 14, '');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 3, 15, '');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 3, 16, '');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 3, 17, '');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 3, 18, '');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 1, 1, 'Was von Anfang an war, was wir gehört haben, was wir mit unseren Augen gesehen haben, was wir geschaut und unsere Hände berührt haben, über das Wort des Lebens –');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 1, 2, 'und das Leben ist erschienen (wurde offenbar, sichtbar), und wir sahen und bezeugen und verkünden Euch das ewige Leben, das bei dem Vater war und uns erschienen ist –');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 1, 3, 'was wir [also] gesehen und gehört haben, verkünden wir auch Euch, damit auch Ihr mit uns Gemeinschaft habt. Und unsere Gemeinschaft mit dem Vater ist {aber} auch [Gemeinschaft] mit seinem Sohn Jesus Christus.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 1, 4, 'Und dies (diese Dinge) schreiben wir, damit unsere Freue vollkommen sei.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 1, 5, 'Und das ist die Botschaft (Nachricht), die wir gehört haben von ihm und euch verkündigen, dass Gott Licht ist und überhaupt (absolut) keine Finsternis (Dunkel) in ihm ist.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 1, 6, 'Wenn wir sagen, daß wir mit ihm Gemeinschaft haben und in der Dunkelheit (in der Finsterniss, im Finstern) wandeln (leben), lügen wir und tun die Wahrheit nicht.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 1, 7, 'Wenn wir aber im Licht wandeln (leben), wie er im Licht ist, haben wir Gemeinschaft miteinander und das Blut Jesu, seines Sohnes, reinigt uns von aller Sünde.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 1, 8, 'Wenn wir sagen, dass wir Sünde nicht in uns haben, betrügen wir uns selbst und die Wahrheit ist nicht in uns.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 1, 9, 'Wenn wir unsere Sünden bekennen, ist er treu und gerecht, dass er uns die Sünden vergibt und uns reinigt von aller Ungerechtigkeit.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 1, 10, 'Wenn wir sagen, dass wir nicht gesündigt haben, machen wir ihn zum Lügner und sein Wort ist nicht in uns.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 1, 'Meine Kinder, dieses schreibe ich euch, damit ihr nicht sündigt. Und wenn jemand sündigt, haben wir einen Parakleten (Fürsprecher, Helfer, Beistand) bei dem Vater, Jesus Christus [den] Gerechten.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 2, 'Und er ist die Sühnung für unsere Sünden, nicht für die unseren allein, sondern auch für die ganze Welt.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 3, 'Und daran (darin) erkennen wir, daß wir ihn erkannt haben, daß (wenn) wir seine Gebote halten.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 4, 'Wer sagt: {Daß} „Ich habe ihn erkannt“und seine Gebote nicht hält, ist ein Lügner, und in diesem ist die Wahrheit nicht.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 5, 'Wer immer sein Wort bewahrt (hält), in diesem ist die Liebe Gottes wahrhaft (wirklich) vollendet. Daran (Darin) erkenn wir, daß wir in ihm sind.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 6, 'Wer behauptet (sagt) in ihm zu bleiben, muß (ist verpflichtet), wie jener wandelte, auch selbst (zu) wandeln.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 7, 'Geliebte, ich schreibe Euch nicht ein neues Gebot, sondern ein altes Gebot, das Ihr von Anfang an hattet. Das Gebot, das alte ist das Wort, das Ihr gehört habt.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 8, 'Dann aber (Wiederum) schreibe ich Euch [doch] ein neues Gebot, das wahrhaftig (wahr, wirklich) in ihm ist und in Euch, denn die Finsternis (Dunkelheit) vergeht und das Licht, das wahre scheint schon.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 9, 'Wer behauptet (sagt) in dem Licht zu sein und seinen Bruder haßt, ist in der Finsternis (Dunkelheit) bis jetzt.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 10, 'Wer seinen Bruder liebt, bleibt im Licht, und in (an) ihm ist kein Anstoß (Ärgerniss).');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 11, 'Wer aber seinen Bruder hasst, ist in der Finsternis (Dunkelheit) und wandelt in der Finsternis (Dunkelheit) und weiß nicht, wohin er geht, weil die Finsternis (Dunkelheit) seine Augen blind gemacht (geblendet) hat.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 12, 'Ich schreibe Euch, Kinder, dass (weil) Euch die Sünden vergeben (erlassen; worden) sind wegen seines Namens.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 13, 'Ich schreibe Euch, Väter, dass (weil) Ihr den [, der] von Anfang an [ist (war)], erkannt habt. Ich schreibe Euch, Jünglinge, dass (weil) Ihr den Bösen (Schlechten) besiegt habt.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 14, 'Ich habe Euch geschrieben (schreibe Euch), Kinder, dass (weil) Ihr den Vater erkannt habt. Ich habe Euch geschrieben (schreibe Euch), Väter, dass (weil) Ihr den [, der] von Anfang an [ist (war)], erkannt habt. Ich habe Euch geschrieben (schreibe Euch), Jünglinge, dass (weil) Ihr stark seid und das Wort Gottes in Euch bleibt und Ihr den Bösen (Schlechten) besiegt habt.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 15, 'Liebt nicht die Welt und nicht die Dinge (das, was) in der Welt ([ist]). Wenn einer die Welt liebt, ist die Liebe des Vaters (zum Vater) nicht in ihm.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 16, 'Denn alles {das} in der Welt, die Begierde (Lust) des Fleisches und die Begierde (Lust) der Augen und der Hochmut (Stolz) des Lebens (Vermögens), ist nicht vom (aus dem) Vater, sondern von (aus) der Welt.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 17, 'Und die Welt vergeht und ihre Begierde (Lust), wer aber den Willen Gottes tut, bleibt in {die} Ewigkeit.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 18, 'Kinder, [es] ist [die] letzte Stunde, und wie Ihr gehört habt, daß ein Antichristus (der Antichrist) kommt, sind jetzt auch viele Antichristusse (Antichriste) geworden (entstanden, da), woran (woraus, woher) wir erkennen, daß [es die] letzte Stunde ist.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 19, 'Von (Aus) uns gingen (kamen) sie aus (heraus), aber sie waren nicht von (aus) uns. Wenn sie nämlich von (aus) uns gewesen wären, wären sie bei (mit) uns geblieben – aber damit offenbar wird (sie offenbar gemacht werden), dass sie alle nicht (nicht alle) von (aus) uns sind [sind sie von uns gegangen].');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 20, 'Und Ihr habt eine Salbung vom Heiligen und wißt alle (seid alle Wissende, wißt es alle).');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 21, 'Ich habe Euch nicht geschrieben (schreibe Euch nicht), dass (weil) Ihr die Wahrheit nicht kennt, sondern dass (weil) Ihr sie kennt, und dass (weil) jede Lüge nicht aus der Wahrheit ist.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 22, 'Wer ist der Lügner, wenn nicht [der,] der leugnet, dass Jesus {nicht} der Christus ist? Dieser ist der Antichristus (Antichrist), der den Vater und den Sohn leugnet.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 23, 'Jeder, der den Sohn leugnet, hat auch den Vater nicht; wer den Sohn bekennt (anerkennt), hat auch den Vater.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 24, '(Ihr [nun:]) Was Ihr von Anfang an gehört habt, bleibe in Euch. Wenn in Euch bleibt, was Ihr von Anfang an gehört habt, bleibt auch Ihr im Sohn und im Vater.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 25, 'Und dieses ist die Zusage (die Verheißung das Versprechen), die (das) er (selbst) uns gegeben (zugesagt, verheißen, versprochen) hat: das ewige Leben.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 26, 'Dies (Diese Dinge) schreibe (habe) ich Euch (geschrieben) über diejenigen, die Euch in die Irre führen (verführen).');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 27, 'Und Ihr [nun]: Die Salbung, die Ihr empfangen habt von ihm, bleibt in Euch, und Ihr habt [es] nicht nötig, daß einer Euch belehrt. Sondern, wie seine Salbung Euch über alles belehrt, und sie (es) wahr (wahrhaftig) ist und nicht Lüge ist ([so] ist sie (es) auch wahr (wahrhaftig) und nicht Lüge), und wie sie Euch belehrt hat, [so] bleibt (Ihr) in ihm.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 28, 'Und nun, Kinder, bleibt in ihm, damit wir, wenn er erscheint (offenbart wird, sichtbar gemacht wird), Zuversicht (Freude) haben und nicht beschämt werden von ihm in seiner Ankunft.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 29, 'Wenn Ihr wißt, dass er gerecht ist, [so] erkennt (Ihr), dass jeder, der die Gerechtigkeit tut, aus ihm geboren (gezeugt) ist.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 1, 'Seht, welche (was für eine) Liebe uns der Vater geschenkt (gegeben) hat, daß wir Kinder Gottes genannt werden (werden sollen; heißen, heißen sollen) – und wir sind [es] auch. Deshalb kennt (erkennt) die Welt uns nicht, weil sie ihn nicht gekannt (erkannt) hat.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 2, 'Geliebte, jetzt sind wir Kinder Gottes und es ist noch nicht sichtbar (offenbar) geworden (gemacht worden), was wir sein werden. Wir wissen, daß wir, wenn es sichtbar (offenbar; gemacht) wird (er erscheinen wird), ihm ähnlich (gleich) sein werden, weil wir ihn sehen werden, wie er ist.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 3, 'Und jeder, der diese Hoffnung auf ihn hat, heiligt (reinigt) sich, so wie er (jener) heilig (rein) ist.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 4, 'Jeder, der sündigt (die Sünde tut), handelt auch gesetzwidrig (gesetzlos; tut auch die Gesetzwidrigkeit, Gesetzlosigkeit), und die Sünde ist die Gesetzwidrigkeit (Gesetzlosigkeit).');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 5, 'Und Ihr wißt, dass jener erschienen ist, damit er die Sünden trägt (wegnimmt), und in ihm ist keine Sünde.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 6, 'Jeder, der in ihm bleibt, sündigt nicht. Jeder der sündigt, hat ihn nicht gesehen und ihn nicht erkannt.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 7, 'Kinder (Kindlein), keiner soll Euch in die Irre führen (täuschen, verführen): Wer die Gerechtigkeit tut, ist gerecht, wie jener gerecht ist.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 8, 'Wer die Sünde tut, ist vom (aus dem) Teufel (Satan), denn der Teufel (Satan) sündigt von Anfang an. Dazu ist der Sohn Gottes erschienen, daß er die Werke des Teufels (Satans) zerstört.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 9, 'Jeder, der aus Gott geboren (gezeugt) ist, sündigt nicht (tut nicht Sünde), denn sein Samen bleibt in ihm, und er kann nicht sündigen, weil er aus Gott geboren (gezeugt) ist.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 10, 'Daran (Darin) sind die Kinder Gottes erkennbar (sichtbar, offenbar) und die Kinder des Teufels (Satans): Jeder, der Gerechtigkeit nicht tut, ist nicht aus Gott, und der, der seinen Bruder nicht liebt.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 11, 'Denn dieses ist die Botschaft, die ihr von Anfang an gehört habt, daß wir einander lieben sollen.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 12, 'Nicht wie Kain [, der] aus dem Bösen (Schlechten) war und seinen Bruder ermordete (schlachtete). Und weshalb ermordete (schlachtete) er ihn? Weil seine Werke böse (schlecht) waren, die aber seines Bruders gerecht.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 13, 'Wundert Euch nicht, Brüder, wenn die Welt Euch haßt.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 14, 'Wir wissen, dass wir hinübergegangen sind vom (aus dem) Tod in das Leben, weil wir die Brüder lieben. Wer nicht liebt, bleibt im Tod.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 15, 'Jeder, der seinen Bruder hasst, ist ein Mörder (Menschenmörder), und Ihr wißt, dass kein (jeder) Mörder (Menschenmörder) ewiges Leben (nicht) bleibend in sich (ihm) hat.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 16, 'Daran (Darin) haben wir die Liebe erkannt, dass jener für uns sein Leben (seine Seele) hingegeben (eingesetzt) hat. Auch müssen (sind verpflichtet) für die Brüder das Leben (die Seele) hinzugeben (einzusetzen).');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 17, 'Wenn einer (Wer) also die Lebensnotwendigkeiten (das Leben; Vermögen in) der Welt hat und [er] sieht seinen Bruder Not leiden (haben) und verschließt sein Herz (Innerstes) vor ihm, wie bleibt ([kann, (soll)]) die Liebe Gottes in ihm (bleiben)?');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 18, 'Kinder (Kindlein), laßt uns nicht mit (einem) Wort und nicht mit der Zunge lieben, sondern in Tat und Wahrheit.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 19, 'Daran (Darin) werden wir erkennen, dass wir aus der Wahrheit sind, und vor ihm (ihm gegenüber, in seiner Gegenwart) werden wir unser Herz überzeugen (beruhigen),');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 20, 'dass, wenn ([in Bezug auf alles], dessentwegen) das Herz uns verurteilt, {dass} (denn) Gott (ist) größer ist als unser Herz und (kennt) alles kennt.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 21, 'Geliebte, wenn das Herz uns nicht verurteilt, haben wir Zuversicht (Freimut, Offenheit, offenen Zugang) gegenüber (zu) Gott,');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 22, 'und was immer wir erbitten, empfangen wir von ihm, weil wir seine Gebote halten und das (vor) ihm Angenehme tun.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 23, 'Und dies ist sein Gebot, daß wir an den Namen seines Sohnes Jesus Christus glauben und einander liebern, wie er [es] uns als (ein) Gebot gegeben hat.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 24, 'Und wer seine Gebote hält, bleibt in ihm und er in ihm; und daran (darin) erkennen wir, daß er in uns bleibt: an (aus) dem Geist, den er uns gegeben hat.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 4, 1, '[Meine] Lieben (Geliebten), vertraut nicht jedem Geist, sondern prüft die Geister, ob sie von (aus) Gott sind, denn viele Lügenpropheten (falsche Propheten) sind in die Welt gekommen.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 4, 2, 'Daran erkennt ihr den Geist Gottes: Jeder Geist, der Jesus Christus [als] im Fleisch gekommen bekennt, ist von Gott,');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 4, 3, 'und jeder Geist, der Jesus nicht bekennt, ist nicht von Gott; und so ein [Geist] ist der [Geist] des Antichristen – desjenigen [, von dem] ihr gehört habt, dass er kommt, und er ist [auch] jetzt schon in der Welt.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 4, 4, '\'\'Ihr\'\' seid von Gott, [meine] Kinder, und ihr habt sie besiegt, denn derjenige [Geist] in euch ist besser (größer) als derjenige in der Welt.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 4, 5, '\'\'Sie\'\' sind von (aus) der Welt, aus diesem Grund (deshalb) sprechen sie [wie] von (aus) der Welt, und die Welt hört auf sie.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 4, 6, '\'\'Wir\'\' sind von (aus) Gott. Wer (jeder, der) Gott kennt, hört auf uns. Wer nicht von (aus) Gott ist, hört nicht auf uns. Auf diese Weise (daran) erkennen wir den Geist der Wahrheit und den Geist der Falschheit (Lüge).');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 4, 7, '[Meine] Lieben (Geliebten), wir wollen einander lieben, denn die Liebe ist von (aus) Gott, und jeder, der liebt, ist von (aus) Gott geboren {worden} und kennt Gott.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 4, 8, 'Wer nicht liebt, hat Gott nicht erkannt, denn Gott ist Liebe.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 4, 9, 'Darin hat sich die Liebe Gottes in (unter) uns gezeigt (ist klar/sichtbar geworden), dass Gott seinen einzigen (einzigartigen) Sohn in die Welt gesandt hat, damit (sodass) wir leben können (leben).');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 4, 10, 'Darin ist Liebe, nicht weil (dass) \'\'wir Gott\'\' geliebt haben, sondern weil (dass) \'\'er uns\'\' geliebt und seinen Sohn [als] Mittel zur Vergebung (Sühneopfer; [zur] Sühne) unserer Sünden gesandt hat.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 4, 11, '[Meine] Lieben (Geliebten), wenn Gott uns auf diese Weise (so sehr) geliebt hat, dann (und) \'\'müssen wir\'\' (sind wir verpflichtet) einander lieben!');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 4, 12, 'Gott hat [noch] niemals jemand gesehen. [Aber] wenn wir einander lieben, dann lebt (bleibt) er in (unter) uns und seine Liebe ist in (unter) uns vollkommen geworden.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 4, 13, 'Auf diese Weise (daran) erkennen (wissen) wir, dass wir in ihm leben (bleiben) und er in uns, weil er uns [Anteil] an seinem Geist gegeben hat.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 4, 14, 'Und \'\'wir haben gesehen und bezeugen\'\', dass der Vater den Sohn [als] Retter der Welt gesandt hat.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 4, 15, 'Wenn sich jemand dazu bekennt, dass Jesus der Sohn Gottes ist, lebt (bleibt) Gott in ihm und er in Gott.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 4, 16, 'Und \'\'wir\'\' haben die Liebe \'\'erkannt und [ihr] geglaubt\'\', die Gott uns gegenüber (in uns) hat. Gott ist Liebe, und wer in der Liebe lebt (bleibt), lebt (bleibt) in Gott, und Gott lebt (bleibt) in ihm.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 4, 17, 'Auf diese Weise (darin) ist die Liebe mit uns vollkommen geworden, damit wir am Tag des Gerichts Zuversicht (Mut) haben, denn (dass) genau wie er (jener), [so] sind auch wir in dieser Welt.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 4, 18, '\'\'Angst\'\' gibt es nicht in der Liebe. Vielmehr (sondern) die vollkommene Liebe wirft die Angst hinaus, denn die Angst hat [mit] Bestrafung [zu tun], und (aber) wer sich fürchtet, ist nicht in der Liebe vollkommen geworden.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 4, 19, 'Wir lieben, denn er hat uns zuerst geliebt.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 4, 20, 'Wenn jemand sagt: „Ich liebe Gott“, und [dabei] seinen Bruder (sein Geschwister) hasst, so ist er ein Lügner: Denn wer seinen Bruder nicht liebt, den er [bereits] gesehen hat, dann kann er Gott, den er nicht gesehen hat, nicht lieben.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 4, 21, 'Und dieses Gebot haben wir von ihm: Dass wer Gott liebt, auch seinen Bruder liebe.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 5, 1, 'Jeder, der glaubt, daß Jesus der Christus (Messias) ist, ist aus {dem} Gott geboren (gezeugt, entstanden), und jeder, der den Gebärenden (Zeugenden) liebt, liebt auch den aus ihm Geborenen (Gezeugten).');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 5, 2, 'Daran erkennen wir, daß wir die Kinder {des} Gottes lieben, daß (wenn) wir {den} Gott lieben und seine Gebote halten (tun).');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 5, 3, 'Das nämlich ist die Liebe zu {dem} Gott, daß wir seine Gebote halten (bewahren) – und seine Gebote sind nicht schwer.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 5, 4, 'Denn alles, was aus (von) Gott geboren (gezeugt, entstanden) ist, besiegt die Welt. Und das ist der Sieg, der die Welt besiegt hat: Unser Glaube.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 5, 5, 'Wer aber ist [der (es),] der die Welt besiegt, wenn nicht der, der glaubt, daß Jesus der Sohn {des} Gottes ist?');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 5, 6, 'Dieser ist es (der), der durch Wasser und Blut gekommen ist, Jesus Christus. Nicht im Wasser allein, sondern im Wasser und im Blut. Und der Geist ist [es (der),] der bezeugt, denn (daß) der Geist die Wahrheit (ist).');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 5, 7, 'Denn drei sind [es], die Zeugnis geben (ablegen; bezeugen),');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 5, 8, 'Der Geist und das Wasser und das Blut, und die drei sind in das Eine (eins).');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 5, 9, 'Wenn wir das Zeugnis der Menschen annehmen – das Zeugnis Gottes ist größer, weil dies das Zeugnis Gottes ist, das er über (für) seinen Sohne Zeugnis gegeben (abgelegt; bezeugt) hat.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 5, 10, 'Wer an den Sohn Gottes glaubt, hat das Zeugnis in sich; wer Gott nicht glaubt, hat [aus ihm] einen Lügner gemacht, weil er nicht an das Zeugnis geglaubt hat, das Gott über (für) seinen Sohn gegeben (abgelegt; bezeugt) hat.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 5, 11, 'Und dies ist das Zeugnis, dass Gott uns ewiges Leben gegeben hat und dieses Leben in seinem Sohn ist.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 5, 12, 'Wer den Sohn hat, hat das Leben. Wer den Sohn Gottes nicht hat, hat das Leben nicht.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 5, 13, 'Dies (Diese Dinge) habe ich Euch – denen, die an den Namen des Sohnes Gottes glauben – geschrieben, damit Ihr wisst, dass Ihr ewiges Leben habt.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 5, 14, 'Und dies ist die Freimütigkeit (Zuversicht, gutes Zutrauen, Offenheit), welche wir zu ihm haben, dass, wenn wir irgendetwas erbitten nach (gemäß) seinem Willen, er uns hört (erhört).');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 5, 15, 'Und wenn wir wissen, dass er uns erhört (hört) in Bezug auf [alles], was (immer) wir erbitten, wissen wir, dass wir alles (das Erbetene, die erbetenen Dinge) haben, was (die) wir von ihm erbeten haben.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 5, 16, 'Wenn einer seinen Bruder sündigen sieht, eine Sünde [, die] nicht zum Tod [führt], soll (wird) er [für ihn] bitten, und er (Gott) wird ihm Leben geben - denen die nicht zum Tod sündigen. Es gibt Sünde [, die] zum Tod [führt]. Nicht über diese (jene) [Sünde] sage ich, daß er bitten soll.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 5, 17, 'Jedes Unrecht [Jede Ungerechtigkeit] ist Sünde, und es gibt Sünde [, die] nicht zum Tod [führt].');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 5, 18, 'Wir wissen, daß jeder, der aus (von) Gott geboren (gezeugt) ist, nicht sündigt, sondern, wer aus (von) Gott geboren (gezeugt) wurde, den bewahrt er (der hütet/bewahrt sich), und der Böse (Schlechte) berührt (erreicht) ihn nicht.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 5, 19, 'Wir wissen, daß wir aus Gott sind und die ganze Welt im (in [der Sphäre des]) Bösen (Schlechten, Argen) liegt.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 5, 20, 'Wir wissen aber, dass der Sohn Gottes gekommen ist und uns gegeben hat [das] Erkenntnisvermögen (Verstehen, Sinn), damit wir erkennen den Wahrhaftigen und wir sind in dem Wahrhaftigen, in seinem Sohn Jesus Christus. Dieser ist der wahrhaftige Gott und [das] ewige Leben.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 5, 21, 'Kindlein (Kinderchen), hütet (schützt) euch {selbst} vor den Bildern (Trugbildern, Götzen)!');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 1, 1, '');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 1, 2, '');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 1, 3, '');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 1, 4, '');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 1, 5, '');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 1, 6, '');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 1, 7, '');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 1, 8, '');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 1, 9, '');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 1, 10, '');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 1, 11, '');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 1, 12, '');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 1, 13, '');
