INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 12, 1, 'Und es erschien ein großes Zeichen am Himmel (im Himmel): eine Frau, umworfen mit der Sonne, und der Mond unter ihren Füssen, und auf ihrem Haupt ein Kranz von zwölf Sternen.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 12, 2, 'Sie trägt schwanger, und sie schreit in Wehen und Schmerzen einer Geburt.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 12, 3, 'Und ein anderes Zeichen erschien am Himmel: Siehe, ein Drache, gross und feuerrot, mit sieben Köpfen und zehn Hörnern, und auf seinen Köpfen sieben Diademe.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 12, 4, '');
