INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 12, 17, '');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 13, 1, 'Und ich sah ein Tier aus dem Meer aufsteigen, welches zehn Hörner und sieben Köpfe und auf seinen Hörnern zehn Diademe und auf seinen Köpfen einen blasphemischen Namen hatte.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 13, 2, 'Und das Tier, welches ich sah, war wie ein Leopard und seine Füße wie die eines Bären und sein Mund wie der Mund eines Löwen. Und der Drache gab ihm seine Macht und seinen Thron und große Gewalt.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 13, 3, 'Und [ich sah] einen seiner Köpfe wie zu Tode ge-schlachtet und die Wunde seines Todes wurde geheilt. Und die ganze Welt wunderte sich hinter dem Tier her.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 13, 4, 'Und sie beteten den Drachen an,weil er dem Tier die Gewalt gegeben hatte, und sie beugten ihre Knie vor dem Tier, wobei sie sagten: „Wer ist wie das Tier und wer kann es bekämpfen?“');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 13, 5, 'Und ihm wurde ein Mund gegeben um Lautes und Blasphemisches zu reden und ihm wurde Gewalt gegeben, (es) zweiundvierzig Monate zu tun');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 13, 6, 'Und es öffnete seinen Mund zur Blasphemie um Gott zu lästern, seinen Namen und sein Zelt und diejenigen, welche im Himmel leben.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 13, 7, 'ihm wurde gegeben die Gewalt über jeden Stamm und (jedes) Volk und (jede) Sprache und (jede) Nation.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 13, 8, 'Und alle, die auf der Erde leben, werden vor ihm ihre Knie beugen, (jeder) dessen Name nicht geschrieben wurde in das Buch des Lebens des geschlachteten Lammes, vom Anfang der Welt an.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 13, 9, 'Wenn jemand ein Ohr hat, so höre er.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 13, 10, 'Wenn jemand in Gefangenschaft führt, so geht er in Gefangenschaft Wenn jemand mit einem Schwert tötet, so wird er mit einem Schwert getötet. Hier ist die Geduld und der Glaube der Heiligen.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 13, 11, 'Und ich sah ein anderes Tier aus der Erde hinaufsteigen und es hatte zwei Hörner wie ein Lamm und sprach wie ein Drache.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 13, 12, 'Und die ganze Gewalt des ersten Tieres tat es vor ihm, und es veranlasst die Erde und die auf ihr Lebenden, dass sie das erste Tier anbeten, dessen tödliche Wunde geheilt wurde.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 13, 13, 'Und es tut große Zeichen, indem es auch selbst Feuer aus dem Himmel auf die Erde herabkommen lasse vor den Menschen.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 13, 14, 'Und es täuschte diejenigen, welche auf der Erde wohnen, durch die Zeichen, die ihm vor dem Tier zu tun gegeben worden, indem es diesen auf der Erde Lebenden befahl, dem Tier ein Bild zu machen, welches die Wunde des Schwertes hat und (wieder) lebendig wurde.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 13, 15, 'Und ihm wurde gegeben dem Bild des Tieres Geist zu geben, sodass auch das Bild des Tieres sprach und veranlasste, dass alle getötet werden, die nicht anbeten das Bild des Tieres.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 13, 16, 'Und es veranlasst alle dazu, die Kleinen und die Großen, und die Reichen und die Armen, und die Freien und die Sklaven, dass sie sich ein Malzeichen geben an die rechte Hand oder ihre Stirn.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 13, 17, 'und so dass niemand kaufen oder verkaufen kann, wenn nicht derjenige, der das Zeichen des Namens des Tieres hat oder die Zahl seines Namens.');
INSERT INTO `GerOffBiSt_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 13, 18, 'Da ist Erkenntnis vonnöten: Wer den Geist (Fähigkeit) hat, errechne die Nummer des Tieres - die Nummer für einen Menschen -: Seine Nummer ist sechshundertsechsundsechzig.');
